import { redirect } from 'next/navigation'
import LoginPage from '@/features/auth/screens/LoginPage'

export default function Page() {
  redirect('/login')
}

'use client'

import React, { useState, useRef, useEffect } from 'react'
import { ChevronDown, Check } from 'lucide-react'
import { useLanguage, type Language } from '@/providers/language-provider'
import { VietnamFlag, UsaFlag } from '@/components/ui/flags'

interface Props {
  variant?: 'full' | 'compact'
  className?: string
}

export function LanguageDropdown({ variant = 'compact', className = '' }: Props) {
  const { language, setLanguage, t } = useLanguage()
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const handleSelect = (code: Language) => {
    setLanguage(code)
    setOpen(false)
  }

  const isVi = language === 'vi'

  return (
    <div className={`relative ${className}`} ref={ref}>
      {/* Trigger Button: Hiển thị lá cờ SVG & tên đầy đủ không viết tắt */}
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="
          h-10 px-3 flex items-center gap-2.5 rounded-2xl border transition-all duration-150
          border-slate-200/80 hover:border-orange-500/40 bg-white/90 hover:bg-white shadow-xs
          dark:border-slate-800 dark:hover:border-orange-500/40 dark:bg-slate-900/90 dark:hover:bg-slate-900
          text-slate-700 dark:text-slate-200 hover:text-orange-600 dark:hover:text-orange-400
          cursor-pointer select-none group
        "
        aria-haspopup="listbox"
        aria-expanded={open}
        title={isVi ? 'Đang chọn Tiếng Việt' : 'English selected'}
      >
        <span className="flex items-center shrink-0">
          {isVi ? <VietnamFlag className="w-5 h-3.5" /> : <UsaFlag className="w-5 h-3.5" />}
        </span>

        <span className="text-xs font-bold tracking-tight text-slate-800 dark:text-slate-100 group-hover:text-orange-600 dark:group-hover:text-orange-400 transition-colors">
          {isVi ? 'Tiếng Việt' : 'English'}
        </span>

        <ChevronDown
          size={12}
          className={`text-slate-400 transition-transform duration-200 ml-0.5 ${open ? 'rotate-180' : ''}`}
        />
      </button>

      {/* Dropdown Menu */}
      {open && (
        <div
          role="listbox"
          className="
            absolute right-0 top-full mt-2 z-50 w-56
            rounded-2xl border border-slate-200/90 bg-white/95 backdrop-blur-xl
            shadow-xl shadow-slate-300/40
            dark:border-slate-800 dark:bg-[#0f1117]/95
            dark:shadow-black/60
            overflow-hidden animate-fade-in-up
          "
        >
          <div className="px-4 py-2.5 border-b border-slate-100 dark:border-slate-800/80">
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500">
              {isVi ? 'Chọn ngôn ngữ' : 'Select language'}
            </p>
          </div>

          <div className="p-1.5 space-y-1">
            {/* Tiếng Việt - Lá cờ Việt Nam */}
            <button
              type="button"
              onClick={() => handleSelect('vi')}
              className={`
                w-full flex items-center justify-between gap-3 rounded-xl px-3 py-2.5
                text-left transition-all duration-150 cursor-pointer
                ${
                  isVi
                    ? 'bg-orange-500/10 dark:bg-orange-500/20 text-orange-600 dark:text-orange-400 font-bold border border-orange-500/20'
                    : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800/70 border border-transparent'
                }
              `}
            >
              <div className="flex items-center gap-2.5 min-w-0">
                <VietnamFlag className="w-5 h-3.5" />
                <div>
                  <p className="text-xs font-bold leading-tight">Tiếng Việt</p>
                  <p className="text-[10px] text-slate-400 dark:text-slate-500">Việt Nam</p>
                </div>
              </div>
              {isVi && <Check size={14} className="shrink-0 text-orange-500" />}
            </button>

            {/* English - Lá cờ Mỹ */}
            <button
              type="button"
              onClick={() => handleSelect('en')}
              className={`
                w-full flex items-center justify-between gap-3 rounded-xl px-3 py-2.5
                text-left transition-all duration-150 cursor-pointer
                ${
                  !isVi
                    ? 'bg-orange-500/10 dark:bg-orange-500/20 text-orange-600 dark:text-orange-400 font-bold border border-orange-500/20'
                    : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800/70 border border-transparent'
                }
              `}
            >
              <div className="flex items-center gap-2.5 min-w-0">
                <UsaFlag className="w-5 h-3.5" />
                <div>
                  <p className="text-xs font-bold leading-tight">English</p>
                  <p className="text-[10px] text-slate-400 dark:text-slate-500">Mỹ (United States)</p>
                </div>
              </div>
              {!isVi && <Check size={14} className="shrink-0 text-orange-500" />}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import React, { useState, useRef, useEffect } from 'react'
import { MapPin, ChevronDown, Check, Building2 } from 'lucide-react'
import { CAMPUSES, getActiveCampus, setActiveCampus, CAMPUS_CHANGE_EVENT, type CampusInfo } from '@/lib/campus'
import { useLanguage } from '@/providers/language-provider'

interface Props {
  variant?: 'compact' | 'full'
  className?: string
}

export function CampusSelector({ variant = 'compact', className = '' }: Props) {
  const { language } = useLanguage()
  const isVi = language === 'vi'
  const [campus, setCampusState] = useState<CampusInfo>(CAMPUSES[0])
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setCampusState(getActiveCampus())

    const handleCampusChange = (e: any) => {
      if (e.detail) {
        setCampusState(e.detail)
      } else {
        setCampusState(getActiveCampus())
      }
    }

    window.addEventListener(CAMPUS_CHANGE_EVENT, handleCampusChange)
    window.addEventListener('storage', handleCampusChange)
    return () => {
      window.removeEventListener(CAMPUS_CHANGE_EVENT, handleCampusChange)
      window.removeEventListener('storage', handleCampusChange)
    }
  }, [])

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const handleSelect = (item: CampusInfo) => {
    setActiveCampus(item.id)
    setCampusState(item)
    setOpen(false)
  }

  const displayName = isVi ? campus.nameVi : campus.name
  const shortDisplay = campus.shortName

  return (
    <div className={`relative ${className}`} ref={ref}>
      {/* Trigger Button */}
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="
          h-10 px-3 flex items-center gap-2 rounded-2xl border transition-all duration-150
          border-slate-200/80 hover:border-orange-500/40 bg-white/90 hover:bg-white shadow-xs
          dark:border-slate-800 dark:hover:border-orange-500/40 dark:bg-slate-900/90 dark:hover:bg-slate-900
          text-slate-700 dark:text-slate-200 hover:text-orange-600 dark:hover:text-orange-400
          group cursor-pointer select-none
        "
        aria-haspopup="listbox"
        aria-expanded={open}
        title={displayName}
      >
        <div className="w-5 h-5 rounded-lg bg-orange-500/10 text-orange-600 dark:text-orange-400 flex items-center justify-center shrink-0">
          <MapPin size={13} className="text-orange-600 dark:text-orange-400" />
        </div>

        <div className="flex flex-col items-start leading-tight text-left">
          <span className="text-[9px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500">
            Campus
          </span>
          <span className="text-xs font-bold text-slate-800 dark:text-slate-100 group-hover:text-orange-600 dark:group-hover:text-orange-400 transition-colors">
            <span className="hidden xl:inline">{displayName}</span>
            <span className="xl:hidden">{shortDisplay}</span>
          </span>
        </div>

        <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 font-bold ml-0.5">
          {campus.code}
        </span>

        <ChevronDown
          size={12}
          className={`text-slate-400 transition-transform duration-200 ml-0.5 ${open ? 'rotate-180' : ''}`}
        />
      </button>

      {/* Dropdown Menu */}
      {open && (
        <div
          role="listbox"
          className="
            absolute right-0 top-full mt-2 z-50 w-72
            rounded-2xl border border-slate-200/90 bg-white/95 backdrop-blur-xl
            shadow-xl shadow-slate-300/40
            dark:border-slate-800 dark:bg-[#0f1117]/95
            dark:shadow-black/60
            overflow-hidden animate-fade-in-up
          "
        >
          <div className="px-4 py-2.5 border-b border-slate-100 dark:border-slate-800/80 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Building2 size={14} className="text-orange-500" />
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400">
                {isVi ? 'Cơ sở đào tạo FPT' : 'FPT University Campuses'}
              </p>
            </div>
            <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-bold">
              {isVi ? 'Trực tuyến' : 'Live'}
            </span>
          </div>

          <div className="p-1.5 space-y-1">
            {CAMPUSES.map((item) => {
              const isActive = item.id === campus.id
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => handleSelect(item)}
                  className={`
                    w-full flex items-center justify-between gap-3 rounded-xl px-3 py-2.5
                    text-left transition-all duration-150 cursor-pointer
                    ${
                      isActive
                        ? 'bg-orange-500/10 dark:bg-orange-500/20 text-orange-600 dark:text-orange-400 font-bold border border-orange-500/20'
                        : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800/70 border border-transparent'
                    }
                  `}
                >
                  <div className="flex items-start gap-2.5 min-w-0">
                    <MapPin
                      size={14}
                      className={`shrink-0 mt-0.5 ${isActive ? 'text-orange-600 dark:text-orange-400' : 'text-slate-400'}`}
                    />
                    <div className="min-w-0">
                      <div className="flex items-center gap-1.5">
                        <p className="text-xs font-bold truncate leading-tight">
                          {isVi ? item.nameVi : item.name}
                        </p>
                        <span className="text-[9px] font-mono px-1 py-0.2 rounded bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 font-bold">
                          {item.code}
                        </span>
                      </div>
                      {item.address && (
                        <p className="text-[10px] text-slate-400 dark:text-slate-500 truncate mt-0.5 max-w-[200px]">
                          {item.address}
                        </p>
                      )}
                    </div>
                  </div>

                  {isActive && <Check size={14} className="shrink-0 text-orange-500" />}
                </button>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import * as React from 'react'
import Link from 'next/link'
import { useAuth } from '@/providers/auth-provider'
import { useTheme } from '@/providers/theme-provider'
import { useLanguage } from '@/providers/language-provider'
import { LanguageDropdown } from '@/components/i18n/LanguageDropdown'
import { CampusSelector } from '@/components/layout/CampusSelector'
import { Shield, School, GraduationCap, Sun, Moon, Menu, Bell } from 'lucide-react'
import { useNotifications } from '@/providers/notification-provider'

interface NavbarProps {
  title?: string
  subtitle?: string
  onMenu?: () => void
  onCollapse?: () => void
  collapsed?: boolean
}

function getMajorInfo(role: string | null | undefined, studentCode?: string, isVi: boolean = true) {
  if (role === 'lecturer') {
    return {
      major: isVi ? 'Kỹ thuật phần mềm' : 'Software Engineering',
      majorCode: 'SE',
      department: isVi ? 'Khoa CNTT' : 'IT Faculty',
      subInfo: isVi ? 'Giảng viên chuyên ngành' : 'Lecturer',
    }
  }
  if (role === 'admin') {
    return {
      major: isVi ? 'Ban Đào tạo' : 'Academic Affairs',
      majorCode: 'FPTU',
      department: isVi ? 'Quản trị hệ thống' : 'System Admin',
      subInfo: isVi ? 'Quản trị viên' : 'Administrator',
    }
  }

  // Student role:
  const code = (studentCode || '').toUpperCase()
  let major = isVi ? 'Kỹ thuật phần mềm' : 'Software Engineering'
  let majorCode = 'SE'

  if (code.startsWith('IA')) {
    major = isVi ? 'An toàn thông tin' : 'Information Assurance'
    majorCode = 'IA'
  } else if (code.startsWith('AI')) {
    major = isVi ? 'Trí tuệ nhân tạo' : 'Artificial Intelligence'
    majorCode = 'AI'
  } else if (code.startsWith('GD')) {
    major = isVi ? 'Thiết kế mỹ thuật số' : 'Graphic Design'
    majorCode = 'GD'
  } else if (code.startsWith('IS')) {
    major = isVi ? 'Hệ thống thông tin' : 'Information Systems'
    majorCode = 'IS'
  }

  return {
    major: `${major} (${majorCode})`,
    majorName: major,
    majorCode,
    classCode: 'SE1701',
    cohort: 'K17',
    semester: 'Spring 2026',
  }
}

export function Navbar({ title, subtitle, onMenu, onCollapse, collapsed }: NavbarProps) {
  const { user, role } = useAuth()
  const { theme, toggleTheme } = useTheme()
  const { t, language } = useLanguage()
  const { unreadCount, hasNew, isConnected } = useNotifications()
  const isVi = language === 'vi'

  // Format Display Name & ID for User
  const displayName = user?.fullName || user?.name || (role === 'student' ? 'Nguyễn Văn An' : role === 'lecturer' ? 'TS. Trần Văn Nam' : 'Quản trị viên')
  const rawId = user?.studentCode || user?.lecturerCode || user?.externalId || user?.id
  const displayId = rawId ? (rawId.length > 12 ? rawId.slice(0, 10).toUpperCase() : rawId) : (role === 'student' ? 'SE170245' : role === 'lecturer' ? 'GV1042' : 'ADM001')
  const idPrefix = role === 'student' ? 'MSSV' : role === 'lecturer' ? 'MSGV' : 'ID'

  const majorInfo = getMajorInfo(role, displayId, isVi)

  return (
    <header className="min-h-16 gap-3 border-b border-slate-200/80 dark:border-slate-800/80 bg-white/80 dark:bg-slate-950/70 backdrop-blur-xl px-3 py-2 sm:py-0 md:px-6 flex flex-wrap sm:flex-nowrap items-center justify-between sticky top-0 z-20 transition-colors">
      <div className="flex flex-1 items-center gap-3 min-w-0">
        <button type="button" aria-label={t('ui.open_menu', 'Mở menu điều hướng')} onClick={onMenu} className="p-2 lg:hidden">
          <Menu size={20} />
        </button>

        {/* User Identity Display: Tên, Chuyên ngành & Mã số SV (Không avatar) */}
        <Link
          href="/profile"
          title={t('nav.view_profile', 'Xem thông tin tài khoản')}
          className="group flex flex-col justify-center min-w-0 transition-all select-none text-left py-1"
        >
          {/* Line 1: Name + Major Tag */}
          <div className="flex items-center gap-2 min-w-0">
            <span className="text-sm font-black text-slate-900 dark:text-white tracking-tight group-hover:text-orange-600 dark:group-hover:text-orange-400 transition-colors truncate max-w-[150px] sm:max-w-[220px]">
              {displayName}
            </span>
            <span className="shrink-0 inline-flex items-center px-1.5 py-0.5 rounded-md text-[10px] font-bold bg-orange-500/10 text-orange-600 dark:text-orange-400 border border-orange-500/20 tracking-wide">
              {majorInfo.major}
            </span>
          </div>

          {/* Line 2: MSSV, Class & Semester */}
          <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mt-0.5 flex-wrap">
            <span className="font-mono text-[11px] tracking-wider shrink-0">
              {idPrefix}: <span className="font-bold text-slate-800 dark:text-slate-200">{displayId}</span>
            </span>
            {role === 'student' && (
              <>
                <span className="text-slate-300 dark:text-slate-700 text-xs font-light">•</span>
                <span className="text-[11px] font-medium text-slate-600 dark:text-slate-300">
                  {majorInfo.classCode}
                </span>
                <span className="text-slate-300 dark:text-slate-700 text-xs font-light hidden sm:inline">•</span>
                <span className="text-[11px] text-slate-400 dark:text-slate-500 hidden sm:inline">
                  {isVi ? 'Kỳ' : 'Sem'} {majorInfo.semester}
                </span>
              </>
            )}
          </div>
        </Link>
      </div>

      <div className="contents sm:flex sm:items-center sm:gap-2.5">
        <div className="order-last flex w-full items-center gap-2 sm:contents">
        {/* Campus Display */}
        <CampusSelector />

        {/* Language Switcher */}
        <LanguageDropdown />
        </div>

        {/* Notification Bell with Real-time WebSocket Counter */}
        <Link
          href={role ? `/${role}/notifications` : '/student/notifications'}
          title={
            unreadCount > 0
              ? `${unreadCount} ${t('nav.unread_notifs', 'thông báo chưa đọc')}`
              : t('nav.notifications', 'Thông báo')
          }
          className="relative h-10 w-10 flex items-center justify-center rounded-2xl border border-slate-200/80 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 text-slate-600 hover:text-orange-600 dark:text-slate-400 dark:hover:text-orange-400 transition-all shadow-xs group"
        >
          <Bell
            size={17}
            className={`transition-transform duration-200 group-hover:scale-110 ${
              hasNew ? 'animate-bounce text-orange-600 dark:text-orange-400' : ''
            }`}
          />
          {unreadCount > 0 && (
            <span className="absolute -top-1 -right-1 min-w-[19px] h-[19px] px-1 bg-gradient-to-r from-orange-500 to-rose-500 text-white text-[10px] font-black rounded-full flex items-center justify-center shadow-sm shadow-orange-500/40 ring-2 ring-white dark:ring-slate-950 animate-in zoom-in-50">
              {unreadCount > 99 ? '99+' : unreadCount}
            </span>
          )}
          {/* Subtle live WebSocket connection dot */}
          {isConnected && (
            <span
              title={isVi ? 'Thông báo đang cập nhật trực tiếp' : 'Notifications are updating live'}
              className="absolute bottom-1 right-1 w-1.5 h-1.5 rounded-full bg-emerald-500 ring-1 ring-white dark:ring-slate-900"
            />
          )}
        </Link>

        {/* Theme Toggle */}
        <button
          type="button"
          onClick={toggleTheme}
          title={theme === 'light' ? t('nav.theme.dark', 'Chế độ tối') : t('nav.theme.light', 'Chế độ sáng')}
          className="h-10 w-10 flex items-center justify-center rounded-2xl border border-slate-200/80 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 text-slate-600 hover:text-slate-900 dark:text-slate-400 dark:hover:text-slate-200 transition-all shadow-xs"
        >
          {theme === 'light' ? (
            <Moon size={16} className="text-slate-600" />
          ) : (
            <Sun size={16} className="text-amber-400" />
          )}
        </button>

        {/* Divider */}
        <div className="h-5 w-px bg-slate-200 dark:bg-slate-800 hidden sm:block" />

        {/* Current Role Badge */}
        {role && (
          <div className="hidden sm:flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-orange-50 dark:bg-orange-500/10 border border-orange-200 dark:border-orange-500/20 text-xs font-bold text-orange-600 dark:text-orange-400">
            {role === 'admin' && <Shield className="w-3.5 h-3.5" />}
            {role === 'lecturer' && <School className="w-3.5 h-3.5" />}
            {role === 'student' && <GraduationCap className="w-3.5 h-3.5" />}
            <span>
              {role === 'admin' ? t('nav.role_admin', 'Quản trị') : role === 'lecturer' ? t('nav.role_lecturer', 'Giảng viên') : t('nav.role_student', 'Sinh viên')}
            </span>
          </div>
        )}
      </div>
    </header>
  )
}

'use client'

import * as React from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { prefetchPageData } from '@/lib/api/prefetch'
import { useAuth } from '@/providers/auth-provider'
import { useLanguage } from '@/providers/language-provider'
import { useNotifications } from '@/providers/notification-provider'
import { AnonymousAvatar } from '@/components/ui/avatar'
import type { NavItem } from '@/types'
import {
  LayoutDashboard,
  Users,
  BookOpen,
  Library,
  FileSignature,
  BarChart3,
  FileText,
  Bot,
  Settings,
  FileCheck,
  Bell,
  UserCircle,
  GraduationCap,
  LogOut,
  Sparkles,
  Layers,
  Shield,
  Briefcase,
  ArrowLeftRight,
  Cpu,
} from 'lucide-react'

const ICON_MAP: Record<string, React.ElementType> = {
  LayoutDashboard,
  Users,
  BookOpen,
  Library,
  FileSignature,
  BarChart3,
  FileText,
  Bot,
  Settings,
  FileCheck,
  Bell,
  UserCircle,
  GraduationCap,
  Sparkles,
  Layers,
  Shield,
  Briefcase,
  ArrowLeftRight,
  Cpu,
}

interface SidebarProps {
  navItems: NavItem[]
  title: string
  roleLabel: string
  collapsed?: boolean
  onNavigate?: () => void
  className?: string
}

export function Sidebar({ navItems, title, roleLabel, collapsed = false, onNavigate, className }: SidebarProps) {
  const pathname = usePathname()
  const { user, role, logout } = useAuth()
  const { t } = useLanguage()
  const { unreadCount } = useNotifications()

  // Group by category
  const categories = React.useMemo(() => {
    const map = new Map<string, NavItem[]>()
    navItems.forEach((item) => {
      const cat = item.category || 'Khác'
      if (!map.has(cat)) map.set(cat, [])
      map.get(cat)!.push(item)
    })
    return Array.from(map.entries())
  }, [navItems])

  return (
    <aside
      aria-label={title}
      className={cn(
        'border-r border-slate-200/80 dark:border-slate-800/80 bg-white/95 dark:bg-slate-950/90 backdrop-blur-2xl flex flex-col justify-between shrink-0 h-screen sticky top-0 select-none z-30 transition-all duration-200',
        collapsed ? 'w-20' : 'w-72',
        className
      )}
    >
      <div className="flex-1 flex flex-col min-h-0">
