              className={cn(
                'w-11 h-11 rounded-2xl flex items-center justify-center text-white shadow-lg transition-all',
                isFinished
                  ? 'bg-gradient-to-tr from-emerald-500 to-teal-400 shadow-emerald-500/25 ring-2 ring-emerald-400/40'
