        </div>

        {/* Modal Body */}
        <div className="p-5 sm:p-6 overflow-y-auto space-y-4 flex-1 custom-scrollbar bg-slate-950/50">
          {/* HIGH-END PRODUCTION UPLOAD CARD (Active when uploading) */}
