                    className={cn(
                      'break-words',
                      lg.type === 'highlight'
                        ? 'text-amber-300 font-medium'
                        : lg.type === 'error'
                        ? 'text-rose-400 font-medium'
                        : lg.type === 'success'
                        ? 'text-emerald-400 font-medium'
