        {/* Modal Footer Actions */}
        <div className="p-4 sm:p-5 border-t border-slate-800 bg-slate-900/90 flex flex-col sm:flex-row items-center justify-between gap-3 shrink-0">
          <div className="text-xs text-slate-400 flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-400" />
            <span>
              Quy trình: <strong>Tiếp nhận bài nộp & Chờ công bố kết quả</strong>
            </span>
          </div>

          <div className="flex items-center gap-2.5 w-full sm:w-auto justify-end">
            {uploadError && (
              <button
                type="button"
                onClick={handleFinishAndClose}
                className="px-4 py-2.5 rounded-xl text-xs font-semibold text-slate-300 bg-slate-800 hover:bg-slate-700 border border-slate-700 cursor-pointer transition-colors"
              >
                Đóng & Chọn lại tệp
              </button>
            )}

            {isFinished && (
              <button
                type="button"
                onClick={handleDownload}
                disabled={isDownloading}
                className="px-4 py-2.5 rounded-xl text-xs font-semibold text-slate-300 bg-slate-800 hover:bg-slate-700 border border-slate-700 flex items-center gap-1.5 cursor-pointer disabled:opacity-50 transition-colors"
                title="Tải tệp ZIP bài làm vừa nộp về máy"
              >
                {isDownloading ? <Loader2 className="w-3.5 h-3.5 animate-spin text-blue-400" /> : <Download className="w-3.5 h-3.5 text-blue-400" />}
                <span>Tải tệp vừa nộp (.zip)</span>
              </button>
            )}

            <button
              type="button"
              onClick={handleFinishAndClose}
              disabled={isUploadingLive && !uploadError}
              className={cn(
                'px-6 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer disabled:opacity-50',
                isFinished
                  ? 'bg-gradient-to-r from-emerald-500 via-teal-500 to-emerald-600 text-white shadow-lg shadow-emerald-500/25 hover:opacity-95 ring-1 ring-emerald-400/50'
                  : 'bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700'
              )}
            >
              {isFinished ? 'Xác nhận & Xem bài nộp' : isUploadingLive ? 'Đang gửi & Chờ xác nhận...' : 'Đóng'}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

/** Read legacy HTML as text; the document viewer never executes lecturer-supplied markup. */
export function readableAssignmentText(content: unknown): string {
  if (typeof content !== 'string') return ''
  if (!/<(?:p|div|h[1-6]|ul|ol|table|br)\b/i.test(content)) return content
  return content.replace(/<(script|style|iframe|object)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
    .replace(/<h([1-6])\b[^>]*>/gi, (_, level) => '\n' + '#'.repeat(Number(level)) + ' ')
    .replace(/<li\b[^>]*>/gi, '\n- ').replace(/<br\s*\/?\s*>|<\/(?:p|div|h[1-6]|li|tr|table)>/gi, '\n')
    .replace(/<\/(?:td|th)>/gi, ' | ').replace(/<[^>]*>/g, '')
    .replaceAll('&nbsp;', ' ').replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&quot;', '"').replaceAll('&#39;', "'").replaceAll('&amp;', '&')
    .replace(/\n{3,}/g, '\n\n').trim()
}
export function assignmentDocumentContent(summary: any, grading?: any): string {
  const candidates = [summary?.documentContent, summary?.description, grading?.metadata?.content, summary?.content, grading?.metadata?.description]
  return candidates.find(value => typeof value === 'string' && value.trim() && !/^Barem tiêu chí chấm điểm tự động và AI\.?$/i.test(value.trim())) || ''
}

import { assignmentsApi } from '@/lib/api/modules/assignments'
import { submissionsApi } from '@/lib/api/modules/submissions'
import type { AssignmentRow, SubmissionRow } from '@/lib/api/contracts'

export async function loadStudentAssignment(id: string, callbacks: {
  assignment: (assignment: AssignmentRow, grading: any) => void
  assignmentError: (error: unknown) => void
  assignmentSettled: () => void
  submission: (submission: SubmissionRow | null) => void
  submissionError: (error: unknown) => void
}) {
  let assignment: AssignmentRow | undefined
  let grading: any = null
  const primary = assignmentsApi.getAssignment(id).then(value => {
    assignment = value
    callbacks.assignment(value, grading)
  }).catch(callbacks.assignmentError).finally(callbacks.assignmentSettled)
  const enrichment = assignmentsApi.getGradingAssignment(id).then(value => {
    grading = value
    if (assignment) callbacks.assignment(assignment, grading)
  }).catch(() => {}) // Optional enrichment must not block the assignment document.
  const history = submissionsApi.getSubmissions({ assignmentId: id, view: 'summary' }).then(rows => {
    callbacks.submission([...rows].sort((a, b) => new Date(b.submittedAt ?? 0).getTime() - new Date(a.submittedAt ?? 0).getTime())[0] || null)
  }).catch(callbacks.submissionError)
  await Promise.allSettled([primary, enrichment, history])
}

