'use client'

import { useCallback, useEffect, useState } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { ADMIN_NAV } from '@/config/navigation'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Modal } from '@/components/ui/modal'
import { ErrorNotice } from '@/components/ui/feedback'
import { classesApi } from '@/lib/api/modules/classes'
import { usersApi } from '@/lib/api/modules/users'
import { errorMessage } from '@/lib/api/errors'
import type { ClassRow, StudentRow, UserRow } from '@/lib/api/contracts'
import { ArrowLeft, Edit3, GraduationCap, Users, UserPlus, BookOpen } from 'lucide-react'

export default function AdminClassDetailPage() {
  const params = useParams()
  const router = useRouter()
  const classId = (params?.id as string) || ''

  const [cls, setCls] = useState<ClassRow | null>(null)
  const [students, setStudents] = useState<StudentRow[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)

  // Note Modal
  const [noteModalOpen, setNoteModalOpen] = useState(false)
  const [noteForm, setNoteForm] = useState('')

  // Enroll Modal
  const [enrollModalOpen, setEnrollModalOpen] = useState(false)
  const [enrollForm, setEnrollForm] = useState('')
  const [allStudents, setAllStudents] = useState<any[]>([])
  const [cohortFilter, setCohortFilter] = useState('all')
  const [majorFilter, setMajorFilter] = useState('all')
  const [searchLoading, setSearchLoading] = useState(false)

  const loadData = useCallback(async () => {
    if (!classId) return
    setLoading(true)
    setError(null)
    try {
      const [classRes, studentsRes] = await Promise.all([
        classesApi.getClassDetail(classId),
        classesApi.getClassStudents(classId),
      ])
      setCls(classRes)
      setStudents(Array.isArray(studentsRes) ? studentsRes : [])
    } catch (cause) {
      setError(errorMessage(cause))
    } finally {
      setLoading(false)
    }
  }, [classId])

  useEffect(() => {
    void loadData()
  }, [loadData])

  const handleUpdateNote = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!classId || saving) return
    setSaving(true)
    try {
      await classesApi.updateClass(classId, { note: noteForm } as any)
      setNoteModalOpen(false)
      void loadData()
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  const openEnrollModal = async () => {
    setEnrollModalOpen(true)
    setSearchLoading(true)
    try {
      const res = await usersApi.getUsers('student', 1, 200)
      setAllStudents(Array.isArray(res) ? res : [])
    } catch (err) {
      console.error(err)
    } finally {
      setSearchLoading(false)
    }
  }

  const filteredEnrollStudents = allStudents.filter(st => {
    const code = (st.studentCode || st.code || '').toUpperCase()
    const name = (st.name || st.fullName || '').toLowerCase()
    const email = (st.email || '').toLowerCase()
    const searchMatch = !enrollForm || name.includes(enrollForm.toLowerCase()) || code.includes(enrollForm.toUpperCase()) || email.includes(enrollForm.toLowerCase())
    if (!searchMatch) return false

    if (cohortFilter !== 'all') {
      const cohortDigits = cohortFilter.replace('K', '')
      if (!code.includes(cohortDigits)) return false
    }

    if (majorFilter !== 'all') {
      if (!code.startsWith(majorFilter)) return false
    }

    return true
  })

  const handleEnroll = async (studentId: string) => {
    if (saving) return
    setSaving(true)
    try {
      await classesApi.enrollStudent(classId, studentId)
      await loadData()
      alert('Đã thêm sinh viên vào lớp thành công!')
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  return (
    <DashboardLayout navItems={ADMIN_NAV} title="AITA Admin" roleLabel="Quản trị viên" requiredRole="admin" headerTitle="Chi tiết lớp học" headerSubtitle="Thành viên, ghi chú và thông tin">
      <div className="space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="outline" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2 className="text-xl font-bold">Chi tiết lớp học {cls?.code || classId}</h2>
            {cls?.subjectName && <p className="text-xs text-slate-500">{cls.subjectCode ? `${cls.subjectCode} - ` : ''}{cls.subjectName}</p>}
          </div>
        </div>

        <ErrorNotice message={error} onRetry={() => void loadData()} />

        {/* Note Display Card */}
        {cls?.note && (
          <div className="p-4 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-sm space-y-1 shadow-2xs">
            <span className="text-xs font-extrabold text-slate-900 dark:text-white flex items-center gap-1.5">
              <Edit3 className="w-3.5 h-3.5 text-[#FA7014]" /> Ghi chú hiện hành của lớp:
            </span>
            <p className="text-xs text-slate-700 dark:text-slate-300 whitespace-pre-wrap">{cls.note}</p>
          </div>
        )}

        {/* Quick Actions */}
        <div className="flex flex-wrap gap-3">
          <Button variant="outline" onClick={() => router.push(`/admin/gradebook?classId=${encodeURIComponent(classId)}`)}>
            <BookOpen className="w-4 h-4 mr-2" /> Bảng điểm học phần
          </Button>
          <Button onClick={openEnrollModal} variant="primary">
            <UserPlus className="w-4 h-4 mr-2" /> Thêm sinh viên vào lớp
          </Button>
          <Button variant="outline" className="rounded-xl font-bold border-slate-200 dark:border-slate-800" onClick={() => { setNoteForm(cls?.note || ''); setNoteModalOpen(true); }}>
            <Edit3 className="w-4 h-4 mr-2" /> Cập nhật ghi chú
          </Button>
        </div>

        {/* Roster */}
        <div className="rounded-xl border border-slate-200 bg-white overflow-hidden shadow-2xs dark:border-slate-800 dark:bg-slate-900">
          <div className="p-5 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center">
            <h3 className="font-extrabold text-slate-900 dark:text-white flex items-center gap-2">
              <Users className="w-5 h-5 text-[#FA7014]" /> Danh sách sinh viên ({students.length})
            </h3>
          </div>
          {loading ? (
            <p className="p-8 text-center text-slate-500 text-sm">Đang tải danh sách...</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left">
                <thead className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-800">
                  <tr>
                    <th className="px-5 py-3.5 text-[11px] font-extrabold text-slate-900 dark:text-slate-200 uppercase tracking-wider">MSSV</th>
                    <th className="px-5 py-3.5 text-[11px] font-extrabold text-slate-900 dark:text-slate-200 uppercase tracking-wider">Họ và tên</th>
                    <th className="px-5 py-3.5 text-[11px] font-extrabold text-slate-900 dark:text-slate-200 uppercase tracking-wider">Email</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                  {students.map(st => (
                    <tr key={st.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                      <td className="px-5 py-3.5 font-mono font-bold text-slate-900 dark:text-white text-xs">{(st as any).studentCode || (st as any).studentId || 'N/A'}</td>
                      <td className="px-5 py-3.5 font-bold text-slate-900 dark:text-white text-xs">{st.name}</td>
                      <td className="px-5 py-3.5 text-slate-600 dark:text-slate-400 text-xs font-mono">{st.email}</td>
                    </tr>
                  ))}
                  {students.length === 0 && (
                    <tr><td colSpan={3} className="px-5 py-8 text-center text-slate-500 text-xs">Lớp chưa có sinh viên nào.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {/* Note Modal */}
      <Modal isOpen={noteModalOpen} onClose={() => setNoteModalOpen(false)} title="Cập nhật ghi chú">
        <form onSubmit={handleUpdateNote} className="space-y-4">
          <label className="block space-y-2">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ghi chú lớp học</span>
            <textarea
              className="w-full rounded-xl border border-slate-200 bg-white p-3 text-xs dark:border-slate-800 dark:bg-slate-900 min-h-[100px] focus:outline-none focus:border-[#FA7014]"
              value={noteForm}
              onChange={e => setNoteForm(e.target.value)}
              placeholder="Nhập ghi chú cho lớp học này..."
            />
          </label>
          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={() => setNoteModalOpen(false)} className="rounded-xl font-bold border-slate-200 dark:border-slate-800">Hủy</Button>
            <Button type="submit" variant="primary" isLoading={saving}>Lưu ghi chú</Button>
          </div>
        </form>
      </Modal>

      {/* Enroll Modal */}
      <Modal 
        isOpen={enrollModalOpen} 
        onClose={() => setEnrollModalOpen(false)} 
        title="Thêm sinh viên vào lớp học"
        description="Lọc sinh viên toàn trường theo Khóa và Ngành để thêm vào danh sách lớp"
        maxWidth="3xl"
      >
        <div className="space-y-4">
          {/* Filters row */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
            <select
              className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs font-medium focus:border-[#FA7014]"
              value={cohortFilter}
              onChange={e => setCohortFilter(e.target.value)}
            >
              <option value="all">Tất cả Khóa</option>
              <option value="K17">Khóa K17</option>
              <option value="K18">Khóa K18</option>
              <option value="K19">Khóa K19</option>
            </select>

            <select
              className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs font-medium focus:border-[#FA7014]"
              value={majorFilter}
              onChange={e => setMajorFilter(e.target.value)}
            >
              <option value="all">Tất cả Ngành</option>
              <option value="SE">SE - Kỹ thuật phần mềm</option>
              <option value="IA">IA - An toàn thông tin</option>
              <option value="AI">AI - Trí tuệ nhân tạo</option>
              <option value="IS">IS - Hệ thống thông tin</option>
              <option value="GD">GD - Thiết kế đồ họa</option>
            </select>

            <Input 
              placeholder="Tìm theo MSSV hoặc Tên..." 
              value={enrollForm} 
              onChange={e => setEnrollForm(e.target.value)}
              className="text-xs h-9 rounded-xl border-slate-200 dark:border-slate-800 focus:border-[#FA7014]"
            />
          </div>

          <div className="text-[11px] text-slate-600 dark:text-slate-400 flex items-center justify-between">
            <span>Tìm thấy {filteredEnrollStudents.length} sinh viên</span>
            <span className="text-[#FA7014] font-bold">Lớp hiện tại: {students.length} SV</span>
          </div>

          <div className="max-h-80 overflow-y-auto border border-slate-200 rounded-xl dark:border-slate-800 divide-y divide-slate-100 dark:divide-slate-800 bg-white dark:bg-slate-900">
            {searchLoading ? (
              <p className="p-6 text-center text-xs text-slate-400">Đang tải danh sách sinh viên...</p>
            ) : filteredEnrollStudents.length === 0 ? (
              <p className="p-6 text-center text-xs text-slate-400">Không tìm thấy sinh viên nào phù hợp bộ lọc.</p>
            ) : (
              filteredEnrollStudents.map(user => {
                const isAlreadyIn = students.some(s => s.id === user.id || (s as any).studentId === user.id)
                const uCode = (user.studentCode || user.code || '').toUpperCase()

                return (
                  <div key={user.id} className="p-3 flex justify-between items-center hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                    <div className="min-w-0 pr-3">
                      <div className="flex items-center gap-2">
                        <p className="font-bold text-xs text-slate-900 dark:text-white truncate">{user.name || user.fullName}</p>
                        <span className="px-1.5 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700">
                          {uCode || 'SV'}
                        </span>
                      </div>
                      <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate">{user.email}</p>
                    </div>

                    {isAlreadyIn ? (
                      <span className="text-[11px] font-bold text-emerald-600 bg-emerald-50 dark:bg-emerald-950/40 px-2 py-1 rounded-md shrink-0">
                        ✓ Đã trong lớp
                      </span>
                    ) : (
                      <Button size="sm" onClick={() => handleEnroll(user.id)} disabled={saving} variant="primary" className="text-xs shrink-0">
                        Thêm vào lớp
                      </Button>
                    )}
                  </div>
                )
              })
            )}
          </div>
        </div>
      </Modal>

    </DashboardLayout>
  )
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { ADMIN_NAV } from '@/config/navigation'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Modal } from '@/components/ui/modal'
import { ErrorNotice, Pagination } from '@/components/ui/feedback'
import { classesApi } from '@/lib/api/modules/classes'
import { subjectsApi } from '@/lib/api/modules/subjects'
import { semestersApi } from '@/lib/api/modules/semesters'
import { usersApi } from '@/lib/api/modules/users'
import { errorMessage } from '@/lib/api/errors'
import type { ClassRow, CreateClassBody, SemesterRow, SubjectRow, UserRow } from '@/lib/api/contracts'
import { useAuth } from '@/providers/auth-provider'
import { useLanguage } from '@/providers/language-provider'
import Link from 'next/link'
import { ExternalLink, GraduationCap, Users, BookOpen, Calendar, Sparkles, School, RefreshCw } from 'lucide-react'

const blankForm = { code: '', subjectId: '', semesterId: '', lecturerId: '' }
const selectStyle = 'w-full rounded-xl border border-slate-300 bg-white p-2.5 text-xs dark:border-slate-700 dark:bg-slate-900 focus:outline-none focus:border-[#FA7014]'

// Selectors require available IDs; the class list remains server-paginated.
async function loadOptions<T>(fetchPage: (page: number, limit: number) => Promise<T[]>): Promise<T[]> {
  const rows: T[] = []
  for (let page = 1; ; page++) {
    const batch = await fetchPage(page, 50)
    rows.push(...batch)
    if (batch.length < 50) return rows
  }
}

export default function AdminClassesPage() {
  const { isAuthenticated, role } = useAuth()
  const { t } = useLanguage()
  const [classes, setClasses] = useState<ClassRow[]>([])
  const [subjects, setSubjects] = useState<SubjectRow[]>([])
  const [semesters, setSemesters] = useState<SemesterRow[]>([])
  const [lecturers, setLecturers] = useState<UserRow[]>([])
  const [allStudents, setAllStudents] = useState<any[]>([])
  const [selectedStudentIds, setSelectedStudentIds] = useState<Set<string>>(new Set())
  const [studentCohortFilter, setStudentCohortFilter] = useState('all')
  const [studentMajorFilter, setStudentMajorFilter] = useState('all')
  const [studentSearch, setStudentSearch] = useState('')

  const [page, setPage] = useState(1)
  const [search, setSearch] = useState('')
  const [hasNext, setHasNext] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [formError, setFormError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const [optionsLoading, setOptionsLoading] = useState(false)
  const [modalOpen, setModalOpen] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [form, setForm] = useState(blankForm)
  const sequence = useRef({ value: 0 })

  const loadClasses = useCallback(async () => {
    if (!isAuthenticated || role !== 'admin') return
    const requestId = ++sequence.current.value
    setLoading(true)
    setHasNext(false)
    void classesApi.getClasses(page + 1, 10, search).then(next => {
      if (requestId === sequence.current.value) setHasNext(next.length > 0)
    }).catch(() => {})
    return classesApi.getClasses(page, 10, search).then(rows => {
      if (requestId !== sequence.current.value) return
      setClasses(rows)
      setError(null)
    }).catch(cause => {
      if (requestId === sequence.current.value) setError(errorMessage(cause))
    }).finally(() => {
      if (requestId === sequence.current.value) setLoading(false)
    })
  }, [isAuthenticated, role, page, search])

  useEffect(() => {
    const tracker = sequence.current
    const handler = setTimeout(() => {
      void loadClasses()
    }, 300)
    return () => { tracker.value++; clearTimeout(handler) }
  }, [loadClasses])

  async function openForm(row?: ClassRow) {
    setEditingId(row?.id ?? null)
    setForm(row ? {
      code: row.code,
      subjectId: typeof row.subject === 'object' && row.subject ? row.subject.id : '',
      semesterId: typeof row.semester === 'object' && row.semester ? row.semester.id : '',
      lecturerId: row.lecturers?.[0]?.id ?? '',
    } : blankForm)
    setFormError(null)
    setSelectedStudentIds(new Set())
    setStudentCohortFilter('all')
    setStudentMajorFilter('all')
    setStudentSearch('')
    setModalOpen(true)
    setOptionsLoading(true)
    try {
      const [subjectRows, semesterRows, lecturerRows, studentRows] = await Promise.all([
        loadOptions(subjectsApi.getSubjects),
        semestersApi.getSemesters(),
        usersApi.getUsers('lecturer', 1, 100),
        usersApi.getUsers('student', 1, 200),
      ])
      setSubjects(subjectRows)
      setSemesters(semesterRows)
      setLecturers(lecturerRows)
      setAllStudents(Array.isArray(studentRows) ? studentRows : [])
    } catch (cause) { setFormError(errorMessage(cause)) }
    finally { setOptionsLoading(false) }
  }

  // Filter students based on cohort, major, and search text
  const filteredStudents = allStudents.filter(st => {
    const code = (st.studentCode || st.code || '').toUpperCase()
    const name = (st.name || st.fullName || '').toLowerCase()
    const email = (st.email || '').toLowerCase()
    const searchMatch = !studentSearch || name.includes(studentSearch.toLowerCase()) || code.includes(studentSearch.toUpperCase()) || email.includes(studentSearch.toLowerCase())
    if (!searchMatch) return false

    // Cohort filter (K17, K18, K19...)
    if (studentCohortFilter !== 'all') {
      const cohortDigits = studentCohortFilter.replace('K', '')
      if (!code.includes(cohortDigits)) return false
    }

    // Major filter (SE, IA, AI, IS, GD...)
    if (studentMajorFilter !== 'all') {
      if (!code.startsWith(studentMajorFilter)) return false
    }

    return true
  })

  const toggleStudent = (id: string) => {
    setSelectedStudentIds(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const selectAllFilteredStudents = () => {
    setSelectedStudentIds(prev => {
      const next = new Set(prev)
      filteredStudents.forEach(st => next.add(st.id))
      return next
    })
  }

  const clearAllSelectedStudents = () => {
    setSelectedStudentIds(new Set())
  }

  async function submit(event: React.FormEvent) {
    event.preventDefault()
    if (saving || optionsLoading) return
    setSaving(true)
    setFormError(null)
    const payload: CreateClassBody = {
      code: form.code.trim(),
      subjectId: form.subjectId,
      ...(form.semesterId ? { semesterId: form.semesterId } : {}),
      ...(form.lecturerId ? { lecturerId: form.lecturerId } : {}),
      studentIds: Array.from(selectedStudentIds),
    }
    try {
      if (editingId) {
        await classesApi.updateClass(editingId, { ...payload, keepExistingInstructors: false })
        // If editing and selected students to add
        if (selectedStudentIds.size > 0) {
          for (const sId of selectedStudentIds) {
            try { await classesApi.enrollStudent(editingId, sId) } catch { /* ignore duplicate */ }
          }
        }
      } else {
        await classesApi.createClass(payload)
      }
      setModalOpen(false)
      await loadClasses()
    } catch (cause) { setFormError(errorMessage(cause)) }
    finally { setSaving(false) }
  }

  async function deleteClass(row: ClassRow) {
    if (!window.confirm(t('admin.classes.confirm_delete', 'Xóa lớp {{code}}?').replace('{{code}}', row.code))) return
    setSaving(true)
    try {
      await classesApi.deleteClass(row.id)
      if (classes.length === 1 && page > 1) setPage(page - 1)
      else await loadClasses()
    } catch (cause) { setError(errorMessage(cause)) }
    finally { setSaving(false) }
  }

  // Derived statistics for executive KPI cards
  const totalClassesCount = classes.length
  const assignedLecturerCount = classes.filter(c => c.lecturers && c.lecturers.length > 0).length
  const totalStudentsEnrolled = classes.reduce((sum, c) => sum + (c.studentCount ?? 0), 0)

  return (
    <DashboardLayout
      navItems={ADMIN_NAV}
      title="AITA Admin"
      roleLabel={t('profile.role_admin', 'Quản trị viên')}
      requiredRole="admin"
      headerTitle={t('admin.classes.title', 'Quản lý lớp học phần')}
      headerSubtitle={t('admin.classes.subtitle', 'Môn học, học kỳ và phân công giảng viên')}
    >
      <div className="space-y-6 w-full pb-12">
        {/* ── 1. SIGNATURE EXECUTIVE KPI CARDS ── */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* KPI 1: Tổng số lớp */}
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Tổng Lớp Học Phần
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <BookOpen className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">
              {loading ? '…' : totalClassesCount}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Đang mở trong kỳ hiện tại</span>
            </div>
          </div>

          {/* KPI 2: Đã phân công giảng viên */}
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Đã Gán Giảng Viên
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <School className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">
              {loading ? '…' : assignedLecturerCount}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>{Math.round((assignedLecturerCount / (totalClassesCount || 1)) * 100)}% lớp có GV đứng lớp</span>
            </div>
          </div>

          {/* KPI 3: Sinh viên ghi danh */}
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Lượt Ghi Danh SV
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <Users className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">
              {loading ? '…' : totalStudentsEnrolled}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Sinh viên đã vào lớp</span>
            </div>
          </div>

          {/* KPI 4: Học kỳ áp dụng */}
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Học Kỳ Triển Khai
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <Calendar className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">
              {semesters.length || 1}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Spring / Summer / Fall</span>
            </div>
          </div>
        </div>

        {/* ── 2. TOOLBAR: SEARCH & ACTIONS ── */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
          <div>
            <h2 className="text-base font-extrabold text-slate-900 dark:text-white">
              {t('admin.classes.list_title', 'Danh sách lớp học phần')}
            </h2>
            <p className="text-xs text-slate-600 dark:text-slate-400">
              Quản lý phân công giảng viên, danh sách sinh viên theo lớp
            </p>
          </div>
          <div className="flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
            <Input 
              placeholder={t('admin.classes.search_placeholder', 'Tìm kiếm mã lớp, môn học...')} 
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(1); }}
              className="w-full sm:w-64 text-xs focus:ring-2 focus:ring-orange-400/25 focus:border-orange-400 rounded-xl border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900"
            />
            <Button
              onClick={() => void openForm()}
              className="shrink-0 bg-gradient-to-r from-orange-500 via-amber-500 to-orange-500 hover:from-orange-600 hover:via-amber-600 hover:to-orange-600 shadow-orange-500/25 text-white font-bold rounded-2xl h-10 px-5 text-xs cursor-pointer shadow-md active:scale-95 transition-all"
            >
              <Sparkles className="w-4 h-4 mr-1.5" />
              {t('admin.classes.open_new', 'Mở lớp mới')}
            </Button>
          </div>
        </div>

        <ErrorNotice message={error} onRetry={() => void loadClasses()} />

        {/* ── 3. CLASSES DATA TABLE ── */}
        <Card className="rounded-2xl bg-white dark:bg-slate-900 shadow-xs overflow-hidden border border-slate-200/80 dark:border-slate-800">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b text-[11px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400 border-slate-200/80 dark:border-slate-800 bg-slate-50/75 dark:bg-slate-800/50">
                  <th className="py-3.5 pl-5 pr-3">Mã lớp học</th>
                  <th className="py-3.5 px-3">Học kỳ</th>
                  <th className="py-3.5 px-3">Môn học</th>
                  <th className="py-3.5 px-3">Giảng viên phụ trách</th>
                  <th className="py-3.5 px-3">Sĩ số</th>
                  <th className="py-3.5 pl-3 pr-5 text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60 text-xs">
                {loading ? (
                  <tr>
                    <td colSpan={6} className="py-16 text-center text-slate-400">
                      <div className="inline-flex items-center gap-2">
                        <RefreshCw className="w-4 h-4 animate-spin text-slate-500" />
                        <span>{t('admin.classes.loading', 'Đang tải danh sách lớp học…')}</span>
                      </div>
                    </td>
                  </tr>
                ) : !error && classes.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="py-16 text-center text-slate-400">
                      <div className="flex flex-col items-center justify-center gap-2">
                        <School className="w-8 h-8 text-slate-300 dark:text-slate-600" />
                        <p className="font-semibold text-slate-600 dark:text-slate-300">
                          {t('admin.classes.no_classes', 'Chưa có lớp học ở trang này.')}
                        </p>
                      </div>
                    </td>
                  </tr>
                ) : !error && classes.map(row => {
                  const semesterCode = typeof row.semester === 'object' ? (row.semester as any)?.season || (row.semester as any)?.code : row.semester || '—'
                  const subjectTitle = typeof row.subject === 'object' ? `${row.subject?.code} — ${row.subject?.name}` : row.subject || t('admin.classes.no_subject', 'Chưa có môn học')
                  const lecturerNames = row.lecturers?.map(l => l.name).join(', ')

                  return (
                    <tr
                      key={row.id}
                      className="group transition-colors hover:bg-slate-50/70 dark:hover:bg-slate-800/40"
                    >
                      {/* Cột 1: Mã lớp */}
                      <td className="py-3.5 pl-5 pr-3">
                        <Link
                          href={`/admin/classes/${row.id}`}
                          className="font-mono font-bold text-xs text-slate-900 dark:text-white hover:text-blue-600 dark:hover:text-blue-400 inline-flex items-center gap-1.5 transition-colors"
                        >
                          <span>{row.code}</span>
                          <ExternalLink className="w-3 h-3 text-slate-400 group-hover:text-blue-500 transition-colors" />
                        </Link>
                      </td>

                      {/* Cột 2: Học kỳ */}
                      <td className="py-3.5 px-3">
                        <span className="font-mono text-[11px] font-semibold px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 inline-block">
                          {semesterCode}
                        </span>
                      </td>

                      {/* Cột 3: Môn học */}
                      <td className="py-3.5 px-3">
                        <span className="font-medium text-slate-800 dark:text-slate-200">
                          {subjectTitle}
                        </span>
                      </td>

                      {/* Cột 4: Giảng viên phụ trách */}
                      <td className="py-3.5 px-3">
                        {lecturerNames ? (
                          <div className="flex items-center gap-2">
                            <div className="w-6 h-6 rounded-md bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-500 dark:text-slate-400 shrink-0">
                              <School className="w-3.5 h-3.5" />
                            </div>
                            <span className="font-medium text-slate-800 dark:text-slate-200">
                              {lecturerNames}
                            </span>
                          </div>
                        ) : (
                          <span className="text-[11px] font-medium px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800/80 text-slate-500 dark:text-slate-400 border border-slate-200/80 dark:border-slate-700 inline-flex items-center gap-1.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-slate-400" />
                            Chưa phân công giảng viên
                          </span>
                        )}
                      </td>

                      {/* Cột 5: Sĩ số */}
                      <td className="py-3.5 px-3">
                        <div className="inline-flex items-center gap-1.5 text-slate-700 dark:text-slate-300 font-medium">
                          <Users className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                          <span>{row.studentCount ?? 0} sinh viên</span>
                        </div>
                      </td>

                      {/* Cột 6: Thao tác */}
                      <td className="py-3.5 pl-3 pr-5 text-right">
                        <div className="flex items-center justify-end gap-1.5">
                          <Button
                            variant="outline"
                            size="sm"
                            disabled={saving}
                            onClick={() => void openForm(row)}
                            className="text-xs h-7 px-2.5 border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-200 rounded-lg cursor-pointer font-medium"
                          >
                            {t('ui.edit', 'Chỉnh sửa')}
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            disabled={saving}
                            onClick={() => void deleteClass(row)}
                            className="text-xs h-7 px-2.5 text-rose-600 hover:text-rose-700 hover:bg-rose-50 dark:hover:bg-rose-950/40 rounded-lg cursor-pointer font-medium"
                          >
                            {t('ui.delete', 'Xóa')}
                          </Button>
                        </div>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
          <div className="p-3 border-t border-slate-100 dark:border-slate-800 flex justify-end">
            <Pagination page={page} hasNext={hasNext} loading={loading || saving} onChange={next => { setLoading(true); setPage(next) }} />
          </div>
        </Card>
      </div>
    {(() => {
      const selectedSubject = subjects.find(s => s.id === form.subjectId)
      const selectedSemester = semesters.find(s => s.id === form.semesterId)
      const selectedLecturer = lecturers.find(l => l.id === form.lecturerId)

      return (
        <Modal
          isOpen={modalOpen}
          onClose={() => { if (!saving) setModalOpen(false) }}
          maxWidth="5xl"
          title={
            <div className="flex items-center gap-2">
              <span className="p-1.5 rounded-lg bg-orange-50 text-[#FA7014] dark:bg-orange-950/60 dark:text-orange-400 border border-orange-200">
                <GraduationCap className="w-5 h-5" />
              </span>
              <span className="font-extrabold text-slate-900 dark:text-white">{editingId ? t('admin.classes.edit_modal_title', 'Chỉnh sửa lớp học & Phân công') : t('admin.classes.modal_title', 'Mở lớp học mới & Phân công Giảng viên')}</span>
            </div>
          }
          description="Thiết lập mã lớp, môn học, phân công giảng viên và thêm sinh viên theo Khóa & Ngành"
        >
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
            {/* Form Column (7 cols) */}
            <form onSubmit={submit} className="lg:col-span-7 space-y-4">
              <ErrorNotice message={formError} />
              {optionsLoading && <p role="status" className="text-xs text-[#FA7014] font-semibold">{t('admin.classes.loading_options', 'Đang tải môn, kỳ, giảng viên và sinh viên…')}</p>}
              
              <div className="grid grid-cols-2 gap-3">
                <label className="block space-y-1">
                  <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">{t('admin.classes.form_code', 'Mã lớp học')}</span>
                  <Input required minLength={2} placeholder="Ví dụ: PRM392_SE1701" value={form.code} onChange={e => setForm({ ...form, code: e.target.value })} className="text-xs focus:border-[#FA7014] rounded-xl border-slate-200 dark:border-slate-800" />
                </label>

                <label className="block space-y-1">
                  <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">{t('admin.classes.col_semester', 'Học kỳ')}</span>
                  <select aria-label={t('admin.classes.col_semester', 'Học kỳ')} disabled={optionsLoading || saving} className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-2.5 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:border-[#FA7014]" value={form.semesterId} onChange={e => setForm({ ...form, semesterId: e.target.value })}>
                    <option value="" disabled={!!editingId && !!form.semesterId}>{t('admin.classes.select_semester', 'Chọn học kỳ')}</option>
                    {semesters.map(semester => <option key={semester.id} value={semester.id}>{semester.season} {semester.code}</option>)}
                  </select>
                </label>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <label className="block space-y-1">
                  <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">{t('admin.classes.form_subject', 'Môn học')}</span>
                  <select aria-label={t('admin.classes.form_subject', 'Môn học')} required disabled={optionsLoading || saving} className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-2.5 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:border-[#FA7014]" value={form.subjectId} onChange={e => setForm({ ...form, subjectId: e.target.value })}>
                    <option value="">{t('admin.classes.select_subject', 'Chọn môn học')}</option>
                    {subjects.map(subject => <option key={subject.id} value={subject.id}>{subject.code} — {subject.name}</option>)}
                  </select>
                </label>

                <label className="block space-y-1">
                  <span className="text-xs font-semibold text-slate-900 dark:text-slate-200 flex items-center justify-between">
                    <span>{t('admin.classes.lecturer', 'Giảng viên phụ trách')}</span>
                    <span className="text-[10px] text-[#FA7014] font-bold">FPT Faculty</span>
                  </span>
                  <select aria-label={t('admin.classes.lecturer', 'Giảng viên')} disabled={optionsLoading || saving} className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-2.5 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:border-[#FA7014]" value={form.lecturerId} onChange={e => setForm({ ...form, lecturerId: e.target.value })}>
                    <option value="">-- Chưa chỉ định giảng viên --</option>
                    {lecturers.map(lecturer => (
                      <option key={lecturer.id} value={lecturer.id}>
                        {lecturer.lecturerCode ? `[${lecturer.lecturerCode}] ` : ''}{lecturer.name} ({lecturer.email})
                      </option>
                    ))}
                  </select>
                </label>
              </div>

              {/* ── BỘ CHỌN SINH VIÊN THEO KHÓA & NGÀNH ── */}
              <div className="pt-2 border-t border-slate-200 dark:border-slate-800 space-y-2.5">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-1.5">
                    <Users className="w-4 h-4 text-[#FA7014]" />
                    <span className="text-xs font-bold text-slate-900 dark:text-white">
                      Thêm sinh viên vào lớp theo Khóa & Ngành
                    </span>
                  </div>
                  <span className="text-xs font-mono font-bold text-slate-900 dark:text-white bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-lg border border-slate-200 dark:border-slate-700">
                    Đã chọn: {selectedStudentIds.size} SV
                  </span>
                </div>

                {/* Filter controls row */}
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 text-xs">
                  {/* Cohort Filter */}
                  <select
                    className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs font-medium focus:border-[#FA7014]"
                    value={studentCohortFilter}
                    onChange={e => setStudentCohortFilter(e.target.value)}
                  >
                    <option value="all">Tất cả Khóa (K17, K18, K19)</option>
                    <option value="K17">Khóa K17</option>
                    <option value="K18">Khóa K18</option>
                    <option value="K19">Khóa K19</option>
                  </select>

                  {/* Major Filter */}
                  <select
                    className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs font-medium focus:border-[#FA7014]"
                    value={studentMajorFilter}
                    onChange={e => setStudentMajorFilter(e.target.value)}
                  >
                    <option value="all">Tất cả Ngành</option>
                    <option value="SE">SE - Kỹ thuật phần mềm</option>
                    <option value="IA">IA - An toàn thông tin</option>
                    <option value="AI">AI - Trí tuệ nhân tạo</option>
                    <option value="IS">IS - Hệ thống thông tin</option>
                    <option value="GD">GD - Thiết kế đồ họa</option>
                  </select>

                  {/* Student Search */}
                  <Input
                    placeholder="Tìm tên hoặc MSSV..."
                    value={studentSearch}
                    onChange={e => setStudentSearch(e.target.value)}
                    className="text-xs p-2 h-9 focus:border-[#FA7014] rounded-xl border-slate-200 dark:border-slate-800"
                  />
                </div>

                {/* Quick actions row */}
                <div className="flex items-center justify-between text-[11px] pt-1">
                  <span className="text-slate-500">
                    Hiển thị {filteredStudents.length} sinh viên phù hợp
                  </span>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={selectAllFilteredStudents}
                      className="text-[#FA7014] hover:underline font-bold cursor-pointer"
                    >
                      Chọn tất cả ({filteredStudents.length})
                    </button>
                    <span className="text-slate-300">|</span>
                    <button
                      type="button"
                      onClick={clearAllSelectedStudents}
                      className="text-slate-500 hover:text-slate-700 font-semibold cursor-pointer"
                    >
                      Bỏ chọn tất cả
                    </button>
                  </div>
                </div>

                {/* Student Scrollable List */}
                <div className="max-h-72 overflow-y-auto rounded-xl border border-slate-200 dark:border-slate-800 divide-y divide-slate-100 dark:divide-slate-800 bg-white dark:bg-slate-900 p-1">
                  {filteredStudents.length === 0 ? (
                    <div className="p-4 text-center text-xs text-slate-400">
                      Không có sinh viên nào phù hợp bộ lọc.
                    </div>
                  ) : (
                    filteredStudents.map(st => {
                      const isSelected = selectedStudentIds.has(st.id)
                      const stCode = (st.studentCode || st.code || '').toUpperCase()

                      return (
                        <div
                          key={st.id}
                          onClick={() => toggleStudent(st.id)}
                          className={`flex items-center justify-between p-2 rounded-xl text-xs cursor-pointer transition-colors ${
                            isSelected
                              ? 'bg-orange-50/70 dark:bg-orange-950/30'
                              : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'
                          }`}
                        >
                          <div className="flex items-center gap-2.5 min-w-0">
                            <input
                              type="checkbox"
                              checked={isSelected}
                              onChange={() => toggleStudent(st.id)}
                              className="w-4 h-4 rounded text-[#FA7014] focus:ring-[#FA7014] cursor-pointer"
                              onClick={e => e.stopPropagation()}
                            />
                            <div className="min-w-0">
                              <div className="flex items-center gap-1.5">
                                <span className="font-bold text-slate-900 dark:text-white truncate">
                                  {st.name || st.fullName}
                                </span>
                                <span className="px-1.5 py-0.2 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700">
                                  {stCode}
                                </span>
                              </div>
                              <span className="text-[11px] text-slate-400 truncate block">
                                {st.email}
                              </span>
                            </div>
                          </div>

                          <div className="flex items-center gap-1.5 shrink-0">
                            {stCode.startsWith('SE') && <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200">SE</span>}
                            {stCode.startsWith('IA') && <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-rose-50 text-rose-600">IA</span>}
                            {stCode.startsWith('AI') && <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-purple-50 text-purple-600">AI</span>}
                            {stCode.startsWith('IS') && <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-amber-50 text-amber-600">IS</span>}
                            {stCode.startsWith('GD') && <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-emerald-50 text-emerald-600">GD</span>}
                          </div>
                        </div>
                      )
                    })
                  )}
                </div>
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-slate-100 dark:border-slate-800">
                <Button type="button" variant="ghost" disabled={saving} onClick={() => setModalOpen(false)} className="rounded-xl font-bold">{t('ui.cancel', 'Hủy')}</Button>
                <Button type="submit" variant="primary" disabled={saving || optionsLoading || !form.subjectId}>
                  {saving ? t('ui.saving', 'Đang lưu…') : (
                    selectedStudentIds.size > 0 
                      ? `Lưu lớp & Thêm ${selectedStudentIds.size} SV` 
                      : t('admin.classes.form_submit', 'Lưu lớp học')
                  )}
                </Button>
              </div>
            </form>

            {/* Live Class Card Preview Column (5 cols) */}
            <div className="lg:col-span-5 bg-slate-50 dark:bg-slate-800/40 p-4 rounded-xl border border-slate-200 dark:border-slate-800 space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-extrabold tracking-wider text-slate-900 dark:text-white uppercase flex items-center gap-1.5">
                  <BookOpen className="w-3.5 h-3.5 text-[#FA7014]" />
                  Thẻ Lớp Học Trực Quan
                </span>
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                  Live View
                </span>
              </div>

              {/* Class Card */}
              <div className="rounded-xl overflow-hidden border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-2xs">
                <div className="p-4 bg-[#FA7014] text-white relative">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-white/90">Lớp Học FPT</span>
                    <span className="px-2 py-0.5 rounded-md bg-white/20 text-white text-[10px] font-bold backdrop-blur-sm">
                      {selectedSemester ? `${selectedSemester.season} ${selectedSemester.code}` : 'Học kỳ chưa chọn'}
                    </span>
                  </div>
                  <h3 className="text-xl font-black tracking-tight text-white mt-2 font-mono">
                    {form.code.trim() || 'CLASS_CODE'}
                  </h3>
                </div>

                <div className="p-4 space-y-3">
                  <div>
                    <p className="text-[10px] uppercase font-semibold text-slate-500">Môn học phụ trách</p>
                    <p className="text-sm font-bold text-slate-900 dark:text-white mt-0.5">
                      {selectedSubject ? `${selectedSubject.code} — ${selectedSubject.name}` : 'Chưa chọn môn học'}
                    </p>
                  </div>

                  <div className="pt-2 border-t border-slate-100 dark:border-slate-800">
                    <p className="text-[10px] uppercase font-semibold text-slate-500">Giảng viên đứng lớp</p>
                    <div className="flex items-center gap-2.5 mt-1.5">
                      <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 flex items-center justify-center font-bold text-xs">
                        {selectedLecturer ? selectedLecturer.name.charAt(0) : <School className="w-4 h-4" />}
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="text-xs font-semibold text-slate-900 dark:text-white truncate">
                          {selectedLecturer ? selectedLecturer.name : 'Chưa phân công giảng viên'}
                        </p>
                        <p className="text-[10px] text-slate-500 truncate">
                          {selectedLecturer ? selectedLecturer.email : 'Sẽ chỉ định sau khi mở lớp'}
                        </p>
                      </div>
                    </div>
                  </div>

                  <div className="pt-2 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs">
                    <span className="flex items-center gap-1 font-semibold text-slate-900 dark:text-slate-200">
                      <Users className="w-3.5 h-3.5 text-[#FA7014]" />
                      Sĩ số: {selectedStudentIds.size} sinh viên
                    </span>
                    <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-50 text-emerald-600 dark:bg-emerald-950/40 dark:text-emerald-300">
                      Sẵn sàng kích hoạt
                    </span>
                  </div>
                </div>
              </div>

              {/* Selected Students Preview Chips */}
              {selectedStudentIds.size > 0 && (
                <div className="p-3 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 space-y-1.5">
                  <span className="text-[11px] font-bold text-slate-900 dark:text-white block">
                    Sinh viên được chọn đưa vào lớp ({selectedStudentIds.size}):
                  </span>
                  <div className="flex flex-wrap gap-1 max-h-24 overflow-y-auto">
                    {Array.from(selectedStudentIds).slice(0, 10).map(sId => {
                      const st = allStudents.find(s => s.id === sId)
                      return (
                        <span key={sId} className="px-2 py-0.5 rounded-md text-[10px] font-mono bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-slate-200">
                          {st?.studentCode || st?.code || 'SV'}: {st?.name || st?.fullName || ''}
                        </span>
                      )
                    })}
                    {selectedStudentIds.size > 10 && (
                      <span className="px-2 py-0.5 rounded-md text-[10px] font-bold text-[#FA7014]">
                        +{selectedStudentIds.size - 10} SV khác
                      </span>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </Modal>
      )
    })()}
    </DashboardLayout>
  )
}

'use client'

import * as React from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { LECTURER_NAV } from '@/config/navigation'
import { useLanguage } from '@/providers/language-provider'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Modal } from '@/components/ui/modal'
import { classesApi } from '@/lib/api/modules/classes'
import { assignmentsApi } from '@/lib/api/modules/assignments'
import { submissionsApi } from '@/lib/api/modules/submissions'
import {
  ArrowLeft, BookOpen, Clock, FileText, CheckCircle2, Users, FileEdit,
  GraduationCap, XCircle, Megaphone, Plus, Pencil, Trash2, Loader2, Bell, Download
} from 'lucide-react'

type TabId = 'assignments' | 'roster' | 'announcements'

export default function LecturerClassDetailPage() {
  const params = useParams()
  const router = useRouter()
  const classId = (params?.id as string) || ''
  const { t } = useLanguage()

  const [classData, setClassData] = React.useState<any>(null)
  const [students, setStudents] = React.useState<any[]>([])
  const [assignments, setAssignments] = React.useState<any[]>([])
  const [announcements, setAnnouncements] = React.useState<any[]>([])
  const [loading, setLoading] = React.useState(true)
  const [rosterLoading, setRosterLoading] = React.useState(true)
  const [activeTab, setActiveTab] = React.useState<TabId>('assignments')

  // Announcement form state
  const [annModal, setAnnModal] = React.useState(false)
  const [annEditId, setAnnEditId] = React.useState<string | null>(null)
  const [annForm, setAnnForm] = React.useState({ title: '', content: '' })
  const [annSaving, setAnnSaving] = React.useState(false)

  const loadAnnouncements = React.useCallback(async () => {
    try {
      const res = await classesApi.getClassAnnouncements(classId)
      setAnnouncements(Array.isArray(res) ? res : [])
    } catch { setAnnouncements([]) }
  }, [classId])

  React.useEffect(() => {
    if (!classId) return
    let cancelled = false
    setLoading(true)
    setRosterLoading(true)
    const assignmentsRequest = assignmentsApi.getAssignments({ classId }).then(rows => rows.filter((a: any) =>
      a.classId === classId || a.class?.id === classId ||
      (Array.isArray(a.classIds) && a.classIds.includes(classId)) ||
      (Array.isArray(a.classes) && a.classes.some((c: any) => typeof c === 'string' ? c === classId : c?.id === classId))
    )).catch(() => [])
    void Promise.all([
      classesApi.getClassDetail(classId).catch(() => null),
      assignmentsRequest,
    ]).then(([currentClass, rows]) => {
      if (cancelled) return
      setClassData(currentClass)
      setAssignments(rows)
    }).finally(() => { if (!cancelled) setLoading(false) })
    void classesApi.getClassAnnouncements(classId).then(rows => {
      if (!cancelled) setAnnouncements(Array.isArray(rows) ? rows : [])
    }).catch(() => {})
    void Promise.all([
      classesApi.getClassStudents(classId).catch(() => []),
      submissionsApi.getSubmissions({ classId, view: 'summary' }).catch(() => []),
      assignmentsRequest,
    ]).then(([studentsData, submissions, filteredAssignments]) => {
      if (cancelled) return
      const submissionIndex = new Map<string, any>()
      for (const sub of submissions) {
        const id = sub.assignmentId || sub.examId
        if (!id) continue
        const key = `${id}:${String(sub.studentId).toLowerCase()}`
        if (!submissionIndex.has(key)) submissionIndex.set(key, sub)
      }
      const rawStudents = Array.isArray(studentsData) ? studentsData : []
      const studentsWithGrades = rawStudents.map((s: any) => {
        const studentSubs: Record<string, any> = {}
        let totalScore = 0, submitCount = 0
        filteredAssignments.forEach((a: any) => {
          const sCode = String(s.studentId || s.studentCode || '').toLowerCase()
          const sUserId = String(s.id || s.userId || '').toLowerCase()
          const mySub = submissionIndex.get(`${a.id}:${sCode}`) || submissionIndex.get(`${a.id}:${sUserId}`)
          studentSubs[a.id] = mySub
          if (mySub) {
            submitCount++
            totalScore += Number(mySub.score ?? mySub.finalScore ?? mySub.totalScore ?? 0)
          }
        })
        return { ...s, submissions: studentSubs, submitCount, avgScore: submitCount > 0 ? (totalScore / submitCount).toFixed(1) : '-' }
      })
      setStudents(studentsWithGrades)
    }).finally(() => { if (!cancelled) setRosterLoading(false) })
    return () => { cancelled = true }
  }, [classId])

  const handleExportGradebookCSV = () => {
    if (!students || students.length === 0) {
      alert('Không có dữ liệu sinh viên để xuất bảng điểm.')
      return
    }
    const headers = ['Mã SV', 'Họ và tên', 'Số bài nộp', 'Điểm trung bình', ...assignments.map((a: any) => `"${(a.title || 'Bài tập').replace(/"/g, '""')}"`)]
    const rows = students.map((s: any) => {
      const row = [
        s.studentId || s.studentCode || '',
        `"${(s.name || s.fullName || '').replace(/"/g, '""')}"`,
        `${s.submitCount}/${assignments.length}`,
        s.avgScore ?? '',
      ]
      assignments.forEach((a: any) => {
        const sub = s.submissions?.[a.id]
        const score = sub ? (sub.score ?? sub.finalScore ?? sub.totalScore ?? 'Đã nộp') : 'Chưa nộp'
        row.push(score)
      })
      return row.join(',')
    })
    const csvContent = [headers.join(','), ...rows].join('\n')
    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.setAttribute('download', `Bang_Diem_${classData?.classCode || classId}_${new Date().toISOString().slice(0, 10)}.csv`)
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }

  async function saveAnnouncement(e: React.FormEvent) {
    e.preventDefault()
    if (!annForm.content.trim()) return
    setAnnSaving(true)
    try {
      if (annEditId) {
        await classesApi.updateClassAnnouncement(classId, annEditId, annForm.content, annForm.title)
      } else {
        await classesApi.postClassAnnouncement(classId, annForm.content, annForm.title)
      }
      setAnnModal(false)
      setAnnForm({ title: '', content: '' })
      setAnnEditId(null)
      await loadAnnouncements()
    } catch (err: any) {
      alert(err?.message || 'Lỗi khi lưu thông báo.')
    } finally { setAnnSaving(false) }
  }

  async function deleteAnnouncement(id: string) {
    if (!confirm('Xóa thông báo này?')) return
    try {
      await classesApi.deleteClassAnnouncement(classId, id)
      await loadAnnouncements()
    } catch (err: any) { alert(err?.message || 'Lỗi.') }
  }

  const tabs: { id: TabId; label: string; icon: React.ElementType; count?: number }[] = [
    { id: 'assignments', label: 'Bài tập', icon: FileText, count: assignments.length },
    { id: 'roster', label: 'Danh sách sinh viên', icon: Users, count: students.length },
    { id: 'announcements', label: 'Thông báo lớp', icon: Megaphone, count: announcements.length },
  ]

  if (loading) {
    return (
      <DashboardLayout navItems={LECTURER_NAV} title="AITA Lecturer" roleLabel="Giảng viên" requiredRole="lecturer">
        <div className="flex flex-col items-center justify-center min-h-[60vh] gap-3">
          <Loader2 className="w-10 h-10 animate-spin text-orange-500" />
          <p className="text-sm text-slate-500">Đang tải thông tin lớp học...</p>
        </div>
      </DashboardLayout>
    )
  }

  if (!classData) {
    return (
      <DashboardLayout navItems={LECTURER_NAV} title="AITA Lecturer" roleLabel="Giảng viên" requiredRole="lecturer">
        <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
          <p className="text-slate-500">Không tìm thấy lớp học.</p>
          <Button variant="outline" onClick={() => router.push('/lecturer/classes')}>Quay lại</Button>
        </div>
      </DashboardLayout>
    )
  }

  return (
    <DashboardLayout
      navItems={LECTURER_NAV}
      title="AITA Lecturer"
      roleLabel="Giảng viên"
      requiredRole="lecturer"
      headerTitle={`${classData.classCode || 'Lớp học'} · ${classData.subject?.code || ''}`}
      headerSubtitle={classData.subject?.name || 'Chi tiết lớp học'}
    >
      <div className="space-y-6 w-full pb-12">
        {/* Top nav */}
        <div className="flex items-center justify-between">
          <Button variant="ghost" size="sm" onClick={() => router.push('/lecturer/classes')} className="gap-2 text-slate-500 hover:text-slate-900 dark:hover:text-white -ml-3">
            <ArrowLeft className="w-4 h-4" />
            Quay lại danh sách lớp
          </Button>
          <Badge variant="orange" className="font-mono">{classData.semester?.season} {classData.semester?.code}</Badge>
        </div>

        {/* Hero card */}
        <div className="rounded-3xl bg-gradient-to-br from-orange-500 to-amber-600 p-6 sm:p-8 text-white shadow-xl shadow-orange-200/40 dark:shadow-orange-900/30">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <span className="px-3 py-1 rounded-lg bg-white/20 text-xs font-bold font-mono">{classData.classCode}</span>
                <span className="px-3 py-1 rounded-lg bg-white/15 text-xs font-bold">{classData.subject?.code}</span>
              </div>
              <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight">{classData.subject?.name || 'Lớp học'}</h1>
            </div>
            <div className="flex gap-6 text-white/90">
              <div className="text-center">
                <p className="text-2xl font-extrabold">{students.length}</p>
                <p className="text-xs opacity-80">Sinh viên</p>
              </div>
              <div className="text-center">
                <p className="text-2xl font-extrabold">{assignments.length}</p>
                <p className="text-xs opacity-80">Bài tập</p>
              </div>
              <div className="text-center">
                <p className="text-2xl font-extrabold">{announcements.length}</p>
                <p className="text-xs opacity-80">Thông báo</p>
              </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 p-1.5 bg-slate-100 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-x-auto">
          {tabs.map(tab => {
            const Icon = tab.icon
            const isActive = activeTab === tab.id
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${
                  isActive
                    ? 'bg-white dark:bg-slate-800 text-orange-600 dark:text-orange-400 shadow-sm'
                    : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-200/50 dark:hover:bg-slate-800/50'
                }`}
              >
                <Icon className={`w-4 h-4 ${isActive ? 'text-orange-500' : 'text-slate-400'}`} />
                {tab.label}
                {tab.count !== undefined && (
                  <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-bold ${isActive ? 'bg-orange-100 dark:bg-orange-950 text-orange-600 dark:text-orange-400' : 'bg-slate-200 dark:bg-slate-700 text-slate-500'}`}>
                    {tab.count}
                  </span>
                )}
              </button>
            )
          })}
        </div>

        {/* Tab: Assignments */}
        {activeTab === 'assignments' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Danh sách bài tập</h3>
              <Link href={`/lecturer/grading/assignments?classId=${classId}`}>
                <Button variant="primary" size="sm" className="gap-1.5 text-xs">
                  <Plus className="w-4 h-4" /> Tạo bài tập
                </Button>
              </Link>
            </div>

            {assignments.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 gap-4 border border-dashed border-slate-200 dark:border-slate-800 rounded-3xl bg-white/50 dark:bg-slate-900/50">
                <FileText className="w-10 h-10 text-slate-300" />
                <p className="text-sm text-slate-400">Lớp học chưa có bài tập nào.</p>
                <Link href={`/lecturer/grading/assignments?classId=${classId}`}>
                  <Button variant="primary" size="sm" className="gap-1.5 text-xs">
                    <Plus className="w-4 h-4" /> Tạo bài tập đầu tiên
                  </Button>
                </Link>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {assignments.map((a: any) => {
                  const isOverdue = a.due ? new Date(a.due) < new Date() : false
                  return (
                    <div key={a.id} className="group p-5 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200/60 dark:border-slate-800 hover:border-orange-500/40 hover:shadow-lg transition-all space-y-3">
                      <div className="flex items-center justify-between">
                        <Badge variant={a.status === 'published' ? 'success' : 'default'} className="text-[10px]">
                          {a.status === 'published' ? 'Đã giao' : 'Bản nháp'}
                        </Badge>
                        {a.type && <span className="text-[10px] text-slate-400 font-mono">{a.type}</span>}
                      </div>
                      <h4 className="font-bold text-sm text-slate-900 dark:text-white line-clamp-2 group-hover:text-orange-500 transition-colors">{a.title}</h4>
                      <div className={`text-xs flex items-center gap-1.5 ${isOverdue ? 'text-rose-500' : 'text-slate-400'}`}>
                        <Clock className="w-3.5 h-3.5" />
                        <span>{a.due ? new Date(a.due).toLocaleDateString('vi-VN') : 'Không có hạn'}</span>
                        {isOverdue && <span className="font-semibold">· Đã quá hạn</span>}
                      </div>
                      <div className="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">
                        <span className="text-xs text-slate-500">Điểm tối đa: <strong className="text-orange-500">{a.maxScore || 10}</strong></span>
                        <Link href={`/lecturer/assignments/${a.id}`}>
                          <Button size="sm" variant="primary" className="text-xs gap-1.5 h-8">
                            <FileEdit className="w-3.5 h-3.5" /> Workspace
                          </Button>
                        </Link>
                      </div>
                    </div>
                  )
                })}
              </div>
            )}
          </div>
        )}

        {/* Tab: Roster */}
        {activeTab === 'roster' && (
          <div className="space-y-4">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Sinh viên & Tiến độ ({students.length})</h3>
              {!rosterLoading && students.length > 0 && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleExportGradebookCSV}
                  className="gap-1.5 text-xs self-start sm:self-auto cursor-pointer font-semibold border-slate-200 dark:border-slate-700"
                >
                  <Download className="w-3.5 h-3.5 text-emerald-600" />
                  <span>Xuất bảng điểm Excel (CSV)</span>
                </Button>
              )}
            </div>

            {rosterLoading ? (
              <p role="status" className="py-8 text-center text-sm text-slate-500">Đang tải danh sách sinh viên và điểm…</p>
            ) : students.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 gap-3 border border-dashed border-slate-200 dark:border-slate-800 rounded-3xl bg-white/50 dark:bg-slate-900/50">
                <GraduationCap className="w-10 h-10 text-slate-300" />
                <p className="text-sm text-slate-400">Lớp học chưa có sinh viên.</p>
              </div>
            ) : (
              <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm border-collapse">
                    <thead>
                      <tr className="border-b border-slate-200 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-800/50">
                        <th className="px-5 py-4 font-bold text-slate-600 dark:text-slate-300 sticky left-0 bg-slate-50 dark:bg-slate-800 z-10 min-w-[220px]">Sinh viên</th>
                        <th className="px-5 py-4 font-bold text-slate-600 dark:text-slate-300 text-center whitespace-nowrap">Tiến độ</th>
                        <th className="px-5 py-4 font-bold text-slate-600 dark:text-slate-300 text-center whitespace-nowrap">ĐTB</th>
                        {assignments.map((a: any) => (
                          <th key={a.id} className="px-4 py-4 font-bold text-slate-600 dark:text-slate-300 min-w-[140px] text-center">
                            <span className="block truncate max-w-[140px] text-xs" title={a.title}>{a.title}</span>
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {students.map((s: any) => (
                        <tr key={s.id || s.studentId} className="border-b border-slate-100 dark:border-slate-800/50 hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                          <td className="px-5 py-4 sticky left-0 bg-white dark:bg-slate-900 z-10 border-r border-slate-100 dark:border-slate-800/50">
                            <div className="flex items-center gap-3">
                              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-orange-400 to-amber-500 flex items-center justify-center shrink-0 text-white font-bold text-xs">
                                {(s.name || s.fullName || '?').charAt(0).toUpperCase()}
                              </div>
                              <div>
                                <p className="font-bold text-slate-900 dark:text-white text-sm">{s.name || s.fullName}</p>
                                <p className="text-xs text-slate-400 font-mono">{s.studentId || s.studentCode}</p>
                              </div>
                            </div>
                          </td>
                          <td className="px-5 py-4 text-center">
                            <Badge variant={s.submitCount === assignments.length && assignments.length > 0 ? 'success' : 'default'} className="text-[10px]">
                              {s.submitCount}/{assignments.length}
                            </Badge>
                          </td>
                          <td className="px-5 py-4 text-center font-bold text-slate-700 dark:text-slate-300">{s.avgScore}</td>
                          {assignments.map((a: any) => {
                            const sub = s.submissions?.[a.id]
                            if (!sub) return (
                              <td key={a.id} className="px-4 py-4 text-center">
                                <div className="flex flex-col items-center text-slate-300 dark:text-slate-600">
                                  <XCircle className="w-4 h-4" />
                                  <span className="text-[9px] mt-0.5">Chưa nộp</span>
                                </div>
                              </td>
                            )
                            const score = sub.score ?? sub.finalScore ?? sub.totalScore
                            const isGraded = score !== null && score !== undefined
                            const isPublished = sub.isPublished || sub.reviewStatus === 'PUBLISHED'
                            return (
                              <td key={a.id} className="px-4 py-4 text-center">
                                {isGraded ? (
                                  <div className="flex flex-col items-center">
                                    <span className={`text-sm font-bold ${isPublished ? 'text-green-600' : 'text-orange-500'}`}>
                                      {score}<span className="text-[10px] font-normal text-slate-400">/{a.maxScore || 10}</span>
                                    </span>
                                    {sub.submittedAt && <span className="text-[9px] text-slate-400">{new Date(sub.submittedAt).toLocaleDateString('vi-VN')}</span>}
                                  </div>
                                ) : (
                                  <div className="flex flex-col items-center text-blue-500">
                                    <CheckCircle2 className="w-4 h-4" />
                                    <span className="text-[9px] mt-0.5">Đã nộp</span>
                                  </div>
                                )}
                              </td>
                            )
                          })}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Tab: Announcements */}
        {activeTab === 'announcements' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Thông báo lớp ({announcements.length})</h3>
              <Button variant="primary" size="sm" className="gap-1.5 text-xs" onClick={() => { setAnnEditId(null); setAnnForm({ title: '', content: '' }); setAnnModal(true) }}>
                <Plus className="w-4 h-4" /> Đăng thông báo
              </Button>
            </div>

            {announcements.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 gap-4 border border-dashed border-slate-200 dark:border-slate-800 rounded-3xl bg-white/50 dark:bg-slate-900/50">
                <Bell className="w-10 h-10 text-slate-300" />
                <p className="text-sm text-slate-400">Chưa có thông báo nào cho lớp này.</p>
                <Button variant="primary" size="sm" className="gap-1.5 text-xs" onClick={() => { setAnnEditId(null); setAnnForm({ title: '', content: '' }); setAnnModal(true) }}>
                  <Plus className="w-4 h-4" /> Đăng thông báo đầu tiên
                </Button>
              </div>
            ) : (
              <div className="space-y-3">
                {announcements.map((ann: any) => (
                  <div key={ann.id} className="p-5 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200/60 dark:border-slate-800 hover:shadow-sm transition-all">
                    <div className="flex items-start justify-between gap-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-2">
                          <Megaphone className="w-4 h-4 text-orange-500 shrink-0" />
                          <h4 className="font-bold text-sm text-slate-900 dark:text-white truncate">{ann.title || 'Thông báo'}</h4>
                          <span className="text-xs text-slate-400 shrink-0">{ann.createdAt ? new Date(ann.createdAt).toLocaleDateString('vi-VN') : ''}</span>
                        </div>
                        <p className="text-sm text-slate-600 dark:text-slate-300 whitespace-pre-wrap leading-relaxed">{ann.content}</p>
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        <button
                          onClick={() => { setAnnEditId(ann.id); setAnnForm({ title: ann.title || '', content: ann.content || '' }); setAnnModal(true) }}
                          className="p-2 rounded-xl text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-500/10 transition-colors"
                        >
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => deleteAnnouncement(ann.id)}
                          className="p-2 rounded-xl text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/10 transition-colors"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Announcement Modal */}
      <Modal isOpen={annModal} onClose={() => !annSaving && setAnnModal(false)} title={annEditId ? 'Chỉnh sửa thông báo' : 'Đăng thông báo lớp'}>
        <form onSubmit={saveAnnouncement} className="space-y-4">
          <div className="space-y-1.5">
            <label className="block text-xs font-semibold text-slate-600 dark:text-slate-400">Tiêu đề (tùy chọn)</label>
            <input
              className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-orange-500"
              placeholder="Tiêu đề thông báo..."
              value={annForm.title}
              onChange={e => setAnnForm({ ...annForm, title: e.target.value })}
            />
          </div>
          <div className="space-y-1.5">
            <label className="block text-xs font-semibold text-slate-600 dark:text-slate-400">Nội dung *</label>
            <textarea
              required
              rows={5}
              className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-orange-500 resize-none"
              placeholder="Nhập nội dung thông báo cho sinh viên..."
              value={annForm.content}
              onChange={e => setAnnForm({ ...annForm, content: e.target.value })}
            />
          </div>
          <div className="flex justify-end gap-3 pt-3 border-t border-slate-200 dark:border-slate-800">
            <Button variant="outline" size="sm" type="button" onClick={() => setAnnModal(false)}>Hủy</Button>
            <Button variant="primary" size="sm" type="submit" isLoading={annSaving}>
              {annEditId ? 'Lưu thay đổi' : 'Đăng thông báo'}
            </Button>
          </div>
        </form>
      </Modal>
    </DashboardLayout>
  )
}

'use client'

import * as React from 'react'
import dynamic from 'next/dynamic'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { STUDENT_NAV } from '@/config/navigation'
import { useLanguage } from '@/providers/language-provider'
import { useAuth } from '@/providers/auth-provider'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { studentPortalApi } from '@/lib/api/modules/student-portal'
import { useAssignmentSync } from '@/features/assignments/hooks/useAssignmentSync'
import {
  ArrowLeft,
  BookOpen,
  Clock,
  FileText,
  CheckCircle2,
  Users,
  Search,
  Mail,
  Phone,
  GraduationCap,
  Copy,
  Check,
  Megaphone,
  AlertCircle,
  ExternalLink,
  Sparkles,
  Award,
  Send,
  Calendar
} from 'lucide-react'

const StudentSyllabus = dynamic(() => import('@/features/subjects/components/StudentSyllabus'))

export default function StudentClassDetailPage() {
  const params = useParams()
  const router = useRouter()
  const { user } = useAuth()
  const classId = (params?.id as string) || ''
  const [classData, setClassData] = React.useState<any>(null)
  const [loading, setLoading] = React.useState(true)
  const loadSequence = React.useRef(0)
  const [activeTab, setActiveTab] = React.useState<'assignments' | 'students' | 'syllabus'>('assignments')
  const [studentSearch, setStudentSearch] = React.useState('')
  const [assignmentSearch, setAssignmentSearch] = React.useState('')
  const [assignmentFilter, setAssignmentFilter] = React.useState<'all' | 'pending' | 'submitted' | 'graded'>('all')
  const [copiedEmail, setCopiedEmail] = React.useState<string | null>(null)
  const { t, language } = useLanguage()
  const isVi = language === 'vi'

  React.useEffect(() => {
    const sequence = ++loadSequence.current
    if (classId) {
      setLoading(true)
      studentPortalApi.getStudentClassDetail(classId)
        .then((data) => { if (sequence === loadSequence.current) setClassData(data) })
        .catch((err) => {
          console.error('Failed to load class detail:', err)
          if (sequence === loadSequence.current) setClassData(null)
        })
        .finally(() => setLoading(false))
    }
  }, [classId])

  useAssignmentSync(async () => {
    if (!classId) return
    const sequence = ++loadSequence.current
    const data = await studentPortalApi.getStudentClassDetail(classId)
    if (sequence === loadSequence.current) setClassData(data)
  })

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text)
    setCopiedEmail(text)
    setTimeout(() => setCopiedEmail(null), 2000)
  }

  if (loading) {
    return (
      <DashboardLayout
        navItems={STUDENT_NAV}
        title="AITA Student"
        roleLabel={t('profile.role_student', 'Sinh viên')}
        requiredRole="student"
      >
        <div className="flex flex-col justify-center items-center h-80 space-y-3 text-slate-500">
          <div className="w-8 h-8 border-3 border-orange-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-xs font-medium">{isVi ? 'Đang tải thông tin lớp học...' : 'Loading class details...'}</p>
        </div>
      </DashboardLayout>
    )
  }

  if (!classData) {
    return (
      <DashboardLayout
        navItems={STUDENT_NAV}
        title="AITA Student"
        roleLabel={t('profile.role_student', 'Sinh viên')}
        requiredRole="student"
      >
        <div className="flex flex-col justify-center items-center h-80 text-slate-500 space-y-3">
          <AlertCircle className="w-10 h-10 text-slate-400" />
          <p className="text-sm font-medium">{isVi ? 'Không tìm thấy thông tin lớp học.' : 'Class not found.'}</p>
          <Button variant="outline" size="sm" onClick={() => router.push('/student/classes')}>
            <ArrowLeft className="w-4 h-4 mr-1.5" />
            {isVi ? 'Quay lại danh sách' : 'Back to classes'}
          </Button>
        </div>
      </DashboardLayout>
    )
  }

  const lecturers = classData.lecturers || []
  const students = classData.students || []
  const assignments = classData.assignments || []
  const announcements = classData.announcements || []

  const filteredStudents = students.filter((s: any) => {
    if (!studentSearch.trim()) return true
    const q = studentSearch.toLowerCase().trim()
    const name = (s.fullName || '').toLowerCase()
    const code = (s.studentCode || '').toLowerCase()
    const email = (s.email || '').toLowerCase()
    return name.includes(q) || code.includes(q) || email.includes(q)
  })

  const filteredAssignments = assignments.filter((a: any) => {
    if (assignmentFilter === 'submitted' && !a.isSubmitted) return false
    if (assignmentFilter === 'graded' && (a.score === null || a.score === undefined)) return false
    if (assignmentFilter === 'pending' && a.isSubmitted) return false

    if (!assignmentSearch.trim()) return true
    const q = assignmentSearch.toLowerCase().trim()
    const title = (a.title || '').toLowerCase()
    const desc = (a.description || '').toLowerCase()
    const type = (a.type || '').toLowerCase()
    return title.includes(q) || desc.includes(q) || type.includes(q)
  })

  const submittedCount = assignments.filter((a: any) => a.isSubmitted).length
  const gradedCount = assignments.filter((a: any) => a.score !== null && a.score !== undefined).length
  const pendingCount = assignments.length - submittedCount
  const primaryLecturer = lecturers[0]

  return (
    <DashboardLayout
      navItems={STUDENT_NAV}
      title="AITA Student"
      roleLabel={t('profile.role_student', 'Sinh viên')}
      requiredRole="student"
      headerTitle={`${classData.subject?.code || ''} - ${classData.classCode || 'Lớp học'}`}
      headerSubtitle={classData.subject?.name || (isVi ? 'Chi tiết lớp học phần' : 'Class Details')}
    >
      {/* Almost full-width container */}
      <div className="space-y-5 w-full max-w-[99%] 2xl:max-w-[1850px] mx-auto pb-14 px-1 sm:px-2">
        {/* Navigation & Breadcrumb */}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/student/classes')}
            className="h-8 px-2.5 -ml-2 text-xs gap-1.5 font-semibold text-slate-600 dark:text-slate-300 hover:text-orange-600 dark:hover:text-orange-400"
          >
            <ArrowLeft className="w-4 h-4" />
            <span>{isVi ? 'Quay lại danh sách Lớp & Môn học' : 'Back to Classes & Courses'}</span>
          </Button>

          <div className="flex items-center gap-2">
            <span className="px-2.5 py-1 rounded-lg text-xs font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
              {classData.semester?.season || 'Spring 2026'} {classData.semester?.code ? `(${classData.semester.code})` : ''}
            </span>
            <span className="px-2.5 py-1 rounded-lg text-xs font-semibold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/25 flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              {isVi ? 'Đang diễn ra' : 'Active'}
            </span>
          </div>
        </div>

        {/* Header: Lớp, Môn và Giảng viên phụ trách (không khung) */}
        <div className="py-1">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="space-y-1.5">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-xs font-black uppercase px-2.5 py-0.5 rounded-md bg-orange-500 text-white font-mono tracking-wide">
                  {classData.subject?.code || 'MÔN HỌC'}
                </span>
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 font-mono">
                  {isVi ? 'Lớp:' : 'Class:'} {classData.classCode}
                </span>
              </div>

              <h1 className="text-xl sm:text-2xl font-black text-slate-900 dark:text-white tracking-tight">
                {classData.subject?.name || classData.classCode}
              </h1>

              {classData.subject?.description && (
                <p className="text-xs text-slate-500 dark:text-slate-400 max-w-3xl line-clamp-2">
                  {classData.subject.description}
                </p>
              )}
            </div>

            {/* Giảng viên phụ trách lớp */}
            <div className="flex items-center gap-3 shrink-0">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-orange-400 to-amber-500 text-white font-bold text-sm flex items-center justify-center shrink-0 shadow-2xs overflow-hidden">
                {primaryLecturer?.avatar ? (
                  <img src={primaryLecturer.avatar} alt={primaryLecturer.name} className="w-full h-full object-cover" />
                ) : (
                  (primaryLecturer?.name || 'G').charAt(0).toUpperCase()
                )}
              </div>
              <div className="min-w-0">
                <span className="text-[11px] text-slate-400 font-medium block">
                  {isVi ? 'Giảng viên' : 'Instructor'}
                </span>
                <span className="text-sm font-bold text-slate-900 dark:text-white truncate block">
                  {primaryLecturer?.name || (isVi ? 'Giảng viên Bộ môn' : 'Instructor')}
                </span>
                {primaryLecturer?.email && (
                  <span className="text-[11px] text-slate-500 dark:text-slate-400 font-mono truncate block">
                    {primaryLecturer.email}
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Executive KPI Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Tổng bài tập
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <FileText className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {assignments.length}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Toàn bộ bài tập của lớp</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Chưa nộp bài
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <Clock className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {pendingCount}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-amber-500" />
              <span>Cần hoàn thành đúng hạn</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Đã nộp bài
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <CheckCircle2 className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {submittedCount}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
              <span>Đã tải lên hệ thống</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Đã có điểm
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <Award className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {gradedCount}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Đã công bố điểm & rubric</span>
            </div>
          </div>
        </div>

        {/* Tab Controls Bar */}
        <div className="inline-flex flex-wrap p-1.5 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 shadow-xs gap-1">
          <button
            onClick={() => setActiveTab('assignments')}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer ${
              activeTab === 'assignments'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            <FileText className="w-4 h-4" />
            <span>{isVi ? 'Danh sách Bài tập' : 'Assignments'}</span>
            <span className={`px-2 py-0.5 rounded-full text-[11px] font-mono font-bold ${
              activeTab === 'assignments' ? 'bg-white/20 text-white' : 'bg-orange-100/80 text-orange-700'
            }`}>
              {assignments.length}
            </span>
          </button>

          <button
            onClick={() => setActiveTab('students')}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer ${
              activeTab === 'students'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            <Users className="w-4 h-4" />
            <span>{isVi ? 'Danh sách Sinh viên' : 'Student Roster'}</span>
            <span className={`px-2 py-0.5 rounded-full text-[11px] font-mono font-bold ${
              activeTab === 'students' ? 'bg-white/20 text-white' : 'bg-orange-100/80 text-orange-700'
            }`}>
              {students.length}
            </span>
          </button>
          <button
            onClick={() => setActiveTab('syllabus')}
            aria-pressed={activeTab === 'syllabus'}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer ${
              activeTab === 'syllabus'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            <span>{isVi ? 'Đề cương môn học (Syllabus)' : 'Course Syllabus'}</span>
          </button>
        </div>

        {activeTab === 'syllabus' && (
          <StudentSyllabus key={classData.subject?.id} subjectId={classData.subject?.id} />
        )}

        {/* ============================================================ */}
        {/* TAB 1: ASSIGNMENTS (MODERN DATA TABLE)                      */}
        {/* ============================================================ */}
        {activeTab === 'assignments' && (
          <div className="space-y-4">
            {/* Filters bar */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-4 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
              <div className="flex items-center gap-1.5 flex-wrap">
                <button
                  onClick={() => setAssignmentFilter('all')}
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    assignmentFilter === 'all'
                      ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                      : 'text-slate-600 hover:text-orange-600 dark:text-slate-400 hover:bg-orange-50/60'
                  }`}
                >
                  {isVi ? 'Tất cả' : 'All'} ({assignments.length})
                </button>
                <button
                  onClick={() => setAssignmentFilter('pending')}
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    assignmentFilter === 'pending'
                      ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                      : 'text-slate-600 hover:text-orange-600 dark:text-slate-400 hover:bg-orange-50/60'
                  }`}
                >
                  {isVi ? 'Cần làm' : 'Pending'} ({pendingCount})
                </button>
                <button
                  onClick={() => setAssignmentFilter('submitted')}
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    assignmentFilter === 'submitted'
                      ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                      : 'text-slate-600 hover:text-orange-600 dark:text-slate-400 hover:bg-orange-50/60'
                  }`}
                >
                  {isVi ? 'Đã nộp bài' : 'Submitted'} ({submittedCount})
                </button>
                <button
                  onClick={() => setAssignmentFilter('graded')}
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    assignmentFilter === 'graded'
                      ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                      : 'text-slate-600 hover:text-orange-600 dark:text-slate-400 hover:bg-orange-50/60'
                  }`}
                >
                  {isVi ? 'Đã có điểm AI' : 'Graded'} ({gradedCount})
                </button>
              </div>

              <div className="relative w-full sm:w-72">
                <Search className="w-3.5 h-3.5 absolute left-3 top-2.5 text-slate-400" />
                <Input
                  placeholder={isVi ? 'Tìm bài tập theo tên, loại bài...' : 'Search assignment...'}
                  className="pl-8 h-9 text-xs bg-white dark:bg-slate-900 border-orange-200/80 rounded-xl focus:border-orange-400"
                  value={assignmentSearch}
                  onChange={(e) => setAssignmentSearch(e.target.value)}
                />
              </div>
            </div>

            {/* Assignments Table */}
            <div className="rounded-2xl border border-orange-100/90 dark:border-orange-900/30 overflow-hidden bg-white dark:bg-slate-900 shadow-xs">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse text-xs">
                  <thead>
                    <tr className="border-b border-orange-100/90 dark:border-slate-800 bg-gradient-to-r from-orange-50/70 via-amber-50/40 to-orange-50/50 dark:bg-slate-950/60 text-[11px] font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                      <th className="px-4 py-3.5 w-12 text-center">#</th>
                      <th className="px-4 py-3.5 min-w-[240px]">{isVi ? 'Tên bài tập & Mô tả' : 'Assignment & Description'}</th>
                      <th className="px-4 py-3.5 w-28 text-center">{isVi ? 'Phân loại' : 'Type'}</th>
                      <th className="px-4 py-3.5 min-w-[170px]">{isVi ? 'Hạn nộp' : 'Deadline'}</th>
                      <th className="px-4 py-3.5 w-24 text-center">{isVi ? 'Thang điểm' : 'Max Points'}</th>
                      <th className="px-4 py-3.5 w-36 text-center">{isVi ? 'Trạng thái' : 'Status'}</th>
                      <th className="px-4 py-3.5 w-28 text-center">{isVi ? 'Điểm số' : 'Score'}</th>
                      <th className="px-4 py-3.5 min-w-[200px] w-52 text-right pr-5 whitespace-nowrap">{isVi ? 'Thao tác' : 'Actions'}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-800/70">
                    {filteredAssignments.length === 0 ? (
                      <tr>
                        <td colSpan={8} className="p-12 text-center text-slate-400">
                          <FileText className="w-8 h-8 mx-auto text-slate-300 dark:text-slate-600 mb-2" />
                          <p className="text-xs">{isVi ? 'Không tìm thấy bài tập nào.' : 'No assignments found.'}</p>
                        </td>
                      </tr>
                    ) : (
                      filteredAssignments.map((a: any, idx: number) => {
                        const dueDate = a.dueDate ? new Date(a.dueDate) : null
                        const isOverdue = dueDate && dueDate < new Date() && !a.isSubmitted
                        const isGraded = a.score !== null && a.score !== undefined

                        return (
                          <tr
                            key={a.id || idx}
                            className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors"
                          >
                            {/* STT */}
                            <td className="px-4 py-3.5 text-center text-slate-400 font-mono">
                              {idx + 1}
                            </td>

                            {/* Title & Description */}
                            <td className="px-4 py-3.5">
                              <Link
                                href={`/student/assignments/${a.id}`}
                                className="font-bold text-slate-900 dark:text-white hover:text-orange-600 dark:hover:text-orange-400 transition-colors text-xs line-clamp-1"
                              >
                                {a.title}
                              </Link>
                              {a.description && (
                                <p className="text-[11px] text-slate-400 line-clamp-1 mt-0.5">
                                  {a.description}
                                </p>
                              )}
                            </td>

                            {/* Type */}
                            <td className="px-4 py-3.5 text-center">
                              <span className="inline-block px-2 py-0.5 rounded-md font-mono text-[10px] font-bold uppercase bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                                {a.type || 'TASK'}
                              </span>
                            </td>

                            {/* Due date */}
                            <td className="px-4 py-3.5 text-slate-600 dark:text-slate-300">
                              {dueDate ? (
                                <div className="space-y-0.5">
                                  <div className="flex items-center gap-1 font-medium">
                                    <Clock className="w-3 h-3 text-slate-400 shrink-0" />
                                    <span>{dueDate.toLocaleDateString(isVi ? 'vi-VN' : 'en-US')}</span>
                                    <span className="text-slate-400 font-mono text-[11px]">
                                      {dueDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </span>
                                  </div>
                                  {isOverdue && (
                                    <span className="text-[10px] text-rose-500 font-semibold block">
                                      {isVi ? 'Đã hết hạn nộp' : 'Overdue'}
                                    </span>
                                  )}
                                </div>
                              ) : (
                                <span className="text-slate-400">{isVi ? 'Không có hạn' : 'No deadline'}</span>
                              )}
                            </td>

                            {/* Max Points */}
                            <td className="px-4 py-3.5 text-center font-mono font-bold text-slate-700 dark:text-slate-300">
                              {a.totalPoints || 10} {isVi ? 'đ' : 'pts'}
                            </td>

                            {/* Status */}
                            <td className="px-4 py-3.5 text-center">
                              {isGraded ? (
                                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">
                                  <Check className="w-3 h-3 text-emerald-600 dark:text-emerald-400 stroke-[2.5]" />
                                  <span>{isVi ? 'Đã có điểm' : 'Graded'}</span>
                                </span>
                              ) : a.isSubmitted ? (
                                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">
                                  <Check className="w-3 h-3 text-emerald-600 dark:text-emerald-400 stroke-[2.5]" />
                                  <span>{isVi ? 'Đã nộp bài' : 'Submitted'}</span>
                                </span>
                              ) : isOverdue ? (
                                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold bg-rose-500/15 text-rose-600 dark:text-rose-400 border border-rose-500/30">
                                  <AlertCircle className="w-3 h-3" />
                                  <span>{isVi ? 'Quá hạn' : 'Overdue'}</span>
                                </span>
                              ) : (
                                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/30">
                                  <Clock className="w-3 h-3" />
                                  <span>{isVi ? 'Cần làm' : 'Pending'}</span>
                                </span>
                              )}
                            </td>

                            {/* Score */}
                            <td className="px-4 py-3.5 text-center">
                              {isGraded ? (
                                <span className="font-mono font-black text-xs text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/40 px-2 py-0.5 rounded-md border border-emerald-200 dark:border-emerald-800">
                                  {a.score}/{a.totalPoints || 10}
                                </span>
                              ) : (
                                <span className="text-slate-300 dark:text-slate-600 font-mono">—</span>
                              )}
                            </td>

                            {/* Action Button */}
                            <td className="px-4 py-3.5 text-right pr-5 whitespace-nowrap">
                              <div className="flex items-center justify-end gap-2 shrink-0 whitespace-nowrap">
                                {isGraded && (
                                  <Link href="/student/results" className="shrink-0">
                                    <Button
                                      variant="ghost"
                                      size="sm"
                                      className="h-8 px-2.5 text-xs font-semibold text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 hover:bg-emerald-50/80 dark:hover:bg-emerald-950/40 border border-emerald-200/80 dark:border-emerald-800/80 gap-1.5 shrink-0 whitespace-nowrap cursor-pointer"
                                      title={isVi ? 'Xem đánh giá AI chi tiết' : 'View AI review'}
                                    >
                                      <Sparkles className="w-3.5 h-3.5 text-emerald-500 shrink-0" />
                                      <span>{isVi ? 'Xem AI' : 'AI Review'}</span>
                                    </Button>
                                  </Link>
                                )}

                                <Link href={`/student/assignments/${a.id}`} className="shrink-0">
                                  <Button
                                    variant={a.isSubmitted ? 'outline' : 'primary'}
                                    size="sm"
                                    className={`h-8 px-3 text-xs font-bold shrink-0 whitespace-nowrap cursor-pointer shadow-xs ${
                                      a.isSubmitted
                                        ? 'border-orange-200/90 dark:border-orange-800/60 text-orange-600 dark:text-orange-400 hover:bg-orange-50/60 dark:hover:bg-slate-800'
                                        : ''
                                    }`}
                                  >
                                    {a.isSubmitted ? (
                                      <span className="flex items-center gap-1.5">
                                        <FileText className="w-3.5 h-3.5 text-orange-500 shrink-0" />
                                        <span>{isVi ? 'Xem bài nộp' : 'View'}</span>
                                      </span>
                                    ) : (
                                      <span className="flex items-center gap-1.5">
                                        <Send className="w-3.5 h-3.5 shrink-0" />
                                        <span>{isVi ? 'Nộp bài' : 'Submit'}</span>
                                      </span>
                                    )}
                                  </Button>
                                </Link>
                              </div>
                            </td>
                          </tr>
                        )
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* ============================================================ */}
        {/* TAB 2: STUDENTS (MODERN DATA TABLE)                         */}
        {/* ============================================================ */}
        {activeTab === 'students' && (
          <div className="space-y-3">
            {/* Header / Search bar */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-4 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
              <div className="relative w-full sm:w-80">
                <Search className="w-3.5 h-3.5 absolute left-3 top-2.5 text-slate-400" />
                <Input
                  placeholder={isVi ? 'Tìm kiếm sinh viên theo tên, MSSV, email...' : 'Search student...'}
                  className="pl-8 h-9 text-xs bg-white dark:bg-slate-900 border-orange-200/80 rounded-xl focus:border-orange-400"
                  value={studentSearch}
                  onChange={(e) => setStudentSearch(e.target.value)}
                />
              </div>

              <div className="flex items-center gap-2 text-xs text-slate-500">
                <Users className="w-4 h-4 text-orange-500" />
                <span>
                  {isVi ? 'Sĩ số hiển thị:' : 'Showing:'}{' '}
                  <strong className="text-slate-900 dark:text-white font-mono font-bold">{filteredStudents.length}</strong> / {students.length} {isVi ? 'sinh viên' : 'students'}
                </span>
              </div>
            </div>

            {/* Students Table */}
            <div className="rounded-2xl border border-orange-100/90 dark:border-orange-900/30 overflow-hidden bg-white dark:bg-slate-900 shadow-xs">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse text-xs">
                  <thead>
                    <tr className="border-b border-orange-100/90 dark:border-slate-800 bg-gradient-to-r from-orange-50/70 via-amber-50/40 to-orange-50/50 dark:bg-slate-950/60 text-[11px] font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                      <th className="px-4 py-3.5 w-12 text-center">#</th>
                      <th className="px-4 py-3.5 min-w-[220px]">{isVi ? 'Họ và tên Sinh viên' : 'Student Name'}</th>
                      <th className="px-4 py-3.5 w-32 font-mono text-center">{isVi ? 'Mã số SV' : 'Student Code'}</th>
                      <th className="px-4 py-3.5 min-w-[220px]">{isVi ? 'Email FPT' : 'FPT Email'}</th>
                      <th className="px-4 py-3.5 w-28 text-center">{isVi ? 'Lớp học phần' : 'Class Code'}</th>
                      <th className="px-4 py-3.5 w-32 text-center">{isVi ? 'Trạng thái' : 'Status'}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-800/70">
                    {filteredStudents.length === 0 ? (
                      <tr>
                        <td colSpan={6} className="p-12 text-center text-slate-400">
                          <Users className="w-8 h-8 mx-auto text-slate-300 dark:text-slate-600 mb-2" />
                          <p className="text-xs">{isVi ? 'Không tìm thấy sinh viên nào.' : 'No students found.'}</p>
                        </td>
                      </tr>
                    ) : (
                      filteredStudents.map((st: any, idx: number) => {
                        const isCurrentUser =
                          (user?.id && st.id === user.id) ||
                          (user?.email && st.email === user.email) ||
                          (user?.studentCode && st.studentCode === user.studentCode)

                        const isCopied = copiedEmail === st.email

                        return (
                          <tr
                            key={st.id || idx}
                            className={`transition-colors ${
                              isCurrentUser
                                ? 'bg-orange-50/30 dark:bg-orange-950/20 font-semibold'
                                : 'hover:bg-slate-50/80 dark:hover:bg-slate-800/40'
                            }`}
                          >
                            {/* STT */}
                            <td className="px-4 py-3 text-center text-slate-400 font-mono">
                              {idx + 1}
                            </td>

                            {/* Student Avatar & Name */}
                            <td className="px-4 py-3">
                              <div className="flex items-center gap-2.5">
                                <div className="w-7 h-7 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-bold text-[11px] flex items-center justify-center shrink-0 border border-slate-200 dark:border-slate-700 overflow-hidden">
                                  {st.avatar ? (
                                    <img src={st.avatar} alt={st.fullName} className="w-full h-full object-cover" />
                                  ) : (
                                    (st.fullName || 'S').charAt(0).toUpperCase()
                                  )}
                                </div>
                                <div className="flex items-center gap-1.5 min-w-0">
                                  <span className="text-slate-900 dark:text-white font-bold truncate">
                                    {st.fullName}
                                  </span>
                                  {isCurrentUser && (
                                    <span className="px-1.5 py-0.2 rounded text-[10px] font-bold bg-orange-500 text-white shrink-0">
                                      {isVi ? 'Bạn' : 'You'}
                                    </span>
                                  )}
                                </div>
                              </div>
                            </td>

                            {/* MSSV */}
                            <td className="px-4 py-3 text-center">
                              <span className="px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 font-mono text-[11px] font-bold text-slate-700 dark:text-slate-300 border border-slate-200/80 dark:border-slate-700">
                                {st.studentCode || `SV${String(idx + 1).padStart(3, '0')}`}
                              </span>
                            </td>

                            {/* Email */}
                            <td className="px-4 py-3">
                              {st.email ? (
                                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400 font-mono text-[11px]">
                                  <span className="truncate">{st.email}</span>
                                  <button
                                    onClick={() => copyToClipboard(st.email)}
                                    className="text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 p-0.5 rounded shrink-0"
                                    title={isVi ? 'Sao chép email' : 'Copy email'}
                                  >
                                    {isCopied ? <Check className="w-3 h-3 text-emerald-500" /> : <Copy className="w-3 h-3" />}
                                  </button>
                                </div>
                              ) : (
                                <span className="text-slate-400">—</span>
                              )}
                            </td>

                            {/* Class Code */}
                            <td className="px-4 py-3 text-center font-mono text-slate-500 text-[11px]">
                              {classData.classCode}
                            </td>

                            {/* Status */}
                            <td className="px-4 py-3 text-center">
                              <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
                                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                                <span>{isVi ? 'Đang học' : 'Enrolled'}</span>
                              </span>
                            </td>
                          </tr>
                        )
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  )
}

'use client'

import { RefreshAction } from '@/components/actions/RefreshAction'

import * as React from 'react'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { STUDENT_NAV } from '@/config/navigation'
import { useLanguage } from '@/providers/language-provider'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { studentPortalApi } from '@/lib/api/modules/student-portal'
import { semestersApi } from '@/lib/api/modules/semesters'
import { clearClientApiCache } from '@/lib/api/client'
import {
  Users,
  BookOpen,
  ArrowRight,
  Search,
  Filter,
  FileText,
  RefreshCw,
  AlertTriangle
} from 'lucide-react'

export default function StudentClassesPage() {
  const [classes, setClasses] = React.useState<any[]>([])
  const [semesters, setSemesters] = React.useState<any[]>([])
  const [selectedSemester, setSelectedSemester] = React.useState<string>('all')
  const [searchQuery, setSearchQuery] = React.useState('')
  const [loading, setLoading] = React.useState(true)
  const [refreshing, setRefreshing] = React.useState(false)
  const [status, setStatus] = React.useState('')
  const inFlight = React.useRef(false)
  const hasLoaded = React.useRef(false)
  const sequence = React.useRef(0)
  const [error, setError] = React.useState<string | null>(null)
  const { t, language } = useLanguage()
  const isVi = language === 'vi'

  const loadData = React.useCallback(async (forceRefresh = false) => {
    if (inFlight.current) return
    inFlight.current = true
    const current = ++sequence.current
    const isRefresh = hasLoaded.current
    setLoading(!isRefresh)
    setRefreshing(isRefresh || forceRefresh)
    setStatus('')
    setError(null)
    try {
      if (forceRefresh) {
        clearClientApiCache('/student-portal/dashboard')
        clearClientApiCache('/semesters')
      }
      const options = forceRefresh ? { cache: 'no-store' as const } : {}
      const [dashData, semsData] = await Promise.allSettled([
        studentPortalApi.getStudentDashboard(options).then(data => {
          if (current === sequence.current) {
            setClasses(data?.enrolledClasses || [])
            setLoading(false)
          }
          return data
        }),
        semestersApi.getSemesters(options)
      ])
      if (current !== sequence.current) return

      if (dashData.status === 'fulfilled') {
        setClasses(dashData.value?.enrolledClasses || [])
      } else {
        if (isRefresh) throw dashData.reason
        console.error('Failed to load student dashboard:', dashData.reason)
        try {
          const subjects = await studentPortalApi.getStudentSubjects()
          if (current !== sequence.current) return
          if (Array.isArray(subjects) && subjects.length > 0) {
            setClasses(subjects.map((s: any) => ({
              id: s.classId || s.id,
              classCode: s.classCode || s.code,
              subject: {
                id: s.id,
                code: s.code,
                name: s.name,
                credit: s.credit || 3,
                description: s.description
              },
              semester: s.semester,
              lecturers: s.lecturers || [],
              studentCount: 30,
              assignmentCount: 0
            })))
          } else {
            setClasses([])
          }
        } catch (err) {
          throw err
        }
      }

      if (semsData.status === 'fulfilled') {
        const list = Array.isArray(semsData.value) ? semsData.value : []
        setSemesters(list)
      }
      hasLoaded.current = true
      if (semsData.status === 'rejected') {
        setError(isVi ? 'Đã cập nhật lớp học nhưng chưa tải được danh sách học kỳ. Vui lòng thử lại.' : 'Classes updated, but semesters could not be refreshed. Please try again.')
      } else if (forceRefresh) {
        setStatus(isVi ? 'Đã cập nhật danh sách lớp học.' : 'Class list updated.')
      }
    } catch (err: any) {
      if (current !== sequence.current) return
      console.error('Error loading classes:', err)
      setError(err?.message || (isVi ? 'Không thể tải danh sách lớp học.' : 'Failed to load classes.'))
    } finally {
      if (current === sequence.current) {
        inFlight.current = false
        setLoading(false)
        setRefreshing(false)
      }
    }
  }, [isVi])

  React.useEffect(() => {
    void loadData()
    return () => { sequence.current++; inFlight.current = false }
  }, [loadData])

  const filteredClasses = React.useMemo(() => {
    let list = classes
    if (selectedSemester !== 'all') {
      list = list.filter((cls: any) => {
        const semSeason = cls.semester?.season || cls.semester?.code || ''
        const semLabel = cls.semester?.label || ''
        return (
          semSeason.toLowerCase().includes(selectedSemester.toLowerCase()) ||
          semLabel.toLowerCase().includes(selectedSemester.toLowerCase())
        )
      })
    }
    if (!searchQuery.trim()) return list
    const q = searchQuery.toLowerCase().trim()
    return list.filter((cls: any) => {
      const classCode = (cls.classCode || '').toLowerCase()
      const subjCode = (cls.subject?.code || '').toLowerCase()
      const subjName = (cls.subject?.name || '').toLowerCase()
      const lecturerNames = (cls.lecturers || []).map((l: any) => (l.name || '').toLowerCase()).join(' ')
      return (
        classCode.includes(q) ||
        subjCode.includes(q) ||
        subjName.includes(q) ||
        lecturerNames.includes(q)
      )
    })
  }, [classes, selectedSemester, searchQuery])

  const totalClasses = classes.length
  const totalAssignments = classes.reduce((sum, c) => sum + (c.assignmentCount || 0), 0)

  return (
    <DashboardLayout
