    const graded = assignmentsList.filter((a) => a.status === 'GRADED' && a.score != null)
    if (graded.length === 0) return null
    const sum = graded.reduce((acc, a) => acc + Number(a.score), 0)
    return (sum / graded.length).toFixed(1)
