  })

  // SQL Answer key
  const [isUploadingAnswerKey, setIsUploadingAnswerKey] = useState(false)
  const [existingTotalWeight, setExistingTotalWeight] = useState(0)

  // Subscribe to AI store
  useEffect(() => {
    const unsub = aiGenerationStore.subscribe((state) => {
      setIsLoading(state.isGenerating)
      if (state.loadingMsg) setLoadingMsg(state.loadingMsg)
      if (state.error) setError(state.error)
      if (state.result) {
        setContent(cleanAssignmentHtml(state.result.content))
        setRubric(state.result.rubric)
        setBlueprint(state.result.blueprint)
        setMetadata((prev: any) => ({
          ...prev,
          ...state.result?.metadata,
          dueDate: prev.dueDate || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 16)
        }))
        setStep(2)
      }
      if (state.selectedSemester) setSelectedSemester(state.selectedSemester)
      if (state.subjectCode) setSubjectCode(state.subjectCode)
      if (state.assignmentType) setSelectedAssignmentType(state.assignmentType)
      if (state.textPrompt) setTextPrompt(state.textPrompt)
    })
    return unsub
  }, [])

  // Load initial options
  useEffect(() => {
    async function loadData() {
      try {
        const [clsData, semsData, subjData] = await Promise.all([
          classesApi.getClasses(1, 1000).catch(() => []),
          semestersApi.getSemesters().catch(() => []),
          subjectsApi.getSubjects(1, 1000).catch(() => [])
        ])

        const classes = Array.isArray(clsData) ? clsData : []
        setAllClasses(classes)

        const subs = Array.isArray(subjData) ? subjData : ((subjData as any)?.data || [])
        setAllSubjects(subs)

        const sems = Array.isArray(semsData) ? semsData : []
        setSemesters(sems)

        // Teacher's unique subjects
        const uniqueSubs = new Set<string>()
        classes.forEach((c: any) => {
          const code = c.subject?.code || c.subjectCode
          if (code) uniqueSubs.add(code)
        })
        const teacherSubs = Array.from(uniqueSubs).sort()
        setTeacherSubjects(teacherSubs)

        // Default semester
        const activeSem = sems.find((s: any) => s.isActive) || sems[0]
        if (activeSem) setSelectedSemester(activeSem.id)

        // Default subject
        if (teacherSubs.length > 0) {
          setSubjectCode(teacherSubs[0])
        }
      } catch (err) {
        console.error('Failed to load initial assignment upload data:', err)
      }
    }
    void loadData()
  }, [])

  // Update syllabus assignment types when subject changes
  useEffect(() => {
    if (!subjectCode) {
      setAvailableAssignmentTypes([])
      setSelectedAssignmentType('')
      return
    }
    const found = allSubjects.find((s) => s.code?.toLowerCase() === subjectCode.toLowerCase())
    const types = extractAssignmentTypesFromSyllabus(found?.syllabusData)
    setAvailableAssignmentTypes(types)
    if (types.length > 0) {
      setSelectedAssignmentType((prev) => (types.includes(prev) ? prev : types[0]))
    } else {
      setSelectedAssignmentType('Assignment')
    }

    // Load prompt templates for subject
    if (found?.id) {
      promptsApi.getPromptTemplates(found.id).then(setPromptTemplates).catch(() => setPromptTemplates([]))
    }
  }, [subjectCode, allSubjects])

  // Filter classes available for selected semester and subject
  const availableClasses = allClasses.filter((c: any) => {
    const semMatch = !selectedSemester || c.semester?.id === selectedSemester || c.semesterId === selectedSemester
    const subMatch = !subjectCode || c.subject?.code?.toLowerCase() === subjectCode.toLowerCase()
    return semMatch && subMatch
  })

  // Start Generation via Text
  const handleGenerateText = () => {
    if (!textPrompt.trim()) {
      setError('Vui lòng nhập mô tả hoặc yêu cầu đề bài')
      return
    }
    if (!selectedSemester || !subjectCode) {
      setError('Vui lòng chọn Học kỳ và Môn học')
      return
    }
    setError(null)
    aiGenerationStore.startGeneration(textPrompt, selectedSemester, subjectCode, selectedAssignmentType)
  }

  // Start Generation via File
  const handleUploadFile = async (file: File) => {
    if (!selectedSemester || !subjectCode) {
      setError('Vui lòng chọn Học kỳ và Môn học trước khi tải file')
      return
    }
    setError(null)
    setUploadedFile(file)
    await aiGenerationStore.startFileGeneration(file, selectedSemester, subjectCode, selectedAssignmentType)
  }

  // Handle SQL Answer Key upload
  const handleAnswerKeyUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    setIsUploadingAnswerKey(true)
    setError(null)
    try {
      if (rubric?.rules) {
        const formData = new FormData()
        formData.append('file', file)
        formData.append('rubricRules', JSON.stringify(rubric.rules))
        const res = await gradingApi.parseSqlKey(formData)
        if (res.rules) {
          setRubric({ ...rubric, rules: res.rules })
        }
      }
    } catch (err: any) {
      setError(err?.message || 'Không thể đọc file SQL Answer Key')
    } finally {
      setIsUploadingAnswerKey(false)
    }
  }

  // Publish assignment
  const handlePublish = async () => {
    if (!rubric || !blueprint) return

    if (selectedClasses.length === 0) {
      setError('Vui lòng chọn ít nhất một lớp học áp dụng bài tập')
      return
    }
    if (!metadata.dueDate) {
      setError('Vui lòng đặt hạn nộp bài')
      return
    }
    if (new Date(metadata.dueDate).getTime() <= Date.now()) {
      setError('Hạn nộp bài phải ở thời điểm tương lai.')
      return
    }

    const newWeight = metadata.weightPercentage !== undefined ? Number(metadata.weightPercentage) : 0
    if (newWeight > 70) {
      setError('Tỷ trọng điểm của bài tập không được vượt quá 70%.')
      return
    }

    // Check cumulative weight per class across active assignments
    try {
      const allExams = await assignmentsApi.getAssignments()
      if (Array.isArray(allExams) && selectedClasses.length > 0) {
        for (const classId of selectedClasses) {
          const targetClass = allClasses.find((c: any) => c.id === classId)
          const className = targetClass?.name || targetClass?.classCode || targetClass?.code || classId

          const classExams = allExams.filter((a: any) => {
            if (a.isDeleted || a.status === 'deleted' || a.status === 'Deleted') return false
            const matchesClass = Array.isArray(a.classes)
              ? a.classes.includes(classId)
              : (a.classId === classId || (Array.isArray(a.classIds) && a.classIds.includes(classId)))
            return matchesClass
          })

          const existingTotal = classExams.reduce((sum: number, a: any) => sum + (Number(a.weightPercentage) || 0), 0)
          if (existingTotal + newWeight > 70) {
            setError(`Tổng trọng số các bài tập trong lớp ${className} không được vượt quá 70%. Hiện tại đã là ${existingTotal}%, thêm mới ${newWeight}% sẽ thành ${existingTotal + newWeight}%.`)
            return
          }
        }
      }
    } catch (weightCheckErr: any) {
      setError('Không thể kiểm tra tổng trọng số các bài tập trong lớp: ' + (weightCheckErr?.message || 'Lỗi đọc dữ liệu'))
      return
    }

    const totalWeight = rubric.rules ? rubric.rules.reduce((sum: number, r: any) => sum + (Number(r.weight) || 0), 0) : 0
    if (Math.abs(totalWeight - (metadata.totalPoints || 10)) > 0.05) {
      setError(`Tổng điểm các tiêu chí rubric (${totalWeight}) phải bằng điểm tối đa (${metadata.totalPoints || 10})`)
      return
    }

    setIsLoading(true)
    setLoadingMsg('Đang tạo và phân phối bài tập đến các lớp học...')
    try {
      const isLocked = metadata.latePolicyOption === 'NONE_LOCKED'
      const allowLateSubmission = metadata.allowLateSubmission !== undefined ? metadata.allowLateSubmission : !isLocked
      let latePenaltyType = 'NONE'
      if (metadata.latePolicyOption === 'DAILY_POINTS') latePenaltyType = 'DAILY_POINTS'
      else if (metadata.latePolicyOption === 'DAILY_PERCENT') latePenaltyType = 'DAILY_PERCENT'
      else if (metadata.latePolicyOption === 'FLAT_POINTS') latePenaltyType = 'FLAT_POINTS'

      const finalMetadata = {
        ...metadata,
        title: metadata.title || 'AI Assignment',
        assignmentType: selectedAssignmentType || metadata.category || 'Assignment',
        examType: selectedAssignmentType || metadata.category || 'Assignment',
        category: selectedAssignmentType || metadata.category || 'Assignment',
        semesterId: selectedSemester,
        classIds: selectedClasses,
        content: cleanAssignmentHtml(content),
        gradingStrategy: metadata.gradingStrategy || metadata.strategy || 'CONTINUOUS_QUEUE',
        strategy: metadata.gradingStrategy || metadata.strategy || 'CONTINUOUS_QUEUE',
        allowLateSubmission,
        latePenaltyType,
        latePenaltyValue: Number(metadata.latePenaltyValue) || 0,
        lateSubmitHours: Number(metadata.lateSubmitHours) || 24,
      }

      const assignment = await gradingApi.publishAssignment(finalMetadata, blueprint, rubric)
      aiGenerationStore.reset()
      router.push(`/lecturer/grading/assignments/${assignment.id || assignment.examId}`)
    } catch (err: any) {
      setError(err?.message || 'Không thể tạo bài tập vào hệ thống')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <DashboardLayout
      navItems={LECTURER_NAV}
      title="AITA Lecturer"
      roleLabel={t('profile.role_lecturer', 'Giảng viên')}
      requiredRole="lecturer"
      headerTitle={t('lecturer.upload.header_title', 'Tạo đề bài & Barem AI')}
      headerSubtitle={t('lecturer.upload.header_subtitle', 'Trích xuất tài liệu đào tạo, sinh đề bài tự động và thiết lập barem chấm sandbox')}
    >
      <div className="w-full space-y-6 pb-12">
        {/* Progress Stepper */}
        <div className="relative overflow-hidden flex items-center justify-between bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 p-4 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
          <div className={`flex items-center gap-3 ${step >= 1 ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${step >= 1 ? 'bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/25' : 'bg-slate-100 text-slate-400'}`}>
              1
            </div>
            <span>{t('lecturer.upload.step1', 'Nhập nguồn đề bài')}</span>
          </div>
          <div className="h-0.5 flex-1 mx-4 bg-orange-100/80 dark:bg-slate-800" />
          <div className={`flex items-center gap-3 ${step >= 2 ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${step >= 2 ? 'bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/25' : 'bg-slate-100 text-slate-400'}`}>
              2
            </div>
            <span>{t('lecturer.upload.step2', 'Nội dung & Yêu cầu')}</span>
          </div>
          <div className="h-0.5 flex-1 mx-4 bg-orange-100/80 dark:bg-slate-800" />
          <div className={`flex items-center gap-3 ${step >= 3 ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${step >= 3 ? 'bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/25' : 'bg-slate-100 text-slate-400'}`}>
              3
            </div>
            <span>{t('lecturer.upload.step3', 'Barem Rubric & Xuất bản')}</span>
          </div>
        </div>

        {/* Global Loading Overlay */}
        {isLoading && (
          <div className="p-8 bg-orange-50 dark:bg-orange-950/30 border border-orange-200 dark:border-orange-800/60 rounded-2xl flex items-center gap-4 animate-pulse">
            <Loader2 className="w-6 h-6 text-orange-600 animate-spin shrink-0" />
            <div className="flex-1">
              <p className="text-sm font-semibold text-orange-900 dark:text-orange-200">{loadingMsg || 'Đang xử lý...'}</p>
              <p className="text-xs text-orange-700 dark:text-orange-400">Hệ thống AI đang phân tích dữ liệu, vui lòng đợi trong giây lát.</p>
            </div>
            <Button variant="outline" size="sm" onClick={() => aiGenerationStore.cancelGeneration()} className="text-xs">
              Hủy
            </Button>
          </div>
        )}

        {/* Error Notice */}
        {error && (
          <div className="p-4 bg-rose-50 dark:bg-rose-950/30 border border-rose-200 dark:border-rose-800/60 rounded-2xl flex items-center justify-between text-sm text-rose-700 dark:text-rose-300">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 shrink-0 text-rose-500" />
              <span>{error}</span>
            </div>
            <Button variant="ghost" size="sm" onClick={() => setError(null)} className="text-xs">
              Đóng
            </Button>
          </div>
        )}

        {/* STEP 1: INPUT SOURCE */}
        {step === 1 && (
          <div className="space-y-6">
            <div className="relative overflow-hidden p-6 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 rounded-2xl shadow-xs">
              <h2 className="text-lg font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-orange-500" />
                Thông tin bài tập & môn học
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Học kỳ</label>
                  <select
                    className="w-full rounded-xl border border-orange-100/90 bg-white p-2.5 text-sm dark:bg-slate-900 dark:border-slate-800 focus:outline-none focus:border-orange-400"
                    value={selectedSemester}
                    onChange={(e) => setSelectedSemester(e.target.value)}
                  >
                    <option value="">Chọn học kỳ</option>
                    {semesters.map((s) => (
                      <option key={s.id} value={s.id}>
                        {s.name || s.code} {s.isActive ? '(Hiện tại)' : ''}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Môn học</label>
                  <select
                    className="w-full rounded-xl border border-orange-100/90 bg-white p-2.5 text-sm dark:bg-slate-900 dark:border-slate-800 focus:outline-none focus:border-orange-400"
                    value={subjectCode}
                    onChange={(e) => setSubjectCode(e.target.value)}
                  >
                    <option value="">Chọn môn học</option>
                    {teacherSubjects.map((code) => (
                      <option key={code} value={code}>
                        {code}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Loại bài tập</label>
                  <select
                    className="w-full rounded-xl border border-orange-100/90 bg-white p-2.5 text-sm dark:bg-slate-900 dark:border-slate-800 focus:outline-none focus:border-orange-400"
                    value={selectedAssignmentType}
                    onChange={(e) => setSelectedAssignmentType(e.target.value)}
                  >
                    {availableAssignmentTypes.map((t) => (
                      <option key={t} value={t}>
                        {t}
                      </option>
                    ))}
                    {!availableAssignmentTypes.includes('Assignment') && <option value="Assignment">Assignment</option>}
                    {!availableAssignmentTypes.includes('Lab') && <option value="Lab">Lab</option>}
                    {!availableAssignmentTypes.includes('Workshop') && <option value="Workshop">Workshop</option>}
                  </select>
                </div>
              </div>

              {/* Mode switch */}
              <div className="inline-flex p-1.5 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 shadow-xs mb-6">
                <button
                  type="button"
                  onClick={() => setInputMode('text')}
                  className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${
                    inputMode === 'text'
                      ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                      : 'text-slate-600 dark:text-slate-400 hover:text-orange-600 dark:hover:text-orange-400'
                  }`}
                >
                  <Sparkles className="w-4 h-4" />
                  Mô tả bằng văn bản / Chỉ dẫn AI
                </button>
                <button
                  type="button"
                  onClick={() => setInputMode('file')}
                  className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${
                    inputMode === 'file'
                      ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                      : 'text-slate-600 dark:text-slate-400 hover:text-orange-600 dark:hover:text-orange-400'
                  }`}
                >
                  <Upload className="w-4 h-4" />
                  Tải lên tài liệu đề bài (PDF / Word / ZIP / SQL)
                </button>
              </div>

              {inputMode === 'text' ? (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-semibold text-slate-600 dark:text-slate-400">
                      Mô tả yêu cầu, chủ đề bài tập hoặc paste nội dung đề:
                    </span>
                    {promptTemplates.length > 0 && (
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => setIsPromptDrawerOpen(!isPromptDrawerOpen)}
                        className="text-xs gap-1.5 text-orange-600"
                      >
                        <Bot className="w-3.5 h-3.5" />
                        Thư viện Prompt ({promptTemplates.length})
                      </Button>
                    )}
                  </div>

                  {isPromptDrawerOpen && (
                    <div className="p-4 bg-orange-50/50 dark:bg-orange-950/20 border border-orange-200 dark:border-orange-800/40 rounded-xl space-y-2 max-h-56 overflow-y-auto">
                      <p className="text-xs font-bold text-orange-800 dark:text-orange-300">Chọn mẫu chỉ dẫn đã lưu:</p>
                      {promptTemplates.map((pt) => (
                        <div
                          key={pt.id}
                          onClick={() => {
                            setTextPrompt(pt.templateContent)
                            promptsApi.incrementPromptUsage(pt.id).catch(console.error)
                            setIsPromptDrawerOpen(false)
                          }}
                          className="p-2.5 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 cursor-pointer hover:border-orange-500 transition-all text-xs"
                        >
                          <div className="font-semibold text-slate-800 dark:text-slate-200">{pt.name}</div>
                          <div className="text-slate-500 line-clamp-1">{pt.templateContent}</div>
                        </div>
                      ))}
                    </div>
                  )}

                  <textarea
                    rows={8}
                    className="w-full rounded-xl border border-slate-200 bg-white p-3 text-sm dark:bg-slate-900 dark:border-slate-800"
                    placeholder="Ví dụ: Tạo bài thực hành SQL gồm 5 câu truy vấn từ cơ bản đến nâng cao cho môn DBI202 về hệ thống Quản lý Thư viện, yêu cầu sinh schema CREATE TABLE, INSERT và các tiêu chí chấm điểm tự động..."
                    value={textPrompt}
                    onChange={(e) => setTextPrompt(e.target.value)}
                  />

                  <div className="flex justify-end">
                    <Button
                      onClick={handleGenerateText}
                      disabled={isLoading || !textPrompt.trim()}
                      className="bg-orange-600 hover:bg-orange-700 text-white gap-2 shadow-sm"
                    >
                      <Sparkles className="w-4 h-4" />
                      Tạo đề bài bằng AI
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  <FileUpload onUpload={handleUploadFile} isUploading={isLoading} />
                </div>
              )}
            </div>
          </div>
        )}

        {/* STEP 2: CONTENT & BLUEPRINT REVIEW */}
        {step === 2 && (
          <div className="space-y-6">
            <Card className="p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-xs space-y-4">
              <div className="flex items-center justify-between pb-4 border-b border-slate-100 dark:border-slate-800">
                <h2 className="text-lg font-bold text-slate-900 dark:text-white flex items-center gap-2">
                  <FileCheck2 className="w-5 h-5 text-orange-500" />
                  Kiểm tra nội dung & Thiết lập bài tập
                </h2>
                <div className="flex items-center gap-2">
                  <Button variant="outline" size="sm" onClick={() => setStep(1)} className="text-xs gap-1">
                    <ArrowLeft className="w-3.5 h-3.5" />
                    Quay lại
                  </Button>
                  <Button
                    size="sm"
                    onClick={() => setStep(3)}
                    className="text-xs bg-orange-600 hover:bg-orange-700 text-white gap-1"
                  >
                    Tiếp tục barem Rubric
                    <ArrowRight className="w-3.5 h-3.5" />
                  </Button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Tiêu đề bài tập</label>
                  <Input
                    value={metadata.title}
                    onChange={(e) => setMetadata({ ...metadata, title: e.target.value })}
                    placeholder="Tên bài tập"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Hạn nộp bài</label>
                  <Input
                    type="datetime-local"
                    value={metadata.dueDate}
                    onChange={(e) => setMetadata({ ...metadata, dueDate: e.target.value })}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Điểm tối đa</label>
                  <Input
                    type="number"
                    value={metadata.totalPoints}
                    onChange={(e) => setMetadata({ ...metadata, totalPoints: Number(e.target.value) || 10 })}
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">Tỷ trọng điểm (%)</label>
                  <Input
                    type="number"
                    value={metadata.weightPercentage}
                    onChange={(e) => setMetadata({ ...metadata, weightPercentage: Number(e.target.value) || 10 })}
                  />
                </div>
              </div>

              {/* Grading Strategy & Late Policy */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4 rounded-xl bg-slate-50 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700/60">
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-slate-700 dark:text-slate-300 block">Chiến lược chấm điểm</label>
                  <select
                    className="w-full rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-2 text-xs"
                    value={metadata.gradingStrategy || 'CONTINUOUS_QUEUE'}
                    onChange={(e) => setMetadata({ ...metadata, gradingStrategy: e.target.value, strategy: e.target.value })}
                  >
                    <option value="CONTINUOUS_QUEUE">Chấm liên tục (Real-time khi nộp)</option>
                    <option value="BATCH_POST_DEADLINE">Chấm hàng loạt sau hạn nộp</option>
                  </select>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-slate-700 dark:text-slate-300 block">Chính sách nộp trễ</label>
                  <select
                    className="w-full rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-2 text-xs"
                    value={metadata.latePolicyOption || 'NONE_LOCKED'}
                    onChange={(e) => {
                      const opt = e.target.value
                      setMetadata({
                        ...metadata,
                        latePolicyOption: opt,
                        allowLateSubmission: opt !== 'NONE_LOCKED',
                      })
                    }}
                  >
                    <option value="NONE_LOCKED">Không chấp nhận (Khóa sau hạn)</option>
                    <option value="DAILY_POINTS">Trừ điểm theo ngày</option>
                    <option value="DAILY_PERCENT">Trừ điểm theo tỷ lệ %</option>
                    <option value="FLAT_POINTS">Trừ điểm cố định khi trễ</option>
                    <option value="NONE_FREE">Cho phép nộp trễ miễn phí</option>
                  </select>
                </div>

                {metadata.latePolicyOption && metadata.latePolicyOption !== 'NONE_LOCKED' && metadata.latePolicyOption !== 'NONE_FREE' && (
                  <>
                    <div className="space-y-1.5">
                      <label className="text-xs font-semibold text-slate-700 dark:text-slate-300 block">
                        Mức phạt {metadata.latePolicyOption === 'DAILY_PERCENT' ? '(%)' : '(điểm)'}
                      </label>
                      <Input
                        type="number"
                        min={0}
                        value={metadata.latePenaltyValue || 0}
                        onChange={(e) => setMetadata({ ...metadata, latePenaltyValue: Number(e.target.value) || 0 })}
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-semibold text-slate-700 dark:text-slate-300 block">
                        Chấp nhận trễ tối đa (giờ)
                      </label>
                      <Input
                        type="number"
                        min={1}
                        value={metadata.lateSubmitHours || 24}
                        onChange={(e) => setMetadata({ ...metadata, lateSubmitHours: Number(e.target.value) || 24 })}
                      />
                    </div>
                  </>
                )}
              </div>

              <div>
                <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block">
                  Nội dung đề bài (HTML / Markdown):
                </label>
                <textarea
                  rows={14}
                  className="w-full rounded-xl border border-slate-200 bg-white p-3 font-mono text-xs dark:bg-slate-900 dark:border-slate-800"
                  value={content}
                  onChange={(e) => setContent(e.target.value)}
                />
              </div>
            </Card>
          </div>
        )}

        {/* STEP 3: RUBRIC & PUBLISH */}
        {step === 3 && (
          <div className="space-y-6">
            <Card className="p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-xs space-y-6">
              <div className="flex items-center justify-between pb-4 border-b border-slate-100 dark:border-slate-800">
                <h2 className="text-lg font-bold text-slate-900 dark:text-white flex items-center gap-2">
                  <CheckCircle className="w-5 h-5 text-emerald-500" />
                  Barem Rubric & Phân phối lớp học
                </h2>
                <Button variant="outline" size="sm" onClick={() => setStep(2)} className="text-xs gap-1">
                  <ArrowLeft className="w-3.5 h-3.5" />
                  Chỉnh sửa đề
                </Button>
              </div>

              {/* Target Classes Selection */}
              <div className="space-y-3">
                <label className="text-xs font-semibold text-slate-700 dark:text-slate-300 block">
                  Chọn lớp học áp dụng bài tập ({availableClasses.length} lớp khả dụng):
                </label>
                {availableClasses.length === 0 ? (
                  <p className="text-xs text-amber-600 italic">Không tìm thấy lớp học nào thuộc môn {subjectCode} trong học kỳ đã chọn.</p>
                ) : (
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                    {availableClasses.map((cls) => {
                      const isSelected = selectedClasses.includes(cls.id)
                      return (
                        <div
                          key={cls.id}
                          onClick={() => {
                            if (isSelected) {
                              setSelectedClasses(selectedClasses.filter((id) => id !== cls.id))
                            } else {
                              setSelectedClasses([...selectedClasses, cls.id])
                            }
                          }}
                          className={`p-3 rounded-xl border text-xs cursor-pointer flex items-center justify-between transition-all ${
                            isSelected
                              ? 'border-orange-500 bg-orange-50 dark:bg-orange-950/30 text-orange-900 dark:text-orange-200 font-semibold'
                              : 'border-slate-200 dark:border-slate-800 hover:border-slate-300'
                          }`}
                        >
                          <span>{cls.code || cls.name}</span>
                          {isSelected && <CheckCircle className="w-4 h-4 text-orange-600 shrink-0" />}
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>

              {/* SQL Answer key if projectType is sql */}
              {blueprint?.projectType === 'sql' && (
                <div className="p-4 bg-blue-50/50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800/60 rounded-xl space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2 text-xs font-bold text-blue-900 dark:text-blue-300">
                      <Database className="w-4 h-4 text-blue-500" />
                      <span>SQL Reference Answer Key (.sql)</span>
                    </div>
                    <label className="cursor-pointer">
                      <Button variant="outline" size="sm" className="text-xs gap-1 pointer-events-none" isLoading={isUploadingAnswerKey}>
                        <Upload className="w-3.5 h-3.5" />
                        Tải file đáp án .sql
                      </Button>
                      <input type="file" accept=".sql" className="hidden" onChange={handleAnswerKeyUpload} />
                    </label>
                  </div>
                  <p className="text-xs text-blue-700 dark:text-blue-400">
                    Tải lên file SQL chứa schema tạo bảng và câu lệnh đáp án mẫu để hệ thống phân tích và điền vào barem rubric.
                  </p>
                </div>
              )}

              {/* Rubric Rules list */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-500">
                    Danh sách tiêu chí chấm điểm Rubric ({rubric?.rules?.length || 0})
                  </span>
                  <span className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                    Tổng điểm:{' '}
                    {rubric?.rules?.reduce((s: number, r: any) => s + (Number(r.weight) || 0), 0) || 0} / {metadata.totalPoints || 10}
                  </span>
                </div>

                {rubric?.rules?.map((rule: any, idx: number) => (
                  <div
                    key={idx}
                    className="p-4 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 space-y-3"
                  >
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex-1">
                        <Input
                          value={rule.title || rule.name || ''}
                          onChange={(e) => {
                            const updated = { ...rubric }
                            updated.rules[idx].title = e.target.value
                            setRubric(updated)
                          }}
                          className="font-semibold text-sm"
                          placeholder="Tên tiêu chí"
                        />
                      </div>
                      <div className="w-28 flex items-center gap-1">
                        <Input
                          type="number"
                          step="0.5"
                          value={rule.weight || 0}
                          onChange={(e) => {
                            const updated = { ...rubric }
                            updated.rules[idx].weight = parseFloat(e.target.value) || 0
                            setRubric(updated)
                          }}
                          className="text-right text-sm"
                        />
                        <span className="text-xs text-slate-500">điểm</span>
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          const updated = { ...rubric }
                          updated.rules.splice(idx, 1)
                          setRubric(updated)
                        }}
                        className="text-slate-400 hover:text-rose-600"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>

                    <textarea
                      rows={2}
                      className="w-full rounded-lg border border-slate-200 bg-white p-2 text-xs dark:bg-slate-900 dark:border-slate-800"
                      placeholder="Mô tả tiêu chuẩn đạt điểm..."
                      value={rule.description || ''}
                      onChange={(e) => {
                        const updated = { ...rubric }
                        updated.rules[idx].description = e.target.value
                        setRubric(updated)
                      }}
                    />

                    {/* Test cases / Probe specification preview */}
                    <RubricRuleSpecViewer rule={rule} />
                  </div>
                ))}
              </div>

              {/* Final Publish Button */}
              <div className="pt-4 border-t border-slate-200 dark:border-slate-800 flex items-center justify-between">
                <Button variant="ghost" onClick={() => setStep(2)}>
                  Quay lại
                </Button>
                <Button
                  onClick={handlePublish}
                  isLoading={isLoading}
                  className="bg-emerald-600 hover:bg-emerald-700 text-white gap-2 shadow-sm font-semibold"
                >
                  <CheckCircle className="w-4 h-4" />
                  Xuất bản & Giao bài tập cho học sinh
                </Button>
              </div>
            </Card>
          </div>
        )}
      </div>
    </DashboardLayout>
  )
}
export default AssignmentUploadPage

'use client'

import * as React from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { LECTURER_NAV } from '@/config/navigation'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Modal } from '@/components/ui/modal'
import { assignmentsApi } from '@/lib/api/modules/assignments'
import { gradingApi } from '@/lib/api/modules/grading'
import { errorMessage } from '@/lib/api/errors'
import {
  ArrowLeft,
  UploadCloud,
  FileArchive,
  CheckCircle2,
  XCircle,
  Clock,
  Loader2,
  StopCircle,
  RefreshCw,
  ExternalLink,
  AlertTriangle,
  RotateCcw,
  Check,
  Search,
} from 'lucide-react'
import { useLanguage } from '@/providers/language-provider'

interface BatchJob {
  id: string
  studentName: string
  studentCode?: string
  fileName: string
  state: 'queued' | 'processing' | 'completed' | 'failed'
  progressPercent: number
  currentTask: string
  error?: string
  score?: number
}

export default function BatchDashboardPage() {
  const { t } = useLanguage()
  const params = useParams()
  const router = useRouter()
  const assignmentId = params?.id ? String(params.id) : undefined

  const [assignment, setAssignment] = React.useState<any>(null)
  const [assignmentTitle, setAssignmentTitle] = React.useState('Bài tập')
  const [isUploading, setIsUploading] = React.useState(false)
  const [isCancelling, setIsCancelling] = React.useState(false)
  const [cancelModal, setCancelModal] = React.useState(false)
  const [search, setSearch] = React.useState('')
  const [filterState, setFilterState] = React.useState<'all' | 'processing' | 'completed' | 'failed'>('all')

  const fileInputRef = React.useRef<HTMLInputElement | null>(null)
  const [elapsedSeconds, setElapsedSeconds] = React.useState(0)

  // Local storage keys
  const jobsKey = assignmentId ? `batchJobs_${assignmentId}` : 'batchJobs_general'
  const startKey = assignmentId ? `batchStartTime_${assignmentId}` : 'batchStartTime_general'

  // Jobs state
  const [jobs, setJobs] = React.useState<BatchJob[]>(() => {
    if (typeof window === 'undefined') return []
    try {
      const saved = localStorage.getItem(jobsKey)
      return saved ? JSON.parse(saved) : []
    } catch {
      return []
    }
  })

  // Start time state
  const [batchStartTime, setBatchStartTime] = React.useState<number | null>(() => {
    if (typeof window === 'undefined') return null
    try {
      const saved = localStorage.getItem(startKey)
      return saved ? parseInt(saved, 10) : null
    } catch {
      return null
    }
  })

  // Load assignment details
  React.useEffect(() => {
    if (assignmentId) {
      assignmentsApi.getAssignment(assignmentId)
        .then(res => {
          setAssignment(res)
          setAssignmentTitle(res?.title || 'Bài tập')
        })
        .catch(console.error)
    }
  }, [assignmentId])

  // Save jobs to localStorage
  React.useEffect(() => {
    if (jobs.length > 0) {
      localStorage.setItem(jobsKey, JSON.stringify(jobs))
    } else {
      localStorage.removeItem(jobsKey)
    }
  }, [jobs, jobsKey])

  // Elapsed timer
  React.useEffect(() => {
    if (!batchStartTime) return
    const activeJobs = jobs.filter(j => j.state === 'queued' || j.state === 'processing')
    if (activeJobs.length === 0) return

    const interval = setInterval(() => {
      setElapsedSeconds(Math.floor((Date.now() - batchStartTime) / 1000))
    }, 1000)
    return () => clearInterval(interval)
  }, [batchStartTime, jobs])

  // Polling for batch status
  React.useEffect(() => {
    const activeJobs = jobs.filter(j => j.state === 'queued' || j.state === 'processing')
    if (activeJobs.length === 0) return

    const interval = setInterval(async () => {
      try {
        const ids = activeJobs.map(j => j.id)
        const res = await gradingApi.getBatchStatus(ids)

        if (res && res.statuses) {
          setJobs(prevJobs => {
            let changed = false
            const nextJobs = prevJobs.map(job => {
              const updated = res.statuses[job.id]
              if (updated) {
                if (
                  job.state !== updated.state ||
                  job.progressPercent !== updated.progressPercent ||
                  job.currentTask !== updated.currentTask ||
                  job.score !== updated.score
                ) {
                  changed = true
                  return {
                    ...job,
                    ...updated,
                  }
                }
              }
              return job
            })
            return changed ? nextJobs : prevJobs
          })
        }
      } catch (err) {
        console.error('Batch polling error:', err)
      }
    }, 3500)

    return () => clearInterval(interval)
  }, [jobs])

  // Multi-file upload with validation
  const handleUploadFiles = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files
    if (!fileList || fileList.length === 0) return

    const files = Array.from(fileList)

    // Validate formats
    const invalidFormatFiles = files.filter(f => !f.name.match(/\.(zip|rar|tar\.gz)$/i))
    if (invalidFormatFiles.length > 0) {
      alert(`Phát hiện ${invalidFormatFiles.length} tệp không đúng định dạng. Hệ thống chỉ hỗ trợ tệp nén ZIP, RAR hoặc TAR.GZ:\n` + invalidFormatFiles.map(f => f.name).join(', '))
      if (fileInputRef.current) fileInputRef.current.value = ''
      return
    }

    // Validate size (max 100MB per file)
    const MAX_SIZE = 100 * 1024 * 1024
    const oversizedFiles = files.filter(f => f.size > MAX_SIZE)
    if (oversizedFiles.length > 0) {
      alert(`Phát hiện ${oversizedFiles.length} tệp vượt quá giới hạn 100MB:\n` + oversizedFiles.map(f => `${f.name} (${(f.size / 1024 / 1024).toFixed(1)}MB)`).join(', '))
      if (fileInputRef.current) fileInputRef.current.value = ''
      return
    }

    setIsUploading(true)
    try {
      const res = await gradingApi.submitBatchProject(files, assignmentId)

      const newJobs: BatchJob[] = (res.jobs || []).map((job: any) => ({
        id: job.submissionId || job.id,
        studentName: job.studentName || job.name || 'Sinh viên',
        studentCode: job.studentCode || '',
        fileName: job.fileName || job.filename || 'source.zip',
        state: 'queued',
        progressPercent: 0,
        currentTask: 'Đang xếp hàng đợi chấm điểm...',
      }))

      const now = Date.now()
      setBatchStartTime(now)
      localStorage.setItem(startKey, now.toString())
      setJobs(prev => [...newJobs, ...prev])
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setIsUploading(false)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }

  // Cancel all pending jobs
  const handleCancelAll = async () => {
    const activeJobs = jobs.filter(j => j.state === 'queued' || j.state === 'processing')
    if (activeJobs.length === 0) return

    setIsCancelling(true)
    try {
      const ids = activeJobs.map(j => j.id)
      await gradingApi.cancelBatch(ids)

      // Optimistic update
      setJobs(prev =>
        prev.map(j => (ids.includes(j.id) ? { ...j, state: 'failed', error: 'Đã hủy bởi giảng viên', currentTask: 'Đã hủy' } : j))
      )
      setCancelModal(false)
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setIsCancelling(false)
    }
  }

  // Retry a single failed job
  const handleRetryJob = async (jobId: string) => {
    try {
      await gradingApi.gradeExistingSubmission(jobId)
      setJobs(prev =>
        prev.map(j => (j.id === jobId ? { ...j, state: 'queued', progressPercent: 0, currentTask: 'Đang xếp hàng thử lại...', error: undefined } : j))
      )
    } catch (err) {
      alert(errorMessage(err))
    }
  }

  // Clear batch
  const handleClearBatch = () => {
    if (!confirm('Bạn có muốn xóa dữ liệu bảng theo dõi batch này khỏi bộ nhớ tạm không?')) return
    localStorage.removeItem(jobsKey)
    localStorage.removeItem(startKey)
    setJobs([])
    setBatchStartTime(null)
    setElapsedSeconds(0)
  }

  const completedCount = jobs.filter(j => j.state === 'completed').length
  const failedCount = jobs.filter(j => j.state === 'failed').length
  const processingCount = jobs.filter(j => j.state === 'processing').length
  const queuedCount = jobs.filter(j => j.state === 'queued').length
  const totalCount = jobs.length

  const overallProgress = totalCount > 0 ? Math.round(((completedCount + failedCount) / totalCount) * 100) : 0

  const filteredJobs = jobs.filter(j => {
    if (filterState === 'completed' && j.state !== 'completed') return false
    if (filterState === 'failed' && j.state !== 'failed') return false
    if (filterState === 'processing' && (j.state !== 'processing' && j.state !== 'queued')) return false
    if (!search) return true
    const text = `${j.studentName} ${j.studentCode || ''} ${j.fileName}`.toLowerCase()
    return text.includes(search.toLowerCase())
  })

  const formatElapsed = (sec: number) => {
    const mins = Math.floor(sec / 60)
    const secs = sec % 60
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  return (
    <DashboardLayout
      navItems={LECTURER_NAV}
      roleLabel="Lecturer"
      requiredRole="lecturer"
      title="Bảng theo dõi chấm hàng loạt (Batch Dashboard)"
    >
      <div className="space-y-6 w-full pb-12">
        {/* Header Bar */}
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <button
              onClick={() => router.back()}
              className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
            >
              <ArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-400" />
            </button>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">
                  {assignmentTitle}
                </span>
                <span className="text-slate-300 dark:text-slate-700">•</span>
                <span className="text-xs text-orange-600 dark:text-orange-400 font-bold">
                  Batch Processing Pipeline
                </span>
              </div>
              <h1 className="text-xl font-bold text-slate-900 dark:text-white">
                Chấm bài hàng loạt & Giám sát tiến độ
              </h1>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            <input
              type="file"
              ref={fileInputRef}
              accept=".zip,.rar,.tar.gz"
              multiple
              onChange={handleUploadFiles}
              className="hidden"
            />
            <Button
              variant="primary"
              size="sm"
              onClick={() => fileInputRef.current?.click()}
              isLoading={isUploading}
              className="text-xs gap-1.5 bg-orange-500 hover:bg-orange-600 text-white shadow-md shadow-orange-500/20"
            >
              <UploadCloud className="w-3.5 h-3.5" />
              <span>Tải thêm file ZIP</span>
            </Button>

            {processingCount + queuedCount > 0 && (
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCancelModal(true)}
                className="text-xs gap-1.5 text-rose-600 border-rose-200 hover:bg-rose-50 dark:border-rose-900/40"
              >
                <StopCircle className="w-3.5 h-3.5" />
                <span>Hủy toàn bộ hàng đợi</span>
              </Button>
            )}

            {jobs.length > 0 && (
              <Button
                variant="outline"
                size="sm"
                onClick={handleClearBatch}
                className="text-xs gap-1.5"
              >
                <RotateCcw className="w-3.5 h-3.5" />
                <span>Xóa bảng theo dõi</span>
              </Button>
            )}
          </div>
        </div>

        {/* Aggregate Progress Banner */}
        {totalCount > 0 && (
          <div className="p-6 rounded-3xl bg-slate-900 border border-slate-800 text-white shadow-xl space-y-4">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
              <div className="space-y-1">
                <span className="text-xs font-semibold text-slate-400 uppercase tracking-wider">
                  Tiến độ chấm bài song song
                </span>
                <div className="flex items-center gap-3">
                  <span className="text-2xl font-black font-mono text-emerald-400">
                    {completedCount + failedCount} / {totalCount} bài
                  </span>
                  <span className="text-xs text-slate-400 font-mono">
                    (Thời gian thực thi: {formatElapsed(elapsedSeconds)})
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-4 text-xs font-mono">
                <span className="flex items-center gap-1.5 text-emerald-400">
                  <CheckCircle2 className="w-4 h-4" />
                  <span>Xong: {completedCount}</span>
                </span>
                <span className="flex items-center gap-1.5 text-amber-400">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Đang chạy: {processingCount + queuedCount}</span>
                </span>
                <span className="flex items-center gap-1.5 text-rose-400">
                  <XCircle className="w-4 h-4" />
                  <span>Lỗi: {failedCount}</span>
                </span>
              </div>
            </div>

            <div className="w-full bg-slate-800/80 rounded-full h-3 overflow-hidden p-0.5 border border-slate-700/50">
              <div
                className="bg-gradient-to-r from-orange-500 via-amber-400 to-emerald-400 h-full rounded-full transition-all duration-300"
                style={{ width: `${overallProgress}%` }}
              />
            </div>
          </div>
        )}

        {/* Filter & Search Bar */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
          <div className="w-full sm:max-w-xs">
            <input
              type="text"
              placeholder="Tìm theo tên sinh viên, file..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full text-xs rounded-xl border border-orange-100/90 dark:border-slate-800 bg-white dark:bg-slate-900 px-3 py-2 text-slate-900 dark:text-slate-100 focus:outline-none focus:border-orange-400"
            />
          </div>

          <div className="inline-flex p-1.5 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
            {(['all', 'processing', 'completed', 'failed'] as const).map(st => (
              <button
                key={st}
                onClick={() => setFilterState(st)}
                className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all ${
                  filterState === st
                    ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                    : 'text-slate-600 dark:text-slate-400 hover:text-orange-600 dark:hover:text-orange-400'
                }`}
              >
                {st === 'all' ? `Tất cả (${totalCount})` :
                 st === 'processing' ? `Đang chấm (${processingCount + queuedCount})` :
                 st === 'completed' ? `Hoàn thành (${completedCount})` :
                 `Lỗi (${failedCount})`}
              </button>
            ))}
          </div>
        </div>

        {/* Batch Jobs Table */}
        <div className="rounded-2xl border border-orange-100/90 dark:border-orange-900/30 overflow-hidden shadow-xs bg-white dark:bg-slate-900">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse text-sm">
              <thead>
                <tr className="border-b border-orange-100/90 bg-gradient-to-r from-orange-50/70 via-amber-50/40 to-orange-50/50 dark:bg-slate-950/60 text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                  <th className="p-4 pl-6">Sinh viên & File</th>
                  <th className="p-4">Trạng thái</th>
                  <th className="p-4">Tiến trình & Nhiệm vụ</th>
                  <th className="p-4">Điểm AI</th>
                  <th className="p-4 pr-6 text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60">
                {filteredJobs.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="p-12 text-center text-slate-400 text-xs">
                      {jobs.length === 0
                        ? 'Chưa có bài nộp nào trong phiên batch. Hãy bấm "Tải thêm file ZIP" để bắt đầu.'
                        : 'Không tìm thấy bài làm nào theo bộ lọc.'}
                    </td>
                  </tr>
                ) : (
                  filteredJobs.map((job) => {
                    const isDone = job.state === 'completed'
                    const isFail = job.state === 'failed'
                    const isRunning = job.state === 'processing' || job.state === 'queued'

                    return (
                      <tr key={job.id} className="hover:bg-slate-50/70 dark:hover:bg-slate-800/30 transition-colors">
                        <td className="p-4 pl-6">
                          <div className="font-bold text-slate-900 dark:text-white">
                            {job.studentName}
                          </div>
                          <div className="text-xs text-slate-400 font-mono flex items-center gap-1.5 pt-0.5">
                            <FileArchive className="w-3.5 h-3.5 text-orange-500" />
                            <span>{job.fileName}</span>
                          </div>
                        </td>
                        <td className="p-4">
                          <Badge variant={isDone ? 'success' : isFail ? 'danger' : 'warning'}>
                            {job.state.toUpperCase()}
                          </Badge>
                        </td>
                        <td className="p-4">
                          <div className="space-y-1.5 max-w-md">
                            <div className="flex items-center justify-between text-xs">
                              <span className="text-slate-600 dark:text-slate-300 font-mono text-[11px] truncate">
                                {job.currentTask}
                              </span>
                              <span className="font-mono font-bold text-slate-500">{job.progressPercent}%</span>
                            </div>
                            <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-1.5 overflow-hidden">
                              <div
                                className={`h-full rounded-full transition-all ${
                                  isFail ? 'bg-rose-500' : isDone ? 'bg-emerald-500' : 'bg-orange-500'
                                }`}
                                style={{ width: `${job.progressPercent}%` }}
                              />
                            </div>
                            {job.error && (
                              <p className="text-[11px] text-rose-500 font-mono">{job.error}</p>
                            )}
                          </div>
                        </td>
                        <td className="p-4">
                          {job.score !== undefined ? (
                            <span className="font-mono font-black text-emerald-600 dark:text-emerald-400 text-base">
                              {Number(job.score).toFixed(1)}
                              <span className="text-xs text-slate-400 font-normal"> / 10</span>
                            </span>
                          ) : (
                            <span className="text-xs text-slate-400">—</span>
                          )}
                        </td>
                        <td className="p-4 pr-6 text-right">
                          <div className="flex items-center justify-end gap-2">
                            {isRunning && (
                              <Link href={`/lecturer/grading/live/${job.id}?assignmentId=${assignmentId || ''}`}>
                                <Button variant="outline" size="sm" className="text-xs py-1 px-2.5 gap-1">
                                  <span>Theo dõi Live</span>
                                </Button>
                              </Link>
                            )}

                            {isDone && (
                              <Link href={`/lecturer/grading/result/${job.id}`}>
                                <Button variant="primary" size="sm" className="text-xs py-1 px-2.5 gap-1 bg-emerald-600 hover:bg-emerald-700 text-white">
                                  <ExternalLink className="w-3 h-3" />
                                  <span>Xem điểm</span>
                                </Button>
                              </Link>
                            )}

                            {isFail && (
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleRetryJob(job.id)}
                                className="text-xs py-1 px-2.5 gap-1 text-orange-600 border-orange-300 hover:bg-orange-50"
                              >
                                <RefreshCw className="w-3 h-3" />
                                <span>Thử lại</span>
                              </Button>
                            )}
                          </div>
                        </td>
                      </tr>
                    )
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Cancel Confirmation Modal */}
        <Modal
          isOpen={cancelModal}
          onClose={() => setCancelModal(false)}
          title="Hủy toàn bộ hàng đợi chấm batch"
          description="Bạn có chắc chắn muốn hủy tất cả các bài đang chờ hoặc đang chấm trong hàng đợi không?"
        >
          <div className="flex justify-end gap-3 pt-4">
            <Button variant="ghost" size="sm" onClick={() => setCancelModal(false)}>
              Quay lại
            </Button>
            <Button variant="danger" size="sm" onClick={handleCancelAll} isLoading={isCancelling}>
              Xác nhận hủy
            </Button>
          </div>
        </Modal>
      </div>
    </DashboardLayout>
  )
}

'use client'

import { RefreshAction } from '@/components/actions/RefreshAction'

import * as React from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { LECTURER_NAV } from '@/config/navigation'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { Pagination } from '@/components/ui/feedback'
import { gradingApi } from '@/lib/api/modules/grading'
import { formatDate } from '@/lib/utils'
import { errorMessage } from '@/lib/api/errors'
import {
  History,
  Search,
  Trash2,
  ExternalLink,
  Award,
  Filter,
  CheckCircle2,
  XCircle,
  Clock,
  ArrowLeft,
} from 'lucide-react'
import { useLanguage } from '@/providers/language-provider'

export default function GradingHistoryPage() {
  const { t } = useLanguage()
  const router = useRouter()

  const [history, setHistory] = React.useState<any[]>([])
  const [loading, setLoading] = React.useState(true)
  const [search, setSearch] = React.useState('')
  const [statusFilter, setStatusFilter] = React.useState('all')
  const [scoreRange, setScoreRange] = React.useState('all')
  const [page, setPage] = React.useState(1)
  const [totalPages, setTotalPages] = React.useState(1)
  const [deletingId, setDeletingId] = React.useState<string | null>(null)

  const loadHistory = React.useCallback(async (background = false) => {
    if (!background) setLoading(true)
    try {
      const res = await gradingApi.getHistory(
        undefined,
        page,
        15,
        search || undefined,
        statusFilter !== 'all' ? statusFilter : undefined,
        scoreRange !== 'all' ? scoreRange : undefined
      )
      setHistory(res?.history || [])
      setTotalPages(res?.meta?.totalPages || 1)
    } catch (err) {
      if (background) throw err
      console.error('Failed to load grading history:', err)
      setHistory([])
    } finally {
      setLoading(false)
    }
  }, [page, search, statusFilter, scoreRange])

  React.useEffect(() => {
    loadHistory()
  }, [loadHistory])

  const handleDelete = async (id: string) => {
    if (!confirm('Bạn có chắc chắn muốn xóa bản ghi lịch sử chấm này không?')) return
    setDeletingId(id)
    try {
      await gradingApi.deleteHistory(id)
      await loadHistory()
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setDeletingId(null)
    }
  }

  return (
    <DashboardLayout
      navItems={LECTURER_NAV}
      roleLabel="Lecturer"
      requiredRole="lecturer"
      title="Lịch sử chấm bài"
    >
      <div className="space-y-6 w-full pb-12">
        {/* Header Banner */}
        <div className="relative overflow-hidden rounded-2xl p-6 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <Badge variant="orange">Audit & History</Badge>
              <span className="text-xs text-slate-500 dark:text-slate-400">Ghi vết toàn bộ phiên chấm</span>
            </div>
            <h1 className="text-xl font-bold text-slate-900 dark:text-white">
              Lịch sử các phiên chấm điểm Rubric AI
            </h1>
          </div>

          <div className="flex items-center gap-2">
            <RefreshAction onRefresh={() => loadHistory(true)} disabled={loading} cachePaths={["/grading"]} />
          </div>
        </div>

        {/* Filters */}
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3">
          <div className="w-full md:max-w-sm">
            <Input
              type="text"
              placeholder="Tìm theo sinh viên, MSSV, bài thi..."
              icon={<Search className="w-4 h-4" />}
              value={search}
              onChange={(e) => {
                setSearch(e.target.value)
                setPage(1)
              }}
              className="border-orange-100/90 dark:border-slate-800 focus:border-orange-400"
            />
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            <select
              value={statusFilter}
              onChange={(e) => {
                setStatusFilter(e.target.value)
                setPage(1)
              }}
              className="px-3 py-2 rounded-xl text-xs border border-orange-100/90 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 focus:outline-none focus:border-orange-400 shadow-2xs"
            >
              <option value="all">Tất cả trạng thái</option>
              <option value="completed">Đã hoàn thành</option>
              <option value="failed">Thất bại / Lỗi</option>
              <option value="processing">Đang chấm</option>
            </select>

            <select
              value={scoreRange}
              onChange={(e) => {
                setScoreRange(e.target.value)
                setPage(1)
              }}
              className="px-3 py-2 rounded-xl text-xs border border-orange-100/90 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 focus:outline-none focus:border-orange-400 shadow-2xs"
            >
              <option value="all">Tất cả khoảng điểm</option>
              <option value="high">Điểm cao (≥ 8.0)</option>
              <option value="medium">Đạt yêu cầu (5.0 - 7.9)</option>
              <option value="low">Chưa đạt (&lt; 5.0)</option>
            </select>
          </div>
        </div>

        {/* History Table */}
        <div className="rounded-2xl border border-orange-100/90 dark:border-orange-900/30 overflow-hidden shadow-xs bg-white dark:bg-slate-900">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse text-sm">
              <thead>
                <tr className="border-b border-orange-100/90 bg-gradient-to-r from-orange-50/70 via-amber-50/40 to-orange-50/50 dark:bg-slate-950/60 text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                  <th className="p-4 pl-6">Sinh viên & MSSV</th>
                  <th className="p-4">Bài tập / Môn học</th>
                  <th className="p-4">Thời gian thực hiện</th>
                  <th className="p-4">Trạng thái</th>
                  <th className="p-4">Điểm số</th>
                  <th className="p-4 pr-6 text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60">
                {loading ? (
                  <tr>
                    <td colSpan={6} className="p-8 text-center text-slate-400 text-xs">
                      Đang tải lịch sử chấm điểm...
                    </td>
                  </tr>
                ) : history.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="p-8 text-center text-slate-400 text-xs">
                      Không tìm thấy bản ghi lịch sử nào phù hợp.
                    </td>
                  </tr>
                ) : (
                  history.map((row) => {
                    const isSucc = row.status === 'completed' || row.state === 'completed' || row.score !== undefined
                    const isFail = row.status === 'failed' || row.state === 'failed'
                    const subId = row.submissionId || row.id

                    return (
                      <tr key={row.id} className="hover:bg-slate-50/70 dark:hover:bg-slate-800/30 transition-colors">
                        <td className="p-4 pl-6">
                          <div className="font-bold text-slate-900 dark:text-white">
                            {row.studentName || row.student || 'Sinh viên'}
                          </div>
                          <div className="text-xs text-slate-400 font-mono">
                            {row.studentCode || row.studentId || 'HE170000'}
                          </div>
                        </td>
                        <td className="p-4">
                          <div className="font-semibold text-slate-800 dark:text-slate-200">
                            {row.assignmentTitle || row.assignment || 'Bài tập lập trình'}
                          </div>
                          <div className="text-xs text-slate-400">
                            {row.subjectCode || 'Môn học'}
                          </div>
                        </td>
                        <td className="p-4 text-xs text-slate-500 dark:text-slate-400">
                          {formatDate(row.createdAt || row.submittedAt)}
                        </td>
                        <td className="p-4">
                          <Badge variant={isSucc ? 'success' : isFail ? 'danger' : 'warning'}>
                            {row.status || row.state || 'Processing'}
                          </Badge>
                        </td>
                        <td className="p-4">
                          {row.score !== undefined && row.score !== null ? (
                            <span className="font-mono font-black text-emerald-600 dark:text-emerald-400 text-base">
                              {Number(row.score).toFixed(1)}
                              <span className="text-xs text-slate-400 font-normal"> / 10</span>
                            </span>
                          ) : (
                            <span className="text-xs text-slate-400">—</span>
                          )}
                        </td>
                        <td className="p-4 pr-6 text-right">
                          <div className="flex items-center justify-end gap-2">
                            {subId && (
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => router.push(`/lecturer/grading/result/${subId}`)}
                                className="text-xs py-1 px-2.5 gap-1 border-slate-200 dark:border-slate-800"
                              >
                                <ExternalLink className="w-3 h-3 text-blue-500" />
                                <span>Xem kết quả</span>
                              </Button>
                            )}

                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDelete(row.id)}
                              disabled={deletingId === row.id}
                              className="text-xs py-1 px-2 text-slate-400 hover:text-rose-500"
                              title="Xóa bản ghi"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </Button>
                          </div>
                        </td>
                      </tr>
                    )
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="p-4 border-t border-slate-200 dark:border-slate-800 flex justify-end">
            <Pagination
              page={page}
              hasNext={page < totalPages}
              loading={loading}
              onChange={(newPage) => setPage(newPage)}
            />
          </div>
        </div>
      </div>
    </DashboardLayout>
  )
}

'use client'

import * as React from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { LECTURER_NAV } from '@/config/navigation'
import { EvaluationReportViewer } from '@/features/submissions/components/EvaluationReportViewer'
import { LiveGradingRunnerModal } from '@/features/grading/components/LiveGradingRunnerModal'
import { Modal } from '@/components/ui/modal'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { submissionsApi } from '@/lib/api/modules/submissions'
import { gradingApi } from '@/lib/api/modules/grading'
import { formatDate } from '@/lib/utils'
import { errorMessage } from '@/lib/api/errors'
import {
  ArrowLeft,
  Share2,
  RotateCcw,
  Download,
  RefreshCw,
  Edit,
  Award,
  AlertTriangle,
  CheckCircle2,
  Clock,
  Sparkles,
  MessageSquare,
  ShieldAlert,
  Terminal,
} from 'lucide-react'
import { useLanguage } from '@/providers/language-provider'

export default function GradingResultPage() {
  const { t } = useLanguage()
  const params = useParams()
  const router = useRouter()
  const submissionId = String(params?.id ?? '')

  const [submission, setSubmission] = React.useState<any>(null)
  const [loading, setLoading] = React.useState(true)
  const [actionLoading, setActionLoading] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [showLiveRunner, setShowLiveRunner] = React.useState(false)

  // Edit score modal
  const [editModal, setEditModal] = React.useState({
    open: false,
    score: 0,
    feedback: '',
    isPublished: false,
  })

  // Appeal resolution modal
  const [appealModal, setAppealModal] = React.useState({
    open: false,
    decision: 'ACCEPT' as 'ACCEPT' | 'REJECT',
    adjustedScore: 0,
    resolutionNote: '',
  })

  const loadData = React.useCallback(async (quiet = false) => {
    try {
      if (!quiet) setLoading(true)
      const data = await submissionsApi.getSubmission(submissionId)
      setSubmission(data)
      setEditModal({
        open: false,
        score: Number(data.score ?? data.finalScore ?? data.rawScore ?? 0),
        feedback: data.instructorFeedback || (data as any).feedback || '',
        isPublished: !!data.isPublished,
      })
    } catch (err) {
      setError(errorMessage(err))
    } finally {
      if (!quiet) setLoading(false)
    }
  }, [submissionId])

  React.useEffect(() => {
    loadData()
  }, [loadData])
  React.useEffect(() => {
    const state = String(submission?.gradingStatus || submission?.status || '').toLowerCase()
    if (!['pending', 'queued', 'processing', 'grading'].includes(state) || submission?.reportData?.error) return
    const timer = setInterval(() => { void loadData(true) }, 5000)
    return () => clearInterval(timer)
  }, [submission?.gradingStatus, submission?.status, submission?.reportData?.error, loadData])

  // Single publish / unpublish
  const handleTogglePublish = async () => {
    if (!submission) return
    const willPublish = !submission.isPublished
    if (willPublish && (submission.score == null || submission.reportData?.error)) { alert('Lượt chấm chưa có kết quả hợp lệ. Cần chấm lại hoặc đánh giá thủ công trước khi công bố.'); return }
    setActionLoading(true)
    try {
      if (willPublish) {
        await gradingApi.publishSubmission(submission.id)
      } else {
        await gradingApi.unpublishSubmission(submission.id)
      }
      await loadData()
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setActionLoading(false)
    }
  }

  // Trigger re-grade with live in-place runner
  const handleRegrade = () => {
    if (!submission) return
    setShowLiveRunner(true)
    gradingApi.gradeExistingSubmission(submission.id).catch((err) => {
      console.warn('Backend grade trigger error:', err)
    })
  }

  // Download submission file
  const handleDownload = async () => {
    if (!submission) return
    try {
      const studentName = typeof submission.student === 'object'
        ? (submission.student?.fullName || submission.student?.name)
        : submission.student
      await gradingApi.downloadSubmission(submission.id, studentName || 'submission')
    } catch (err) {
      alert(errorMessage(err))
    }
  }

  // Save score changes
  const handleSaveScore = async () => {
    if (!submission) return
    setActionLoading(true)
    try {
      await submissionsApi.gradeSubmission(submission.id, {
        score: editModal.score,
        feedback: editModal.feedback,
        isPublished: editModal.isPublished,
      })
      setEditModal(prev => ({ ...prev, open: false }))
      await loadData()
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setActionLoading(false)
    }
  }

  // Handle in-place rule score updates from report viewer
  const handleUpdateRuleScores = async (updatedRuleScores: any[], newTotalScore: number) => {
    if (!submission) return
    setActionLoading(true)
    try {
      const formattedRuleScores = updatedRuleScores.map((r: any) => ({
        ruleId: r.ruleId || r.id,
        earnedScore: r.earnedScore !== undefined ? r.earnedScore : r.score,
        score: r.earnedScore !== undefined ? r.earnedScore : r.score,
        lecturerNote: r.lecturerNote,
        feedback: r.feedback || r.lecturerNote,
        passed: r.passed,
      }))
      const passedRules = updatedRuleScores.filter((r: any) => r.passed)
      const failedRules = updatedRuleScores.filter((r: any) => !r.passed)

      await gradingApi.updateSubmissionResult(submission.id, {
        score: newTotalScore,
        ruleScores: formattedRuleScores,
        rules: passedRules,
        failedRules: failedRules,
      })
      await loadData()
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setActionLoading(false)
    }
  }

  // Resolve student appeal
  const handleResolveAppeal = async () => {
    if (!submission) return
    setActionLoading(true)
    try {
      await submissionsApi.gradeSubmission(submission.id, {
        score: appealModal.decision === 'ACCEPT' ? appealModal.adjustedScore : Number(submission.score ?? 0),
        feedback: `${submission.instructorFeedback || ''}\n[Phản hồi phúc khảo]: ${appealModal.resolutionNote}`.trim(),
        isPublished: true,
      })
      setAppealModal(prev => ({ ...prev, open: false }))
      await loadData()
    } catch (err) {
      alert(errorMessage(err))
    } finally {
      setActionLoading(false)
    }
  }

  const studentName = typeof submission?.student === 'object'
    ? (submission?.student?.fullName || submission?.student?.name)
    : (submission?.student || 'Sinh viên')

  const studentCode = typeof submission?.studentId === 'object'
    ? (submission?.studentId?.studentCode || 'HE170000')
    : (submission?.studentId || 'HE170000')

  const rawScore = Number(submission?.rawScore ?? submission?.rawAiScore ?? submission?.score ?? 0)
  const hasScore = submission?.score != null && !submission?.reportData?.error
  const latePenalty = Number(submission?.latePenaltyAmount ?? 0)
  const finalScore = Number(submission?.finalScore ?? submission?.score ?? Math.max(0, rawScore - latePenalty))

  return (
    <DashboardLayout
      navItems={LECTURER_NAV}
      roleLabel={t('profile.role_lecturer', 'Giảng viên')}
      requiredRole="lecturer"
      title={t('lecturer.grading.result_title', 'Chi tiết bài chấm & Báo cáo Rubric')}
    >
      <div className="space-y-6 w-full pb-12">
        {/* Navigation & Action Bar */}
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <button
              onClick={() => router.back()}
              className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
            >
              <ArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-400" />
            </button>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">
                  {submission?.assignment || 'Bài tập'}
                </span>
                <span className="text-slate-300 dark:text-slate-700">•</span>
                <span className="text-xs font-mono text-slate-500">ID: {submissionId.slice(0, 8)}</span>
              </div>
              <h1 className="text-xl font-bold text-slate-900 dark:text-white">
                {studentName} ({studentCode})
              </h1>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            <Button
              variant="outline"
              size="sm"
              onClick={handleDownload}
              className="text-xs gap-1.5"
            >
              <Download className="w-3.5 h-3.5" />
              <span>Tải file bài làm</span>
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={handleRegrade}
              disabled={actionLoading}
              className="text-xs gap-1.5 border-orange-200 text-orange-600 hover:bg-orange-50 dark:border-orange-500/30 dark:text-orange-400"
            >
              <RefreshCw className="w-3.5 h-3.5" />
              <span>Chấm lại (AI)</span>
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={() => setShowLiveRunner(true)}
              className="text-xs gap-1.5 font-mono text-amber-700 dark:text-amber-300 border-amber-300 dark:border-amber-800/60 bg-amber-50/60 dark:bg-amber-950/20 hover:bg-amber-100 dark:hover:bg-amber-900/40"
              title="Xem chi tiết phiên thực thi Docker Sandbox & AI Rubric (>_ logs)"
            >
              <Terminal className="w-3.5 h-3.5 text-orange-500" />
              <span>&gt;_ Logs Sandbox & AI</span>
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={() => setEditModal({
                open: true,
                score: finalScore,
                feedback: submission?.instructorFeedback || '',
                isPublished: !!submission?.isPublished,
              })}
              className="text-xs gap-1.5"
            >
              <Edit className="w-3.5 h-3.5 text-orange-500" />
              <span>Sửa điểm</span>
            </Button>

            {submission?.isPublished ? (
              <Button
                variant="outline"
                size="sm"
                onClick={handleTogglePublish}
                disabled={actionLoading}
                className="text-xs gap-1.5 text-rose-500 border-rose-200 hover:bg-rose-50 dark:border-rose-900/40"
              >
                <RotateCcw className="w-3.5 h-3.5" />
                <span>Thu hồi công bố</span>
              </Button>
            ) : (
              <Button
                variant="primary"
                size="sm"
                onClick={handleTogglePublish}
                disabled={actionLoading}
                className="text-xs gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white"
              >
                <Share2 className="w-3.5 h-3.5" />
                <span>Công bố điểm</span>
              </Button>
            )}
          </div>
        </div>

        {/* Score Breakdown Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-xs space-y-1">
            <span className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">
              Điểm AI / Barem
            </span>
            <div className="text-2xl font-black text-slate-900 dark:text-white font-mono">
              {hasScore ? rawScore.toFixed(2) : 'Chưa có điểm'}
              <span className="text-xs text-slate-400 font-normal"> / 10</span>
            </div>
            <span className="text-[11px] text-slate-400">Điểm thô tự động tính từ Rubric</span>
          </div>

          <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-xs space-y-1">
            <span className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">
              Trừ trễ hạn / Vi phạm
            </span>
            <div className="text-2xl font-black text-rose-600 dark:text-rose-400 font-mono">
              {latePenalty > 0 ? `-${latePenalty.toFixed(2)}` : '0.00'}
            </div>
            <span className="text-[11px] text-slate-400">
              {latePenalty > 0 ? 'Áp dụng theo chính sách nộp muộn' : 'Không vi phạm thời gian nộp'}
            </span>
          </div>

          <div className="p-4 rounded-2xl bg-gradient-to-br from-orange-500/10 via-amber-500/10 to-emerald-500/10 border border-orange-500/30 rounded-2xl shadow-xs space-y-1">
            <span className="text-xs font-bold text-orange-600 dark:text-orange-400 uppercase tracking-wider block">
              Điểm chính thức
            </span>
            <div className="text-3xl font-black text-emerald-600 dark:text-emerald-400 font-mono">
              {hasScore ? finalScore.toFixed(2) : 'Chưa có điểm'}
              <span className="text-xs text-slate-400 font-normal"> / 10</span>
            </div>
            <span className="text-[11px] text-slate-500 dark:text-slate-400">Điểm sau cùng hiển thị cho sinh viên</span>
          </div>

          <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-xs space-y-1">
            <span className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">
              Trạng thái công bố
            </span>
            <div className="pt-1">
              <Badge variant={submission?.isPublished ? 'success' : 'warning'}>
                {submission?.isPublished ? 'Đã công bố điểm' : 'Bản nháp (Chưa công bố)'}
              </Badge>
            </div>
            <span className="text-[11px] text-slate-400 block pt-1">
              Nộp lúc: {submission?.submittedAt ? formatDate(submission.submittedAt) : 'Chưa rõ'}
            </span>
          </div>
        </div>

        {/* Student Appeal Notification Card if exists */}
        {submission?.studentFeedback && (
          <div className="p-5 rounded-2xl bg-amber-500/10 border border-amber-500/30 flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <MessageSquare className="w-4 h-4 text-amber-500" />
                <span className="text-xs font-bold text-amber-700 dark:text-amber-300 uppercase tracking-wider">
                  Sinh viên đã gửi phản hồi / Phúc khảo điểm bài thi
                </span>
              </div>
              <p className="text-sm text-slate-700 dark:text-slate-200 italic">
                &ldquo;{submission.studentFeedback}&rdquo;
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setAppealModal({
                open: true,
                decision: 'ACCEPT',
                adjustedScore: finalScore,
                resolutionNote: '',
              })}
              className="text-xs font-semibold shrink-0 border-amber-300 dark:border-amber-600 text-amber-700 dark:text-amber-300 hover:bg-amber-100 dark:hover:bg-amber-950/40"
            >
              Giải quyết phúc khảo
            </Button>
          </div>
        )}

        {/* Detailed Report Viewer */}
        {loading ? (
          <div className="p-12 text-center text-slate-400 text-sm">
            Đang tải dữ liệu bài làm và phân tích Rubric...
          </div>
        ) : (
          <EvaluationReportViewer
            submission={submission}
            isLecturer={true}
            onUpdateRuleScore={handleUpdateRuleScores}
          />
        )}

        {/* Edit Score Modal */}
        <Modal
          isOpen={editModal.open}
          onClose={() => setEditModal(prev => ({ ...prev, open: false }))}
          title="Điều chỉnh điểm & Nhận xét"
          description={`Sinh viên: ${studentName} (${studentCode})`}
        >
          <div className="space-y-4">
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Điểm số (Thang điểm 10)</label>
              <Input
                type="number"
                step="0.1"
                min="0"
                max="10"
                value={editModal.score}
                onChange={(e) => setEditModal({ ...editModal, score: parseFloat(e.target.value) || 0 })}
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Nhận xét của giảng viên</label>
              <textarea
                rows={4}
                placeholder="Nhập nhận xét trực tiếp cho sinh viên..."
                value={editModal.feedback}
                onChange={(e) => setEditModal({ ...editModal, feedback: e.target.value })}
                className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-950 px-3 py-2 text-xs text-slate-900 dark:text-white placeholder:text-slate-400 focus:outline-none focus:border-orange-500"
              />
            </div>

            <div className="p-3 rounded-xl bg-orange-50/60 dark:bg-orange-500/10 border border-orange-200 dark:border-orange-500/20">
              <label className="flex items-center gap-2 cursor-pointer select-none">
                <input
                  type="checkbox"
                  checked={editModal.isPublished}
                  onChange={(e) => setEditModal({ ...editModal, isPublished: e.target.checked })}
                  className="w-4 h-4 rounded text-orange-500 focus:ring-orange-500 cursor-pointer"
                />
                <span className="text-xs font-bold text-slate-900 dark:text-white">
                  Công bố điểm ngay cho sinh viên này
                </span>
              </label>
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setEditModal(prev => ({ ...prev, open: false }))}
              >
                Hủy bỏ
              </Button>
              <Button
                variant="primary"
                size="sm"
                onClick={handleSaveScore}
                isLoading={actionLoading}
              >
                Lưu điểm
              </Button>
            </div>
          </div>
        </Modal>

        {/* Appeal Resolution Modal */}
        <Modal
          isOpen={appealModal.open}
          onClose={() => setAppealModal(prev => ({ ...prev, open: false }))}
          title="Xử lý đơn phúc khảo của sinh viên"
          description={`Sinh viên: ${studentName} - Lý do: "${submission?.studentFeedback || ''}"`}
        >
          <div className="space-y-4">
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Quyết định</label>
              <div className="grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => setAppealModal(prev => ({ ...prev, decision: 'ACCEPT' }))}
                  className={`p-3 rounded-xl border text-xs font-bold text-center transition-all ${
                    appealModal.decision === 'ACCEPT'
                      ? 'border-emerald-500 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400'
                      : 'border-slate-200 dark:border-slate-800 text-slate-600'
                  }`}
                >
                  ✓ Chấp nhận phúc khảo (Điều chỉnh điểm)
                </button>
                <button
                  type="button"
                  onClick={() => setAppealModal(prev => ({ ...prev, decision: 'REJECT' }))}
                  className={`p-3 rounded-xl border text-xs font-bold text-center transition-all ${
                    appealModal.decision === 'REJECT'
                      ? 'border-rose-500 bg-rose-500/10 text-rose-600 dark:text-rose-400'
                      : 'border-slate-200 dark:border-slate-800 text-slate-600'
                  }`}
                >
                  ✗ Giữ nguyên điểm cũ
                </button>
              </div>
            </div>

            {appealModal.decision === 'ACCEPT' && (
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Điểm mới sau phúc khảo</label>
                <Input
                  type="number"
                  step="0.1"
                  min="0"
                  max="10"
                  value={appealModal.adjustedScore}
                  onChange={(e) => setAppealModal({ ...appealModal, adjustedScore: parseFloat(e.target.value) || 0 })}
                />
              </div>
            )}

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Giải thích / Ghi chú phản hồi cho sinh viên</label>
              <textarea
                rows={3}
                placeholder="Nhập lý do chấp nhận hoặc giải thích vì sao giữ nguyên điểm..."
                value={appealModal.resolutionNote}
                onChange={(e) => setAppealModal({ ...appealModal, resolutionNote: e.target.value })}
                className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-950 px-3 py-2 text-xs text-slate-900 dark:text-white placeholder:text-slate-400 focus:outline-none focus:border-orange-500"
              />
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setAppealModal(prev => ({ ...prev, open: false }))}
              >
                Hủy bỏ
              </Button>
              <Button
                variant="primary"
                size="sm"
                onClick={handleResolveAppeal}
                isLoading={actionLoading}
              >
                Xác nhận giải quyết
              </Button>
            </div>
          </div>
        </Modal>

        {/* Dynamic Sandbox & AI Live Runner Modal */}
        {showLiveRunner && submission && (
          <LiveGradingRunnerModal
            isOpen={showLiveRunner}
            onClose={() => {
              setShowLiveRunner(false)
              void loadData()
            }}
            submissionId={submission.id}
            assignmentTitle={submission.assignment?.title || submission.assignmentTitle || 'Bài tập'}
            subjectCode={submission.assignment?.subjectCode || submission.subjectCode || 'CNTT'}
            role="lecturer"
            studentName={typeof submission.student === 'object' ? (submission.student?.fullName || submission.student?.name) : submission.student}
            studentCode={typeof submission.student === 'object' ? (submission.student?.studentCode || submission.student?.studentId) : undefined}
            onFinished={() => {
              void loadData()
            }}
          />
        )}
      </div>
    </DashboardLayout>
  )
}

