                                ? 'text-slate-400 line-through'
                                : 'text-slate-600 dark:text-slate-300'
                            }`}
                          >
                            {note.timeStr}
                          </span>
                        </div>
                        <p
                          className={`text-[12px] leading-snug break-words ${
                            note.status === 'completed'
                              ? 'text-slate-400 dark:text-slate-600 line-through'
