              </div>

              {isAddingMode ? (
                <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded-xl border border-slate-200 dark:border-slate-800 animate-fade-in-up">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-[11px] font-bold tracking-wider uppercase text-slate-500">
                      {t('notes.create_note', 'Create Note')}
                    </span>
                    <button
                      onClick={() => setIsAddingMode(false)}
                      className="text-slate-400 hover:text-slate-600"
                    >
                      <X size={14} />
                    </button>
                  </div>
                  <input
                    type="time"
                    value={newNoteTime}
                    onChange={(e) => setNewNoteTime(e.target.value)}
                    className="w-full mb-2 h-8 rounded-lg border border-slate-200 text-xs px-2 focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 dark:bg-slate-800 dark:border-slate-700 dark:text-white"
                  />
                  <textarea
                    placeholder={t('notes.desc_placeholder', 'Describe note, task, or deadline...')}
                    value={newNoteContent}
                    onChange={(e) => setNewNoteContent(e.target.value)}
                    className="w-full h-16 resize-none rounded-lg border border-slate-200 text-xs p-2 focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 dark:bg-slate-800 dark:border-slate-700 dark:text-white custom-scrollbar mb-2"
                  />
                  <button
                    onClick={handleAddNote}
                    disabled={!newNoteContent.trim()}
                    className="w-full h-8 rounded-lg bg-slate-900 dark:bg-orange-500 text-white font-bold text-xs hover:bg-[#FA7014] disabled:opacity-50 transition-colors shadow-sm"
                  >
                    {t('notes.save', 'Save Note')}
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setIsAddingMode(true)}
                  className="w-full h-9 border border-dashed border-slate-300 dark:border-slate-700 rounded-xl flex items-center justify-center gap-2 text-xs font-bold text-slate-500 hover:text-orange-600 hover:border-orange-400 dark:hover:border-orange-500 hover:bg-orange-50 dark:hover:bg-orange-500/10 transition-colors"
                >
                  <Plus size={15} /> {t('notes.add_new', 'Add new note')}
                </button>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { notesApi, type NoteItem } from '@/lib/api/modules/notes'

export interface Note {
  id: string
  dateStr: string // YYYY-MM-DD
  timeStr: string // HH:mm
  content: string
  status: 'pending' | 'completed'
}

export interface NoteStatus {
  hasPending: boolean
  hasOverdue: boolean
  pendingCount: number
  overdueCount: number
  nearestMinutes: number
  nearestContent: string
  urgencyLevel: 'critical' | 'imminent' | 'warning' | 'normal'
  totalPending: number
}

export function useNotes() {
  const [notes, setNotes] = useState<Note[]>([])
  const isInitialized = useRef(false)

  // 1. Initial load from local storage for fast instant render, then sync with Neon DB
  useEffect(() => {
    let localNotes: Note[] = []
    try {
      if (typeof window !== 'undefined') {
        const stored = localStorage.getItem('aita_calendar_notes')
        if (stored) {
          localNotes = JSON.parse(stored)
          setNotes(localNotes)
        }
      }
    } catch (error) {
      console.error('Failed to parse notes from local storage:', error)
    }

    // Fetch and sync with Neon PostgreSQL backend
    notesApi
      .getNotes()
      .then((serverNotes) => {
        if (serverNotes && serverNotes.length > 0) {
          // If we had local offline notes not on server, sync them
          const serverIds = new Set(serverNotes.map((n) => n.id))
          const uncommitted = localNotes.filter((n) => !serverIds.has(n.id))

          if (uncommitted.length > 0) {
            notesApi.syncNotes([...serverNotes, ...uncommitted]).then((merged) => {
              if (merged) {
                setNotes(merged)
                localStorage.setItem('aita_calendar_notes', JSON.stringify(merged))
              }
            }).catch(() => {
              setNotes(serverNotes)
              localStorage.setItem('aita_calendar_notes', JSON.stringify(serverNotes))
            })
          } else {
            setNotes(serverNotes)
            localStorage.setItem('aita_calendar_notes', JSON.stringify(serverNotes))
          }
        } else if (localNotes.length > 0) {
          // Push initial local notes to Neon DB
          notesApi.syncNotes(localNotes).then((saved) => {
            if (saved) {
              setNotes(saved)
              localStorage.setItem('aita_calendar_notes', JSON.stringify(saved))
            }
          }).catch(console.warn)
        }
        isInitialized.current = true
      })
      .catch((err) => {
        // Backend might be offline or starting up, keep local notes
        console.warn('Backend notes fetch fallback to local storage:', err)
        isInitialized.current = true
      })
  }, [])

  // Save to local storage whenever notes change
  const saveNotes = useCallback((newNotes: Note[]) => {
    setNotes(newNotes)
    if (typeof window !== 'undefined') {
      localStorage.setItem('aita_calendar_notes', JSON.stringify(newNotes))
    }
  }, [])

  const addNote = useCallback(
    (dateStr: string, timeStr: string, content: string) => {
      const tempId = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : Math.random().toString(36).substring(2, 9)
      const newNote: Note = {
        id: tempId,
        dateStr,
        timeStr,
        content,
        status: 'pending',
      }
      saveNotes([...notes, newNote])

      // Persist to Neon DB
      notesApi
        .createNote({ dateStr, timeStr, content, status: 'pending' })
        .then((created) => {
          if (created && created.id) {
            setNotes((prev) =>
              prev.map((n) => (n.id === tempId ? { ...n, id: created.id } : n))
            )
          }
        })
        .catch((err) => {
          console.warn('Failed to save note to Neon DB, stored locally:', err)
        })
    },
    [notes, saveNotes]
  )

  const deleteNote = useCallback(
    (id: string) => {
      saveNotes(notes.filter((n) => n.id !== id))
      // Delete from Neon DB
      notesApi.deleteNote(id).catch((err) => {
        console.warn('Failed to delete note from Neon DB:', err)
      })
    },
    [notes, saveNotes]
  )

  const toggleNoteStatus = useCallback(
    (id: string) => {
      const target = notes.find((n) => n.id === id)
      const nextStatus = target?.status === 'pending' ? 'completed' : 'pending'

      saveNotes(
        notes.map((n) =>
          n.id === id ? { ...n, status: nextStatus } : n
        )
      )

      // Update in Neon DB
      notesApi.updateNote(id, { status: nextStatus }).catch((err) => {
        console.warn('Failed to update note in Neon DB:', err)
      })
    },
    [notes, saveNotes]
  )

  // Get notes for a specific date (YYYY-MM-DD)
  const getNotesForDate = useCallback(
    (dateStr: string) => {
      return notes
        .filter((n) => n.dateStr === dateStr)
        .sort((a, b) => a.timeStr.localeCompare(b.timeStr))
    },
    [notes]
  )

  // Get overdue/pending/approaching notes with urgency levels
  const getCurrentStatus = useCallback(
    (now: Date): NoteStatus => {
      let hasPending = false
      let hasOverdue = false
      let pendingCount = 0
      let overdueCount = 0
      let nearestMinutes = Infinity
      let nearestContent = ''

      const nowIso = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString()
      const currentComparable = nowIso.replace('T', ' ').substring(0, 16)
      const nowMs = now.getTime()

      notes.forEach((note) => {
        if (note.status === 'pending') {
          const noteComparable = `${note.dateStr} ${note.timeStr}`
          const [y, m, d] = note.dateStr.split('-').map(Number)
          const [h, min] = note.timeStr.split(':').map(Number)
          const noteDate = new Date(y, m - 1, d, h, min)
          const diffMs = noteDate.getTime() - nowMs
          const diffMin = diffMs / 60000

          if (currentComparable > noteComparable) {
            hasOverdue = true
            overdueCount++
          } else {
            hasPending = true
            pendingCount++
            if (diffMin < nearestMinutes) {
              nearestMinutes = diffMin
              nearestContent = note.content
            }
          }
        }
      })

      // urgencyLevel: 'critical' (overdue), 'imminent' (<10min), 'warning' (<30min), 'normal'
      let urgencyLevel: 'critical' | 'imminent' | 'warning' | 'normal' = 'normal'
      if (hasOverdue) urgencyLevel = 'critical'
      else if (nearestMinutes <= 10) urgencyLevel = 'imminent'
      else if (nearestMinutes <= 30) urgencyLevel = 'warning'

      return {
        hasPending,
        hasOverdue,
        pendingCount,
        overdueCount,
        nearestMinutes: nearestMinutes === Infinity ? -1 : Math.round(nearestMinutes),
        nearestContent,
        urgencyLevel,
        totalPending: pendingCount + overdueCount,
      }
    },
    [notes]
  )

  return {
    notes,
    addNote,
    deleteNote,
    toggleNoteStatus,
    getNotesForDate,
    getCurrentStatus,
  }
}

'use client'

import * as React from 'react'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { ADMIN_NAV } from '@/config/navigation'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Modal } from '@/components/ui/modal'
import { notificationsApi } from '@/lib/api/modules/notifications'
import { useNotificationInbox } from '../hooks/useNotificationInbox'
import { NotificationSyncStatus } from '../components/NotificationSyncStatus'
import {
  Bell,
  CheckCircle2,
  ArrowRight,
  Shield,
  Users,
  Settings,
  AlertTriangle,
  CheckCheck,
  Send,
  MessageSquare,
  Trash2,
} from 'lucide-react'
import { useLanguage } from '@/providers/language-provider'


export default function AdminNotificationsPage() {
  const { t } = useLanguage()
  const { notifications, filter, setFilter, loading, working, error, hasMore, loadMore, loadNotifications,
    unreadCount, visibleNotifications, resolveTarget, handleItemClick, handleMarkAllAsRead, handleDeleteOne, handleDeleteAll } = useNotificationInbox('admin')
  const [broadcastModal, setBroadcastModal] = React.useState(false)
  const [broadcasting, setBroadcasting] = React.useState(false)
  const [broadcastData, setBroadcastData] = React.useState({ title: '', message: '', targetRole: 'ALL' })
  const handleBroadcast = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!broadcastData.title.trim() || !broadcastData.message.trim()) return
    setBroadcasting(true)
    try {
      await notificationsApi.broadcastNotification({
        title: broadcastData.title,
        message: broadcastData.message,
        targetRole: broadcastData.targetRole,
        type: 'SYSTEM_UPDATE'
      })
      setBroadcastModal(false)
      setBroadcastData({ title: '', message: '', targetRole: 'ALL' })
      alert(t('admin.notifications.broadcast_success', 'Gửi thông báo thành công!'))
      loadNotifications()
    } catch (err: any) {
      alert(err?.message || t('admin.notifications.broadcast_error', 'Không thể gửi thông báo.'))
    } finally {
      setBroadcasting(false)
    }
  }

  const renderIcon = (type: string, title: string) => {
    const t = String(type || '').toUpperCase()
    const text = String(title || '').toLowerCase()

    if (t === 'SYSTEM_UPDATE' || text.includes('cập nhật')) {
      return (
        <div className="w-10 h-10 rounded-xl bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0 shadow-2xs">
          <Settings className="w-5 h-5" />
        </div>
      )
    }

    if (t === 'SYSTEM_ALERT' || text.includes('cảnh báo')) {
      return (
        <div className="w-10 h-10 rounded-xl bg-rose-50 dark:bg-rose-950/40 text-rose-600 dark:text-rose-400 flex items-center justify-center shrink-0 shadow-2xs">
          <AlertTriangle className="w-5 h-5" />
        </div>
      )
    }

    if (t === 'USER_REGISTER' || text.includes('người dùng') || text.includes('giảng viên')) {
      return (
        <div className="w-10 h-10 rounded-xl bg-indigo-50 dark:bg-indigo-950/40 text-indigo-600 dark:text-indigo-400 flex items-center justify-center shrink-0 shadow-2xs">
          <Users className="w-5 h-5" />
        </div>
      )
    }

