} from 'lucide-react'

type TabType = 'curriculum' | 'all_semesters' | 'classes'

export default function AdminSeasonsPage() {
  const { t } = useLanguage()

  // Primary Data
  const [semesters, setSemesters] = React.useState<SemesterRow[]>([])
  const [loading, setLoading] = React.useState(true)
  const [error, setError] = React.useState<string | null>(null)
  const [refreshing, setRefreshing] = React.useState(false)

  // Navigation & View Mode
  const [activeTab, setActiveTab] = React.useState<TabType>('curriculum')
  const [selectedSeason, setSelectedSeason] = React.useState<string | null>(null)
  const [selectedSemesterId, setSelectedSemesterId] = React.useState<string | null>(null)
  
  // Search & Filters
  const [subjectSearch, setSubjectSearch] = React.useState('')
  const [semesterTableSearch, setSemesterTableSearch] = React.useState('')
  const [semesterSeasonFilter, setSemesterSeasonFilter] = React.useState<string>('all')

  // Date / Month / Year Filters for Seasons
  const [selectedYear, setSelectedYear] = React.useState<string>('all')
  const [dateRangeFilter, setDateRangeFilter] = React.useState<{ start: string; end: string }>({ start: '', end: '' })

  // Sub-data for selected semester
  const [semesterSubjects, setSemesterSubjects] = React.useState<SubjectRow[]>([])
  const [loadingSubjects, setLoadingSubjects] = React.useState(false)

  // Classes inspection modal/drawer
  const [inspectClassesModal, setInspectClassesModal] = React.useState(false)
  const [inspectSubject, setInspectSubject] = React.useState<SubjectRow | null>(null)
  const [inspectClassesList, setInspectClassesList] = React.useState<ClassRow[]>([])
  const [loadingInspectClasses, setLoadingInspectClasses] = React.useState(false)

  // Create Season Modal
  const [seasonModalOpen, setSeasonModalOpen] = React.useState(false)
  const [seasonForm, setSeasonForm] = React.useState<{
    seasonType: CanonicalSeason
    year: number
    startDate: string
    endDate: string
  }>({
    seasonType: 'Fall',
    year: new Date().getFullYear(),
    startDate: `${new Date().getFullYear()}-09-01`,
    endDate: `${new Date().getFullYear()}-12-31`,
  })

  // Create Single Semester Modal
  const [singleSemesterModalOpen, setSingleSemesterModalOpen] = React.useState(false)
  const [singleSemesterForm, setSingleSemesterForm] = React.useState({
    code: '',
    season: '',
    startDate: '',
    endDate: '',
  })

  // Edit Semester Modal
  const [editSemesterModalOpen, setEditSemesterModalOpen] = React.useState(false)
  const [editingSemester, setEditingSemester] = React.useState<SemesterRow | null>(null)
  const [editSemesterForm, setEditSemesterForm] = React.useState({
    code: '',
    season: '',
    startDate: '',
    endDate: '',
  })

  // Add Subjects Modal
  const [addSubjectModalOpen, setAddSubjectModalOpen] = React.useState(false)
  const [allSubjects, setAllSubjects] = React.useState<SubjectRow[]>([])
  const [loadingAllSubjects, setLoadingAllSubjects] = React.useState(false)
  const [addSubjectSearch, setAddSubjectSearch] = React.useState('')
  const [selectedSubjectIdsToAdd, setSelectedSubjectIdsToAdd] = React.useState<Set<string>>(new Set())

  // Class Modal
  const [classModalOpen, setClassModalOpen] = React.useState(false)
  const [editingClassId, setEditingClassId] = React.useState<string | null>(null)
  const [classForm, setClassForm] = React.useState({ code: '', lecturerId: '', subjectId: '' })
  const [lecturers, setLecturers] = React.useState<UserRow[]>([])

  // Action status & Delete Confirmation
  const [saving, setSaving] = React.useState(false)
  const [deleteModal, setDeleteModal] = React.useState<{
    isOpen: boolean
    title: string
    description: string
    onConfirm: () => Promise<void>
  }>({
    isOpen: false,
    title: '',
    description: '',
    onConfirm: async () => {},
  })

  // Current system season calculation
  const currentAcademicSeason = React.useMemo(() => getSeasonFromDate(new Date()), [])

  // Load all semesters
  const loadSemesters = React.useCallback(async (silently = false) => {
    if (!silently) setLoading(true)
    else setRefreshing(true)
    try {
      const data = await semestersApi.getSemesters()
      setSemesters(data || [])
      setError(null)
    } catch (cause) {
      if (silently) throw cause
      setError(errorMessage(cause))
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [])

  React.useEffect(() => {
    void loadSemesters()
  }, [loadSemesters])

  // Group semesters by season
  const groupedSeasons = React.useMemo(() => {
    return semesters.reduce((acc, sem) => {
      const s = sem.season || 'Chưa phân nhóm'
      if (!acc[s]) acc[s] = []
      acc[s].push(sem)
      return acc
    }, {} as Record<string, SemesterRow[]>)
  }, [semesters])

  const seasonNames = React.useMemo(() => Object.keys(groupedSeasons), [groupedSeasons])

  // Extract all distinct academic years from semesters and current date
  const availableYears = React.useMemo(() => {
    const years = new Set<number>()
    semesters.forEach(s => {
      if (s.startDate) {
        years.add(new Date(s.startDate).getFullYear())
      }
      if (s.endDate) {
        years.add(new Date(s.endDate).getFullYear())
      }
      const parsed = parseInt(s.code, 10)
      if (parsed > 2000 && parsed < 2100) {
        years.add(parsed)
      }
      const match = s.season?.match(/\b(20\d{2})\b/)
      if (match) {
        years.add(parseInt(match[1], 10))
      }
    })
    years.add(new Date().getFullYear())
    return Array.from(years).sort((a, b) => b - a)
  }, [semesters])

  // Filter season names by year and custom date range
  const filteredSeasonNames = React.useMemo(() => {
    return seasonNames.filter(season => {
      const sems = groupedSeasons[season] || []
      // Filter by selected year
      if (selectedYear !== 'all') {
        const y = parseInt(selectedYear, 10)
        const matchYear = sems.some(s => {
          const semYear = s.startDate ? new Date(s.startDate).getFullYear() : (parseInt(s.code, 10) || null)
          return semYear === y || (s.season && s.season.includes(selectedYear))
        })
        if (!matchYear) return false
      }
      // Filter by custom start date
      if (dateRangeFilter.start) {
        const filterStart = new Date(dateRangeFilter.start).getTime()
        const matchStart = sems.some(s => !s.endDate || new Date(s.endDate).getTime() >= filterStart)
        if (!matchStart) return false
      }
      // Filter by custom end date
      if (dateRangeFilter.end) {
        const filterEnd = new Date(dateRangeFilter.end).getTime()
        const matchEnd = sems.some(s => !s.startDate || new Date(s.startDate).getTime() <= filterEnd)
        if (!matchEnd) return false
      }
      return true
    })
  }, [seasonNames, groupedSeasons, selectedYear, dateRangeFilter])

  // Automatically select the active season or first season in filtered list
  React.useEffect(() => {
    if (filteredSeasonNames.length > 0) {
      if (!selectedSeason || !filteredSeasonNames.includes(selectedSeason)) {
        // Prioritize active season
        const activeSem = semesters.find(s => s.isActive && s.season && filteredSeasonNames.includes(s.season))
        if (activeSem?.season) {
          setSelectedSeason(activeSem.season)
        } else {
          setSelectedSeason(filteredSeasonNames[0])
        }
      }
    }
  }, [filteredSeasonNames, selectedSeason, semesters])

  // List of terms in current season
  const currentSeasonSemesters = React.useMemo(() => {
    if (!selectedSeason || !groupedSeasons[selectedSeason]) return []
    return [...groupedSeasons[selectedSeason]].sort((a, b) => {
      const numA = parseInt(a.code.replace(/\D/g, '') || '0', 10)
      const numB = parseInt(b.code.replace(/\D/g, '') || '0', 10)
      if (numA && numB) return numA - numB
      return a.code.localeCompare(b.code)
    })
  }, [selectedSeason, groupedSeasons])

  // Automatically select the first term if none selected
  React.useEffect(() => {
    if (currentSeasonSemesters.length > 0) {
      if (!selectedSemesterId || !currentSeasonSemesters.some(s => s.id === selectedSemesterId)) {
        setSelectedSemesterId(currentSeasonSemesters[0].id)
      }
    } else {
      setSelectedSemesterId(null)
    }
  }, [currentSeasonSemesters, selectedSemesterId])

  // Load subjects whenever selectedSemesterId changes
  const loadSemesterSubjects = React.useCallback(async (semId: string) => {
    setLoadingSubjects(true)
    try {
      const data = await semestersApi.getSemesterSubjects(semId)
      setSemesterSubjects(data || [])
    } catch (cause) {
      console.error(cause)
      setSemesterSubjects([])
    } finally {
      setLoadingSubjects(false)
    }
  }, [])

  React.useEffect(() => {
    if (selectedSemesterId) {
      void loadSemesterSubjects(selectedSemesterId)
    } else {
      setSemesterSubjects([])
    }
  }, [selectedSemesterId, loadSemesterSubjects])

  // Active semester info
  const activeSemesterRow = React.useMemo(() => {
    return semesters.find(s => s.isActive) || null
  }, [semesters])

  const activeSeasonName = React.useMemo(() => {
    return activeSemesterRow?.season || null
  }, [activeSemesterRow])

  // Filtered subjects in the current selected term
  const filteredSubjects = React.useMemo(() => {
    if (!subjectSearch.trim()) return semesterSubjects
    const q = subjectSearch.toLowerCase().trim()
    return semesterSubjects.filter(
      s => s.code.toLowerCase().includes(q) || s.name.toLowerCase().includes(q)
    )
  }, [semesterSubjects, subjectSearch])

  // Filtered semesters for Tab 2 (All Semesters Table)
  const filteredTableSemesters = React.useMemo(() => {
    return semesters.filter(sem => {
      const matchSeason = semesterSeasonFilter === 'all' || sem.season === semesterSeasonFilter
      const q = semesterTableSearch.toLowerCase().trim()
      const matchQuery =
        !q ||
        sem.code.toLowerCase().includes(q) ||
        (sem.season && sem.season.toLowerCase().includes(q))
      return matchSeason && matchQuery
    })
  }, [semesters, semesterSeasonFilter, semesterTableSearch])

  // KPI Calculations
  const totalSeasonsCount = seasonNames.length
  const totalSemestersCount = semesters.length
  const totalSubjectsCount = semesters.reduce((sum, s) => sum + (s.subjectCount || 0), 0)
  const totalClassesCount = semesters.reduce((sum, s) => sum + (s.classCount || 0), 0)

  // Handlers for Season Management
  const handleActivateSeason = async (season: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation()
    setSaving(true)
    try {
      await semestersApi.activateSeason(season)
      await loadSemesters(true)
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  const handleDeleteSeasonPrompt = (season: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation()
    setDeleteModal({
      isOpen: true,
      title: `Xác nhận xóa toàn bộ Chu kỳ "${season}"?`,
      description: `Hành động này sẽ xóa toàn bộ các học kỳ, danh sách môn học liên kết và lớp học phần thuộc chu kỳ ${season}. Thao tác không thể hoàn tác!`,
      onConfirm: async () => {
        try {
          await semestersApi.deleteSeason(season)
          setDeleteModal(prev => ({ ...prev, isOpen: false }))
          if (selectedSeason === season) {
            setSelectedSeason(null)
          }
          await loadSemesters()
        } catch (cause) {
          alert(errorMessage(cause))
        }
      },
    })
  }

  // Preset date update for Season creation
  const handleSeasonTypeChange = (type: CanonicalSeason) => {
    const y = seasonForm.year
    let start = `${y}-09-01`
    let end = `${y}-12-31`
    if (type === 'Spring') {
      start = `${y}-01-15`
      end = `${y}-05-30`
    } else if (type === 'Summer') {
      start = `${y}-06-01`
      end = `${y}-08-31`
    }
    setSeasonForm(prev => ({
      ...prev,
      seasonType: type,
      startDate: start,
      endDate: end,
    }))
  }

  const handleCreateSeasonSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (saving) return
    const seasonName = `${seasonForm.seasonType} ${seasonForm.year}`
    setSaving(true)
    try {
      await semestersApi.createSeason({
        season: seasonName,
        startDate: seasonForm.startDate || undefined,
        endDate: seasonForm.endDate || undefined,
      })
      setSeasonModalOpen(false)
      setSelectedSeason(seasonName)
      await loadSemesters()
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  // Create Single Semester Submit
  const handleCreateSingleSemester = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!singleSemesterForm.code.trim() || saving) return
    setSaving(true)
    try {
      await semestersApi.createSemester({
        code: singleSemesterForm.code.trim(),
        season: singleSemesterForm.season.trim() || undefined,
        startDate: singleSemesterForm.startDate || undefined,
        endDate: singleSemesterForm.endDate || undefined,
        isActive: false,
      })
      setSingleSemesterModalOpen(false)
      setSingleSemesterForm({ code: '', season: '', startDate: '', endDate: '' })
      await loadSemesters()
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  // Edit Semester
  const handleOpenEditSemester = (sem: SemesterRow, e?: React.MouseEvent) => {
    if (e) e.stopPropagation()
    setEditingSemester(sem)
    setEditSemesterForm({
      code: sem.code || '',
      season: sem.season || '',
      startDate: sem.startDate ? sem.startDate.slice(0, 10) : '',
      endDate: sem.endDate ? sem.endDate.slice(0, 10) : '',
    })
    setEditSemesterModalOpen(true)
  }

  const handleUpdateSemesterSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!editingSemester || saving) return
    setSaving(true)
    try {
      await semestersApi.updateSemester(editingSemester.id, {
        code: editSemesterForm.code.trim(),
        season: editSemesterForm.season.trim() || undefined,
        startDate: editSemesterForm.startDate || undefined,
        endDate: editSemesterForm.endDate || undefined,
      })
      setEditSemesterModalOpen(false)
      setEditingSemester(null)
      await loadSemesters()
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  const handleDeleteSemesterPrompt = (sem: SemesterRow, e?: React.MouseEvent) => {
    if (e) e.stopPropagation()
    setDeleteModal({
      isOpen: true,
      title: `Xóa học kỳ "${sem.code}"?`,
      description: `Học kỳ này và các liên kết môn học sẽ bị xóa. Các lớp học phần có thể cần được phân bổ lại.`,
      onConfirm: async () => {
        try {
          await semestersApi.deleteSemester(sem.id)
          setDeleteModal(prev => ({ ...prev, isOpen: false }))
          await loadSemesters()
        } catch (cause) {
          alert(errorMessage(cause))
        }
      },
    })
  }

  // Subject Management inside Semester
  const handleOpenAddSubjects = async () => {
    if (!selectedSemesterId) return
    setAddSubjectModalOpen(true)
    setLoadingAllSubjects(true)
    setSelectedSubjectIdsToAdd(new Set())
    setAddSubjectSearch('')
    try {
      const subs = await subjectsApi.getSubjects(1, 500)
      setAllSubjects(subs || [])
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setLoadingAllSubjects(false)
    }
  }

  const handleAddSemesterSubjectsSubmit = async () => {
    if (!selectedSemesterId || selectedSubjectIdsToAdd.size === 0) return
    setSaving(true)
    try {
      await semestersApi.addSemesterSubjects(selectedSemesterId, Array.from(selectedSubjectIdsToAdd))
      await loadSemesterSubjects(selectedSemesterId)
      await loadSemesters(true)
      setAddSubjectModalOpen(false)
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  const handleRemoveSemesterSubject = async (subId: string, subName: string) => {
    if (!selectedSemesterId) return
    setDeleteModal({
      isOpen: true,
      title: `Gỡ môn học khỏi kỳ này?`,
      description: `Bạn có chắc muốn gỡ môn "${subName}" khỏi học kỳ hiện tại? Các lớp học phần đã mở của môn này trong kỳ vẫn được giữ nguyên.`,
      onConfirm: async () => {
        try {
          await semestersApi.removeSemesterSubject(selectedSemesterId, subId)
          setSemesterSubjects(prev => prev.filter(s => s.id !== subId))
          setDeleteModal(prev => ({ ...prev, isOpen: false }))
          await loadSemesters(true)
        } catch (cause) {
          alert(errorMessage(cause))
        }
      },
    })
  }

  // Inspect Classes of a Subject
  const handleInspectClasses = async (sub: SubjectRow) => {
    if (!selectedSemesterId) return
    setInspectSubject(sub)
    setInspectClassesModal(true)
    setLoadingInspectClasses(true)
    try {
      const data = await semestersApi.getClassesBySubject(selectedSemesterId, sub.id)
      setInspectClassesList(data || [])
    } catch (cause) {
      console.error(cause)
      setInspectClassesList([])
    } finally {
      setLoadingInspectClasses(false)
    }
  }

  // Class Management Handlers
  const handleOpenCreateClassForSubject = async (subId: string) => {
    if (!selectedSemesterId) return
    setEditingClassId(null)
    setClassForm({ code: '', lecturerId: '', subjectId: subId })
    setClassModalOpen(true)
    if (lecturers.length === 0) {
      try {
        const rows: UserRow[] = []
        for (let p = 1; p <= 5; p++) {
          const batch = await usersApi.getUsers('lecturer', p, 100)
          rows.push(...batch)
          if (batch.length < 100) break
        }
        setLecturers(rows)
      } catch (cause) {
        console.error(cause)
      }
    }
  }

  const handleSaveClassSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedSemesterId || !classForm.subjectId || !classForm.code.trim() || saving) return
    setSaving(true)
    try {
      const payload = {
        code: classForm.code.trim().toUpperCase(),
        subjectId: classForm.subjectId,
        semesterId: selectedSemesterId,
        ...(classForm.lecturerId ? { lecturerId: classForm.lecturerId } : {}),
      }
      if (editingClassId) {
        await classesApi.updateClass(editingClassId, { ...payload, keepExistingInstructors: false })
      } else {
        await classesApi.createClass(payload)
      }
      setClassModalOpen(false)
      if (inspectSubject && inspectSubject.id === classForm.subjectId) {
        const data = await semestersApi.getClassesBySubject(selectedSemesterId, inspectSubject.id)
        setInspectClassesList(data || [])
      }
      await loadSemesters(true)
    } catch (cause) {
      alert(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  const selectedSemesterObj = React.useMemo(() => {
    return semesters.find(s => s.id === selectedSemesterId) || null
  }, [semesters, selectedSemesterId])

  // Neutral icon for seasons (no distracting colors)
  const getSeasonVisual = (seasonName: string) => {
    const lower = seasonName.toLowerCase()
    let icon = Leaf
    if (lower.includes('spring') || lower.includes('xuân')) {
      icon = Flower2
    } else if (lower.includes('summer') || lower.includes('hè')) {
      icon = Sun
    }
    return {
      icon,
      color: 'text-slate-500 dark:text-slate-400',
      bg: 'bg-slate-100 dark:bg-slate-800 border-slate-200/80 dark:border-slate-700',
    }
  }

  return (
    <DashboardLayout
      navItems={ADMIN_NAV}
      title="AITA Admin"
      roleLabel={t('profile.role_admin', 'Quản trị viên')}
      requiredRole="admin"
      headerTitle={t('admin.seasons.title', 'Chương trình Đào tạo & Quản lý Học kỳ')}
      headerSubtitle={t(
        'admin.seasons.subtitle',
        'Điều phối chu kỳ năm học (Seasons), lộ trình 9 kỳ đào tạo, phân bổ môn học và lớp học phần'
      )}
    >
      <div className="w-full space-y-6 pb-12">
        {/* ── 1. HEADER EXECUTIVE ACTION TOOLBAR ── */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 sm:p-5 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800 shadow-xs">
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-2xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/20 shrink-0">
              <Layers className="w-6 h-6" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base font-extrabold text-slate-900 dark:text-white">
                  Quản lý Chương trình & Học kỳ
                </h2>
                {activeSeasonName && (
                  <Badge variant="success" className="text-[11px] font-bold">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                    Kỳ hiện tại: {activeSeasonName}
                  </Badge>
                )}
              </div>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                Chu kỳ đào tạo hiện tại của năm học: <span className="font-semibold text-slate-700 dark:text-slate-300">{currentAcademicSeason.label} ({currentAcademicSeason.nameVi})</span>
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2.5 flex-wrap w-full sm:w-auto">
            <RefreshAction onRefresh={() => loadSemesters(true)} disabled={loading} busy={refreshing} cachePaths={["/semesters"]} />

            <Button
              variant="outline"
              size="sm"
              onClick={() => setSingleSemesterModalOpen(true)}
              className="gap-1.5 text-xs rounded-xl border-slate-200 dark:border-slate-800"
            >
              <CalendarDays className="w-3.5 h-3.5 text-slate-500" />
              <span>Tạo Kỳ riêng lẻ</span>
            </Button>

            <Button
              variant="primary"
              size="sm"
              onClick={() => {
                setSeasonForm({
                  seasonType: currentAcademicSeason.season,
                  year: currentAcademicSeason.year,
                  startDate: `${currentAcademicSeason.year}-09-01`,
                  endDate: `${currentAcademicSeason.year}-12-31`,
                })
                setSeasonModalOpen(true)
              }}
              className="gap-1.5 text-xs rounded-xl font-bold shadow-sm"
            >
              <Plus className="w-4 h-4" />
              <span>Khởi tạo Season mới</span>
            </Button>
          </div>
        </div>



        {error && <ErrorNotice message={error} onRetry={() => void loadSemesters()} />}

        {/* ── 2. COMPACT DATE & SEASON FILTER BAR ── */}
        <div className="p-3.5 sm:p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800 shadow-xs space-y-3">
          {/* Top row: Section Title + Year & Date Range Filters */}
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-3 pb-3 border-b border-slate-100 dark:border-slate-800">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-orange-50 dark:bg-orange-950/40 text-orange-600 dark:text-orange-400 flex items-center justify-center shrink-0 border border-orange-200/60 dark:border-orange-900/60">
                <CalendarDays className="w-4 h-4" />
              </div>
              <div>
                <h3 className="text-xs font-bold uppercase tracking-wider text-slate-800 dark:text-slate-200 flex items-center gap-2">
                  <span>Lọc & Chọn Chu kỳ Học kỳ</span>
                  <span className="text-[11px] font-normal text-slate-400">
                    ({filteredSeasonNames.length} chu kỳ)
                  </span>
                </h3>
                <p className="text-[11px] text-slate-500">
                  Lọc theo năm đào tạo và khoảng thời gian (ngày / tháng / năm)
                </p>
              </div>
            </div>

            {/* Date / Month / Year Filters */}
            <div className="flex items-center gap-2 flex-wrap">
              {/* Year Selector */}
              <div className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-800/60 border border-slate-200/80 dark:border-slate-800 rounded-xl px-2.5 py-1">
                <span className="text-[11px] font-semibold text-slate-500">Năm:</span>
                <select
                  value={selectedYear}
                  onChange={e => setSelectedYear(e.target.value)}
                  className="bg-transparent text-xs font-bold text-slate-800 dark:text-slate-200 focus:outline-none cursor-pointer"
                >
                  <option value="all">Tất cả năm</option>
                  {availableYears.map(y => (
                    <option key={y} value={String(y)}>{y}</option>
                  ))}
                </select>
              </div>

              {/* Date From */}
              <div className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-800/60 border border-slate-200/80 dark:border-slate-800 rounded-xl px-2.5 py-1">
                <span className="text-[11px] font-semibold text-slate-500">Từ ngày:</span>
                <input
                  type="date"
                  value={dateRangeFilter.start}
                  onChange={e => setDateRangeFilter(prev => ({ ...prev, start: e.target.value }))}
                  className="bg-transparent text-xs text-slate-700 dark:text-slate-300 focus:outline-none font-mono"
                />
              </div>

              {/* Date To */}
              <div className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-800/60 border border-slate-200/80 dark:border-slate-800 rounded-xl px-2.5 py-1">
                <span className="text-[11px] font-semibold text-slate-500">Đến ngày:</span>
                <input
                  type="date"
                  value={dateRangeFilter.end}
                  onChange={e => setDateRangeFilter(prev => ({ ...prev, end: e.target.value }))}
                  className="bg-transparent text-xs text-slate-700 dark:text-slate-300 focus:outline-none font-mono"
                />
              </div>

              {/* Clear filters */}
              {(selectedYear !== 'all' || dateRangeFilter.start || dateRangeFilter.end) && (
                <button
                  type="button"
                  onClick={() => {
                    setSelectedYear('all')
                    setDateRangeFilter({ start: '', end: '' })
                  }}
                  className="text-[11px] font-semibold text-orange-600 hover:text-orange-700 hover:underline px-2 py-1 cursor-pointer"
                >
                  Xóa lọc
                </button>
              )}
            </div>
          </div>

          {/* Bottom row: Compact Season Pills */}
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none pt-0.5">
            {filteredSeasonNames.map(season => {
              const sems = groupedSeasons[season] || []
              const isSelected = selectedSeason === season
              const isActiveSeason = sems.some(s => s.isActive)
              const visual = getSeasonVisual(season)
              const VisualIcon = visual.icon
              const totalClasses = sems.reduce((sum, s) => sum + (s.classCount || 0), 0)
              const firstSem = sems[0]
              const dateText = firstSem?.startDate && firstSem?.endDate
                ? `${new Date(firstSem.startDate).toLocaleDateString('vi-VN')} - ${new Date(firstSem.endDate).toLocaleDateString('vi-VN')}`
                : null

              return (
                <div
                  key={season}
                  onClick={() => setSelectedSeason(season)}
                  className={cn(
                    "px-3.5 py-2 rounded-xl border transition-all cursor-pointer shrink-0 flex items-center gap-2.5 select-none",
                    isSelected
                      ? "bg-white dark:bg-slate-900 border-orange-500 shadow-sm ring-1 ring-orange-500/30 text-slate-900 dark:text-white"
                      : "bg-slate-50/70 dark:bg-slate-800/50 border-slate-200/80 dark:border-slate-800 text-slate-600 dark:text-slate-300 hover:border-slate-300 dark:hover:border-slate-700"
                  )}
                >
                  <div className={cn("w-6 h-6 rounded-lg flex items-center justify-center shrink-0 border", visual.bg, visual.color)}>
                    <VisualIcon className="w-3.5 h-3.5" />
                  </div>

                  <div className="flex flex-col">
                    <div className="flex items-center gap-1.5">
                      <span className="font-extrabold text-xs">{season}</span>
                      {isActiveSeason && (
                        <span className="inline-flex items-center gap-1 px-1.5 py-0.2 rounded-full text-[9px] font-bold bg-emerald-50 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400 border border-emerald-200/60 dark:border-emerald-800/60">
                          <span className="w-1 h-1 rounded-full bg-emerald-500 animate-pulse" />
                          Active
                        </span>
                      )}
                    </div>
                    <span className="text-[10px] text-slate-400 font-mono">
                      {dateText || `${sems.length} kỳ • ${totalClasses} lớp`}
                    </span>
                  </div>

                  {isSelected && (
                    <div className="flex items-center gap-1 ml-1 pl-1.5 border-l border-slate-200 dark:border-slate-700">
                      {!isActiveSeason && (
                        <button
                          type="button"
                          onClick={(e) => void handleActivateSeason(season, e)}
                          title="Kích hoạt làm kỳ hiện tại"
                          className="text-[10px] font-semibold text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950/40 p-1 rounded-md transition-colors"
                        >
                          Kích hoạt
                        </button>
                      )}
                      <button
                        type="button"
                        onClick={(e) => handleDeleteSeasonPrompt(season, e)}
                        title="Xóa chu kỳ"
                        className="text-slate-400 hover:text-rose-600 p-1 rounded-md transition-colors"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </div>
                  )}
                </div>
              )
            })}

            {filteredSeasonNames.length === 0 && (
              <p className="text-xs text-slate-400 py-1">
                Không tìm thấy chu kỳ nào trong khoảng thời gian đã lọc.
              </p>
            )}
          </div>
        </div>

        {/* ── 4. TABS NAVIGATION (CURRICULUM / ALL SEMESTERS / CLASSES) ── */}
        <div className="border-b border-slate-200 dark:border-slate-800 flex items-center justify-between gap-4">
          <div className="flex items-center gap-1">
            <button
              onClick={() => setActiveTab('curriculum')}
              className={cn(
                "px-4 py-2.5 text-xs font-bold border-b-2 transition-all cursor-pointer flex items-center gap-2",
                activeTab === 'curriculum'
                  ? "border-orange-500 text-orange-600 dark:text-orange-400 bg-orange-50/50 dark:bg-orange-950/20 rounded-t-xl"
                  : "border-transparent text-slate-500 hover:text-slate-900 dark:hover:text-slate-200"
              )}
            >
              <BookOpen className="w-4 h-4" />
              <span>Khung 9 Kỳ & Môn học ({selectedSeason || 'Chu kỳ'})</span>
            </button>

            <button
              onClick={() => setActiveTab('all_semesters')}
              className={cn(
                "px-4 py-2.5 text-xs font-bold border-b-2 transition-all cursor-pointer flex items-center gap-2",
                activeTab === 'all_semesters'
                  ? "border-orange-500 text-orange-600 dark:text-orange-400 bg-orange-50/50 dark:bg-orange-950/20 rounded-t-xl"
                  : "border-transparent text-slate-500 hover:text-slate-900 dark:hover:text-slate-200"
              )}
            >
              <CalendarDays className="w-4 h-4" />
              <span>Bảng Tổng hợp Tất cả Học kỳ ({semesters.length})</span>
            </button>
          </div>

          {activeTab === 'curriculum' && selectedSemesterObj && (
            <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500">
              <span>Học kỳ: <strong className="text-slate-800 dark:text-slate-200">{selectedSemesterObj.code}</strong></span>
              {(selectedSemesterObj.startDate || selectedSemesterObj.endDate) && (
                <span className="font-mono text-[11px] text-slate-400">
                  ({selectedSemesterObj.startDate ? selectedSemesterObj.startDate.slice(0, 10) : ''} → {selectedSemesterObj.endDate ? selectedSemesterObj.endDate.slice(0, 10) : ''})
                </span>
              )}
            </div>
          )}
        </div>

        {/* ── 5. TAB 1: CURRICULUM 9-TERM MATRIX VIEW ── */}
        {activeTab === 'curriculum' && (
          <div className="space-y-6 animate-in fade-in duration-200">
            {/* Term Pill Selector (Kỳ 1 -> Kỳ 9) */}
            <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800 shadow-xs space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                  Lộ trình phân bổ đào tạo trong {selectedSeason}:
                </span>
                <span className="text-xs text-slate-400">
                  {currentSeasonSemesters.length} Kỳ học phần
                </span>
              </div>

              <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none">
                {currentSeasonSemesters.map((sem) => {
                  const isSelected = selectedSemesterId === sem.id
                  return (
                    <button
                      key={sem.id}
                      onClick={() => setSelectedSemesterId(sem.id)}
                      className={cn(
                        "px-4 py-2.5 rounded-xl font-bold text-xs shrink-0 transition-all flex items-center gap-2 cursor-pointer border",
                        isSelected
                          ? "bg-orange-500 text-white border-orange-500 shadow-md shadow-orange-500/25"
                          : "bg-slate-50 dark:bg-slate-800/60 border-slate-200/80 dark:border-slate-800 text-slate-700 dark:text-slate-300 hover:border-slate-300 dark:hover:border-slate-700"
                      )}
                    >
                      <span>{sem.code}</span>
                      <span
                        className={cn(
                          "px-1.5 py-0.5 rounded-md text-[10px] font-mono",
                          isSelected
                            ? "bg-white/20 text-white"
                            : "bg-slate-200/70 dark:bg-slate-700 text-slate-600 dark:text-slate-300"
                        )}
                      >
                        {sem.subjectCount || 0} môn
                      </span>
                    </button>
                  )
                })}

                {currentSeasonSemesters.length === 0 && (
                  <p className="text-xs text-slate-400 py-2">
                    Chu kỳ này chưa có kỳ đào tạo nào. Vui lòng tạo mới season hoặc thêm kỳ.
                  </p>
                )}
              </div>
            </div>

            {/* Selected Term Details & Subject Table */}
            {selectedSemesterObj ? (
              <Card className="rounded-2xl border-slate-200/80 dark:border-slate-800 shadow-xs overflow-hidden">
                <CardHeader className="p-4 sm:p-5 border-b border-slate-200/80 dark:border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-50/50 dark:bg-slate-900/50">
                  <div>
                    <div className="flex items-center gap-2">
                      <CardTitle className="text-base font-extrabold text-slate-900 dark:text-white flex items-center gap-2">
                        <span>Danh sách Môn học phân bổ trong {selectedSemesterObj.code}</span>
                        {selectedSemesterObj.season && (
                          <Badge variant="outline" className="text-xs">
                            {selectedSemesterObj.season}
                          </Badge>
                        )}
                      </CardTitle>
                    </div>
                    <CardDescription className="text-xs text-slate-500 mt-1">
                      Tổng số {semesterSubjects.length} môn học được kích hoạt mở lớp trong kỳ này
                    </CardDescription>
                  </div>

                  <div className="flex items-center gap-2.5 flex-wrap">
                    {/* Subject search within term */}
                    <div className="relative w-56">
                      <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                      <Input
                        value={subjectSearch}
                        onChange={e => setSubjectSearch(e.target.value)}
                        placeholder="Tìm mã hoặc tên môn..."
                        className="pl-8 text-xs h-9 rounded-xl border-slate-200 dark:border-slate-800"
                      />
                      {subjectSearch && (
                        <button
                          onClick={() => setSubjectSearch('')}
                          className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                        >
                          <X className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>

                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleOpenEditSemester(selectedSemesterObj)}
                      className="gap-1.5 text-xs rounded-xl border-slate-200 dark:border-slate-800 h-9"
                    >
                      <Edit3 className="w-3.5 h-3.5 text-slate-500" />
                      <span>Sửa Kỳ</span>
                    </Button>

                    <Button
                      variant="primary"
                      size="sm"
                      onClick={() => void handleOpenAddSubjects()}
                      className="gap-1.5 text-xs rounded-xl font-bold h-9"
                    >
                      <Plus className="w-4 h-4" />
                      <span>Gán môn vào Kỳ</span>
                    </Button>
                  </div>
                </CardHeader>

                <CardContent className="p-0">
                  {loadingSubjects ? (
                    <div className="p-12 text-center text-xs text-slate-400 space-y-2">
                      <RefreshCw className="w-5 h-5 animate-spin mx-auto text-orange-500" />
                      <p>Đang tải danh sách môn học của học kỳ...</p>
                    </div>
                  ) : (
                    <div className="overflow-x-auto">
                      <table className="w-full text-xs text-left border-collapse">
                        <thead className="bg-slate-50/80 dark:bg-slate-800/50 text-slate-900 dark:text-slate-200 font-extrabold border-b border-slate-200/80 dark:border-slate-800 uppercase tracking-wider text-[11px]">
                          <tr>
                            <th className="px-5 py-3.5 w-16 text-center">STT</th>
                            <th className="px-5 py-3.5">Mã Môn Học</th>
                            <th className="px-5 py-3.5">Tên Môn Học</th>
                            <th className="px-5 py-3.5 text-center">Số Tín Chỉ</th>
                            <th className="px-5 py-3.5 text-center">Lớp Đang Mở</th>
                            <th className="px-5 py-3.5 text-right">Thao Tác</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-slate-800 bg-white dark:bg-slate-900">
                          {filteredSubjects.map((sub, idx) => (
                            <tr
                              key={sub.id}
                              className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors group"
                            >
                              <td className="px-5 py-3.5 text-center text-slate-400 font-mono text-[11px]">
                                {idx + 1}
                              </td>

                              <td className="px-5 py-3.5">
                                <span className="px-2 py-0.5 rounded-lg bg-orange-50 dark:bg-orange-950/40 text-orange-600 dark:text-orange-400 font-mono font-bold text-xs border border-orange-200/60 dark:border-orange-900/60">
                                  {sub.code}
                                </span>
                              </td>

                              <td className="px-5 py-3.5">
                                <div className="font-semibold text-slate-900 dark:text-white">
                                  {sub.name}
                                </div>
                                {sub.description && (
                                  <p className="text-[11px] text-slate-400 line-clamp-1 mt-0.5">
                                    {sub.description}
                                  </p>
                                )}
                              </td>

                              <td className="px-5 py-3.5 text-center">
                                <Badge variant="outline" className="font-mono text-xs">
                                  {sub.credit || 3} Tín chỉ
                                </Badge>
                              </td>

                              <td className="px-5 py-3.5 text-center">
                                <button
                                  onClick={() => void handleInspectClasses(sub)}
                                  className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-orange-50 dark:hover:bg-orange-950/40 hover:text-orange-600 transition-colors cursor-pointer text-xs font-semibold"
                                >
                                  <School className="w-3.5 h-3.5 text-orange-500" />
                                  <span>Xem lớp</span>
                                </button>
                              </td>

                              <td className="px-5 py-3.5 text-right">
                                <div className="flex items-center justify-end gap-1.5">
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => void handleOpenCreateClassForSubject(sub.id)}
                                    className="text-xs h-7 px-2.5 rounded-lg border-slate-200 dark:border-slate-800"
                                    title="Mở thêm lớp học phần cho môn này"
                                  >
                                    <Plus className="w-3.5 h-3.5 mr-1 text-orange-500" />
                                    <span>Tạo lớp</span>
                                  </Button>

                                  <Link href={`/admin/subjects`}>
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-7 w-7 rounded-lg text-slate-400 hover:text-slate-900"
                                      title="Đi tới danh mục môn học"
                                    >
                                      <ExternalLink className="w-3.5 h-3.5" />
                                    </Button>
                                  </Link>

                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    onClick={() => void handleRemoveSemesterSubject(sub.id, sub.name)}
                                    className="h-7 w-7 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50"
                                    title="Gỡ môn học khỏi kỳ này"
                                  >
                                    <Trash2 className="w-3.5 h-3.5" />
                                  </Button>
                                </div>
                              </td>
                            </tr>
                          ))}

                          {filteredSubjects.length === 0 && (
                            <tr>
                              <td colSpan={6} className="px-5 py-12 text-center text-slate-400 space-y-3">
                                <Library className="w-8 h-8 mx-auto text-slate-300 dark:text-slate-700" />
                                <p className="text-xs font-medium">
                                  {subjectSearch
                                    ? `Không tìm thấy môn học nào khớp với "${subjectSearch}"`
                                    : 'Chưa có môn học nào được gán vào học kỳ này.'}
                                </p>
                                {!subjectSearch && (
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => void handleOpenAddSubjects()}
                                    className="text-xs rounded-xl"
                                  >
                                    <Plus className="w-3.5 h-3.5 mr-1" />
                                    Gán môn học ngay
                                  </Button>
                                )}
                              </td>
                            </tr>
                          )}
                        </tbody>
                      </table>
                    </div>
                  )}
                </CardContent>
              </Card>
            ) : (
              <div className="p-12 text-center text-slate-400 bg-white dark:bg-slate-900 rounded-2xl border border-slate-200/80 dark:border-slate-800">
                <CalendarDays className="w-10 h-10 mx-auto text-slate-300 mb-2" />
                <p className="text-xs">Vui lòng chọn một học kỳ ở thanh trên để xem danh sách môn học.</p>
              </div>
            )}
          </div>
        )}

        {/* ── 6. TAB 2: ALL SEMESTERS COMPREHENSIVE DATA TABLE ── */}
        {activeTab === 'all_semesters' && (
          <Card className="rounded-2xl border-slate-200/80 dark:border-slate-800 shadow-xs overflow-hidden animate-in fade-in duration-200">
            <CardHeader className="p-4 sm:p-5 border-b border-slate-200/80 dark:border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-50/50 dark:bg-slate-900/50">
              <div>
                <CardTitle className="text-base font-extrabold text-slate-900 dark:text-white">
                  Danh sách Tổng hợp Tất cả Học kỳ
                </CardTitle>
                <CardDescription className="text-xs text-slate-500 mt-1">
                  Quản lý mã học kỳ, chu kỳ đào tạo (Season), thời gian bắt đầu và kết thúc
                </CardDescription>
              </div>

              <div className="flex items-center gap-2.5 flex-wrap">
                {/* Season dropdown filter */}
                <select
                  value={semesterSeasonFilter}
                  onChange={e => setSemesterSeasonFilter(e.target.value)}
                  className="h-9 rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs px-3 focus:outline-none focus:border-orange-500 font-medium text-slate-700 dark:text-slate-300"
                >
                  <option value="all">Tất cả chu kỳ ({totalSeasonsCount})</option>
                  {seasonNames.map(s => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>

                {/* Table search input */}
                <div className="relative w-60">
                  <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <Input
                    value={semesterTableSearch}
                    onChange={e => setSemesterTableSearch(e.target.value)}
                    placeholder="Tìm mã kỳ, chu kỳ..."
                    className="pl-8 text-xs h-9 rounded-xl border-slate-200 dark:border-slate-800"
                  />
                  {semesterTableSearch && (
                    <button
                      onClick={() => setSemesterTableSearch('')}
                      className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>

                <Button
                  variant="primary"
                  size="sm"
                  onClick={() => setSingleSemesterModalOpen(true)}
                  className="gap-1.5 text-xs rounded-xl font-bold h-9"
                >
                  <Plus className="w-4 h-4" />
                  <span>Tạo kỳ mới</span>
                </Button>
              </div>
            </CardHeader>

            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full text-xs text-left border-collapse">
                  <thead className="bg-slate-50/80 dark:bg-slate-800/50 text-slate-900 dark:text-slate-200 font-extrabold border-b border-slate-200/80 dark:border-slate-800 uppercase tracking-wider text-[11px]">
                    <tr>
                      <th className="px-5 py-3.5">Mã Học Kỳ</th>
                      <th className="px-5 py-3.5">Chu kỳ (Season)</th>
                      <th className="px-5 py-3.5">Thời Gian Diễn Ra</th>
                      <th className="px-5 py-3.5 text-center">Trạng Thái</th>
                      <th className="px-5 py-3.5 text-center">Môn Học</th>
                      <th className="px-5 py-3.5 text-center">Lớp Học</th>
                      <th className="px-5 py-3.5 text-right">Thao Tác</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-800 bg-white dark:bg-slate-900">
                    {filteredTableSemesters.map(sem => (
                      <tr
                        key={sem.id}
                        className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors"
                      >
                        <td className="px-5 py-3.5">
                          <span className="font-mono font-bold text-slate-900 dark:text-white text-xs">
                            {formatSemesterCode(sem.code)}
                          </span>
                        </td>

                        <td className="px-5 py-3.5">
                          <Badge variant="outline" className="text-xs">
                            {sem.season || 'Chưa phân nhóm'}
                          </Badge>
                        </td>

                        <td className="px-5 py-3.5 text-slate-500 font-mono text-[11px]">
                          {sem.startDate || sem.endDate ? (
                            <span>
                              {sem.startDate ? sem.startDate.slice(0, 10) : '—'} → {sem.endDate ? sem.endDate.slice(0, 10) : '—'}
                            </span>
                          ) : (
                            <span className="text-slate-400">Chưa đặt thời gian</span>
                          )}
                        </td>

                        <td className="px-5 py-3.5 text-center">
                          {sem.isActive ? (
                            <Badge variant="success" className="text-[11px]">
                              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                              Đang kích hoạt
                            </Badge>
                          ) : (
                            <Badge variant="outline" className="text-[11px] text-slate-400">
                              Lưu trữ
                            </Badge>
                          )}
                        </td>

                        <td className="px-5 py-3.5 text-center font-bold text-slate-700 dark:text-slate-300">
                          {sem.subjectCount || 0}
                        </td>

                        <td className="px-5 py-3.5 text-center font-bold text-slate-700 dark:text-slate-300">
                          {sem.classCount || 0}
                        </td>

                        <td className="px-5 py-3.5 text-right">
                          <div className="flex items-center justify-end gap-1.5">
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                if (sem.season) setSelectedSeason(sem.season)
                                setSelectedSemesterId(sem.id)
                                setActiveTab('curriculum')
                              }}
                              className="text-xs h-7 px-2 rounded-lg"
                              title="Xem chi tiết môn học trong kỳ"
                            >
                              <BookOpen className="w-3.5 h-3.5 mr-1" />
                              Xem môn
                            </Button>

                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleOpenEditSemester(sem)}
                              className="h-7 w-7 rounded-lg text-slate-400 hover:text-slate-900"
                              title="Chỉnh sửa kỳ"
                            >
                              <Edit3 className="w-3.5 h-3.5" />
                            </Button>

                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleDeleteSemesterPrompt(sem)}
                              className="h-7 w-7 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50"
                              title="Xóa kỳ"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </Button>
                          </div>
                        </td>
                      </tr>
                    ))}

                    {filteredTableSemesters.length === 0 && (
                      <tr>
                        <td colSpan={7} className="px-5 py-12 text-center text-slate-400">
                          Không tìm thấy học kỳ nào phù hợp với điều kiện tìm kiếm.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        )}

      </div>

      {/* ── MODAL: KHỞI TẠO SEASON MỚI (NĂM HỌC / CHU KỲ) ── */}
      <Modal
        isOpen={seasonModalOpen}
        onClose={() => setSeasonModalOpen(false)}
        title="Khởi tạo Chu kỳ Năm học Mới (Season)"
        maxWidth="lg"
      >
        <form onSubmit={handleCreateSeasonSubmit} className="space-y-4">
          <div className="p-3.5 rounded-xl bg-orange-50/70 dark:bg-orange-950/40 border border-orange-200/60 dark:border-orange-900/60 flex items-start gap-3">
            <Sparkles className="w-5 h-5 text-orange-500 shrink-0 mt-0.5" />
            <div className="text-xs text-slate-700 dark:text-slate-300 leading-relaxed">
              <strong>Hệ thống tự động hóa:</strong> Khi khởi tạo Season, hệ thống sẽ tự sinh <strong>9 Kỳ đào tạo (Kỳ 1 → Kỳ 9)</strong> và tự động gán toàn bộ môn học tương ứng theo ma trận chuẩn ngành CNTT.
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-semibold text-slate-900 dark:text-slate-200">
              Chọn Mùa học kỳ (Season Type)
            </label>
            <div className="grid grid-cols-3 gap-3">
              {(['Fall', 'Spring', 'Summer'] as CanonicalSeason[]).map(type => (
                <button
                  key={type}
                  type="button"
                  onClick={() => handleSeasonTypeChange(type)}
                  className={cn(
                    "p-3 rounded-xl border text-center transition-all cursor-pointer flex flex-col items-center gap-1",
                    seasonForm.seasonType === type
                      ? "border-orange-500 bg-orange-50/80 dark:bg-orange-950/50 text-orange-700 dark:text-orange-300 font-bold shadow-xs"
                      : "border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300"
                  )}
                >
                  <span className="text-xs font-bold">{type}</span>
                  <span className="text-[11px] text-slate-400">
                    {type === 'Fall' ? 'Kỳ Thu (09 - 12)' : type === 'Spring' ? 'Kỳ Xuân (01 - 05)' : 'Kỳ Hè (06 - 08)'}
                  </span>
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Năm học</span>
              <Input
                type="number"
                required
                value={seasonForm.year}
                onChange={e => {
                  const val = parseInt(e.target.value, 10) || new Date().getFullYear()
                  setSeasonForm(prev => ({ ...prev, year: val }))
                }}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800 focus:border-orange-500"
              />
            </label>

            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Tên chu kỳ dự kiến</span>
              <Input
                disabled
                value={`${seasonForm.seasonType} ${seasonForm.year}`}
                className="text-xs rounded-xl bg-slate-50 dark:bg-slate-800 font-bold text-orange-600 dark:text-orange-400 border-slate-200 dark:border-slate-800"
              />
            </label>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ngày bắt đầu</span>
              <Input
                type="date"
                value={seasonForm.startDate}
                onChange={e => setSeasonForm(prev => ({ ...prev, startDate: e.target.value }))}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
              />
            </label>
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ngày kết thúc</span>
              <Input
                type="date"
                value={seasonForm.endDate}
                onChange={e => setSeasonForm(prev => ({ ...prev, endDate: e.target.value }))}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
              />
            </label>
          </div>

          <div className="flex justify-end gap-2.5 pt-3 border-t border-slate-100 dark:border-slate-800">
            <Button
              type="button"
              variant="outline"
              onClick={() => setSeasonModalOpen(false)}
              className="rounded-xl text-xs font-semibold"
            >
              Hủy bỏ
            </Button>
            <Button
              type="submit"
              variant="primary"
              isLoading={saving}
              className="rounded-xl text-xs font-bold"
            >
              Khởi tạo Season & Ma trận 9 Kỳ
            </Button>
          </div>
        </form>
      </Modal>

      {/* ── MODAL: TẠO HỌC KỲ RIÊNG LẺ ── */}
      <Modal
        isOpen={singleSemesterModalOpen}
        onClose={() => setSingleSemesterModalOpen(false)}
        title="Tạo Kỳ Học phần Riêng lẻ"
        maxWidth="md"
      >
        <form onSubmit={handleCreateSingleSemester} className="space-y-4">
          <label className="block space-y-1.5">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Mã học kỳ (*)</span>
            <Input
              required
              placeholder="VD: Kỳ 1, FA26, SP26..."
              value={singleSemesterForm.code}
              onChange={e => setSingleSemesterForm(prev => ({ ...prev, code: e.target.value }))}
              className="text-xs rounded-xl border-slate-200 dark:border-slate-800 font-mono"
            />
          </label>

          <label className="block space-y-1.5">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Thuộc Season / Chu kỳ</span>
            <Input
              placeholder="VD: Fall 2026, Summer 2026..."
              value={singleSemesterForm.season}
              onChange={e => setSingleSemesterForm(prev => ({ ...prev, season: e.target.value }))}
              className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
            />
          </label>

          <div className="grid grid-cols-2 gap-3">
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ngày bắt đầu</span>
              <Input
                type="date"
                value={singleSemesterForm.startDate}
                onChange={e => setSingleSemesterForm(prev => ({ ...prev, startDate: e.target.value }))}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
              />
            </label>
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ngày kết thúc</span>
              <Input
                type="date"
                value={singleSemesterForm.endDate}
                onChange={e => setSingleSemesterForm(prev => ({ ...prev, endDate: e.target.value }))}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
              />
            </label>
          </div>

          <div className="flex justify-end gap-2.5 pt-3 border-t border-slate-100 dark:border-slate-800">
            <Button
              type="button"
              variant="outline"
              onClick={() => setSingleSemesterModalOpen(false)}
              className="rounded-xl text-xs font-semibold"
            >
              Hủy
            </Button>
            <Button
              type="submit"
              variant="primary"
              isLoading={saving}
              className="rounded-xl text-xs font-bold"
            >
              Tạo Học kỳ
            </Button>
          </div>
        </form>
      </Modal>

      {/* ── MODAL: CHỈNH SỬA HỌC KỲ ── */}
      <Modal
        isOpen={editSemesterModalOpen}
        onClose={() => setEditSemesterModalOpen(false)}
        title={`Chỉnh sửa Học kỳ ${editingSemester?.code || ''}`}
        maxWidth="md"
      >
        <form onSubmit={handleUpdateSemesterSubmit} className="space-y-4">
          <label className="block space-y-1.5">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Mã học kỳ (*)</span>
            <Input
              required
              value={editSemesterForm.code}
              onChange={e => setEditSemesterForm(prev => ({ ...prev, code: e.target.value }))}
              className="text-xs rounded-xl border-slate-200 dark:border-slate-800 font-mono"
            />
          </label>

          <label className="block space-y-1.5">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Tên Season / Nhóm kỳ</span>
            <Input
              value={editSemesterForm.season}
              onChange={e => setEditSemesterForm(prev => ({ ...prev, season: e.target.value }))}
              className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
            />
          </label>

          <div className="grid grid-cols-2 gap-3">
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ngày bắt đầu</span>
              <Input
                type="date"
                value={editSemesterForm.startDate}
                onChange={e => setEditSemesterForm(prev => ({ ...prev, startDate: e.target.value }))}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
              />
            </label>
            <label className="block space-y-1.5">
              <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Ngày kết thúc</span>
              <Input
                type="date"
                value={editSemesterForm.endDate}
                onChange={e => setEditSemesterForm(prev => ({ ...prev, endDate: e.target.value }))}
                className="text-xs rounded-xl border-slate-200 dark:border-slate-800"
              />
            </label>
          </div>

          <div className="flex justify-end gap-2.5 pt-3 border-t border-slate-100 dark:border-slate-800">
            <Button
              type="button"
              variant="outline"
              onClick={() => setEditSemesterModalOpen(false)}
              className="rounded-xl text-xs font-semibold"
            >
              Hủy
            </Button>
            <Button
              type="submit"
              variant="primary"
              isLoading={saving}
              className="rounded-xl text-xs font-bold"
            >
              Lưu thay đổi
            </Button>
          </div>
        </form>
      </Modal>

      {/* ── MODAL: GẮN MÔN HỌC VÀO HỌC KỲ (VỚI TÌM KIẾM THÔNG MINH) ── */}
      <Modal
        isOpen={addSubjectModalOpen}
        onClose={() => setAddSubjectModalOpen(false)}
        title={`Gán Môn Học vào ${selectedSemesterObj?.code || 'Học kỳ'}`}
        maxWidth="2xl"
      >
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
            {/* Search Input */}
            <div className="relative flex-1">
              <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                value={addSubjectSearch}
                onChange={e => setAddSubjectSearch(e.target.value)}
                placeholder="Tìm mã môn (PRJ, CSD...) hoặc tên môn..."
                className="pl-8 text-xs h-9 rounded-xl border-slate-200 dark:border-slate-800"
              />
              {addSubjectSearch && (
                <button
                  onClick={() => setAddSubjectSearch('')}
                  className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2">
              <span className="text-xs font-semibold text-slate-500">
                Đã chọn: <strong className="text-orange-600 dark:text-orange-400">{selectedSubjectIdsToAdd.size}</strong> môn
              </span>
            </div>
          </div>

          {/* Subjects Checklist */}
          <div className="max-h-[380px] overflow-y-auto border border-slate-200 dark:border-slate-800 rounded-xl divide-y divide-slate-100 dark:divide-slate-800 bg-white dark:bg-slate-900">
            {loadingAllSubjects ? (
              <div className="p-8 text-center text-xs text-slate-400">
                <RefreshCw className="w-4 h-4 animate-spin mx-auto text-orange-500 mb-2" />
                Đang tải danh mục môn học...
              </div>
            ) : (
              (() => {
                const available = allSubjects
                  .filter(s => !semesterSubjects.some(ss => ss.id === s.id))
                  .filter(s => {
                    if (!addSubjectSearch.trim()) return true
                    const q = addSubjectSearch.toLowerCase().trim()
                    return s.code.toLowerCase().includes(q) || s.name.toLowerCase().includes(q)
                  })

                if (available.length === 0) {
                  return (
                    <div className="p-8 text-center text-xs text-slate-400">
                      {addSubjectSearch ? 'Không tìm thấy môn học nào khớp với từ khóa.' : 'Tất cả môn học đã được gán vào kỳ này.'}
                    </div>
                  )
                }

                return available.map(sub => {
                  const isChecked = selectedSubjectIdsToAdd.has(sub.id)
                  return (
                    <label
                      key={sub.id}
                      className={cn(
                        "flex items-center justify-between p-3 transition-colors cursor-pointer select-none",
                        isChecked
                          ? "bg-orange-50/60 dark:bg-orange-950/30"
                          : "hover:bg-slate-50 dark:hover:bg-slate-800/40"
                      )}
                    >
                      <div className="flex items-center gap-3">
                        <input
                          type="checkbox"
                          checked={isChecked}
                          onChange={() => {
                            const next = new Set(selectedSubjectIdsToAdd)
                            if (next.has(sub.id)) next.delete(sub.id)
                            else next.add(sub.id)
                            setSelectedSubjectIdsToAdd(next)
                          }}
                          className="w-4 h-4 rounded text-orange-600 focus:ring-orange-500 border-slate-300 dark:border-slate-700"
                        />
                        <div>
                          <div className="flex items-center gap-2">
                            <span className="font-mono font-bold text-xs text-slate-900 dark:text-white">
                              {sub.code}
                            </span>
                            <span className="text-xs text-slate-700 dark:text-slate-300">
                              {sub.name}
                            </span>
                          </div>
                        </div>
                      </div>

                      <Badge variant="outline" className="text-[10px] font-mono">
                        {sub.credit || 3} Tín chỉ
                      </Badge>
                    </label>
                  )
                })
              })()
            )}
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800">
            <span className="text-[11px] text-slate-400">
              Chỉ hiển thị các môn chưa được gán vào học kỳ này.
            </span>
            <div className="flex gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setAddSubjectModalOpen(false)}
                className="rounded-xl text-xs"
              >
                Hủy
              </Button>
              <Button
                type="button"
                onClick={() => void handleAddSemesterSubjectsSubmit()}
                isLoading={saving}
                disabled={selectedSubjectIdsToAdd.size === 0}
                variant="primary"
                className="rounded-xl text-xs font-bold"
              >
                Gán {selectedSubjectIdsToAdd.size > 0 ? `${selectedSubjectIdsToAdd.size} Môn Học` : ''}
              </Button>
            </div>
          </div>
        </div>
      </Modal>

      {/* ── MODAL: XEM DANH SÁCH LỚP HỌC PHẦN CỦA MÔN ── */}
      <Modal
        isOpen={inspectClassesModal}
        onClose={() => setInspectClassesModal(false)}
        title={`Các Lớp Học Phần môn ${inspectSubject?.code || ''} (${selectedSemesterObj?.code || ''})`}
        maxWidth="lg"
      >
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <p className="text-xs text-slate-500">
              {inspectSubject?.name} • Tổng cộng {inspectClassesList.length} lớp học phần
            </p>
            {inspectSubject && (
              <Button
                variant="primary"
                size="sm"
                onClick={() => void handleOpenCreateClassForSubject(inspectSubject.id)}
                className="gap-1 text-xs rounded-xl h-8"
              >
                <Plus className="w-3.5 h-3.5" />
                <span>Thêm Lớp</span>
              </Button>
            )}
          </div>

          {loadingInspectClasses ? (
            <div className="p-8 text-center text-xs text-slate-400">
              <RefreshCw className="w-4 h-4 animate-spin mx-auto text-orange-500 mb-2" />
              Đang tải danh sách lớp học...
            </div>
          ) : (
            <div className="border border-slate-200 dark:border-slate-800 rounded-xl divide-y divide-slate-100 dark:divide-slate-800 bg-white dark:bg-slate-900 overflow-hidden">
              {inspectClassesList.map(cls => (
                <div key={cls.id} className="p-3.5 flex items-center justify-between gap-3 hover:bg-slate-50/50 dark:hover:bg-slate-800/30">
                  <div>
                    <div className="flex items-center gap-2">
                      <Link
                        href={`/admin/classes/${cls.id}`}
                        className="font-mono font-bold text-xs text-slate-900 dark:text-white hover:text-orange-600 flex items-center gap-1"
                      >
                        {cls.code}
                        <ExternalLink className="w-3 h-3 text-slate-400" />
                      </Link>
                      <Badge variant="outline" className="text-[10px]">
                        {cls.studentCount || 0} Sinh viên
                      </Badge>
                    </div>
                    <p className="text-[11px] text-slate-500 mt-0.5">
                      Giảng viên: <strong className="text-slate-700 dark:text-slate-300">{cls.lecturers?.map(l => l.name).join(', ') || 'Chưa phân công'}</strong>
                    </p>
                  </div>

                  <Link href={`/admin/classes/${cls.id}`}>
                    <Button variant="outline" size="sm" className="text-xs h-7 rounded-lg">
                      Quản lý lớp
                    </Button>
                  </Link>
                </div>
              ))}

              {inspectClassesList.length === 0 && (
                <div className="p-8 text-center text-xs text-slate-400 space-y-2">
                  <School className="w-8 h-8 mx-auto text-slate-300 dark:text-slate-700" />
                  <p>Chưa có lớp học phần nào mở cho môn này trong học kỳ.</p>
                </div>
              )}
            </div>
          )}

          <div className="flex justify-end pt-2">
            <Button
              variant="outline"
              onClick={() => setInspectClassesModal(false)}
              className="text-xs rounded-xl"
            >
              Đóng
            </Button>
          </div>
        </div>
      </Modal>

      {/* ── MODAL: TẠO LỚP HỌC PHẦN MỚI CHO MÔN ── */}
      <Modal
        isOpen={classModalOpen}
        onClose={() => setClassModalOpen(false)}
        title="Tạo Lớp Học Phần Mới"
        maxWidth="md"
      >
        <form onSubmit={handleSaveClassSubmit} className="space-y-4">
          <label className="block space-y-1.5">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Mã lớp (*)</span>
            <Input
              required
              placeholder="VD: SE1801, IA1902..."
              value={classForm.code}
              onChange={e => setClassForm(prev => ({ ...prev, code: e.target.value }))}
              className="text-xs rounded-xl border-slate-200 dark:border-slate-800 font-mono uppercase"
            />
          </label>

          <label className="block space-y-1.5">
            <span className="text-xs font-semibold text-slate-900 dark:text-slate-200">Phân công Giảng viên</span>
            <select
              className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-2.5 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:border-orange-500"
              value={classForm.lecturerId}
              onChange={e => setClassForm(prev => ({ ...prev, lecturerId: e.target.value }))}
            >
              <option value="">-- Chưa phân công giảng viên --</option>
              {lecturers.map(l => (
                <option key={l.id} value={l.id}>
                  {l.name} ({l.email})
                </option>
              ))}
            </select>
          </label>

          <div className="flex justify-end gap-2.5 pt-3 border-t border-slate-100 dark:border-slate-800">
            <Button
              type="button"
              variant="outline"
              onClick={() => setClassModalOpen(false)}
              className="rounded-xl text-xs font-semibold"
            >
              Hủy
            </Button>
            <Button
              type="submit"
              variant="primary"
              isLoading={saving}
              className="rounded-xl text-xs font-bold"
            >
              Khởi tạo Lớp
            </Button>
          </div>
        </form>
      </Modal>

      {/* ── MODAL: XÁC NHẬN XÓA (CLEAN DESIGN SYSTEM CONFIRMATION) ── */}
      <Modal
        isOpen={deleteModal.isOpen}
        onClose={() => setDeleteModal(prev => ({ ...prev, isOpen: false }))}
        title={deleteModal.title}
        maxWidth="md"
      >
        <div className="space-y-4">
          <div className="p-3.5 rounded-xl bg-rose-50 dark:bg-rose-950/40 border border-rose-200/60 dark:border-rose-900/60 flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-rose-600 shrink-0 mt-0.5" />
            <p className="text-xs text-rose-800 dark:text-rose-300 leading-relaxed">
              {deleteModal.description}
            </p>
          </div>

          <div className="flex justify-end gap-2.5 pt-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => setDeleteModal(prev => ({ ...prev, isOpen: false }))}
              className="rounded-xl text-xs font-semibold"
            >
              Hủy bỏ
            </Button>
            <Button
              type="button"
              variant="danger"
              onClick={() => void deleteModal.onConfirm()}
              className="rounded-xl text-xs font-bold bg-rose-600 hover:bg-rose-700 text-white"
            >
              Xác nhận Xóa
            </Button>
          </div>
        </div>
      </Modal>
    </DashboardLayout>
  )
}

'use client'

import * as React from 'react'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { ADMIN_NAV } from '@/config/navigation'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { ErrorNotice } from '@/components/ui/feedback'
import { settingsApi } from '@/lib/api/modules/settings'
import { reportsApi } from '@/lib/api/modules/reports'
import { errorMessage } from '@/lib/api/errors'
import type { AIConfig } from '@/lib/api/contracts'
import { useAuth } from '@/providers/auth-provider'
import { useLanguage } from '@/providers/language-provider'
import {
  Bot,
  Sparkles,
  Zap,
  Server,
  Sliders,
  ShieldCheck,
  CheckCircle2,
  AlertCircle,
  RefreshCw,
  Cpu,
  Layers,
  KeyRound,
  Save,
  Check,
} from 'lucide-react'

const PROVIDER_PRESETS = [
  {
    id: 'gemini',
    name: 'Google Gemini',
    models: ['gemini-1.5-flash', 'gemini-1.5-pro', 'gemini-2.0-flash'],
    recommended: 'gemini-1.5-flash',
    desc: 'Tốc độ phản hồi cực nhanh, tối ưu cho phân tích Barem Rubric và chấm code lớn.',
    endpoint: 'https://generativelanguage.googleapis.com/v1beta',
    badge: 'Khuyên dùng',
  },
  {
    id: 'openai',
    name: 'OpenAI GPT',
    models: ['gpt-4o-mini', 'gpt-4o'],
    recommended: 'gpt-4o-mini',
    desc: 'Khả năng suy luận mã nguồn và giải thích logic sâu, độ chính xác cao.',
    endpoint: 'https://api.openai.com/v1',
  },
  {
    id: 'claude',
    name: 'Anthropic Claude',
    models: ['claude-3-5-sonnet', 'claude-3-haiku'],
    recommended: 'claude-3-5-sonnet',
    desc: 'Xuất sắc trong phân tích cú pháp và tuân thủ chặt chẽ tiêu chí chấm Rubric.',
    endpoint: 'https://api.anthropic.com/v1',
  },
]

export default function AdminAIConfigPage() {
  const { role, isAuthenticated } = useAuth()
  const { t } = useLanguage()

  const [config, setConfig] = React.useState<AIConfig | null>(null)
  const [error, setError] = React.useState<string | null>(null)
  const [saving, setSaving] = React.useState(false)
  const [saved, setSaved] = React.useState(false)
  const [testing, setTesting] = React.useState(false)
  const [testResult, setTestResult] = React.useState<{ status: 'success' | 'error'; message: string; latency?: number } | null>(null)

  const loadConfig = React.useCallback(async () => {
    if (!isAuthenticated || role !== 'admin') return
    try {
      const res = await settingsApi.getAIConfig()
      setConfig(res)
    } catch (cause) {
      setError(errorMessage(cause))
    }
  }, [isAuthenticated, role])

  React.useEffect(() => {
    void loadConfig()
  }, [loadConfig])

  const handleSelectPreset = (preset: typeof PROVIDER_PRESETS[0]) => {
    if (!config) return
    setConfig({
      ...config,
      aiModel: preset.recommended,
      aiEndpoint: preset.endpoint,
    })
    setSaved(false)
    setTestResult(null)
  }

  const handleTestConnection = async () => {
    setTesting(true)
    setTestResult(null)
    const startTime = Date.now()
    try {
      // Live diagnostic test via backend health & model verification
      const health = await reportsApi.getSystemHealth()
      const latency = Date.now() - startTime
      setTestResult({
        status: 'success',
        latency,
        message: `Kết nối thành công tới Engine AI (Độ trễ: ${latency}ms, Chế độ máy chủ: ${health?.aiEngine.mode || 'Active'})`,
      })
    } catch (err) {
      setTestResult({
        status: 'error',
        message: `Lỗi kết nối kiểm tra: ${errorMessage(err)}`,
      })
    } finally {
      setTesting(false)
    }
  }

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!config || saving) return
    setSaving(true)
    setSaved(false)
    setError(null)
    try {
      await settingsApi.updateAIConfig(config)
      const persisted = await settingsApi.getAIConfig()
      setConfig(persisted)
      setSaved(true)
      setTimeout(() => setSaved(false), 4000)
    } catch (cause) {
      setError(errorMessage(cause))
    } finally {
      setSaving(false)
    }
  }

  return (
    <DashboardLayout
      navItems={ADMIN_NAV}
      title="AITA Admin"
      roleLabel={t('profile.role_admin', 'Quản trị viên')}
      requiredRole="admin"
      headerTitle={t('admin.ai.title', 'Cấu hình Mô hình Trí tuệ Nhân tạo')}
      headerSubtitle={t('admin.ai.subtitle', 'Quản trị Engine AI chấm bài tự động, mô hình đánh giá và hạn mức tham số')}
    >
      <div className="space-y-6 w-full pb-12">
        {/* ── TOP BANNER ── */}
        <div className="rounded-xl p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xs flex flex-col md:flex-row items-start md:items-center justify-between gap-5">
          <div className="space-y-1.5 max-w-2xl">
            <div className="flex items-center gap-2">
              <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-bold border border-orange-200 dark:border-orange-900/60 text-[#FA7014] bg-orange-50 dark:bg-orange-950/30">
                <Sparkles className="w-3.5 h-3.5 text-[#FA7014]" />
                AI Evaluation Engine
              </span>
              <span className="text-xs text-slate-500 font-mono">v3.5 Multi-Provider</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-2">
              <span>Trung tâm Điều phối Mô hình AI</span>
            </h2>
            <p className="text-xs sm:text-sm text-slate-600 dark:text-slate-400 leading-relaxed font-medium">
              Hệ thống sử dụng mô hình ngôn ngữ lớn kết hợp Docker Sandbox để phân tích mã nguồn sinh viên, đối chiếu barem Rubric tiêu chí Part A, B, C và đề xuất điểm số chính xác.
            </p>
          </div>

          <div className="flex items-center gap-2.5 shrink-0">
            <Button
              variant="outline"
              size="sm"
              onClick={handleTestConnection}
              isLoading={testing}
              className="text-xs gap-1.5 cursor-pointer font-bold rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-900 dark:text-slate-100"
            >
              <Zap className="w-4 h-4 text-[#FA7014]" />
              <span>Kiểm tra kết nối AI</span>
            </Button>
          </div>
        </div>

        {testResult && (
          <div
            className={`p-4 rounded-xl border text-xs flex items-center justify-between gap-3 ${
              testResult.status === 'success'
                ? 'bg-emerald-50 text-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800'
                : 'bg-rose-50 text-rose-800 dark:bg-rose-950/40 dark:text-rose-300 border-rose-200 dark:border-rose-800'
            }`}
          >
            <div className="flex items-center gap-2">
              {testResult.status === 'success' ? (
                <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
              ) : (
                <AlertCircle className="w-4 h-4 text-rose-500 shrink-0" />
              )}
              <span className="font-medium">{testResult.message}</span>
            </div>
            <button
              type="button"
              onClick={() => setTestResult(null)}
              className="text-slate-400 hover:text-slate-600 text-xs cursor-pointer"
            >
              ✕
            </button>
          </div>
        )}

        {error && <ErrorNotice message={error} onRetry={() => void loadConfig()} />}

        {/* ── 1. PROVIDER PRESETS SELECTOR ── */}
        <div className="space-y-3">
          <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">
            <div className="w-6 h-6 rounded-lg bg-orange-50 dark:bg-orange-950/40 text-[#FA7014] border border-orange-200/60 dark:border-orange-900/60 flex items-center justify-center">
              <Cpu className="w-3.5 h-3.5" />
            </div>
            <span>Chọn Nhà Cung Cấp Mô hình (Provider Presets)</span>
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {PROVIDER_PRESETS.map((preset) => {
              const isSelected = config?.aiModel.includes(preset.id) || config?.aiEndpoint.includes(preset.id)
              return (
                <div
                  key={preset.id}
                  onClick={() => handleSelectPreset(preset)}
                  className={`p-5 space-y-3 cursor-pointer transition-all rounded-xl relative overflow-hidden ${
                    isSelected
                      ? 'border-2 border-[#FA7014] bg-orange-50/20 dark:bg-orange-950/20 shadow-xs'
                      : 'border border-slate-200 dark:border-slate-800 hover:border-slate-300 dark:hover:border-slate-700 bg-white dark:bg-slate-900 shadow-2xs'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-sm text-slate-900 dark:text-white">
                      {preset.name}
                    </span>
                    {preset.badge && (
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-[#FA7014] text-white shadow-2xs">
                        {preset.badge}
                      </span>
                    )}
                  </div>

                  <p className="text-xs text-slate-600 dark:text-slate-400 leading-relaxed font-medium">
                    {preset.desc}
                  </p>

                  <div className="pt-2 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px]">
                    <span className="font-mono text-slate-500">Mẫu: {preset.recommended}</span>
                    <span className="text-[#FA7014] font-bold">Chọn mẫu →</span>
                  </div>
                </div>
              )
            })}
          </div>
        </div>

        {/* ── 2. CONFIGURATION FORM ── */}
        {!config ? (
          !error && <div className="py-12 text-center text-slate-400 text-xs">Đang tải cấu hình AI...</div>
        ) : (
          <form onSubmit={handleSave} className="space-y-6">
            <div className="rounded-xl p-6 space-y-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xs">
              <div className="flex items-center gap-2.5 pb-3 border-b border-slate-200 dark:border-slate-800">
                <div className="w-9 h-9 rounded-xl bg-orange-50 dark:bg-orange-950/40 text-[#FA7014] border border-orange-200/60 dark:border-orange-900/60 flex items-center justify-center">
                  <Sliders className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <span>Tham số Điều khiển & Engine Endpoint</span>
                  </h3>
                  <p className="text-xs text-slate-600 dark:text-slate-400 font-medium">
                    Cấu hình kết nối API và ngưỡng thời gian chờ
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                {/* AI Model Identifier */}
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-900 dark:text-slate-200 flex items-center justify-between">
                    <span>Mã định danh Mô hình (Model Name)</span>
                    <span className="text-[11px] text-slate-400 font-normal">Ví dụ: gemini-1.5-flash</span>
                  </label>
                  <Input
                    required
                    value={config.aiModel}
                    onChange={(e) => setConfig({ ...config, aiModel: e.target.value })}
                    className="text-xs font-mono rounded-xl border-slate-200 dark:border-slate-800 focus:border-[#FA7014] text-slate-900 dark:text-white"
                    placeholder="gemini-1.5-flash"
                  />
                </div>

                {/* AI Endpoint */}
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-900 dark:text-slate-200 flex items-center justify-between">
                    <span>AI API Endpoint URL</span>
                    <span className="text-[11px] text-slate-400 font-normal">Đường dẫn REST API</span>
                  </label>
                  <Input
                    type="url"
                    value={config.aiEndpoint}
                    onChange={(e) => setConfig({ ...config, aiEndpoint: e.target.value })}
                    className="text-xs font-mono rounded-xl border-slate-200 dark:border-slate-800 focus:border-[#FA7014] text-slate-900 dark:text-white"
                    placeholder="https://generativelanguage.googleapis.com/v1beta"
                  />
                </div>

                {/* Timeout */}
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-900 dark:text-slate-200 flex items-center justify-between">
                    <span>Thời gian chờ tối đa (Timeout)</span>
                    <span className="text-[11px] text-slate-400 font-normal">Giây (1 - 3600s)</span>
                  </label>
                  <Input
                    type="number"
                    required
                    min={5}
                    max={3600}
                    step={1}
                    value={config.aiTimeout}
                    onChange={(e) => setConfig({ ...config, aiTimeout: e.target.value })}
                    className="text-xs font-mono rounded-xl border-slate-200 dark:border-slate-800 focus:border-[#FA7014] text-slate-900 dark:text-white"
                  />
                </div>

                {/* API Key Management Note */}
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-900 dark:text-slate-200">
                    Bảo mật Khóa API (API Key Status)
                  </label>
                  <div className="p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-800 text-xs flex items-center justify-between">
                    <span className="flex items-center gap-2 font-mono text-slate-700 dark:text-slate-300">
                      <KeyRound className="w-3.5 h-3.5 text-[#FA7014]" />
                      GEMINI_API_KEY (Server Env)
                    </span>
                    <span className="text-emerald-600 dark:text-emerald-400 font-bold text-[11px]">
                      ✔ Đã cấu hình
                    </span>
                  </div>
                </div>
              </div>

              {/* Simulation Mode Toggle */}
              <div className="pt-4 border-t border-slate-200 dark:border-slate-800">
                <label className="flex items-start sm:items-center justify-between gap-4 p-4 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-800 cursor-pointer">
                  <div className="space-y-0.5">
                    <span className="text-xs font-bold text-slate-900 dark:text-white flex items-center gap-1.5">
                      <Zap className="w-3.5 h-3.5 text-[#FA7014]" />
                      Chế độ Stub / Giả lập Sandbox (AI Stub Mode)
                    </span>
                    <p className="text-[11px] text-slate-600 dark:text-slate-400 font-medium">
                      Khi bật, hệ thống sẽ sử dụng bộ sinh đánh giá heuristic nội bộ thay vì gọi trực tiếp API trả phí bên ngoài.
                    </p>
                  </div>
                  <input
                    type="checkbox"
                    checked={config.aiStubMode === 'true'}
                    onChange={(e) => setConfig({ ...config, aiStubMode: String(e.target.checked) })}
                    className="w-5 h-5 rounded accent-[#FA7014] cursor-pointer shrink-0"
                  />
                </label>
              </div>

              {/* Footer Save Action */}
              <div className="flex flex-col sm:flex-row items-center justify-between gap-4 pt-3">
                <div>
                  {saved && (
                    <span className="inline-flex items-center gap-1.5 text-xs font-bold text-emerald-600 dark:text-emerald-400">
                      <Check className="w-4 h-4" />
                      Cấu hình AI đã được lưu thành công vào cơ sở dữ liệu!
                    </span>
                  )}
                </div>

                <Button
                  type="submit"
                  size="md"
                  variant="primary"
                  isLoading={saving}
                  className="gap-1.5"
                >
                  <Save className="w-4 h-4" />
                  <span>Lưu cấu hình hệ thống</span>
                </Button>
              </div>
            </div>
          </form>
        )}
      </div>
    </DashboardLayout>
  )
}

'use client'

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { subjectsApi } from '@/lib/api/modules/subjects'
import type { SubjectRow } from '@/lib/api/contracts'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { ADMIN_NAV } from '@/config/navigation'
import { 
  ArrowLeft, Loader2, ChevronRight, AlertCircle,
  Pencil, Save, X, Search, Download, Check
} from 'lucide-react'

type TabType = 'syllabus' | 'clos' | 'sessions' | 'assessment'

// Type for which card is currently being edited
type EditingCard = 'header' | 'description' | 'learningOutcomes' | 'studentTasks' | 'tools' | 'assessments' | 'clos' | 'sessions' | null

export function AdminSubjectDetailPage() {
  const params = useParams()
  const id = params?.id as string
  const router = useRouter()
  
  const [subject, setSubject] = useState<SubjectRow | null>(null)
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<TabType>('syllabus')
  const [sessionSearch, setSessionSearch] = useState('')
  const [downloadingSession, setDownloadingSession] = useState<number | null>(null)

  // Inline editing state
  const [editingCard, setEditingCard] = useState<EditingCard>(null)
  const [editHeaderName, setEditHeaderName] = useState('')
  const [editHeaderCode, setEditHeaderCode] = useState('')
  const [editHeaderDegree, setEditHeaderDegree] = useState('')
  const [editHeaderSemester, setEditHeaderSemester] = useState<number>(1)
  const [editHeaderCredits, setEditHeaderCredits] = useState<number>(3)
  const [editHeaderTimeAlloc, setEditHeaderTimeAlloc] = useState('')
  const [editHeaderPrereqs, setEditHeaderPrereqs] = useState('')
  const [editDescription, setEditDescription] = useState('')
  const [editStudentTasks, setEditStudentTasks] = useState<string[]>([])
  const [editTools, setEditTools] = useState<string[]>([])
  const [editLearningOutcomes, setEditLearningOutcomes] = useState<any[]>([])
  const [editAssessments, setEditAssessments] = useState<any[]>([])
  const [editClos, setEditClos] = useState<any[]>([])
  const [editSessions, setEditSessions] = useState<any[]>([])
  const [isSaving, setIsSaving] = useState(false)



  // Handles download for both Cloudinary (fl_attachment) and Google Drive URLs.
  // Google Drive's virus-scan redirect breaks <a download>, so we fetch as blob.
  const handleDownload = useCallback(async (url: string, filename: string, sessionNo: number) => {
    const isGoogleDrive = url.includes('drive.google.com')
    if (!isGoogleDrive) {
      // Cloudinary with fl_attachment — server sends Content-Disposition: attachment, just open
      window.open(url, '_blank', 'noopener,noreferrer')
      return
    }
    // Google Drive: fetch blob to bypass virus-scan warning page
    try {
      setDownloadingSession(sessionNo)
      const response = await fetch(url)
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const blob = await response.blob()
      const blobUrl = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = blobUrl
      a.download = filename
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(blobUrl)
    } catch {
      // Fallback: open in new tab if fetch fails (e.g. CORS)
      window.open(url, '_blank', 'noopener,noreferrer')
    } finally {
      setDownloadingSession(null)
    }
  }, [])

  const [loadError, setLoadError] = useState<string | null>(null)

  const fetchSubject = useCallback(() => {
    if (!id) return
    setLoading(true)
    setLoadError(null)
    subjectsApi.getSubject(id)
      .then((res: any) => {
        const found = res?.data || res
        if (found) {
          setSubject(found)
        } else {
          setSubject({
            id: id,
            code: id.toUpperCase(),
            name: 'Course Subject',
            description: ''
          })
        }
      })
      .catch((err: any) => {
        setLoadError(err?.message || 'Failed to load subject details. Please try again.')
      })
      .finally(() => setLoading(false))
  }, [id])

  useEffect(() => {
    fetchSubject()
  }, [fetchSubject])

  const hasSyllabusData = useMemo(() => {
    if (subject?.syllabusData) {
      try {
        const parsed = typeof subject.syllabusData === 'string' ? JSON.parse(subject.syllabusData) : subject.syllabusData
        if (parsed && typeof parsed === 'object' && Object.keys(parsed).length > 0 && (parsed.clos?.length > 0 || parsed.sessions?.length > 0 || parsed.description)) return true
      } catch (e) {
        // ignore
      }
    }
    return false
  }, [subject])

  const rawSyllabus = useMemo(() => {
    if (subject?.syllabusData) {
      try {
        const parsed = typeof subject.syllabusData === 'string' ? JSON.parse(subject.syllabusData) : subject.syllabusData
        if (parsed && typeof parsed === 'object' && Object.keys(parsed).length > 0) return parsed
      } catch (e) {
        // ignore
      }
    }
    return null
  }, [subject])

  // Centralized save helper: merges updated fields into rawSyllabus, persists via API, and updates local state
  const saveSyllabusData = useCallback(async (updatedFields: Record<string, any>) => {
    if (!subject || !rawSyllabus) return
    setIsSaving(true)
    try {
      const updatedSyllabus = { ...rawSyllabus, ...updatedFields }
      const syllabusJson = JSON.stringify(updatedSyllabus)
      await subjectsApi.updateSubject(subject.id, {
        code: subject.code,
        name: subject.name,
        description: updatedSyllabus.description ?? subject.description,
        syllabusData: syllabusJson,
      })
      setSubject((prev: SubjectRow | null) => prev ? {
        ...prev,
        syllabusData: syllabusJson,
        description: updatedSyllabus.description ?? prev.description,
      } : prev)
      setEditingCard(null)
    } catch (e) {
      console.error('Save failed', e)
    } finally {
      setIsSaving(false)
    }
  }, [subject, rawSyllabus])

  const syllabus = useMemo(() => {
    if (!rawSyllabus) return null
    const s = rawSyllabus as any
    const credits = s.credits ?? s.noCredit ?? 3
    const degreeLevel = s.degreeLevel || 'Bachelor'
    const timeAllocation = s.timeAllocation || 'Study hour (150h) = 45h contact hours + 1h final exam + 104h self-study'
    const prerequisites = s.prerequisites || s.preRequisite || 'None'
    const description = s.description || subject?.description || ''

    const studentTasksList: string[] = Array.isArray(s.studentTasks)
      ? s.studentTasks
      : s.studentTasks ? [s.studentTasks] : [
          'Students must attend at least 80% of contact sessions in order to be accepted to the final examination.',
          'Student is responsible to do all assigned exercises given by instructor in class or at home and submit on time.',
          'Use laptop in class only for learning purpose.',
          'Promptly access to the https://flm.fpt.edu.vn/ for up-to-date course information.'
        ]

    const tools: string[] = s.tools || ['Internet', 'C language utility (ex.DevC++ 6.3)']

    const defaultLearningOutcomes = [
      {
        category: '1. Knowledge',
        code: '(ABET e)',
        items: [
          'Explain the way to solve a real problem using computer.',
          'Understand the basic concepts computer system, and software development.',
          'Understand the basic concepts of programming, focus on procedure programming, testing and debugging, unit testing.'
        ]
      },
      {
        category: '2. Skills in programming',
        code: '(ABET k)',
        items: [
          'Read and understand the simple C programs;',
          'Solve real problems using C.'
        ]
      },
      {
        category: '3. Apply learning methods effectively',
        code: '(ABET i)',
        items: [
          'Academic reading.',
          'Individual and team work behaviors.'
        ]
      }
    ]

    const learningOutcomes = s.learningOutcomes || defaultLearningOutcomes

    const clos = (s.clos || []).map((c: any) => ({
      code: c.code || c.cloName || 'CLO',
      details: c.details || c.cloDetails || '',
      loDetails: c.loDetails || ''
    }))

    const abetBreakdown = learningOutcomes.map((item: any) => ({
      domain: `${item.category} ${item.code || ''}`.trim(),
      clos: item.items || []
    }))

    const assessments = (s.assessments || s.assessmentScheme || []).map((a: any) => ({
      category: a.category || a.name || 'Assessment',
      weightPercent: (a.weightPercent ?? parseFloat(String(a.weight || '0').replace('%', ''))) || 0
    }))

    const sessions = (s.sessions || []).map((ses: any, index: number) => ({
      sessionNo: ses.sessionNo ?? ses.session ?? (index + 1),
      topic: ses.topic || '',
      type: ses.type || 'Offline',
      clo: ses.clo || 'CLO1',
      itu: ses.itu || 'I',
      studentTasks: Array.isArray(ses.studentTasks) ? ses.studentTasks.join(', ') : (ses.studentTasks || ''),
      materialsDownloadUrl: ses.materialsDownloadUrl || ses.cloudinaryUrl || (ses.sDownload ? '#' : undefined),
      sDownload: ses.sDownload || 'Slide PDF'
    }))

    const totalAssessmentWeight = assessments.reduce((acc: number, item: any) => acc + (item.weightPercent || 0), 0)

    return {
      code: s.code || subject?.code || 'PRF192',
      name: s.name || subject?.name || 'Programming Fundamentals',
      description,
      credits,
      degreeLevel,
      timeAllocation,
      prerequisites,
      studentTasksList,
      tools,
      learningOutcomes,
      clos,
      abetBreakdown,
      assessments,
      totalAssessmentWeight,
      sessions
    }
  }, [rawSyllabus, subject])

  // Sync header edit states whenever syllabus loads/changes — must be AFTER syllabus useMemo
  useEffect(() => {
    if (!syllabus) return
    setEditHeaderName(syllabus.name)
    setEditHeaderCode(syllabus.code)
    setEditHeaderDegree(syllabus.degreeLevel)
    setEditHeaderCredits(syllabus.credits)
    setEditHeaderTimeAlloc(syllabus.timeAllocation)
    setEditHeaderPrereqs(syllabus.prerequisites)
  }, [syllabus?.code, syllabus?.name]) // only re-sync when course changes, not on every keystroke

  // Computed live total of editAssessments
  const editAssessmentTotal = useMemo(() => {
    return editAssessments.reduce((acc, a) => acc + (Number(a.weightPercent) || 0), 0)
  }, [editAssessments])

  const isAssessmentTotalValid = useMemo(() => {
    return Math.abs(editAssessmentTotal - 100) < 0.01
  }, [editAssessmentTotal])

  // Handle single assessment weight change with automatic adjustment of the last item
  const handleAssessmentWeightChange = useCallback((index: number, newWeight: number) => {
    setEditAssessments(prev => {
      if (prev.length === 0) return prev
      const updated = prev.map((item, i) => i === index ? { ...item, weightPercent: newWeight } : { ...item })
      const lastIdx = updated.length - 1
      // If changing any item except the last one, auto-balance the last item so the sum equals 100%
      if (index !== lastIdx && lastIdx > 0) {
        const otherSum = updated
          .slice(0, lastIdx)
          .reduce((sum, item) => sum + (Number(item.weightPercent) || 0), 0)
        const remainder = Math.max(0, Math.round((100 - otherSum) * 10) / 10)
        updated[lastIdx].weightPercent = remainder
      }
      return updated
    })
  }, [])

  // Auto balance all assessment weights so the total equals 100%
  const handleAutoBalanceAssessments = useCallback(() => {
    setEditAssessments(prev => {
      if (prev.length === 0) return prev
      const lastIdx = prev.length - 1
      const updated = prev.map(item => ({ ...item }))
      const otherSum = updated.slice(0, lastIdx).reduce((sum, item) => sum + (Number(item.weightPercent) || 0), 0)
      updated[lastIdx].weightPercent = Math.max(0, Math.round((100 - otherSum) * 10) / 10)
      return updated
    })
  }, [])

  const filteredSessions = useMemo(() => {
    if (!syllabus || !sessionSearch.trim()) return syllabus?.sessions || []
    const q = sessionSearch.toLowerCase()
    return syllabus.sessions.filter(
      (s: any) => s.topic.toLowerCase().includes(q) ||
           s.studentTasks.toLowerCase().includes(q) ||
           String(s.sessionNo).includes(q)
    )
  }, [syllabus, sessionSearch])

  if (loading) {
    return (
      <DashboardLayout navItems={ADMIN_NAV} title="AITA Admin" roleLabel="Quản trị viên" requiredRole="admin">
        <div className="flex flex-col items-center justify-center min-h-[60vh]">
          <Loader2 className="w-10 h-10 animate-spin text-brand-500 mb-4" />
          <p className="text-sm text-slate-500 font-medium">Loading course syllabus details...</p>
        </div>
      </DashboardLayout>
    )
  }

  if (loadError && !subject) {
    return (
      <DashboardLayout navItems={ADMIN_NAV} title="AITA Admin" roleLabel="Quản trị viên" requiredRole="admin">
        <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-4 text-center p-6">
          <div className="w-14 h-14 rounded-2xl bg-rose-50 dark:bg-rose-950/40 text-rose-500 flex items-center justify-center border border-rose-200 dark:border-rose-800">
            <AlertCircle size={28} />
          </div>
          <div className="space-y-1 max-w-md">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Không thể tải thông tin môn học</h3>
            <p className="text-xs text-slate-500 dark:text-slate-400">{loadError}</p>
          </div>
          <div className="flex items-center gap-3 pt-2">
            <button
              onClick={() => router.push('/admin/subjects')}
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 text-xs font-semibold text-slate-700 dark:text-slate-300 hover:bg-slate-50"
            >
              <ArrowLeft size={14} /> Quay lại
            </button>
            <button
              onClick={fetchSubject}
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-orange-600 hover:bg-orange-700 text-white text-xs font-semibold shadow-xs"
            >
              Thử lại
            </button>
          </div>
        </div>
      </DashboardLayout>
    )
  }

  // Handle courses without syllabus data yet (Not provided yet)
  if (!hasSyllabusData || !syllabus) {
    return (
      <DashboardLayout navItems={ADMIN_NAV} title="AITA Admin" roleLabel="Quản trị viên" requiredRole="admin">
      <div className="space-y-6 w-full p-4 sm:p-6 animate-in fade-in duration-300">
        <div className="flex items-center justify-between">
          <button
            onClick={() => router.push('/admin/subjects')}
            className="inline-flex items-center gap-2 text-sm font-semibold text-slate-600 dark:text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 transition-colors"
          >
            <ArrowLeft size={16} /> Back to Subjects
          </button>
          <div className="flex items-center gap-2 text-xs font-semibold text-slate-400">
            <Link href="/admin" className="hover:underline">Admin</Link>
            <ChevronRight size={12} />
            <Link href="/admin/subjects" className="hover:underline">Subjects</Link>
            <ChevronRight size={12} />
            <span className="text-slate-700 dark:text-slate-200 font-bold">{subject?.code || id}</span>
          </div>
        </div>

        {/* Hero Header */}
        <div className="relative overflow-hidden rounded-xl bg-white dark:bg-slate-900 text-slate-900 dark:text-white p-6 sm:p-8 shadow-2xs border border-slate-200 dark:border-slate-800">
          <div className="relative z-10 space-y-4">
            <div className="flex flex-wrap items-center gap-2.5">
              <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700">
                Subject Code: {subject?.code || id}
              </span>
              <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                Degree Level: Bachelor
              </span>
              <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                Semester: {subject?.semester ? `Semester ${subject.semester}` : 'Semester 1'}
              </span>
            </div>

            <h1 className="text-3xl sm:text-4xl font-extrabold tracking-tight text-slate-900 dark:text-white leading-tight">
              {subject?.name || 'Course Subject'}
            </h1>
          </div>
        </div>

        {/* Empty State Card in English */}
        <div className="p-12 sm:p-16 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xs text-center space-y-4">
          <div className="w-16 h-16 rounded-xl bg-orange-50 dark:bg-orange-950/40 text-[#FA7014] flex items-center justify-center mx-auto border border-orange-200/60 dark:border-orange-900/60">
            <AlertCircle size={32} />
          </div>
          <div className="space-y-1.5 max-w-md mx-auto">
            <h3 className="text-xl font-extrabold text-slate-900 dark:text-white">
              Syllabus Not Provided Yet
            </h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed font-normal">
              Detailed syllabus content for <strong className="text-slate-900 dark:text-white font-bold">{subject?.code || id} - {subject?.name}</strong> has not been provided yet.
            </p>
          </div>
          <div className="pt-2">
            <button
              onClick={() => router.push('/admin/subjects')}
              className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 hover:from-orange-600 hover:via-amber-500 hover:to-orange-500 text-white font-bold text-xs shadow-md shadow-orange-500/20 transition-all cursor-pointer"
            >
              <ArrowLeft size={14} /> Back to Subjects Directory
            </button>
          </div>
        </div>
      </div>
      </DashboardLayout>
    )
  }

  return (
    <DashboardLayout navItems={ADMIN_NAV} title="AITA Admin" roleLabel="Quản trị viên" requiredRole="admin">
    <div className="space-y-6 max-w-7xl mx-auto p-4 sm:p-6 animate-in fade-in duration-300">
      
      {/* Top Navigation & Breadcrumb */}
      <div className="flex items-center justify-between">
        <button
          onClick={() => router.push('/admin/subjects')}
          className="inline-flex items-center gap-2 text-sm font-semibold text-slate-600 dark:text-slate-400 hover:text-[#FA7014] transition-colors cursor-pointer"
        >
          <ArrowLeft size={16} /> Back to Subjects
        </button>
        <div className="flex items-center gap-2 text-xs font-semibold text-slate-400">
          <Link href="/admin" className="hover:underline">Admin</Link>
          <ChevronRight size={12} />
          <Link href="/admin/subjects" className="hover:underline">Subjects</Link>
          <ChevronRight size={12} />
          <span className="text-slate-900 dark:text-white font-bold">{syllabus.code}</span>
        </div>
      </div>

      {/* Hero Banner Header */}
      <div className="relative overflow-hidden rounded-xl bg-white dark:bg-slate-900 p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-2xs">
        <div className="relative z-10 space-y-4">

          {/* Badges row + edit/save button */}
          <div className="flex items-start justify-between gap-3 flex-wrap">
            <div className="flex flex-wrap items-center gap-2">
              {editingCard === 'header' ? (
                <>
                  <input
                    value={editHeaderCode}
                    onChange={e => setEditHeaderCode(e.target.value)}
                    className="px-3 py-1 rounded-xl text-xs font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white w-28 focus:outline-none focus:border-[#FA7014] transition-all"
                    placeholder="Code"
                  />
                  <input
                    value={editHeaderDegree}
                    onChange={e => setEditHeaderDegree(e.target.value)}
                    className="px-3 py-1 rounded-xl text-xs font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white w-28 focus:outline-none focus:border-[#FA7014] transition-all"
                    placeholder="Degree Level"
                  />
                  <div className="flex items-center gap-1 px-2 py-1 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700">
                    <span className="text-xs font-semibold text-slate-600 dark:text-slate-400">Sem</span>
                    <input
                      type="number"
                      value={editHeaderSemester}
                      onChange={e => setEditHeaderSemester(Number(e.target.value) || 1)}
                      className="text-xs font-bold bg-transparent text-slate-900 dark:text-white w-8 focus:outline-none text-center"
                      min={1} max={10}
                    />
                  </div>
                  <div className="flex items-center gap-1 px-2 py-1 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700">
                    <span className="text-xs font-semibold text-slate-600 dark:text-slate-400">Credits</span>
                    <input
                      type="number"
                      value={editHeaderCredits}
                      onChange={e => setEditHeaderCredits(Number(e.target.value) || 3)}
                      className="text-xs font-bold bg-transparent text-slate-900 dark:text-white w-8 focus:outline-none text-center"
                      min={1} max={10}
                    />
                  </div>
                </>
              ) : (
                <>
                  <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700">
                    {syllabus.code}
                  </span>
                  <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                    {syllabus.degreeLevel}
                  </span>
                  <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                    Semester {subject?.semester || 1}
                  </span>
                  <span className="px-3 py-1 rounded-md text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                    {syllabus.credits} Credits
                  </span>
                </>
              )}
            </div>

            {/* Pencil → Save/Cancel khi edit */}
            {editingCard === 'header' ? (
              <div className="flex items-center gap-1.5">
                <button
                  disabled={isSaving}
                  onClick={() => setEditingCard(null)}
                  className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200/70 dark:hover:bg-slate-700 transition-all"
                  title="Cancel"
                >
                  <X size={16} />
                </button>
                <button
                  disabled={isSaving}
                  onClick={async () => {
                    await saveSyllabusData({
                      code: editHeaderCode,
                      name: editHeaderName,
                      degreeLevel: editHeaderDegree,
                      credits: editHeaderCredits,
                      timeAllocation: editHeaderTimeAlloc,
                      prerequisites: editHeaderPrereqs,
                    })
                    if (subject) {
                      setSubject((prev: SubjectRow | null) => prev ? {
                        ...prev,
                        code: editHeaderCode,
                        name: editHeaderName,
                        semester: editHeaderSemester,
                      } : prev)
                    }
                  }}
                  className="p-1.5 rounded-lg text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950 transition-all disabled:opacity-50"
                  title="Save"
                >
                  {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                </button>
              </div>
            ) : (
              <button
                onClick={() => {
                  setEditHeaderName(syllabus.name)
                  setEditHeaderCode(syllabus.code)
                  setEditHeaderDegree(syllabus.degreeLevel)
                  setEditHeaderSemester(subject?.semester ? Number(subject.semester) : 1)
                  setEditHeaderCredits(syllabus.credits)
                  setEditHeaderTimeAlloc(syllabus.timeAllocation)
                  setEditHeaderPrereqs(syllabus.prerequisites)
                  setEditingCard('header')
                }}
                className="p-1.5 rounded-lg text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-slate-200/70 dark:hover:bg-slate-700 transition-all"
                title="Edit"
              >
                <Pencil size={16} />
              </button>
            )}
          </div>

          {/* Subject name */}
          {editingCard === 'header' ? (
            <input
              value={editHeaderName}
              onChange={e => setEditHeaderName(e.target.value)}
              className="text-2xl sm:text-3xl font-extrabold tracking-tight w-full bg-white dark:bg-slate-700 text-slate-900 dark:text-white px-3 py-2 rounded-xl border border-slate-300 dark:border-slate-600 focus:border-brand-400 dark:focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500/20 transition-all"
              placeholder="Subject Name"
            />
          ) : (
            <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-slate-900 dark:text-white leading-tight">
              {syllabus.name}
            </h1>
          )}

          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed max-w-2xl">
            Detailed course syllabus, Learning Outcomes (CLO/ABET), session schedule, and assessment scheme.
          </p>

          {/* Time & Prerequisites */}
          <div className="pt-2 flex flex-wrap items-center gap-x-6 gap-y-2 text-xs text-slate-500 dark:text-slate-400 border-t border-brand-100 dark:border-slate-700/60">
            {editingCard === 'header' ? (
              <>
                <div className="flex items-center gap-1.5">
                  <span className="font-semibold shrink-0">Time:</span>
                  <input
                    value={editHeaderTimeAlloc}
                    onChange={e => setEditHeaderTimeAlloc(e.target.value)}
                    className="bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded px-2 py-0.5 text-xs w-72 focus:outline-none focus:border-brand-500 text-slate-700 dark:text-slate-200 transition-all"
                  />
                </div>
                <div className="flex items-center gap-1.5 flex-1 min-w-0">
                  <span className="font-semibold shrink-0">Prerequisites:</span>
                  <input
                    value={editHeaderPrereqs}
                    onChange={e => setEditHeaderPrereqs(e.target.value)}
                    className="bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded px-2 py-0.5 text-xs w-full max-w-xs focus:outline-none focus:border-brand-500 text-slate-700 dark:text-slate-200 transition-all"
                  />
                </div>
              </>
            ) : (
              <>
                <span>Time: <strong className="text-slate-700 dark:text-slate-200">{syllabus.timeAllocation}</strong></span>
                <span>Prerequisites: <strong className="text-slate-700 dark:text-slate-200">{syllabus.prerequisites}</strong></span>
              </>
            )}
            <span className="text-slate-400 dark:text-slate-500">
              Sessions: <strong className="text-slate-600 dark:text-slate-300">{syllabus.sessions.length}</strong>
            </span>
          </div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="flex flex-wrap items-center gap-1 p-1 bg-slate-100 dark:bg-slate-800/60 rounded-lg border border-slate-200/80 dark:border-slate-700/50 w-fit">
        {[
          { key: 'syllabus' as TabType, label: 'Syllabus Overview' },
          { key: 'clos' as TabType, label: `CLO List (${syllabus.clos.length})` },
          { key: 'sessions' as TabType, label: `Sessions (${syllabus.sessions.length})` },
          { key: 'assessment' as TabType, label: `Assessment (${syllabus.assessments.length})` },
        ].map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`px-4 py-2 rounded-md text-sm font-semibold transition-all ${
              activeTab === tab.key
                ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm'
                : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* TAB 1: OVERVIEW */}
      {activeTab === 'syllabus' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            {/* Description Card */}
            <div className="p-5 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-slate-800 dark:text-slate-100 font-bold text-base">Course Description</h3>
                {editingCard === 'description' ? (
                  <div className="flex items-center gap-1.5">
                    <button
                      disabled={isSaving}
                      onClick={() => { setEditingCard(null) }}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                      title="Cancel"
                    >
                      <X size={16} />
                    </button>
                    <button
                      disabled={isSaving}
                      onClick={async () => {
                        await saveSyllabusData({ description: editDescription })
                      }}
                      className="p-1.5 rounded-lg text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950 transition-all disabled:opacity-50"
                      title="Save"
                    >
                      {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                    </button>
                  </div>
                ) : (
                  <button
                    onClick={() => { setEditDescription(syllabus.description); setEditingCard('description') }}
                    className="p-1.5 rounded-lg text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-950 transition-all"
                    title="Edit content"
                  >
                    <Pencil size={16} />
                  </button>
                )}
              </div>
              {editingCard === 'description' ? (
                <textarea
                  value={editDescription}
                  onChange={e => setEditDescription(e.target.value)}
                  className="w-full min-h-[180px] p-3 rounded-xl text-sm leading-relaxed font-medium bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 focus:outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500/30 transition-all resize-y"
                />
              ) : (
                <p className="text-slate-600 dark:text-slate-300 text-sm leading-relaxed whitespace-pre-line font-medium">
                  {syllabus.description}
                </p>
              )}
            </div>

            {/* ABET Course Learning Outcomes Card */}
            <div className="p-5 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50 space-y-5">
              <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-700/50">
                <h3 className="text-slate-800 dark:text-slate-100 font-bold text-base">Course Learning Outcomes (ABET)</h3>
                <div className="flex items-center gap-2">
                  <span className="text-xs font-semibold text-slate-400">Upon completing the course</span>
                  {editingCard === 'learningOutcomes' ? (
                    <div className="flex items-center gap-1.5">
                      <button
                        disabled={isSaving}
                        onClick={() => { setEditingCard(null) }}
                        className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                        title="Cancel"
                      >
                        <X size={16} />
                      </button>
                      <button
                        disabled={isSaving}
                        onClick={async () => {
                          await saveSyllabusData({ learningOutcomes: editLearningOutcomes })
                        }}
                        className="p-1.5 rounded-lg text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950 transition-all disabled:opacity-50"
                        title="Save"
                      >
                        {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                      </button>
                    </div>
                  ) : (
                    <button
                      onClick={() => { setEditLearningOutcomes(JSON.parse(JSON.stringify(syllabus.learningOutcomes))); setEditingCard('learningOutcomes') }}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-950 transition-all"
                      title="Edit content"
                    >
                      <Pencil size={16} />
                    </button>
                  )}
                </div>
              </div>

              {editingCard === 'learningOutcomes' ? (
                <div className="space-y-6">
                  {editLearningOutcomes.map((section: any, idx: number) => (
                    <div key={idx} className="space-y-3">
                      <div className="flex items-center gap-2">
                        <h4 className="font-extrabold text-slate-900 dark:text-white text-sm">
                          {section.category}
                        </h4>
                        <span className="px-2 py-0.5 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 text-xs font-mono font-bold rounded">
                          {section.code}
                        </span>
                      </div>
                      <div className="space-y-2 pl-1">
                        {section.items.map((item: string, i: number) => (
                          <div key={i} className="flex items-start gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 shrink-0 mt-3" />
                            <input
                              type="text"
                              value={item}
                              onChange={e => {
                                const newOutcomes = [...editLearningOutcomes]
                                newOutcomes[idx] = { ...newOutcomes[idx], items: [...newOutcomes[idx].items] }
                                newOutcomes[idx].items[i] = e.target.value
                                setEditLearningOutcomes(newOutcomes)
                              }}
                              className="flex-1 px-2.5 py-1.5 rounded-lg text-xs sm:text-sm bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 focus:outline-none focus:border-brand-500 transition-all"
                            />
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="space-y-6">
                  {syllabus.learningOutcomes.map((section: any, idx: number) => (
                    <div key={idx} className="space-y-3">
                      <div className="flex items-center gap-2">
                        <h4 className="font-extrabold text-slate-900 dark:text-white text-sm">
                          {section.category}
                        </h4>
                        <span className="px-2 py-0.5 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 text-xs font-mono font-bold rounded">
                          {section.code}
                        </span>
                      </div>

                      <ul className="space-y-2 pl-1">
                        {section.items.map((item: string, i: number) => (
                          <li key={i} className="flex items-start gap-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 shrink-0 mt-2" />
                            <span>{item}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Student Tasks Card */}
            <div className="p-5 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-slate-800 dark:text-slate-100 font-bold text-base">Student Tasks</h3>
                {editingCard === 'studentTasks' ? (
                  <div className="flex items-center gap-1.5">
                    <button
                      disabled={isSaving}
                      onClick={() => { setEditingCard(null) }}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                      title="Cancel"
                    >
                      <X size={16} />
                    </button>
                    <button
                      disabled={isSaving}
                      onClick={async () => {
                        await saveSyllabusData({ studentTasks: editStudentTasks })
                      }}
                      className="p-1.5 rounded-lg text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950 transition-all disabled:opacity-50"
                      title="Save"
                    >
                      {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                    </button>
                  </div>
                ) : (
                  <button
                    onClick={() => { setEditStudentTasks([...syllabus.studentTasksList]); setEditingCard('studentTasks') }}
                    className="p-1.5 rounded-lg text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-950 transition-all"
                    title="Edit content"
                  >
                    <Pencil size={16} />
                  </button>
                )}
              </div>
              {editingCard === 'studentTasks' ? (
                <div className="space-y-3">
                  {editStudentTasks.map((task, idx) => (
                    <div key={idx} className="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-900/40 rounded-lg border border-slate-100 dark:border-slate-700/50">
                      <span className="text-xs font-mono font-bold text-slate-400 shrink-0 mt-2">{idx + 1}.</span>
                      <textarea
                        value={task}
                        onChange={e => {
                          const newTasks = [...editStudentTasks]
                          newTasks[idx] = e.target.value
                          setEditStudentTasks(newTasks)
                        }}
                        className="flex-1 min-h-[40px] px-2.5 py-1.5 rounded-lg text-xs sm:text-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 focus:outline-none focus:border-brand-500 transition-all resize-y leading-relaxed font-medium"
                      />
                    </div>
                  ))}
                </div>
              ) : (
                <div className="space-y-2">
                  {syllabus.studentTasksList.map((task, idx) => (
                    <div key={idx} className="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-900/40 rounded-lg border border-slate-100 dark:border-slate-700/50">
                      <span className="text-xs font-mono font-bold text-slate-400 shrink-0 mt-0.5">{idx + 1}.</span>
                      <p className="text-xs sm:text-sm text-slate-700 dark:text-slate-300 leading-relaxed">
                        {task}
                      </p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Right Column (1/3 width) */}
          <div className="space-y-6">
            {/* Tools Card */}
            <div className="p-5 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-slate-800 dark:text-slate-100 font-bold text-base">Tools & Software</h3>
                {editingCard === 'tools' ? (
                  <div className="flex items-center gap-1.5">
                    <button
                      disabled={isSaving}
                      onClick={() => { setEditingCard(null) }}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                      title="Cancel"
                    >
                      <X size={16} />
                    </button>
                    <button
                      disabled={isSaving}
                      onClick={async () => {
                        await saveSyllabusData({ tools: editTools })
                      }}
                      className="p-1.5 rounded-lg text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950 transition-all disabled:opacity-50"
                      title="Save"
                    >
                      {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                    </button>
                  </div>
                ) : (
                  <button
                    onClick={() => { setEditTools([...syllabus.tools]); setEditingCard('tools') }}
                    className="p-1.5 rounded-lg text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-950 transition-all"
                    title="Edit content"
                  >
                    <Pencil size={16} />
                  </button>
                )}
              </div>
              {editingCard === 'tools' ? (
                <div className="flex flex-col gap-2">
                  {editTools.map((t: string, i: number) => (
                    <div key={i} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-slate-50 dark:bg-slate-900/40 border border-slate-200 dark:border-slate-700/50">
                      <span className="text-xs font-mono text-slate-400 shrink-0">{i + 1}.</span>
                      <input
                        type="text"
                        value={t}
                        onChange={e => {
                          const newTools = [...editTools]
                          newTools[i] = e.target.value
                          setEditTools(newTools)
                        }}
                        className="flex-1 bg-transparent text-slate-700 dark:text-slate-300 text-xs font-medium focus:outline-none"
                      />
                    </div>
                  ))}
                </div>
              ) : (
                <div className="flex flex-col gap-2">
                  {syllabus.tools.map((t: string, i: number) => (
                    <div key={i} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-slate-50 dark:bg-slate-900/40 text-slate-700 dark:text-slate-300 text-xs font-medium border border-slate-200 dark:border-slate-700/50">
                      <span className="text-xs font-mono text-slate-400 shrink-0">•</span>
                      <span>{t}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Assessment Summary Box */}
            <div className="p-5 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-slate-800 dark:text-slate-100 font-bold text-base">Assessment Weight</h3>
                <div className="flex items-center gap-2">
                  {editingCard === 'assessments' ? (
                    <div className="flex items-center gap-1.5">
                      <button
                        disabled={isSaving}
                        onClick={() => { setEditingCard(null) }}
                        className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                        title="Cancel"
                      >
                        <X size={16} />
                      </button>
                      <button
                        disabled={isSaving || !isAssessmentTotalValid}
                        onClick={async () => {
                          await saveSyllabusData({ assessments: editAssessments })
                        }}
                        className="p-1.5 rounded-lg text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950 transition-all disabled:opacity-40 disabled:cursor-not-allowed"
                        title={!isAssessmentTotalValid ? 'Total weight must be exactly 100%' : 'Save'}
                      >
                        {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                      </button>
                    </div>
                  ) : (
                    <>
                      <button onClick={() => setActiveTab('assessment')} className="text-xs text-brand-600 dark:text-brand-400 font-bold hover:underline">
                        View Details
                      </button>
                      <button
                        onClick={() => { setEditAssessments(JSON.parse(JSON.stringify(syllabus.assessments))); setEditingCard('assessments') }}
                        className="p-1.5 rounded-lg text-slate-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-950 transition-all"
                        title="Edit content"
                      >
                        <Pencil size={16} />
                      </button>
                    </>
                  )}
                </div>
              </div>
              {editingCard === 'assessments' ? (
                <div className="space-y-3">
                  {/* Alert banner for non-100% total */}
                  {!isAssessmentTotalValid ? (
                    <div className="p-3 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-700 dark:text-amber-300 text-xs font-semibold flex items-center justify-between gap-2">
                      <div className="flex items-center gap-1.5">
                        <AlertCircle size={15} className="shrink-0 text-amber-500" />
                        <span>
                          {editAssessmentTotal > 100
                            ? `Current total is ${editAssessmentTotal.toFixed(1)}% (exceeds 100%)`
                            : `Current total is ${editAssessmentTotal.toFixed(1)}% (under 100%)`}
                        </span>
                      </div>
                      <button
                        type="button"
                        onClick={handleAutoBalanceAssessments}
                        className="px-2 py-0.5 rounded-md bg-amber-500 text-white hover:bg-amber-600 text-[11px] font-bold transition-all shrink-0 shadow-xs"
                      >
                        Balance 100%
                      </button>
                    </div>
                  ) : (
                    <div className="p-2.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-700 dark:text-emerald-400 text-xs font-semibold flex items-center gap-1.5">
                      <Check size={14} className="shrink-0 text-emerald-500" strokeWidth={3} />
                      <span>Total weight perfectly matches 100%</span>
                    </div>
                  )}

                  <div className="space-y-2">
                    {editAssessments.map((a: any, idx: number) => {
                      const isLast = idx === editAssessments.length - 1
                      return (
                        <div key={idx} className="flex items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 text-xs">
                          <input
                            type="text"
                            value={a.category}
                            onChange={e => {
                              const newAssessments = [...editAssessments]
                              newAssessments[idx] = { ...newAssessments[idx], category: e.target.value }
                              setEditAssessments(newAssessments)
                            }}
                            className="flex-1 font-semibold text-slate-700 dark:text-slate-300 bg-transparent focus:outline-none border-b border-transparent focus:border-brand-500 transition-all"
                            placeholder="Assessment component name"
                          />
                          <div className="flex items-center gap-1.5">
                            <input
                              type="number"
                              min="0"
                              max="100"
                              value={a.weightPercent}
                              onChange={e => {
                                const val = parseFloat(e.target.value) || 0
                                handleAssessmentWeightChange(idx, val)
                              }}
                              className="w-14 text-right font-bold text-brand-600 dark:text-brand-400 bg-white dark:bg-slate-950 px-2 py-0.5 rounded-lg border border-slate-200 dark:border-slate-700 focus:outline-none focus:border-brand-500"
                            />
                            <span className="font-bold text-brand-600 dark:text-brand-400">%</span>
                            {isLast && (
                              <span className="text-[10px] font-bold text-brand-500 bg-brand-50 dark:bg-brand-950 px-1 py-0.5 rounded" title="Auto-balance remaining">
                                Auto
                              </span>
                            )}
                          </div>
                        </div>
                      )
                    })}
                  </div>
                </div>
              ) : (
                <div className="space-y-2.5">
                  {syllabus.assessments.map((a: any, idx: number) => (
                    <div key={idx} className="flex items-center justify-between p-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 text-xs">
                      <span className="font-semibold text-slate-700 dark:text-slate-300">{a.category}</span>
                      <span className="font-bold text-brand-600 dark:text-brand-400 bg-brand-50 dark:bg-brand-950 px-2 py-0.5 rounded-lg">
                        {a.weightPercent}%
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* TAB 2: CLOS */}
      {activeTab === 'clos' && (
        <div className="space-y-6">
          <div className="p-5 rounded-xl bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50 space-y-5">
            <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-700/50">
              <h3 className="font-bold text-base text-slate-800 dark:text-slate-100">
                CLO List
              </h3>
              <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-brand-600 bg-brand-50 dark:bg-brand-950 px-3 py-1 rounded-full">
                  Total: {syllabus.clos.length} CLOs
                </span>
                {editingCard === 'clos' ? (
                  <div className="flex items-center gap-1.5">
                    <button
                      disabled={isSaving}
                      onClick={() => setEditingCard(null)}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                      title="Cancel"
                    >
                      <X size={16} />
                    </button>
                    <button
                      disabled={isSaving}
                      onClick={async () => {
