type TabType = 'overview' | 'clos' | 'sessions' | 'assessment' | 'assignments'

export default function StudentSubjectDetailPage() {
  const params = useParams()
  const router = useRouter()
  const rawCode = (params?.code as string) || ''
  const code = rawCode.toUpperCase()

  const { language, t } = useLanguage()
  const isVi = language === 'vi'

  const [subject, setSubject] = React.useState<any>(null)
  const [assignments, setAssignments] = React.useState<any[]>([])
  const [loading, setLoading] = React.useState(true)
  const [activeTab, setActiveTab] = React.useState<TabType>('overview')
  const [sessionSearch, setSessionSearch] = React.useState('')

  React.useEffect(() => {
    if (!code) return

    setLoading(true)
    Promise.all([
      subjectsApi.getSubjects(1, 1000).catch(() => []),
      assignmentsApi.getAssignments().catch(() => []),
    ])
      .then(([subjectsList, allAssignments]) => {
        const found = (subjectsList || []).find(
          (s: any) =>
            (s.code && s.code.toLowerCase() === code.toLowerCase()) ||
            (s.SubjectCode && s.SubjectCode.toLowerCase() === code.toLowerCase())
        )

        if (found) {
          setSubject(found)
        } else {
          setSubject({
            id: code,
            code: code,
            name: `${code} - Course Subject`,
            description: DEFAULT_SUBJECT_DESCRIPTIONS[code] || 'Chương trình đào tạo kỹ thuật phần mềm chuẩn Đại học FPT.',
            credits: 3,
          })
        }

        // Filter assignments matching this subject code or id
        const subjectAssignments = (allAssignments || []).filter((a: any) => {
          const sId = String(found?.id || (found as any)?.Id || '')
          return (
            (a.subjectId && sId && a.subjectId === sId) ||
            (a.subjectName && a.subjectName.toLowerCase() === code.toLowerCase()) ||
            (a.title && a.title.toLowerCase().includes(code.toLowerCase()))
          )
        })
        setAssignments(subjectAssignments)
      })
      .finally(() => setLoading(false))
  }, [code])

  // Parse Syllabus Data
  const syllabus = React.useMemo(() => {
    let parsed: any = null
    if (subject?.syllabusData) {
      try {
        parsed = typeof subject.syllabusData === 'string' ? JSON.parse(subject.syllabusData) : subject.syllabusData
      } catch {
        parsed = null
      }
    }

    const desc =
      parsed?.description ||
      subject?.description ||
      DEFAULT_SUBJECT_DESCRIPTIONS[code] ||
      (isVi ? 'Môn học cung cấp kiến thức nền tảng và chuyên sâu về cấu trúc dữ liệu, giải thuật và phát triển phần mềm theo tiêu chuẩn đào tạo của Đại học FPT.' : 'Provides fundamental and advanced knowledge on data structures, algorithms and software development.')

    const credits = parsed?.credits ?? parsed?.noCredit ?? subject?.credits ?? 3
    const degreeLevel = parsed?.degreeLevel || 'Bachelor of Software Engineering'
    const timeAllocation = parsed?.timeAllocation || '150 giờ (45h tiếp xúc trên lớp + 1h thi cuối kỳ + 104h tự học)'
    const prerequisites = parsed?.prerequisites || parsed?.preRequisite || 'None'

    const studentTasks: string[] = Array.isArray(parsed?.studentTasks)
      ? parsed.studentTasks
      : isVi ? [
          'Sinh viên phải tham gia tối thiểu 80% thời lượng các buổi học để đủ điều kiện thi cuối kỳ (FE).',
          'Hoàn thành đầy đủ các bài tập Lab, Practical Exam và Assignment đúng hạn trên hệ thống AITA.',
          'Sử dụng máy tính cá nhân trong lớp học đúng mục đích nghiên cứu và thực hành lập trình.',
          'Chủ động tra cứu tài liệu học tập, slide bài giảng và cập nhật thông báo trên cổng thông tin FLM / AITA.',
        ] : [
          'Attend at least 80% of classes to be eligible for Final Exam (FE).',
          'Complete all Lab, Practical Exam and Assignments on AITA.',
          'Use personal laptop in class for programming and research purposes.',
          'Proactively review materials and check notices on FLM/AITA.',
        ]

    const tools: string[] = parsed?.tools || ['VS Code / IntelliJ IDEA / NetBeans', 'Git / GitHub', 'Java JDK 17 / .NET 8 / C++ Compiler', 'SQL Server / PostgreSQL']

    const defaultLearningOutcomes = [
      {
        category: isVi ? '1. Kiến thức cốt lõi' : '1. Core Knowledge',
        code: '(ABET e)',
        items: [
          'Hiểu rõ các nguyên lý thuật toán, cấu trúc dữ liệu và mô hình hướng đối tượng.',
          'Nắm vững quy trình thiết kế, kiểm thử và tối ưu mã nguồn theo chuẩn công nghiệp.',
        ],
      },
      {
        category: isVi ? '2. Kỹ năng lập trình & Giải quyết vấn đề' : '2. Programming Skills',
        code: '(ABET k)',
        items: [
          'Hiện thực hóa thuật toán và cấu trúc dữ liệu vào giải quyết bài toán thực tế.',
          'Tổ chức mã nguồn khoa học, xử lý ngoại lệ và debug lỗi hiệu quả.',
        ],
      },
      {
        category: isVi ? '3. Tác phong & Làm việc nhóm' : '3. Professional Practice',
        code: '(ABET i)',
        items: [
          'Kỹ năng tự nghiên cứu tài liệu kỹ thuật tiếng Anh chuyên ngành.',
          'Tuân thủ đạo đức nghề nghiệp, bảo mật mã nguồn và bản quyền phần mềm.',
        ],
      },
    ]

    const learningOutcomes = parsed?.learningOutcomes || defaultLearningOutcomes

    const clos = (parsed?.clos || []).length > 0
      ? parsed.clos.map((c: any) => ({
          code: c.code || c.cloName || 'CLO',
          details: c.details || c.cloDetails || '',
          loDetails: c.loDetails || '',
        }))
      : isVi ? [
          { code: 'CLO1', loDetails: 'LO1', details: 'Nắm vững các khái niệm và cú pháp lập trình căn bản.' },
          { code: 'CLO2', loDetails: 'LO2', details: 'Áp dụng các cấu trúc dữ liệu và giải thuật vào giải quyết bài toán nghiệp vụ.' },
          { code: 'CLO3', loDetails: 'LO3', details: 'Phân tích độ phức tạp thời gian/không gian thuật toán và tối ưu hóa.' },
          { code: 'CLO4', loDetails: 'LO4', details: 'Xây dựng ứng dụng hoàn chỉnh có kiểm thử và xử lý lỗi an toàn.' },
        ] : [
          { code: 'CLO1', loDetails: 'LO1', details: 'Master basic programming concepts and syntax.' },
          { code: 'CLO2', loDetails: 'LO2', details: 'Apply data structures and algorithms to business problems.' },
          { code: 'CLO3', loDetails: 'LO3', details: 'Analyze time/space complexity and optimization.' },
          { code: 'CLO4', loDetails: 'LO4', details: 'Build complete apps with testing and error handling.' },
        ]

    const assessments = (parsed?.assessments || parsed?.assessmentScheme || []).length > 0
      ? (parsed?.assessments || parsed?.assessmentScheme || []).map((a: any) => ({
          category: a.category || a.name || 'Assessment',
          weightPercent: (a.weightPercent ?? parseFloat(String(a.weight || '0').replace('%', ''))) || 0,
        }))
      : [
          { category: 'Attendance & Participation', weightPercent: 10 },
          { category: 'Assignment 1 & 2 (AI Grading)', weightPercent: 20 },
          { category: 'Progress Tests (PT)', weightPercent: 15 },
          { category: 'Practical Exam (PE)', weightPercent: 25 },
          { category: 'Final Exam (FE)', weightPercent: 30 },
        ]

    // Default 30 sessions if not in syllabus
    const sessions = (parsed?.sessions || []).length > 0
      ? parsed.sessions.map((ses: any, index: number) => ({
          sessionNo: ses.sessionNo ?? ses.session ?? (index + 1),
          topic: ses.topic || '',
          type: ses.type || 'Offline',
          clo: ses.clo || 'CLO1',
          itu: ses.itu || 'I',
          studentTasks: Array.isArray(ses.studentTasks) ? ses.studentTasks.join(', ') : (ses.studentTasks || ''),
          materialsDownloadUrl: ses.materialsDownloadUrl || ses.cloudinaryUrl || (ses.sDownload ? '#' : undefined),
        }))
      : Array.from({ length: 30 }, (_, i) => ({
          sessionNo: i + 1,
          topic: `Slot ${i + 1}: ${isVi ? (i < 10 ? 'Kiến thức nền tảng & Cấu trúc cơ bản' : i < 20 ? 'Thuật toán nâng cao & Thao tác cấu trúc' : 'Thực hành dự án, Kiểm thử & Đánh giá') : (i < 10 ? 'Fundamental Knowledge & Data Structures' : i < 20 ? 'Advanced Algorithms & Manipulation' : 'Project Practice, Testing & Evaluation')}`,
          type: i % 4 === 0 ? 'Online Lab' : 'Offline Lecture',
          clo: i < 10 ? 'CLO1' : i < 20 ? 'CLO2' : 'CLO3',
          itu: i < 10 ? 'I' : i < 20 ? 'T' : 'U',
          studentTasks: isVi ? 'Nghiên cứu tài liệu trước buổi học, hoàn thành code bài tập tại lớp.' : 'Study materials before class, complete coding exercises in class.',
          materialsDownloadUrl: '#',
        }))

    return {
      name: parsed?.name || subject?.name || subject?.SubjectName || `${code} - ${isVi ? 'Chuyên ngành CNTT' : 'IT Major'}`,
      code: code,
      description: desc,
      credits,
      degreeLevel,
      timeAllocation,
      prerequisites,
      studentTasks,
      tools,
      learningOutcomes,
      clos,
      assessments,
      sessions,
    }
  }, [subject, code, isVi])

  const filteredSessions = React.useMemo(() => {
    if (!sessionSearch.trim()) return syllabus.sessions
    const q = sessionSearch.toLowerCase()
    return syllabus.sessions.filter(
      (s: any) =>
        s.topic.toLowerCase().includes(q) ||
        s.studentTasks.toLowerCase().includes(q) ||
        String(s.sessionNo).includes(q)
    )
  }, [syllabus.sessions, sessionSearch])

  return (
    <DashboardLayout
      navItems={STUDENT_NAV}
      title="AITA Student"
      roleLabel={t('profile.role_student', 'Sinh viên')}
      requiredRole="student"
      headerTitle={`${code} — ${syllabus.name}`}
      headerSubtitle={isVi ? 'Đề cương chi tiết, chuẩn đầu ra (CLO/ABET) và bài tập môn học' : 'Course syllabus, CLO/ABET mapping, and assignments'}
    >
      <div className="space-y-6">
        {/* Breadcrumb Navigation */}
        <div className="flex items-center justify-between">
          <button
            onClick={() => router.push('/student/courses')}
            className="inline-flex items-center gap-2 text-xs font-semibold text-slate-600 dark:text-slate-400 hover:text-orange-500 dark:hover:text-orange-400 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            <span>{isVi ? 'Quay lại danh sách môn học' : 'Back to Courses'}</span>
          </button>
          <div className="flex items-center gap-2 text-xs font-semibold text-slate-400">
            <Link href="/student" className="hover:underline">Student</Link>
            <ChevronRight className="w-3 h-3" />
            <Link href="/student/courses" className="hover:underline">Courses</Link>
            <ChevronRight className="w-3 h-3" />
            <span className="text-orange-500 font-bold">{code}</span>
          </div>
        </div>

        {/* Hero Header Banner */}
        <div className="rounded-2xl p-6 sm:p-8 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 relative overflow-hidden shadow-xs transition-all group">
          <div className="absolute -right-6 -bottom-6 w-40 h-40 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-3xl group-hover:from-orange-400/25 pointer-events-none" />
          <div className="space-y-4 max-w-3xl relative z-10">
            <div className="flex flex-wrap items-center gap-2">
              <Badge variant="orange" className="font-mono text-xs px-2.5 py-1 font-bold">
                {code}
              </Badge>
              <Badge variant="outline" className="text-xs bg-white/60 dark:bg-slate-900/60 border-orange-200/80">
                {syllabus.degreeLevel}
              </Badge>
              <Badge variant="outline" className="text-xs bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800 font-bold">
                {syllabus.credits} {isVi ? 'Tín chỉ' : 'Credits'}
              </Badge>
            </div>

            <h1 className="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white tracking-tight leading-tight">
              {syllabus.name}
            </h1>

            <p className="text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed font-normal">
              {syllabus.description}
            </p>

            <div className="pt-3 border-t border-orange-100/90 dark:border-slate-800 flex flex-wrap items-center gap-x-6 gap-y-2 text-xs text-slate-500 dark:text-slate-400">
              <span className="flex items-center gap-1.5">
                <Clock className="w-3.5 h-3.5 text-orange-500" />
                <span>{isVi ? 'Thời lượng' : 'Duration'}: <strong className="text-slate-700 dark:text-slate-200">{syllabus.timeAllocation}</strong></span>
              </span>
              <span className="flex items-center gap-1.5">
                <BookOpen className="w-3.5 h-3.5 text-orange-500" />
                <span>{isVi ? 'Tiên quyết' : 'Prerequisites'}: <strong className="text-slate-700 dark:text-slate-200">{syllabus.prerequisites}</strong></span>
              </span>
              <span className="flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5 text-orange-500" />
                <span>{isVi ? 'Tổng số buổi' : 'Total Sessions'}: <strong className="text-slate-700 dark:text-slate-200">{syllabus.sessions.length}</strong></span>
              </span>
            </div>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="inline-flex flex-wrap items-center gap-1 p-1.5 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 w-fit text-xs font-bold shadow-xs">
          <button
            onClick={() => setActiveTab('overview')}
            className={`px-3.5 py-1.5 rounded-xl transition-all cursor-pointer ${
              activeTab === 'overview'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20 font-bold'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            {isVi ? 'Tổng quan đề cương' : 'Syllabus Overview'}
          </button>
          <button
            onClick={() => setActiveTab('clos')}
            className={`px-3.5 py-1.5 rounded-xl transition-all cursor-pointer ${
              activeTab === 'clos'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20 font-bold'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            {isVi ? `Chuẩn đầu ra CLO (${syllabus.clos.length})` : `CLO List (${syllabus.clos.length})`}
          </button>
          <button
            onClick={() => setActiveTab('sessions')}
            className={`px-3.5 py-1.5 rounded-xl transition-all cursor-pointer ${
              activeTab === 'sessions'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20 font-bold'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            {isVi ? `Lịch trình buổi học (${syllabus.sessions.length})` : `Sessions (${syllabus.sessions.length})`}
          </button>
          <button
            onClick={() => setActiveTab('assessment')}
            className={`px-3.5 py-1.5 rounded-xl transition-all cursor-pointer ${
              activeTab === 'assessment'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20 font-bold'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            {isVi ? 'Cơ cấu điểm số' : 'Assessment Scheme'}
          </button>
          <button
            onClick={() => setActiveTab('assignments')}
            className={`px-3.5 py-1.5 rounded-xl transition-all flex items-center gap-1.5 cursor-pointer ${
              activeTab === 'assignments'
                ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20 font-bold'
                : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
            }`}
          >
            <span>{isVi ? 'Bài tập nộp bài' : 'Assignments'}</span>
            <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-mono font-bold ${
              activeTab === 'assignments' ? 'bg-white/20 text-white' : 'bg-orange-100/80 text-orange-700'
            }`}>
              {assignments.length}
            </span>
          </button>
        </div>

        {/* TAB 1: OVERVIEW */}
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-6">
              {/* Learning Outcomes (ABET) */}
              <Card className="p-6">
                <h3 className="text-base font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                  <Award className="w-4 h-4 text-orange-500" />
                  {isVi ? 'Mục tiêu học tập & Chuẩn ABET' : 'Course Learning Outcomes (ABET)'}
                </h3>
                <div className="space-y-4">
                  {syllabus.learningOutcomes.map((lo: any, idx: number) => (
                    <div key={idx} className="p-4 rounded-xl bg-slate-50/80 dark:bg-slate-900/50 border border-slate-200/80 dark:border-slate-800">
                      <div className="flex items-center justify-between mb-2">
                        <span className="font-bold text-xs text-slate-900 dark:text-white">{lo.category}</span>
                        <Badge variant="outline" className="text-[10px] font-mono">{lo.code}</Badge>
                      </div>
                      <ul className="space-y-1.5 text-xs text-slate-600 dark:text-slate-300">
                        {lo.items.map((it: string, i: number) => (
                          <li key={i} className="flex items-start gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-orange-500 shrink-0 mt-1.5" />
                            <span>{it}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
                </div>
              </Card>

              {/* Student Tasks */}
              <Card className="p-6">
                <h3 className="text-base font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                  <FileText className="w-4 h-4 text-orange-500" />
                  {isVi ? 'Yêu cầu & Nhiệm vụ của sinh viên' : 'Student Tasks & Requirements'}
                </h3>
                <div className="space-y-2.5">
                  {syllabus.studentTasks.map((task: string, idx: number) => (
                    <div key={idx} className="flex items-start gap-3 p-3 rounded-xl bg-slate-50/80 dark:bg-slate-900/50 border border-slate-200/80 dark:border-slate-800 text-xs">
                      <span className="font-mono font-bold text-orange-500 shrink-0 mt-0.5">{idx + 1}.</span>
                      <p className="text-slate-700 dark:text-slate-300 leading-relaxed">{task}</p>
                    </div>
                  ))}
                </div>
              </Card>
            </div>

            {/* Right Column */}
            <div className="space-y-6">
              {/* Tools & Tech Stack */}
              <Card className="p-6">
                <h3 className="text-base font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                  <Laptop className="w-4 h-4 text-orange-500" />
                  {isVi ? 'Công cụ & Phần mềm' : 'Tools & Software'}
                </h3>
                <div className="space-y-2">
                  {syllabus.tools.map((tool: string, idx: number) => (
                    <div key={idx} className="p-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800 text-xs font-medium flex items-center gap-2 text-slate-700 dark:text-slate-300">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 shrink-0" />
                      <span>{tool}</span>
                    </div>
                  ))}
                </div>
              </Card>

              {/* Assessment Preview Box */}
              <Card className="p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <Sparkles className="w-4 h-4 text-orange-500" />
                    {isVi ? 'Tóm tắt đầu điểm' : 'Grading Scheme'}
                  </h3>
                  <button
                    onClick={() => setActiveTab('assessment')}
                    className="text-xs text-orange-500 hover:underline font-semibold"
                  >
                    {isVi ? 'Chi tiết' : 'Details'}
                  </button>
                </div>
                <div className="space-y-2.5">
                  {syllabus.assessments.map((a: any, idx: number) => (
                    <div key={idx} className="flex items-center justify-between p-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800 text-xs">
                      <span className="font-medium text-slate-700 dark:text-slate-300">{a.category}</span>
                      <Badge variant="orange" className="font-mono text-xs">
                        {a.weightPercent}%
                      </Badge>
                    </div>
                  ))}
                </div>
              </Card>
            </div>
          </div>
        )}

        {/* TAB 2: CLOS */}
        {activeTab === 'clos' && (
          <Card className="p-6">
            <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-200/80 dark:border-slate-800">
              <div>
                <h3 className="text-base font-bold text-slate-900 dark:text-white">
                  {isVi ? 'Danh mục Chuẩn đầu ra môn học (Course Learning Outcomes)' : 'Course Learning Outcomes (CLOs)'}
                </h3>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                  {isVi ? 'Chi tiết các tiêu chuẩn năng lực sinh viên cần đạt sau khi hoàn tất môn học' : 'Detailed competence criteria expected upon course completion'}
                </p>
              </div>
              <Badge variant="orange" className="text-xs">
                {syllabus.clos.length} CLOs
              </Badge>
            </div>

            <div className="overflow-x-auto rounded-xl border border-slate-200/80 dark:border-slate-800">
              <table className="w-full text-left text-xs">
                <thead className="bg-slate-50 dark:bg-slate-900/60 text-slate-600 dark:text-slate-400 border-b border-slate-200/80 dark:border-slate-800">
                  <tr>
                    <th className="p-3 w-28 text-center font-bold">{isVi ? 'Mã CLO' : 'CLO Code'}</th>
                    <th className="p-3 w-32 font-bold">{isVi ? 'Ánh xạ LO' : 'LO Mapping'}</th>
                    <th className="p-3 font-bold">{isVi ? 'Nội dung chi tiết' : 'Details'}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                  {syllabus.clos.map((clo: any, idx: number) => (
                    <tr key={idx} className="hover:bg-slate-50/70 dark:hover:bg-slate-800/40 transition-colors">
                      <td className="p-3 text-center font-bold text-orange-600 dark:text-orange-400 font-mono">
                        {clo.code}
                      </td>
                      <td className="p-3 text-slate-500 dark:text-slate-400 font-mono">
                        {clo.loDetails || clo.code.replace('CLO', 'LO')}
                      </td>
                      <td className="p-3 text-slate-700 dark:text-slate-200 leading-relaxed">
                        {clo.details}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        )}

        {/* TAB 3: SESSIONS */}
        {activeTab === 'sessions' && (
          <Card className="p-6">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 pb-4 border-b border-slate-200/80 dark:border-slate-800">
              <div>
                <h3 className="text-base font-bold text-slate-900 dark:text-white">
                  {isVi ? 'Lịch trình bài giảng & Buổi học chi tiết' : 'Detailed Session Schedule'}
                </h3>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                  {isVi ? 'Kế hoạch từng slot học, tài liệu và nhiệm vụ thực hành' : 'Schedule of each slot, learning materials and tasks'}
                </p>
              </div>

              <div className="w-full sm:w-72">
                <Input
                  type="text"
                  placeholder={isVi ? 'Tìm kiếm slot, chủ đề...' : 'Search slot, topic...'}
                  icon={<Search className="w-4 h-4 text-slate-400" />}
                  value={sessionSearch}
                  onChange={(e) => setSessionSearch(e.target.value)}
                  className="bg-slate-50 dark:bg-slate-900"
                />
              </div>
            </div>

            <div className="overflow-x-auto rounded-xl border border-slate-200/80 dark:border-slate-800">
              <table className="w-full text-left text-xs">
                <thead className="bg-slate-50 dark:bg-slate-900/60 text-slate-600 dark:text-slate-400 border-b border-slate-200/80 dark:border-slate-800">
                  <tr>
                    <th className="p-3 w-16 text-center font-bold">Slot</th>
                    <th className="p-3 font-bold">{isVi ? 'Chủ đề bài học (Topic)' : 'Topic'}</th>
                    <th className="p-3 w-28 text-center font-bold">{isVi ? 'Hình thức' : 'Type'}</th>
                    <th className="p-3 w-20 text-center font-bold">CLO</th>
                    <th className="p-3 w-16 text-center font-bold">ITU</th>
                    <th className="p-3 font-bold">{isVi ? 'Nhiệm vụ sinh viên' : 'Student Tasks'}</th>
                    <th className="p-3 w-28 text-center font-bold">{isVi ? 'Tài liệu' : 'Materials'}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                  {filteredSessions.map((ses: any, idx: number) => (
                    <tr key={idx} className="hover:bg-slate-50/70 dark:hover:bg-slate-800/40 transition-colors">
                      <td className="p-3 text-center font-mono font-bold text-slate-500 dark:text-slate-400">
                        #{ses.sessionNo}
                      </td>
                      <td className="p-3 font-medium text-slate-800 dark:text-slate-200">
                        {ses.topic}
                      </td>
                      <td className="p-3 text-center">
                        <Badge variant={ses.type.includes('Online') ? 'blue' : 'outline'} className="text-[10px]">
                          {ses.type}
                        </Badge>
                      </td>
                      <td className="p-3 text-center font-mono text-orange-600 dark:text-orange-400">
                        {ses.clo}
                      </td>
                      <td className="p-3 text-center font-mono font-bold text-slate-500">
                        {ses.itu}
                      </td>
                      <td className="p-3 text-slate-600 dark:text-slate-400 leading-relaxed text-[11px]">
                        {ses.studentTasks}
                      </td>
                      <td className="p-3 text-center">
                        {ses.materialsDownloadUrl ? (
                          <a
                            href={ses.materialsDownloadUrl === '#' ? '#' : ses.materialsDownloadUrl}
                            target={ses.materialsDownloadUrl === '#' ? '_self' : '_blank'}
                            rel="noreferrer"
                            onClick={(e) => {
                              if (ses.materialsDownloadUrl === '#') {
                                e.preventDefault();
                                alert(isVi ? 'Tài liệu đang được cập nhật.' : 'Material is being updated.');
                              }
                            }}
                            className="inline-flex items-center gap-1 text-[10px] h-6 px-2 rounded-lg border border-blue-200 dark:border-blue-900 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/50 transition-colors font-medium"
                          >
                            <Download className="w-3 h-3" />
                            {isVi ? 'Tải về' : 'Download'}
                          </a>
                        ) : (
                          <span className="text-[10px] text-slate-400">—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        )}

        {/* TAB 4: ASSESSMENT */}
        {activeTab === 'assessment' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Card className="p-6">
              <h3 className="text-base font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-orange-500" />
                {isVi ? 'Cơ cấu & Trọng số đầu điểm' : 'Assessment Weights'}
              </h3>
              <div className="space-y-3">
                {syllabus.assessments.map((a: any, idx: number) => (
                  <div key={idx} className="p-3 rounded-xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200/80 dark:border-slate-800 flex justify-between items-center text-xs">
                    <div>
                      <span className="font-bold text-slate-800 dark:text-slate-200">{a.category}</span>
                      <p className="text-slate-500 dark:text-slate-400 text-[11px] mt-0.5">
                        {isVi ? 'Đánh giá năng lực theo chuẩn FLM' : 'Competency assessment per FLM standards'}
                      </p>
                    </div>
                    <Badge variant="orange" className="font-mono text-xs px-2.5 py-1">
                      {a.weightPercent}%
                    </Badge>
                  </div>
                ))}
              </div>
            </Card>

            <Card className="p-6">
              <h3 className="text-base font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-500" />
                {isVi ? 'Quy chế & Điều kiện qua môn (Passing Criteria)' : 'Passing Criteria'}
              </h3>
              <div className="space-y-3 text-xs text-slate-600 dark:text-slate-300">
                <div className="p-3 rounded-xl bg-emerald-50/60 dark:bg-emerald-950/20 border border-emerald-200/80 dark:border-emerald-800/40 space-y-1">
                  <span className="font-bold text-emerald-700 dark:text-emerald-400">{isVi ? '1. Điều kiện tham gia thi cuối kỳ (FE/PE):' : '1. Eligibility for Final Exam (FE/PE):'}</span>
                  <p className="text-[11px] leading-relaxed">
                    {isVi ? 'Sinh viên không nghỉ quá 20% tổng số buổi học và hoàn thành đầy đủ các bài tập Assignment.' : 'Students must not miss more than 20% of total classes and must complete all Assignments.'}
                  </p>
                </div>

                <div className="p-3 rounded-xl bg-orange-50/60 dark:bg-orange-950/20 border border-orange-200/80 dark:border-orange-800/40 space-y-1">
                  <span className="font-bold text-orange-700 dark:text-orange-400">{isVi ? '2. Điểm liệt các phần thi:' : '2. Minimum exam scores:'}</span>
                  <p className="text-[11px] leading-relaxed">
                    {isVi ? 'Điểm thi thực hành (PE) & Điểm thi lý thuyết cuối kỳ (FE) phải đạt tối thiểu từ 4.0 / 10.0 điểm trở lên.' : 'Practical Exam (PE) & Final Exam (FE) scores must be at least 4.0 / 10.0.'}
                  </p>
                </div>

                <div className="p-3 rounded-xl bg-blue-50/60 dark:bg-blue-950/20 border border-blue-200/80 dark:border-blue-800/40 space-y-1">
                  <span className="font-bold text-blue-700 dark:text-blue-400">{isVi ? '3. Điểm tổng kết môn:' : '3. Final subject score:'}</span>
                  <p className="text-[11px] leading-relaxed">
                    {isVi ? 'Điểm tổng kết trung bình có trọng số (Final Average Grade) đạt từ 5.0 / 10.0 trở lên để tính là qua môn.' : 'Final Average Grade must be at least 5.0 / 10.0 to pass the course.'}
                  </p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* TAB 5: ASSIGNMENTS */}
        {activeTab === 'assignments' && (
          <Card className="p-6">
            <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-200/80 dark:border-slate-800">
              <div>
                <h3 className="text-base font-bold text-slate-900 dark:text-white">
                  {isVi ? `Bài tập & Đề thi của môn ${code}` : `Assignments for ${code}`}
                </h3>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                  {isVi ? 'Các bài tập thực hành được chấm điểm tự động bằng Rubric AI' : 'Practical assignments automatically graded by AI Rubric'}
                </p>
              </div>
              <Badge variant="orange" className="text-xs">
                {assignments.length} {isVi ? 'Bài tập' : 'Assignments'}
              </Badge>
            </div>

            {assignments.length === 0 ? (
              <div className="p-12 text-center text-slate-400 text-xs border border-dashed rounded-2xl border-slate-200 dark:border-slate-800">
                <BookOpen className="w-8 h-8 mx-auto mb-2 text-slate-300 dark:text-slate-600" />
                <p>{isVi ? 'Hiện chưa có bài tập nào mở nộp cho môn học này.' : 'No active assignments for this subject at the moment.'}</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {assignments.map((assign: any) => (
                  <div
                    key={assign.id}
                    className="p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 hover:border-orange-500/40 bg-white/70 dark:bg-slate-900/40 transition-all flex flex-col justify-between gap-4 group"
                  >
                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <Badge variant="orange" className="text-[11px]">
                          {assign.type || 'Assignment'}
                        </Badge>
                        <span className="text-[11px] text-slate-400">
                          {isVi ? 'Hạn nộp' : 'Due'}: {assign.dueAt ? new Date(assign.dueAt).toLocaleDateString('vi-VN') : (isVi ? 'Không giới hạn' : 'No limit')}
                        </span>
                      </div>
                      <h4 className="font-bold text-sm text-slate-900 dark:text-white group-hover:text-orange-500 transition-colors">
                        {assign.title}
                      </h4>
                      <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2">
                        {assign.description || (isVi ? 'Đóng gói mã nguồn bài làm thành file .zip để nộp lên hệ thống AITA.' : 'Package your source code into a .zip file and submit to AITA.')}
                      </p>
                    </div>

                    <div className="pt-3 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between">
                      <span className="text-xs text-slate-400 font-medium">{isVi ? 'Barem' : 'Scale'} 10.0</span>
                      <Link href={`/student/assignments/${assign.id}`}>
                        <Button variant="primary" size="sm" className="text-xs gap-1">
                          <span>{isVi ? 'Nộp bài ngay' : 'Submit Code'}</span>
                          <ArrowRight className="w-3.5 h-3.5" />
                        </Button>
                      </Link>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </Card>
        )}
      </div>
    </DashboardLayout>
  )
}

'use client'

import { RefreshAction } from '@/components/actions/RefreshAction'

import * as React from 'react'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { STUDENT_NAV } from '@/config/navigation'
import { useLanguage } from '@/providers/language-provider'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { studentPortalApi } from '@/lib/api/modules/student-portal'
import { subjectsApi } from '@/lib/api/modules/subjects'
import { semestersApi } from '@/lib/api/modules/semesters'
import { BookOpen, ArrowRight, Search, Filter, AlertTriangle, RefreshCw, Layers, CheckCircle2 } from 'lucide-react'

export default function StudentCoursesPage() {
  const [subjects, setSubjects] = React.useState<any[]>([])
  const [semesters, setSemesters] = React.useState<any[]>([])
  const [selectedSemester, setSelectedSemester] = React.useState<string>('all')
  const [viewTab, setViewTab] = React.useState<'enrolled' | 'all'>('enrolled')
  const [searchQuery, setSearchQuery] = React.useState('')
  const [loading, setLoading] = React.useState(true)
  const [error, setError] = React.useState<string | null>(null)
  const { t } = useLanguage()

  // Load semesters list
  React.useEffect(() => {
    semestersApi.getSemesters()
      .then((data) => {
        const list = Array.isArray(data) ? data : []
        setSemesters(list)
      })
      .catch((err) => {
        console.error('Failed to load semesters:', err)
      })
  }, [])

  const loadCourses = React.useCallback(async (background = false) => {
    if (!background) setLoading(true)
    if (!background) setError(null)
    try {
      if (viewTab === 'enrolled') {
        const semParam = selectedSemester === 'all' ? undefined : selectedSemester
        const data = await studentPortalApi.getStudentSubjects(semParam)
        if (Array.isArray(data)) {
          setSubjects(data)
        } else {
          setSubjects([])
        }
      } else {
        const res: any = await subjectsApi.getSubjects(1, 1000)
        const list = Array.isArray(res) ? res : res?.data || []
        setSubjects(list)
      }
      setError(null)
    } catch (err: any) {
      if (background) throw err
      console.error('Failed to load courses:', err)
      setError(err?.message || t('student.courses.load_error', 'Không thể kết nối máy chủ để tải danh sách môn học. Vui lòng thử lại.'))
      setSubjects([])
    } finally {
      setLoading(false)
    }
  }, [viewTab, selectedSemester, t])

  React.useEffect(() => {
    loadCourses()
  }, [loadCourses])

  const filteredSubjects = React.useMemo(() => {
    let list = subjects
    if (selectedSemester !== 'all' && viewTab === 'all') {
      list = list.filter((sub: any) => {
        const rawSem = sub.semester && typeof sub.semester === 'object'
          ? (sub.semester.season || sub.semester.label || sub.semester.code || '')
          : (sub.semester || sub.semesterSeason || sub.SemesterSeason || '')
        const subSem = String(rawSem)
        return subSem.toLowerCase().includes(selectedSemester.toLowerCase())
      })
    }
    if (!searchQuery.trim()) return list
    const q = searchQuery.toLowerCase().trim()
    return list.filter((sub: any) => {
      const code = (sub.code || sub.SubjectCode || '').toLowerCase()
      const name = (sub.name || sub.SubjectName || '').toLowerCase()
      return code.includes(q) || name.includes(q)
    })
  }, [subjects, selectedSemester, viewTab, searchQuery])

  return (
    <DashboardLayout
      navItems={STUDENT_NAV}
      title="AITA Student"
      roleLabel={t('profile.role_student', 'Sinh viên')}
      requiredRole="student"
      headerTitle={t('student.courses.title', 'Môn học của tôi')}
      headerSubtitle={t('student.courses.subtitle', 'Danh sách các môn học CNTT và chương trình đào tạo')}
    >
      <div className="space-y-6 w-full pb-12">
        {/* Executive KPI Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Môn đang học
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <CheckCircle2 className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : subjects.length}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
              <span>Đã đăng ký học phần</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Tổng tín chỉ
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <Layers className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : subjects.reduce((acc, cur) => acc + (cur.credit || cur.credits || 3), 0)}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Tiêu chuẩn tốt nghiệp</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Khung chương trình
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <BookOpen className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : filteredSubjects.length}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Ngành Kỹ thuật phần mềm</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Học kỳ hiện tại
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <BookOpen className="w-5 h-5" />
              </div>
            </div>
            <div className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">
              SP26
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Spring 2026 Active</span>
            </div>
          </div>
        </div>

        {/* Controls Bar */}
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-4 p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
          {/* Tabs: Enrolled vs All */}
          <div className="inline-flex p-1 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 shadow-xs gap-1">
            <button
              onClick={() => setViewTab('enrolled')}
              className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                viewTab === 'enrolled'
                  ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                  : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
              }`}
            >
              <CheckCircle2 className="w-3.5 h-3.5" />
              <span>{t('student.courses.enrolled_tab', 'Môn đang học (Enrolled)')}</span>
            </button>
            <button
              onClick={() => setViewTab('all')}
              className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                viewTab === 'all'
                  ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                  : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
              }`}
            >
              <Layers className="w-3.5 h-3.5" />
              <span>{t('student.courses.all_tab', 'Tất cả môn học (All)')}</span>
            </button>
          </div>

          {/* Filters & Search */}
          <div className="flex items-center gap-3 flex-wrap">
            {/* Semester selector */}
            <div className="flex items-center gap-1.5 text-xs text-slate-500">
              <Filter className="w-3.5 h-3.5 text-slate-400" />
              <select
                value={selectedSemester}
                onChange={(e) => setSelectedSemester(e.target.value)}
                className="bg-white dark:bg-slate-800 border border-orange-200/80 dark:border-slate-700 rounded-xl px-3 py-1.5 text-xs font-semibold text-slate-800 dark:text-slate-200 outline-none focus:ring-2 focus:ring-orange-400/25"
              >
                <option value="all">{t('student.courses.all_semesters', 'Tất cả học kỳ')}</option>
                {semesters.map((sem: any) => (
                  <option key={sem.id || sem.season} value={sem.season || sem.id}>
                    {sem.season || sem.name || sem.id}
                  </option>
                ))}
              </select>
            </div>

            {/* Search */}
            <div className="relative w-full sm:w-60">
              <Search className="w-4 h-4 absolute left-3 top-2.5 text-slate-400" />
              <Input
                placeholder={t('student.courses.search_placeholder', 'Tìm theo mã hoặc tên môn...')}
                className="pl-9 h-9 text-xs rounded-xl border-orange-200/80 focus:border-orange-400"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>
        </div>

        {/* Section Header */}
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-2">
            <BookOpen className="w-5 h-5 text-orange-500 dark:text-orange-400" />
            {viewTab === 'enrolled'
              ? t('student.courses.enrolled_title', 'Môn học đã đăng ký trong chương trình')
              : t('student.courses.all_title', 'Toàn bộ danh mục môn học')}
            <span className="text-sm font-normal text-slate-500 ml-1">({filteredSubjects.length})</span>
          </h2>
        </div>

        {/* Error State Banner */}
        {error && (
          <div className="p-4 rounded-2xl bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-900/60 flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-xl bg-rose-100 dark:bg-rose-900/50 text-rose-600 dark:text-rose-400 flex items-center justify-center shrink-0">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div>
                <h4 className="text-xs font-bold text-rose-800 dark:text-rose-300">
                  {t('ui.error', 'Lỗi tải dữ liệu')}
                </h4>
                <p className="text-xs text-rose-600 dark:text-rose-400 mt-0.5">
                  {error}
                </p>
              </div>
            </div>
            <RefreshAction onRefresh={() => loadCourses(true)} disabled={loading} cachePaths={["/student-portal/subjects","/subjects"]} />
          </div>
        )}

        {/* Loading State */}
        {loading ? (
          <div className="p-16 text-center text-slate-500 dark:text-slate-400 text-sm flex flex-col items-center justify-center gap-2">
            <RefreshCw className="w-5 h-5 animate-spin text-orange-500" />
            <span>{t('ui.loading', 'Đang tải danh sách môn học...')}</span>
          </div>
        ) : filteredSubjects.length === 0 && !error ? (
          <Card className="p-12 text-center text-slate-500 dark:text-slate-400 border-dashed rounded-2xl">
            <BookOpen className="w-10 h-10 mx-auto text-slate-300 dark:text-slate-600 mb-3" />
            <p className="text-sm font-medium">
              {searchQuery
                ? t('student.courses.no_search_results', 'Không tìm thấy môn học nào khớp với từ khóa tìm kiếm.')
                : viewTab === 'enrolled'
                ? t('student.courses.empty_enrolled', 'Chưa có môn học nào được đăng ký trong kỳ được chọn.')
                : t('student.courses.empty_all', 'Không có môn học nào trong hệ thống.')}
            </p>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredSubjects.map((sub: any) => {
              const credits = sub.credit ?? sub.credits ?? 3
              const code = sub.code || sub.SubjectCode || ''
              const name = sub.name || sub.SubjectName || ''
              return (
                <Card
                  key={sub.id || code}
                  className="p-6 hover:border-orange-300 dark:hover:border-orange-800/60 transition-all flex flex-col justify-between group bg-white dark:bg-slate-900 border border-orange-100/90 dark:border-orange-900/30 rounded-2xl shadow-xs hover:shadow-md"
                >
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <Badge variant="orange" className="font-mono text-xs font-bold">
                        {code}
                      </Badge>
                      <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                        {credits} {t('student.courses.credits', 'Tín chỉ')}
                      </span>
                    </div>
                    <div>
                      <h3 className="text-base font-bold text-slate-900 dark:text-white group-hover:text-orange-500 dark:group-hover:text-orange-400 transition-colors">
                        {name}
                      </h3>
                      <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 mt-1">
                        {sub.description || t('student.courses.default_desc', 'Chương trình đào tạo kỹ thuật phần mềm chuẩn Đại học FPT.')}
                      </p>
                    </div>
                  </div>

                  <div className="pt-4 border-t border-slate-100 dark:border-slate-800/60 mt-4 flex items-center justify-between">
                    <span className="text-[11px] text-slate-500 dark:text-slate-400">
                      {sub.semester && typeof sub.semester === 'object'
                        ? (sub.semester.season || sub.semester.label || sub.semester.code)
                        : (sub.semester || sub.semesterSeason || (viewTab === 'enrolled' ? t('student.courses.status_enrolled', 'Đã ghi danh') : t('student.courses.status_available', 'Có sẵn')))}
                    </span>
                    <Link href={`/student/courses/${encodeURIComponent(code)}`}>
                      <Button variant="ghost" size="sm" className="text-xs text-orange-600 dark:text-orange-400 hover:text-orange-700 dark:hover:text-orange-300 gap-1 font-semibold">
                        <span>{t('student.courses.enter', 'Vào môn')}</span>
                        <ArrowRight className="w-3.5 h-3.5" />
                      </Button>
                    </Link>
                  </div>
                </Card>
              )
            })}
          </div>
        )}
      </div>
    </DashboardLayout>
  )
}

'use client'

import { RefreshAction } from '@/components/actions/RefreshAction'

import * as React from 'react'
import Link from 'next/link'
import { DashboardLayout } from '@/components/layout/DashboardLayout'
import { STUDENT_NAV } from '@/config/navigation'
import { useLanguage } from '@/providers/language-provider'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { studentPortalApi } from '@/lib/api/modules/student-portal'
import { assignmentsApi } from '@/lib/api/modules/assignments'
import { submissionsApi } from '@/lib/api/modules/submissions'
import { semestersApi } from '@/lib/api/modules/semesters'
import { peekClientApiCache } from '@/lib/api/client'
import { CardGridSkeleton } from '@/components/ui/skeleton'
import {
  BookOpen,
  Calendar,
  Clock,
  ChevronDown,
  ChevronUp,
  Database,
  Code,
  ArrowRight,
  GraduationCap,
  Check,
  CheckCircle2,
  AlertCircle,
  FileText,
  User,
  ExternalLink,
} from 'lucide-react'

export default function StudentSubjectsPage() {
  const { t } = useLanguage()

  const [subjects, setSubjects] = React.useState<any[]>([])
  const [assignments, setAssignments] = React.useState<any[]>([])
  const [semesters, setSemesters] = React.useState<any[]>([])
  const [selectedSemester, setSelectedSemester] = React.useState<string>('')
  const [activeSubjectTab, setActiveSubjectTab] = React.useState<string>('All')
  const [expandedSubjectId, setExpandedSubjectId] = React.useState<string | null>(null)
  const [loading, setLoading] = React.useState(true)
  const [error, setError] = React.useState<string | null>(null)
  const [semestersReady, setSemestersReady] = React.useState(false)
  const loadSequence = React.useRef(0)
  const selectedSemesterRow = semesters.find(s => s.id === selectedSemester)
  // The student portal endpoint filters by normalized season, not semester ID.
  const semesterFilter = selectedSemester
    ? String(selectedSemesterRow?.season || selectedSemesterRow?.code || selectedSemester).toUpperCase().replace(/\s+/g, '')
    : ''

  // Load semesters
  React.useEffect(() => {
    try {
      if (typeof peekClientApiCache === 'function') {
        const cachedSem = peekClientApiCache<any[]>('/semesters')
        if (cachedSem && cachedSem.length > 0) {
          setSemesters(cachedSem)
          const active = cachedSem.find((s: any) => s.isActive) || cachedSem[0]
          if (active) setSelectedSemester(active.id || active.code || '')
        }
      }
    } catch {}

    semestersApi
      .getSemesters()
      .then((sems) => {
        const list = Array.isArray(sems) ? sems : []
        setSemesters(list)
        const active = list.find((s: any) => s.isActive) || list[0]
        if (active) setSelectedSemester(active.id || active.code || '')
      })
      .catch(() => {})
      .finally(() => setSemestersReady(true))
  }, [])

  // Load subjects, assignments, submissions
  const loadData = React.useCallback(async (background = false) => {
    const sequence = ++loadSequence.current
    const path = `/student-portal/subjects${semesterFilter ? `?semester=${encodeURIComponent(semesterFilter)}` : ''}`
    const cachedSubjects = peekClientApiCache<any[]>(path)
    if (cachedSubjects) setSubjects(cachedSubjects)
    if (!background) setLoading(!cachedSubjects)
    setError(null)
    try {
      const [subjectsRes, assignmentsRes, submissionsRes] = await Promise.all([
        studentPortalApi.getStudentSubjects(semesterFilter || undefined).then(rows => {
          if (sequence === loadSequence.current) {
            setSubjects(Array.isArray(rows) ? rows : [])
            setLoading(false)
          }
          return rows
        }),
        assignmentsApi.getAssignments(),
        submissionsApi.getSubmissions({ view: 'summary' }),
      ])

      if (sequence !== loadSequence.current) return

      const rawSubjects = Array.isArray(subjectsRes) ? subjectsRes : []
      setSubjects(rawSubjects)

      const activeAssignments = (Array.isArray(assignmentsRes) ? assignmentsRes : []).filter(
        (a: any) => !a.isDeleted && !a.IsDeleted && (a.status || '').toLowerCase() !== 'deleted'
      )

      const subsList = Array.isArray(submissionsRes) ? submissionsRes : []
      const submissionsMap = new Map(subsList.map((s: any) => [s.assignmentId || s.examId, s]))

      const merged = activeAssignments.map((a: any) => {
        const sub = submissionsMap.get(a.id)
        if (sub) {
          const isPublished = sub.reviewStatus === 'PUBLISHED' || sub.isPublished === true
          const validScore = isPublished
            ? (sub.finalScore ?? sub.totalScore ?? sub.score ?? sub.Score)
            : undefined
          return {
            ...a,
            status: isPublished && validScore !== undefined && validScore !== null ? 'Graded' : 'Submitted',
            score: validScore,
            submissionId: sub.id,
          }
        }
        return a
      })

      // Sort newest to oldest
      merged.sort((a, b) => {
        const timeA = a.createdAt || a.due ? new Date(a.createdAt || a.due).getTime() : 0
        const timeB = b.createdAt || b.due ? new Date(b.createdAt || b.due).getTime() : 0
        return timeB - timeA
      })

      setAssignments(merged)

      // Auto expand first subject
      if (rawSubjects.length > 0 && !expandedSubjectId) {
        setExpandedSubjectId(rawSubjects[0].id || rawSubjects[0].code)
      }
    } catch (err: any) {
      if (background) throw err
      if (sequence !== loadSequence.current) return
      console.error('Failed to load student subjects data:', err)
      setError(err?.message || 'Không thể tải dữ liệu môn học. Vui lòng thử lại.')
    } finally {
      if (sequence === loadSequence.current) setLoading(false)
    }
  }, [semesterFilter])

  React.useEffect(() => {
    if (!semestersReady) return
    void loadData()
    return () => { loadSequence.current++ }
  }, [loadData, semestersReady])

  // Subject tabs
  const subjectTabs = React.useMemo(() => {
    const codes = Array.from(new Set(subjects.map((s: any) => s.code || s.SubjectCode).filter(Boolean)))
    return ['All', ...codes]
  }, [subjects])

  // Filtered subjects
  const visibleSubjects = React.useMemo(() => {
    if (activeSubjectTab === 'All') return subjects
    return subjects.filter((s: any) => (s.code || s.SubjectCode) === activeSubjectTab)
  }, [subjects, activeSubjectTab])

  // Overall Statistics
  const stats = React.useMemo(() => {
    const total = assignments.length
    const submitted = assignments.filter((a) => a.status === 'Submitted' || a.status === 'Graded').length
    const graded = assignments.filter((a) => a.status === 'Graded' && a.score !== undefined).length
    const missing = total - submitted

    let totalScore = 0
    let gradedCount = 0
    assignments.forEach((a) => {
      if (a.status === 'Graded' && a.score !== undefined && a.score !== null) {
        totalScore += Number(a.score)
        gradedCount++
      }
    })
    const avgScore = gradedCount > 0 ? (totalScore / gradedCount).toFixed(1) : '—'

    return { total, submitted, graded, missing, avgScore }
  }, [assignments])

  return (
    <DashboardLayout
      navItems={STUDENT_NAV}
      title="AITA Student"
      roleLabel={t('profile.role_student', 'Sinh viên')}
      requiredRole="student"
      headerTitle={t('student.results.title', 'Môn học & Kết quả học tập')}
      headerSubtitle={t('student.results.subtitle', 'Theo dõi tiến độ làm bài, điểm số và hạn nộp theo từng môn học')}
    >
      <div className="space-y-6 w-full pb-16">
        {/* Controls Bar: Semester Selector & Tabs */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25 shrink-0">
              <GraduationCap className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold text-slate-900 dark:text-white">{t('student.results.semester', 'Kỳ học')}</h2>
              <p className="text-xs text-slate-500 dark:text-slate-400">{t('student.results.semester_desc', 'Chọn kỳ học để lọc môn và bài tập')}</p>
            </div>
          </div>

          <div className="flex items-center gap-3 w-full sm:w-auto">
            <select
              value={selectedSemester}
              onChange={(e) => setSelectedSemester(e.target.value)}
              className="px-4 py-2 rounded-xl border border-orange-200/80 dark:border-slate-700 bg-white dark:bg-slate-800 text-xs font-semibold text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-orange-400/25"
            >
              <option value="">{t('student.results.all_semesters', 'Tất cả học kỳ')}</option>
              {semesters.map((sem: any) => (
                <option key={sem.id} value={sem.id}>
                  {sem.season || sem.code || sem.name} {sem.isActive ? t('student.results.current', '(Hiện tại)') : ''}
                </option>
              ))}
            </select>

            <RefreshAction onRefresh={() => loadData(true)} disabled={loading} cachePaths={["/student-portal/subjects","/assignments","/exams","/submissions"]} />
          </div>
        </div>

        {/* Executive KPI Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Tổng môn học
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <BookOpen className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : subjects.length}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Chương trình Spring 2026</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Tổng bài tập
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <FileText className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : stats.total}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
              <span>Đã nộp: {stats.submitted} bài</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Đã có điểm
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <CheckCircle2 className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : stats.graded}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Chờ chấm: {Math.max(0, stats.submitted - stats.graded)}</span>
            </div>
          </div>

          <div className="relative overflow-hidden p-4 sm:p-5 rounded-2xl bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 border border-orange-100/90 dark:border-orange-900/30 shadow-xs hover:shadow-md transition-all group">
            <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-gradient-to-tr from-orange-400/15 via-amber-300/15 to-transparent rounded-full blur-2xl group-hover:from-orange-400/25 group-hover:via-amber-300/25 transition-all pointer-events-none" />
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Điểm TB GPA
              </span>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shadow-md shadow-orange-500/25">
                <GraduationCap className="w-5 h-5" />
              </div>
            </div>
            <div className="text-3xl font-black text-slate-900 dark:text-white tracking-tight font-mono">
              {loading ? '…' : stats.avgScore}
            </div>
            <div className="flex items-center gap-1.5 mt-2 text-[11px] font-medium text-slate-500 dark:text-slate-400">
              <span className="w-1.5 h-1.5 rounded-full bg-orange-400" />
              <span>Thang điểm 10</span>
            </div>
          </div>
        </div>

        {/* Subject Chips */}
        {subjectTabs.length > 2 && (
          <div className="inline-flex flex-wrap p-1.5 bg-gradient-to-br from-orange-50/80 via-white to-amber-50/40 dark:from-slate-900 dark:via-slate-900/90 dark:to-orange-950/20 rounded-2xl border border-orange-100/90 dark:border-orange-900/30 shadow-xs gap-1">
            {subjectTabs.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveSubjectTab(tab)}
                className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all whitespace-nowrap cursor-pointer ${
                  activeSubjectTab === tab
                    ? 'bg-gradient-to-r from-orange-500 via-amber-500 to-orange-400 text-white shadow-md shadow-orange-500/20'
                    : 'text-slate-600 hover:text-orange-600 dark:text-slate-300 dark:hover:text-white hover:bg-orange-50/60'
                }`}
              >
                {tab === 'All' ? t('student.results.all_subjects', 'Tất cả môn học') : tab}
              </button>
            ))}
          </div>
        )}

        {/* Error State */}
        {error && (
          <div className="p-4 rounded-2xl bg-rose-50 dark:bg-rose-950/30 border border-rose-200 dark:border-rose-800/60 flex items-center justify-between text-xs text-rose-700 dark:text-rose-300">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 shrink-0 text-rose-500" />
              <span>{error}</span>
            </div>
            <Button variant="outline" size="sm" onClick={() => void loadData()} className="text-xs">
              {t('ui.retry', 'Thử lại')}
            </Button>
          </div>
        )}

        {/* Content List */}
        {loading && visibleSubjects.length === 0 ? (
          <CardGridSkeleton columns={2} count={4} />
        ) : visibleSubjects.length === 0 ? (
          <Card className="p-12 text-center text-slate-500 border-dashed">
            <BookOpen className="w-10 h-10 mx-auto text-slate-400 mb-3" />
            <p className="font-semibold text-sm">{t('student.results.empty_semester', 'Chưa có môn học nào được đăng ký trong kỳ học này.')}</p>
            <p className="text-xs text-slate-400 mt-1">{t('student.results.empty_semester_desc', 'Chọn kỳ học khác hoặc liên hệ phòng đào tạo.')}</p>
          </Card>
        ) : (
          <div className="space-y-4">
            {visibleSubjects.map((sub: any) => {
              const subId = sub.id || sub.code || sub.SubjectCode
              const subCode = sub.code || sub.SubjectCode || 'SUB'
              const subName = sub.name || sub.SubjectName || 'Môn học'
              const isExpanded = expandedSubjectId === subId

              // Filter assignments belonging to this subject
              const subAssignments = assignments.filter((a) => {
                const aCode = (a.subjectCode || a.SubjectCode || '').toLowerCase()
                const sCode = subCode.toLowerCase()
                return aCode === sCode || a.subjectId === sub.id || a.SubjectId === sub.id
              })

              const lecturer = sub.lecturers?.[0] || sub.instructor || null

              return (
                <Card
                  key={subId}
                  className="bg-white dark:bg-slate-900 border border-orange-100/90 dark:border-orange-900/30 rounded-2xl overflow-hidden shadow-xs hover:border-orange-200/90 transition-all"
                >
                  {/* Subject Header */}
                  <div
                    onClick={() => setExpandedSubjectId(isExpanded ? null : subId)}
                    className="p-5 sm:p-6 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 cursor-pointer hover:bg-orange-50/20 dark:hover:bg-slate-800/40 transition-colors"
                  >
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-gradient-to-tr from-orange-500 via-amber-500 to-orange-400 text-white flex items-center justify-center shrink-0 shadow-md shadow-orange-500/25">
                        {subCode.startsWith('DB') ? <Database className="w-6 h-6" /> : subCode.startsWith('SE') || subCode.startsWith('CS') ? <Code className="w-6 h-6" /> : <BookOpen className="w-6 h-6" />}
                      </div>
                      <div>
                        <div className="flex items-center gap-2 flex-wrap">
                          <Badge variant="orange" className="font-mono text-xs">
                            {subCode}
                          </Badge>
                          {sub.classCode && (
                            <Badge variant="outline" className="font-mono text-[10px]">
                              {t('student.results.class', 'Lớp')}: {sub.classCode}
                            </Badge>
                          )}
                          <span className="text-xs text-slate-400">• {subAssignments.length} {t('student.results.tasks_count', 'bài tập')}</span>
                        </div>
                        <h3 className="text-base font-bold text-slate-900 dark:text-white mt-1">
                          {subName}
                        </h3>
                        {lecturer && (
                          <p className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-1.5 mt-1">
                            <User className="w-3.5 h-3.5 text-slate-400" />
                            <span>{t('student.results.lecturer', 'Giảng viên')}: {lecturer.name || lecturer.FullName || t('student.results.unassigned', 'Chưa phân công')}</span>
                          </p>
                        )}
                      </div>
                    </div>

                    <div className="flex items-center gap-3 w-full sm:w-auto justify-between sm:justify-end">
                      <Link
                        href={`/student/courses/${subCode}`}
                        onClick={(e) => e.stopPropagation()}
                        className="inline-flex items-center gap-1 text-xs font-semibold text-orange-600 dark:text-orange-400 hover:text-orange-700 dark:hover:text-orange-300 px-3 py-1.5 rounded-xl hover:bg-orange-50 dark:hover:bg-orange-950/30 transition-colors"
                      >
                        <span>{t('student.results.view_syllabus', 'Xem Giáo trình (Syllabus)')}</span>
                        <ExternalLink className="w-3 h-3" />
                      </Link>

                      <div className="p-2 rounded-xl text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
                        {isExpanded ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                      </div>
                    </div>
                  </div>

                  {/* Expanded Assignments Accordion */}
                  {isExpanded && (
                    <div className="border-t border-slate-100 dark:border-slate-800 p-5 sm:p-6 bg-slate-50/40 dark:bg-slate-900/60 space-y-3">
                      <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                        {t('student.results.assignment_list', 'Danh sách bài tập & kiểm tra')}
                      </h4>

                      {subAssignments.length === 0 ? (
                        <div className="p-6 text-center text-xs text-slate-400 border border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
                          {t('student.results.no_assignments_for_subject', 'Chưa có bài tập nào được giao cho môn học này.')}
                        </div>
                      ) : (
                        <div className="space-y-2.5">
                          {subAssignments.map((a: any) => {
                            const isGraded = a.status === 'Graded'
                            const isSubmitted = a.status === 'Submitted'
                            const isOverdue = a.due && new Date(a.due) < new Date() && !isSubmitted && !isGraded

                            return (
                              <div
                                key={a.id}
                                className="p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-200/80 dark:border-slate-800 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 shadow-2xs hover:border-orange-300 dark:hover:border-orange-800/60 transition-all"
                              >
                                <div className="space-y-1">
                                  <div className="flex items-center gap-2">
                                    <span className="font-bold text-sm text-slate-900 dark:text-white">
                                      {a.title || 'Assignment'}
                                    </span>
                                    <Badge variant="outline" className="text-[10px]">
                                      {a.type || 'Assignment'}
                                    </Badge>
                                  </div>
                                  <div className="flex items-center gap-4 text-xs text-slate-500 dark:text-slate-400">
                                    {a.due && (
                                      <span className="flex items-center gap-1">
                                        <Clock className="w-3.5 h-3.5 text-slate-400" />
                                        {t('student.results.due', 'Hạn nộp')}: {new Date(a.due).toLocaleString('vi-VN', { dateStyle: 'short', timeStyle: 'short' })}
                                      </span>
                                    )}
                                    {a.maxScore !== undefined && (
                                      <span>{t('student.results.max_score', 'Điểm tối đa')}: {a.maxScore}đ</span>
                                    )}
                                  </div>
                                </div>

                                <div className="flex items-center gap-3 w-full sm:w-auto justify-between sm:justify-end">
                                  <div>
                                    {isGraded ? (
                                      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">
                                        <Check className="w-3 h-3 text-emerald-600 dark:text-emerald-400 stroke-[2.5]" />
                                        <span>{t('student.results.score_label', 'Điểm')}: {a.score} / {a.maxScore || 10}</span>
                                      </span>
                                    ) : isSubmitted ? (
                                      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">
                                        <Check className="w-3 h-3 text-emerald-600 dark:text-emerald-400 stroke-[2.5]" />
                                        <span>{t('student.results.status_submitted', 'Đã nộp bài')}</span>
                                      </span>
                                    ) : isOverdue ? (
                                      <Badge variant="danger" className="text-xs">
                                        {t('student.results.status_overdue', 'Quá hạn nộp')}
                                      </Badge>
                                    ) : (
                                      <Badge variant="default" className="text-xs">
                                        {t('student.results.status_pending', 'Chưa nộp')}
                                      </Badge>
                                    )}
                                  </div>

                                  <Link href={`/student/assignments/${a.id}`}>
                                    <Button
                                      size="sm"
                                      variant={isGraded ? 'outline' : 'primary'}
                                      className="text-xs gap-1.5"
                                    >
                                      <span>{isGraded ? t('student.results.view_result', 'Xem kết quả') : isSubmitted ? t('student.results.view_submission', 'Xem bài nộp') : t('student.results.do_assignment', 'Làm bài')}</span>
                                      <ArrowRight className="w-3.5 h-3.5" />
                                    </Button>
                                  </Link>
                                </div>
                              </div>
                            )
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </Card>
              )
            })}
          </div>
        )}
      </div>
    </DashboardLayout>
  )
}

'use client'

import * as React from 'react'
import { Button } from '@/components/ui/button'
import { useAuth } from '@/providers/auth-provider'
import { submissionsApi } from '@/lib/api/modules/submissions'
import { reportFacts, evidenceMatches, assessmentMethod } from '../report-facts'
import { SubmissionHistory } from './SubmissionHistory'
import { VsCodeExplorerViewer } from './VsCodeExplorerViewer'

export interface EvaluationReportViewerProps {
  submission: any
  onResubmit?: () => void
  onGetHint?: (ruleId?: any, ruleTitle?: any) => void | Promise<any>
  isLecturer?: boolean
  onUpdateRuleScore?: (updatedRuleScores: any[], newTotalScore: number) => void
  onOpenAppeal?: () => void
}
const tabs = [['overview', 'Tổng quan'], ['rubric', 'Chi tiết đánh giá'], ['testcases', 'Test cases'], ['review', 'Code Review'], ['history', 'Lịch sử nộp bài']] as const
const languages: Record<string, string> = { kt: 'kotlin', kts: 'kotlin', java: 'java', cpp: 'cpp', c: 'c', h: 'c', cs: 'csharp', py: 'python', ts: 'typescript', tsx: 'typescript', js: 'javascript', sql: 'sql', xml: 'xml', json: 'json' }
const time = (value?: string) => value ? new Date(value).toLocaleString('vi-VN') : 'Chưa rõ thời gian'
const panel = 'rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-5 space-y-4'

export function EvaluationReportViewer({ submission, onResubmit, onGetHint, isLecturer, onUpdateRuleScore, onOpenAppeal }: EvaluationReportViewerProps) {
  const { role } = useAuth()
  const staff = isLecturer || role === 'lecturer' || role === 'admin'
  const facts = reportFacts(!staff && !submission?.isPublished ? { ...submission, reportData: null, ReportData: null, ruleScores: [], score: null, finalScore: null } : submission)
  const submissionId = String(submission?.id || submission?.submissionId || '')
  const [tab, setTab] = React.useState<typeof tabs[number][0]>('overview')
  const [source, setSource] = React.useState<{ id: string; files: { path: string; content: string }[]; hash?: string; skipped?: number; error?: string }>({ id: '', files: [] })
  const [retry, retrySource] = React.useReducer(n => n + 1, 0)
  const [edits, setEdits] = React.useState<Record<string, number>>({})
  const [copied, setCopied] = React.useState<string | null>(null)
  React.useEffect(() => {
    if (!submissionId) return
    const controller = new AbortController()
    setSource({ id: '', files: [] }); setEdits({})
    submissionsApi.getSource(submissionId, controller.signal).then(data => {
      if (!controller.signal.aborted) setSource({ id: submissionId, files: data.files, hash: data.archiveSha256, skipped: data.skipped })
    }).catch(error => { if (!controller.signal.aborted) setSource({ id: submissionId, files: [], error: error.message || 'Không đọc được ZIP.' }) })
    return () => controller.abort()
  }, [submissionId, retry])
  const files = source.id === submissionId ? source.files : []
  const viewerFiles = files.map(file => ({ id: file.path, path: file.path, name: file.path.split('/').pop() || file.path, content: file.content, language: languages[file.path.split('.').pop() || ''] || 'text' }))
  const max = facts.maxScore
  const score = facts.score
  const scoreLabel = score === null ? 'Chưa có điểm' : `${score.toFixed(2)}${max && max > 0 ? ` / ${max}` : ''}`
  const rank = score === null || !max || max <= 0 ? 'Chưa đủ dữ liệu xếp loại' : score / max >= .8 ? 'Đạt tốt' : score / max >= .5 ? 'Đạt yêu cầu' : 'Cần cải thiện'
  const filename = submission?.filename || 'ZIP bài nộp'
  const save = () => {
    const updated = facts.evaluations.map((rule: any, index: number) => ({ ...rule, earnedScore: edits[String(rule.ruleId || index)] ?? rule.earnedScore }))
    onUpdateRuleScore?.(updated, updated.reduce((sum: number, rule: any) => sum + Number(rule.earnedScore || 0), 0))
    setEdits({})
  }
  return <div className="space-y-5 text-slate-900 dark:text-white">
    <section className={panel}>
      <div className="flex flex-wrap justify-between gap-2 text-xs text-slate-500"><span>{submission?.subjectCode || 'Chưa có mã môn'} · Lần nộp #{submission?.attemptNumber ?? '—'}</span><span>{submission?.gradingStatus || submission?.status || 'Chưa có trạng thái'} · {submission?.isPublished ? 'Đã công bố' : 'Chưa công bố'}</span></div>
      <h2 className="text-xl font-bold">{submission?.assignmentTitle || (typeof submission?.assignment === 'string' ? submission.assignment : null) || 'Báo cáo bài nộp'}</h2>
      <p className="text-xs text-slate-500">{filename} · Nộp: {time(submission?.submittedAt)} · Chấm: {time(submission?.gradedAt)}</p>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[['Tổng điểm', scoreLabel, rank], ['Test cases thực thi', facts.testExecuted ? `${facts.testPassed}/${facts.testExecuted}` : 'Chưa có kết quả', 'Chỉ tính bằng chứng thực thi'], ['Tiêu chí barem', facts.evaluations.length, 'Theo báo cáo đã lưu'], ['Biên dịch', facts.compilation === null ? 'Chưa xác minh' : facts.compilation ? 'Đạt' : 'Không đạt', 'Cần log biên dịch riêng']].map(([label, value, note]) => <div key={label} className="rounded-xl bg-slate-50 dark:bg-slate-800 p-4 space-y-2"><p className="text-xs text-slate-500">{label}</p><strong className="text-xl tabular-nums">{value}</strong><p className="text-xs text-slate-500">{note}</p></div>)}
      </div>
      {facts.identityMismatch && <p role="alert" className="text-sm text-red-600">Báo cáo không khớp mã bài tập hoặc lần nộp đang xem. Cần chấm lại đúng ZIP; không sử dụng điểm của báo cáo này.</p>}
      {facts.report.executionSummary?.ready === false && <p role="status" className="rounded-xl bg-amber-50 dark:bg-amber-950/30 p-3 text-sm text-amber-800 dark:text-amber-300">{facts.report.executionSummary.runtimeStack === 'android' ? 'Bài Android được đánh giá từ mã nguồn. Hệ thống chưa chạy ứng dụng trên máy ảo Android; các acceptance test cần được giảng viên kiểm chứng.' : 'Chưa có môi trường chạy ứng dụng trong lượt chấm này. Xem phương thức và bằng chứng của từng tiêu chí bên dưới.'}</p>}
      {facts.gradingError && <p role="alert" className="rounded-xl bg-red-50 dark:bg-red-950/30 p-3 text-sm text-red-700 dark:text-red-300">Lượt chấm chưa hoàn tất: {String(facts.gradingError)}. Điểm lỗi không được coi là điểm 0 của bài làm.</p>}
      {facts.report.manualReviewNotes?.length > 0 && <div role="alert" className="rounded-xl bg-amber-50 dark:bg-amber-950/30 p-3 text-sm text-amber-800 dark:text-amber-300">Cần giảng viên xem lại: {facts.report.manualReviewNotes.join(' · ')}</div>}
    </section>
    <div role="tablist" aria-label="Nội dung báo cáo" className="flex gap-5 overflow-x-auto border-b border-slate-200 dark:border-slate-800">
      {tabs.map(([id, label]) => <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)} className={`shrink-0 pb-3 text-sm font-semibold border-b-2 ${tab === id ? 'border-orange-500 text-orange-600' : 'border-transparent text-slate-500'}`}>{label}</button>)}
    </div>
    {tab === 'overview' && <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">
      <section className={`${panel} xl:col-span-2 min-w-0`}><h3 className="font-bold">Mã nguồn từ ZIP đã nộp</h3>
        {viewerFiles.length ? <VsCodeExplorerViewer key={submissionId} initialFiles={viewerFiles} archiveName={filename} height="h-[520px]" /> : <p role={source.error ? 'alert' : 'status'} className="py-12 text-center text-sm text-slate-500">{source.id !== submissionId ? 'Đang đọc ZIP đã lưu...' : source.error || 'ZIP không có tệp mã nguồn hỗ trợ xem.'}{source.error && <button onClick={retrySource} className="ml-2 text-orange-600 underline">Thử lại</button>}</p>}
        {source.id === submissionId && source.hash && <p className="break-all text-[10px] text-slate-500">ZIP SHA-256: {source.hash} · {files.length} tệp hiển thị · {source.skipped || 0} mục bị bỏ qua (thư viện, tệp nhị phân hoặc giới hạn đọc).</p>}
      </section>
      <section className={panel}><h3 className="font-bold">Chất lượng mã nguồn theo barem</h3><p className="text-xs text-slate-500">Không có điểm Code Quality riêng nếu giảng viên không cấu hình tiêu chí đó. Nhận xét bên dưới lấy từ từng tiêu chí đã chấm.</p>
        {!facts.evaluations.length && <p className="text-sm text-slate-500">Chưa có đánh giá theo tiêu chí.</p>}
        {facts.evaluations.map((rule: any, index: number) => <div key={rule.ruleId || index} className="border-t border-slate-100 dark:border-slate-800 pt-3 text-xs space-y-1"><strong>{rule.title || rule.ruleId} · {rule.earnedScore ?? '—'} / {rule.weight ?? '—'}</strong><p className="whitespace-pre-wrap">{rule.details || rule.reason || 'Chưa có nhận xét.'}</p></div>)}
      </section>
    </div>}
    {tab === 'rubric' && <div className="space-y-4">
      {!facts.evaluations.length && <section className={panel}>Chưa có kết quả theo barem. Không thay bằng tiêu chí mẫu.</section>}
      {facts.evaluations.map((rule: any, index: number) => {
        const id = String(rule.ruleId || index), weight = Number(rule.weight || 0)
        const snippets = rule.evidence?.snippets || (rule.evidence?.codeSnippet ? [rule.evidence] : [])
        return <section key={id} className={panel}>
          <div className="flex flex-wrap justify-between gap-3"><div><span className="text-xs text-slate-500">{id}</span><h3 className="font-bold">{rule.title || 'Tiêu chí chưa có tên'}</h3></div>{staff && onUpdateRuleScore ? <label className="text-xs">Điểm <input aria-label={`Điểm ${id}`} type="number" min="0" max={weight} step="0.25" disabled={weight <= 0} value={edits[id] ?? rule.earnedScore ?? 0} onChange={event => setEdits(previous => ({ ...previous, [id]: Math.max(0, Math.min(weight, Number(event.target.value) || 0)) }))} className="ml-2 w-20 rounded border p-1 bg-transparent" /> / {weight}</label> : <strong>{rule.earnedScore ?? '—'} / {rule.weight ?? '—'} điểm</strong>}</div>
          <p className="text-xs font-medium text-slate-500">{assessmentMethod(rule)}</p>
          <p className="text-sm whitespace-pre-wrap">{rule.details || rule.reason || rule.description || 'Chưa có nhận xét.'}</p>
          {snippets.map((snippet: any, i: number) => <div key={i} className="rounded-xl bg-slate-950 p-3 text-xs text-slate-200 space-y-2"><div className="flex flex-wrap justify-between gap-2"><span className="break-all">{snippet.filePath || 'Chưa có đường dẫn'} · {evidenceMatches(snippet.codeSnippet, snippet.filePath, files) ? 'Đoạn trích khớp ZIP' : 'Chưa xác minh đoạn trích với ZIP'}</span><button onClick={async () => { await navigator.clipboard.writeText(snippet.codeSnippet || ''); setCopied(`${id}:${i}`) }}>{copied === `${id}:${i}` ? 'Đã copy' : 'Copy'}</button></div><pre className="overflow-x-auto">{snippet.codeSnippet}</pre></div>)}
          {!staff && onGetHint && <Button size="sm" variant="outline" onClick={() => void onGetHint(id, rule.title)}>Gợi ý cho tiêu chí này</Button>}
        </section>
      })}
      {staff && onUpdateRuleScore && Object.keys(edits).length > 0 && <Button onClick={save}>Lưu điểm theo barem</Button>}
    </div>}
    {tab === 'testcases' && <section className={panel}><h3 className="font-bold">Kết quả kiểm thử theo barem</h3><p className="text-xs text-slate-500">Chỉ hiển thị kết quả được ghi trong bằng chứng thực thi của tiêu chí. Có tệp unit test hoặc nhận xét AI không có nghĩa testcase đã chạy thành công.</p>
      <p>{facts.testExecuted ? `${facts.testPassed}/${facts.testExecuted} kiểm thử đạt` : facts.report.consoleVerification?.error || 'Chưa có bằng chứng thực thi testcase.'}</p>
      {facts.report.consoleVerification?.scoringImpact === 'none' && <p className="text-xs text-slate-500">Bộ test kiểm chứng việc chạy chương trình; không cộng thêm điểm ngoài barem giảng viên đã duyệt.</p>}
      {facts.tests.map(test => <div key={test.key} className="rounded-xl bg-slate-50 dark:bg-slate-800 p-4 text-xs space-y-2"><div className="flex flex-wrap justify-between gap-2"><strong>{test.ruleId} · {test.kind} · {String(test.name)}</strong><span>{test.passed === true ? 'Đạt' : test.passed === false ? 'Không đạt' : 'Chưa có kết quả'}</span></div>{['input', 'expected', 'actual', 'error'].map(key => test[key] != null && <div key={key}><span className="text-slate-500">{key}:</span><pre className="whitespace-pre-wrap break-words">{String(test[key])}</pre></div>)}</div>)}
    </section>}
    {tab === 'review' && <section className={panel}><h3 className="font-bold">Code Review theo bài nộp và barem</h3>
      <p className="text-xs text-slate-500">Đối chiếu nhận xét với đoạn mã và tiêu chí ở mục Chi tiết đánh giá. Các đoạn trích chưa khớp ZIP cần được giảng viên xem lại.</p>
      {facts.evaluations.map((rule: any, i: number) => <div key={rule.ruleId || i} className="text-sm border-t border-slate-100 dark:border-slate-800 pt-3"><strong>{rule.title || rule.ruleId} · {rule.earnedScore ?? '—'} / {rule.weight ?? '—'}</strong><p className="mt-1 whitespace-pre-wrap">{rule.details || rule.reason || 'Chưa có nhận xét.'}</p></div>)}
      {facts.report.overallFeedback && <p className="whitespace-pre-wrap text-sm rounded-xl bg-slate-50 dark:bg-slate-800 p-4">{facts.report.overallFeedback}</p>}
      {!facts.evaluations.length && !facts.report.overallFeedback && <p className="text-sm text-slate-500">Chưa có nhận xét Code Review.</p>}
      {submission?.instructorFeedback && <p className="whitespace-pre-wrap text-sm"><strong>Nhận xét giảng viên:</strong> {submission.instructorFeedback}</p>}
    </section>}
    {tab === 'history' && <SubmissionHistory submissionId={submissionId} />}
    <div className="flex flex-wrap gap-3">{onResubmit && <Button variant="outline" onClick={onResubmit}>Nộp lại bài</Button>}{!staff && onOpenAppeal && <Button variant="outline" onClick={onOpenAppeal}>Phúc khảo điểm</Button>}</div>
  </div>
}

'use client'

import * as React from 'react'
import Link from 'next/link'
import { submissionsApi } from '@/lib/api/modules/submissions'
import { useAuth } from '@/providers/auth-provider'

export function SubmissionHistory({ submissionId }: { submissionId: string }) {
  const { role } = useAuth()
  const [state, setState] = React.useState<{ id: string; rows: any[]; error: string | null; loading: boolean }>({ id: '', rows: [], error: null, loading: true })
  const [revision, retry] = React.useReducer(n => n + 1, 0)
  React.useEffect(() => {
    const controller = new AbortController()
    setState({ id: submissionId, rows: [], error: null, loading: true })
    submissionsApi.getAttempts(submissionId, controller.signal).then(rows => {
      if (!controller.signal.aborted) setState({ id: submissionId, rows, error: null, loading: false })
    }).catch(error => { if (!controller.signal.aborted) setState({ id: submissionId, rows: [], error: error.message || 'Không tải được lịch sử.', loading: false }) })
    return () => controller.abort()
  }, [submissionId, revision])
  if (state.id !== submissionId || state.loading) return <p role="status">Đang tải lịch sử nộp bài...</p>
  if (state.error) return <div role="alert">{state.error} <button onClick={retry} className="text-orange-600 underline">Thử lại</button></div>
  return <div className="space-y-3">
    <p className="text-xs text-slate-500">Mỗi lần nộp lưu tệp, thời gian và kết quả riêng. Các lần nộp trước đây đã bị ghi đè không thể tự khôi phục từ dữ liệu hiện có.</p>
    {!state.rows.length && <p>Chưa có lịch sử nộp bài.</p>}
    {state.rows.map(row => <div key={row.id} className="rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-4 space-y-2 text-sm">
      <div className="flex flex-wrap justify-between gap-2"><strong>Lần nộp #{row.attemptNumber ?? '—'}{row.id === submissionId ? ' · Đang xem' : ''}</strong><span>{row.score == null ? (row.isPublished ? 'Chưa có điểm' : 'Chưa công bố điểm') : `${Number(row.score)}${row.maxScore ? ` / ${Number(row.maxScore)}` : ''} điểm`}</span></div>
      <p className="text-xs text-slate-500">{row.submittedAt ? new Date(row.submittedAt).toLocaleString('vi-VN') : 'Chưa rõ thời gian'} · {row.filename || 'Chưa có tên tệp'} · {row.gradingStatus || 'Chưa có trạng thái'}</p>
      {row.id !== submissionId && <Link className="text-orange-600 text-xs font-semibold" href={role === 'student' ? `/student/results/${row.id}` : `/lecturer/grading/result/${row.id}`}>Xem lần nộp này →</Link>}
    </div>)}
  </div>
}

'use client'

import * as React from 'react'
import {
  Folder,
  FolderOpen,
  FileCode,
  FileText,
  File,
  ChevronRight,
  ChevronDown,
  Copy,
  CheckCheck,
  AlertCircle,
  XCircle,
  AlertTriangle,
  GitBranch,
  Terminal,
  Maximize2,
  Minimize2,
  Code2
} from 'lucide-react'

export interface CodeErrorAnnotation {
  line: number
  title?: string
  message: string
  severity?: 'error' | 'warning'
  deduction?: string
}

export interface VirtualFile {
  id: string
  path: string
  name: string
  language: string
  content: string
  errorAnnotations?: CodeErrorAnnotation[]
}

interface VsCodeExplorerViewerProps {
  initialFiles?: VirtualFile[]
  activeFileName?: string
  archiveName?: string
  sourceCode?: string
  filename?: string
  height?: string
  readOnly?: boolean
  className?: string
}

// Sample realistic project files with explicit AI error markers
interface TreeNode {
  name: string
  path: string
  isFolder: boolean
  children?: TreeNode[]
  file?: VirtualFile
}

function buildTree(files: VirtualFile[]): TreeNode {
  const root: TreeNode = {
    name: 'root',
    path: '',
    isFolder: true,
    children: []
  }

  files.forEach(file => {
    const parts = file.path.split('/')
    let current = root

    parts.forEach((part, index) => {
      const isFile = index === parts.length - 1
      const currentPath = parts.slice(0, index + 1).join('/')

      if (!current.children) {
        current.children = []
      }

      let child = current.children.find(c => c.name === part)
      if (!child) {
        child = {
          name: part,
          path: currentPath,
          isFolder: !isFile,
          children: isFile ? undefined : [],
          file: isFile ? file : undefined
        }
        current.children.push(child)
      }
      current = child
    })
  })

  // Sort folders first, then files
  const sortChildren = (node: TreeNode) => {
    if (!node.children) return
    node.children.sort((a, b) => {
      if (a.isFolder === b.isFolder) {
        return a.name.localeCompare(b.name)
      }
      return a.isFolder ? -1 : 1
    })
    node.children.forEach(sortChildren)
  }
  sortChildren(root)

  return root
}

export function VsCodeExplorerViewer({
  initialFiles,
  activeFileName = '',
  archiveName = 'ZIP bài nộp',
  sourceCode,
  filename,
  height = 'h-[560px]',
  className = ''
}: VsCodeExplorerViewerProps) {
  const files = React.useMemo(() => {
    if (initialFiles && initialFiles.length > 0) return initialFiles
    if (sourceCode) {
      const targetName = filename && !filename.endsWith('.zip') && !filename.endsWith('.tar.gz') && !filename.endsWith('.rar')
        ? filename
        : 'source.txt'
      const ext = targetName.split('.').pop()?.toLowerCase() || 'text'
      const langMap: Record<string, string> = {
        cpp: 'cpp', c: 'c', h: 'cpp', hpp: 'cpp', java: 'java', py: 'python',
        cs: 'csharp', kt: 'kotlin', kts: 'kotlin', js: 'javascript', ts: 'typescript', sql: 'sql'
      }
      return [
        {
          id: 'submitted-code',
          path: targetName,
          name: targetName,
          language: langMap[ext] || 'text',
          content: sourceCode,
          errorAnnotations: []
        }
      ]
    }
    return []
  }, [initialFiles, sourceCode, filename])

  const initialSelected = React.useMemo(() => {
    return files.find(f => f.name === activeFileName) ||
      files.find(f => (f.errorAnnotations?.length || 0) > 0) ||
      files[0]
  }, [files, activeFileName])

  const [selectedFile, setSelectedFile] = React.useState<VirtualFile>(initialSelected)

  React.useEffect(() => {
    setSelectedFile(initialSelected)
  }, [initialSelected])
  const [expandedFolders, setExpandedFolders] = React.useState<Record<string, boolean>>({
    'src': true,
    'src/main': true,
    'src/main/java': true,
    'src/main/java/com': true,
    'src/main/java/com/example': true,
    'src/main/java/com/example/todo': true,
    'src/main/java/com/example/todo/data': true,
    'src/main/java/com/example/todo/viewmodel': true,
    'src/main/java/com/example/todo/ui': true,
  })
  const [copied, setCopied] = React.useState(false)
  const [showExplorer, setShowExplorer] = React.useState(true)

  const tree = React.useMemo(() => buildTree(files), [files])

  // Count total errors
  const totalErrors = React.useMemo(() => {
    return files.reduce((acc, f) => acc + (f.errorAnnotations?.length || 0), 0)
  }, [files])

  const toggleFolder = (path: string) => {
    setExpandedFolders(prev => ({
      ...prev,
      [path]: !prev[path]
    }))
  }

  const handleCopy = () => {
    if (!selectedFile) return
    navigator.clipboard.writeText(selectedFile.content)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const getFileIcon = (fileName: string) => {
    if (fileName.endsWith('.kt')) return <span className="text-purple-400 font-bold text-[11px]">K</span>
    if (fileName.endsWith('.java')) return <span className="text-orange-400 font-bold text-[11px]">J</span>
    if (fileName.endsWith('.xml')) return <span className="text-amber-400 font-bold text-[11px]">&lt;&gt;</span>
    if (fileName.endsWith('.kts') || fileName.endsWith('.gradle')) return <span className="text-teal-400 font-bold text-[11px]">🐘</span>
    return <FileCode className="w-3.5 h-3.5 text-blue-400" />
  }

  // Recursive Tree Node Renderer
  const renderTree = (node: TreeNode, depth: number = 0) => {
    if (node.isFolder) {
      const isExpanded = expandedFolders[node.path] ?? true
      const hasChildErrors = files.some(
        f => f.path.startsWith(node.path + '/') && (f.errorAnnotations?.length || 0) > 0
      )

      return (
        <div key={node.path || node.name} className="select-none">
          {node.name !== 'root' && (
            <div
              onClick={() => toggleFolder(node.path)}
              style={{ paddingLeft: `${depth * 12 + 6}px` }}
              className="flex items-center gap-1.5 py-1 pr-2 hover:bg-[#2a2d2e] cursor-pointer text-slate-400 hover:text-slate-200 transition-colors text-xs font-mono group"
            >
              <span className="w-3.5 h-3.5 flex items-center justify-center shrink-0">
                {isExpanded ? (
                  <ChevronDown className="w-3 h-3 text-slate-500 group-hover:text-slate-300" />
                ) : (
                  <ChevronRight className="w-3 h-3 text-slate-500 group-hover:text-slate-300" />
                )}
              </span>
              <span className="shrink-0 text-amber-300">
                {isExpanded ? <FolderOpen className="w-3.5 h-3.5" /> : <Folder className="w-3.5 h-3.5" />}
              </span>
              <span className="truncate flex-1 font-sans text-xs">{node.name}</span>
              {hasChildErrors && (
                <span className="w-1.5 h-1.5 rounded-full bg-rose-500 shrink-0" title="Chứa file có lỗi" />
              )}
            </div>
          )}

          {isExpanded && node.children && (
            <div>
              {node.children.map(child => renderTree(child, node.name === 'root' ? depth : depth + 1))}
            </div>
          )}
        </div>
      )
    }

    // File Node
    const isSelected = selectedFile?.id === node.file?.id
    const errorCount = node.file?.errorAnnotations?.length || 0

    return (
      <div
        key={node.path}
        onClick={() => node.file && setSelectedFile(node.file)}
        style={{ paddingLeft: `${depth * 12 + 10}px` }}
        className={`flex items-center gap-1.5 py-1 pr-2 cursor-pointer transition-colors text-xs font-mono group ${
          isSelected
            ? 'bg-[#37373d] text-white font-medium'
            : 'text-slate-300 hover:bg-[#2a2d2e] hover:text-white'
        }`}
      >
        <span className="w-4 h-4 flex items-center justify-center shrink-0">
          {getFileIcon(node.name)}
        </span>
        <span className={`truncate flex-1 font-sans ${errorCount > 0 ? 'text-rose-300' : ''}`}>
          {node.name}
        </span>
        {errorCount > 0 && (
          <span className="px-1.5 py-0.2 rounded text-[10px] font-bold bg-rose-500/20 text-rose-400 border border-rose-500/30">
            {errorCount}
          </span>
        )}
      </div>
    )
  }

  // Parse code lines & identify errors
  const codeLines = selectedFile ? selectedFile.content.split('\n') : []
  const errorMap = React.useMemo(() => {
    const map = new Map<number, CodeErrorAnnotation>()
    selectedFile?.errorAnnotations?.forEach(err => {
      map.set(err.line, err)
    })
    return map
  }, [selectedFile])

  if (!selectedFile) return <div className="p-8 text-sm text-slate-500">Chưa có mã nguồn được cung cấp.</div>

  return (
    <div className={`rounded-lg overflow-hidden border border-slate-800 bg-[#1e1e1e] text-slate-200 shadow-md font-sans text-xs ${className}`}>
      
      {/* ── VS CODE WINDOW TOP BAR ── */}
      <div className="flex items-center justify-between px-3 py-2 bg-[#181818] border-b border-slate-800 select-none">
        {/* Window dots */}
        <div className="flex items-center gap-1.5">
          <span className="w-3 h-3 rounded-full bg-[#ff5f56] inline-block" />
          <span className="w-3 h-3 rounded-full bg-[#ffbd2e] inline-block" />
          <span className="w-3 h-3 rounded-full bg-[#27c93f] inline-block" />
          <span className="ml-2 text-slate-400 text-[11px] font-mono hidden sm:inline">
            {archiveName} — Visual Studio Code (Source Viewer)
          </span>
        </div>

        {/* Action icons */}
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setShowExplorer(!showExplorer)}
            className="px-2 py-1 rounded hover:bg-slate-800 text-slate-400 hover:text-white text-[11px] flex items-center gap-1 transition-colors"
            title="Đóng / mở cây thư mục"
          >
            <Code2 className="w-3 h-3" />
            <span>{showExplorer ? 'Ẩn Explorer' : 'Hiện Explorer'}</span>
          </button>

          <button
            type="button"
            onClick={handleCopy}
            className="px-2 py-1 rounded hover:bg-slate-800 text-slate-400 hover:text-white text-[11px] flex items-center gap-1 transition-colors"
            title="Sao chép code"
          >
            {copied ? <CheckCheck className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
            <span>{copied ? 'Đã sao chép' : 'Copy'}</span>
          </button>
        </div>
      </div>

      {/* ── MAIN WORKSPACE: EXPLORER (LEFT) + CODE EDITOR (RIGHT) ── */}
      <div className={`flex flex-col sm:flex-row ${height} overflow-hidden`}>
        
        {/* Left Pane: VS Code Explorer */}
        {showExplorer && (
          <div className="w-full h-36 sm:h-auto sm:w-60 shrink-0 bg-[#252526] border-r border-slate-800 flex flex-col overflow-hidden">
            {/* Explorer Title */}
            <div className="px-3 py-2 text-[10px] font-bold uppercase tracking-wider text-slate-400 border-b border-slate-800/80 flex items-center justify-between select-none">
              <span>EXPLORER</span>
              <span className="text-[10px] font-mono text-slate-500">PROJECT</span>
            </div>

            {/* Tree View Scrollable */}
            <div className="flex-1 overflow-y-auto py-1">
              {renderTree(tree)}
            </div>

            {/* AI Problems Summary in Explorer footer */}
            <div className="p-2 border-t border-slate-800 bg-[#1e1e1e] text-[11px] select-none">
              <div className="flex items-center justify-between text-slate-400 font-semibold mb-1">
                <span>CHÚ THÍCH ĐÁNH GIÁ</span>
                <span className="font-mono text-rose-400">{totalErrors} chú thích</span>
              </div>
              <div className="text-[10px] text-slate-500 leading-tight">
                Các dòng code tô đỏ là vị trí AI trừ điểm. Nhấp vào file để xem chi tiết.
              </div>
            </div>
          </div>
        )}

        {/* Right Pane: Code Editor Area */}
        <div className="flex-1 min-h-0 min-w-0 flex flex-col overflow-hidden bg-[#1e1e1e]">
          
          {/* Editor Tab Bar */}
          <div className="flex items-center bg-[#181818] border-b border-slate-800 overflow-x-auto select-none">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-[#1e1e1e] border-t-2 border-[#007acc] text-white text-xs font-mono shrink-0">
              {getFileIcon(selectedFile.name)}
              <span className="font-sans">{selectedFile.name}</span>
              {(selectedFile.errorAnnotations?.length || 0) > 0 && (
                <span className="w-1.5 h-1.5 rounded-full bg-rose-500" />
              )}
            </div>
          </div>

          {/* Breadcrumbs */}
          <div className="px-3 py-1 bg-[#1e1e1e] border-b border-slate-800/60 text-[11px] text-slate-400 font-mono flex items-center gap-1.5 select-none overflow-x-auto">
            {selectedFile.path.split('/').map((part, pIdx, arr) => (
              <React.Fragment key={pIdx}>
                <span className={pIdx === arr.length - 1 ? 'text-slate-200 font-semibold' : ''}>
                  {part}
                </span>
                {pIdx < arr.length - 1 && <span className="text-slate-600">/</span>}
              </React.Fragment>
            ))}
          </div>

          {/* Code Viewer Viewport */}
          <div className="flex-1 overflow-auto font-mono text-[12px] leading-relaxed p-0 select-text">
            <div className="py-2">
              {codeLines.map((lineContent, lineIdx) => {
                const lineNum = lineIdx + 1
                const error = errorMap.get(lineNum)
                const isErrorLine = Boolean(error)

                return (
                  <React.Fragment key={lineNum}>
                    {/* Code Line */}
                    <div
                      className={`flex items-start transition-colors ${
                        isErrorLine
                          ? 'bg-rose-950/70 border-l-4 border-rose-500'
                          : 'hover:bg-[#2a2d2e]/50 border-l-4 border-transparent'
                      }`}
                    >
                      {/* Line Number Gutter */}
                      <span
                        className={`w-12 shrink-0 text-right pr-4 select-none font-mono text-[11px] ${
                          isErrorLine
                            ? 'text-rose-400 font-bold'
                            : 'text-slate-600'
                        }`}
                      >
                        {lineNum}
                      </span>

                      {/* Line Content */}
                      <span
                        className={`flex-1 pr-4 whitespace-pre font-mono ${
                          isErrorLine
                            ? 'text-rose-100 font-semibold underline decoration-wavy decoration-rose-500'
                            : 'text-slate-200'
                        }`}
                      >
                        {lineContent || ' '}
                      </span>
                    </div>

                    {/* Inline AI Error Annotation Box (Like VS Code Inline Diagnostic) */}
                    {error && (
                      <div className="my-1.5 mx-4 ml-12 p-3 rounded bg-rose-950/95 border border-rose-600/80 text-rose-100 text-xs shadow-lg space-y-1 select-none animate-in fade-in duration-200">
                        <div className="flex items-center gap-2 text-rose-300 font-bold text-xs">
                          <XCircle className="w-4 h-4 text-rose-400 shrink-0" />
                          <span>{error.title || 'Lỗi phát hiện bởi AI'}</span>
                          {error.deduction && (
                            <span className="px-1.5 py-0.2 rounded text-[10px] font-mono font-bold bg-rose-600 text-white">
                              {error.deduction}
                            </span>
                          )}
                        </div>
                        <p className="text-[11px] text-rose-200 leading-relaxed font-sans pl-6">
                          {error.message}
                        </p>
                      </div>
                    )}
                  </React.Fragment>
                )
              })}
            </div>
          </div>

          {/* ── VS CODE BOTTOM STATUS BAR ── */}
          <div className="flex items-center justify-between px-3 py-1 bg-[#007acc] text-white text-[11px] font-mono select-none">
            <div className="flex items-center gap-3">
              <span className="flex items-center gap-1">
                <FileCode className="w-3 h-3" />
                <span>ZIP source</span>
              </span>
              <span className="flex items-center gap-1 font-bold">
                <XCircle className="w-3 h-3" />
                <span>{selectedFile.errorAnnotations?.length || 0}</span>
              </span>
            </div>

            <div className="flex items-center gap-3">
              <span>Lines: {codeLines.length}</span>
              <span>UTF-8</span>
              <span className="uppercase">{selectedFile.language}</span>
            </div>
          </div>

        </div>

      </div>

    </div>
  )
}

export function parseReport(raw: unknown): any {
  try { return typeof raw === 'string' ? JSON.parse(raw) : raw && typeof raw === 'object' ? raw : null } catch { return null }
}
const finite = (value: unknown) => value === null || value === undefined || value === '' || !Number.isFinite(Number(value)) ? null : Number(value)
export function reportFacts(submission: any) {
  const report = parseReport(submission?.reportData ?? submission?.ReportData) || {}
  const identityMismatch = !!((report.submissionId && report.submissionId !== (submission?.id || submission?.submissionId)) || (report.assignmentId && (submission?.assignmentId || submission?.examId) && report.assignmentId !== (submission.assignmentId || submission.examId)))
  const rules = [...(report.passedRules || []).map((rule: any) => ({ ...rule, passed: true })), ...(report.failedRules || []).map((rule: any) => ({ ...rule, passed: false }))]
  const evaluations = rules.length ? rules : (submission?.ruleScores || []).map((rule: any) => ({ ruleId: rule.ruleId || rule.id, title: rule.ruleName || rule.title || rule.name, description: rule.description, weight: finite(rule.maxScore), earnedScore: finite(rule.score), passed: rule.passed, details: rule.explanation || rule.feedback, evidence: rule.evidence }))
  const tests: any[] = []
  const seen = new Set<string>()
  const add = (cases: any[], kind: string, ruleId = '') => {
    if (!Array.isArray(cases)) return
    cases.forEach((test, index) => {
      const key = `${ruleId}:${kind}:${test.caseId ?? test.id ?? test.name ?? index}`
      if (seen.has(key)) return
      seen.add(key)
      tests.push({ ...test, key, kind, ruleId, name: test.name || test.caseId || test.id || `Case ${index + 1}`, passed: typeof test.passed === 'boolean' ? test.passed : typeof test.success === 'boolean' ? test.success : null })
    })
  }
  for (const rule of evaluations) {
    add(rule.evidence?.ioTestCases, 'I/O', rule.ruleId)
    add(rule.evidence?.sqlTestCases, 'SQL', rule.ruleId)
    add(rule.evidence?.httpSteps, 'HTTP', rule.ruleId)
  }
  add(report.ioTestCases, 'I/O'); add(report.sqlTestCases, 'SQL'); add(report.httpSteps || report.probeSteps, 'HTTP')
  if (report.consoleVerification?.status === 'completed') add(report.consoleVerification.caseResults, 'I/O')
  if (!tests.length) add(report.testCases, 'Test')
  const buildEvidence = evaluations.map((rule: any) => rule.evidence?.compilationPassed).filter((value: unknown) => typeof value === 'boolean')
  return {
    report: identityMismatch ? {} : report, evaluations: identityMismatch ? [] : evaluations, tests: identityMismatch ? [] : tests, identityMismatch,
    score: identityMismatch || report.error ? null : finite(submission?.finalScore ?? submission?.score ?? report.totalScore),
    gradingError: report.error || report.lastGradingError || submission?.gradingError || null,
    maxScore: finite(report.maxPossibleScore ?? submission?.maxScore),
    testPassed: identityMismatch ? 0 : tests.filter(test => test.passed === true).length,
    testExecuted: identityMismatch ? 0 : tests.filter(test => test.passed !== null).length,
    compilation: identityMismatch ? null : typeof report.compilationSummary?.passed === 'boolean' ? report.compilationSummary.passed : buildEvidence.includes(false) ? false : buildEvidence.includes(true) ? true : null,
  }
}

interface AssessmentEvidence {
  ioTestCases?: { passed?: boolean; success?: boolean }[]
  sqlTestCases?: { passed?: boolean; success?: boolean }[]
  httpSteps?: { passed?: boolean; success?: boolean }[]
  snippets?: unknown[]
  codeSnippet?: string
}
export function assessmentMethod(rule: { evidence?: AssessmentEvidence; scoringStrategy?: string }): string {
  const evidence = rule.evidence || {}
  if ([...(evidence.ioTestCases || []), ...(evidence.sqlTestCases || []), ...(evidence.httpSteps || [])].some(test => typeof test.passed === 'boolean' || typeof test.success === 'boolean')) return 'Kiểm thử thực thi'
  if (['UniversalStatic', 'StaticAnalysis'].includes(rule.scoringStrategy || '')) return 'Phân tích tĩnh'
  if (rule.scoringStrategy === 'AIVision') return 'AI đánh giá hình ảnh'
  if (rule.scoringStrategy === 'AiTextAnalysis') return 'AI đánh giá nội dung'
  if (evidence.snippets?.length || evidence.codeSnippet || rule.scoringStrategy === 'AICodeReview') return 'AI đánh giá mã nguồn'
  return 'Chưa xác định phương thức'
}

export function evidenceMatches(code: string, filePath: string | undefined, files: { path: string; content: string }[]) {
  if (!code?.trim() || !filePath) return false
  const normalize = (text: string) => text.replaceAll('\r\n', '\n').trim()
  const requested = filePath.replaceAll('\\', '/').replace(/^\/+/, '')
  const candidates = files.filter(file => file.path === requested || file.path.endsWith('/' + requested))
  const tokens = (text: string) => '\u0000' + (text.match(/"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|[\p{L}\p{N}_$]+|===|!==|==|!=|<=|>=|&&|\|\||=>|->|\?\.|\?:|[^\s]/gu) || []).join('\u0000') + '\u0000'
  return candidates.length === 1 && (normalize(candidates[0].content).includes(normalize(code)) || tokens(candidates[0].content).includes(tokens(code)))
}

