    <DashboardLayout
      navItems={ADMIN_NAV}
      title="AITA Admin"
      roleLabel={t('profile.role_admin', 'Quản trị viên')}
      requiredRole="admin"
      headerTitle={t('lecturer.submissions.header_title', 'Danh sách bài nộp & Chấm điểm')}
