      method: 'POST',
      body: JSON.stringify({ assignmentId, submissionIds, watchBrowser: options?.watchBrowser !== false }),
    })
  },

  getBatchStatus: (ids: string[]) => {
    if (!ids || ids.length === 0) return Promise.resolve({ statuses: {} as Record<string, any> })
