import { notificationsApi } from '../api/modules/notifications'

export interface NotificationItem {
  id: string
  title: string
  message: string
  type: string
  createdAt: string | null
  isRead: boolean
  read: boolean
  referenceId?: string | null
  referenceType?: string | null
  subjectCode?: string | null
  [key: string]: unknown
}

export function normalizeNotification(raw: any): NotificationItem {
  const parsed = [raw.createdAt, raw.CreatedAt].filter(value => value !== null && value !== undefined && value !== '')
    .map(value => new Date(value)).find(date => Number.isFinite(date.getTime()))
  const read = raw.isRead ?? raw.read ?? false
  return {
    ...raw, id: String(raw.id ?? raw.Id ?? ''), title: raw.title ?? raw.Title ?? '',
    message: raw.message ?? raw.content ?? raw.Message ?? '',
    type: raw.type ?? raw.notificationType ?? raw.Type ?? 'SYSTEM',
    referenceId: raw.referenceId ?? raw.ReferenceId ?? null,
    referenceType: raw.referenceType ?? raw.ReferenceType ?? null,
    createdAt: parsed && Number.isFinite(parsed.getTime()) ? parsed.toISOString() : null,
    read: !!read, isRead: !!read,
  }
}

const sorted = (items: NotificationItem[]) => [...new Map(items.filter(n => n.id).map(n => [n.id, n])).values()]
  .sort((a, b) => (Date.parse(b.createdAt || '') || 0) - (Date.parse(a.createdAt || '') || 0) || b.id.localeCompare(a.id))

export class NotificationFeed {
  private listeners = new Set<() => void>()
  private epoch = 0
  private active = true
  private flight: Promise<void> | null = null
  private refreshAgain = false
  private pages = 1
  private queue: Promise<unknown> = Promise.resolve()
  private snapshot = { items: [] as NotificationItem[], unreadCount: 0, loading: true, working: false, error: '', hasMore: false }
  subscribe = (listener: () => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener) } }
  getSnapshot = () => this.snapshot
  private update(patch: Partial<typeof this.snapshot>) {
    if (!this.active) return
    this.snapshot = { ...this.snapshot, ...patch }
    this.listeners.forEach(listener => listener())
  }
  start() { this.active = true; void this.refresh() }
  stop() { this.active = false; this.epoch++ }

  refresh = (): Promise<void> => {
    if (!this.active) return Promise.resolve()
    if (this.snapshot.working) { this.refreshAgain = true; return Promise.resolve() }
    if (this.flight) { this.refreshAgain = true; return this.flight }
    const epoch = this.epoch
    const flight = (async () => {
      try {
        const [batches, { count }] = await Promise.all([
          Promise.all(Array.from({ length: this.pages }, (_, index) => notificationsApi.getMyNotifications({ page: index + 1, limit: 50 }))), notificationsApi.getUnreadCount(),
        ])
        const rows = batches.flat()
        if (epoch !== this.epoch) { this.refreshAgain = true; return }
        const knownDates = new Map(this.snapshot.items.map(item => [item.id, item.createdAt]))
        const items = rows.map(normalizeNotification).map(item => ({ ...item, createdAt: item.createdAt || knownDates.get(item.id) || null }))
        this.update({ items: sorted(items), unreadCount: count, hasMore: batches[batches.length - 1]?.length === 50, error: this.snapshot.error.startsWith('Thao tác') ? this.snapshot.error : '' })
      } catch {
        this.update({ error: 'Không thể đồng bộ thông báo. Dữ liệu hiện có được giữ lại; vui lòng thử lại.' })
      } finally { this.update({ loading: false }) }
    })().finally(() => {
      if (this.flight === flight) this.flight = null
      if (this.refreshAgain && this.active) { this.refreshAgain = false; void this.refresh() }
    })
    this.flight = flight
    return flight
  }
  loadMore = () => {
    if (this.snapshot.loading || this.snapshot.working) return Promise.resolve()
    this.pages++
    this.epoch++
    this.update({ loading: true })
    return this.refresh()
  }
  clearError = () => this.update({ error: '' })

  receive = (event: { type: string; payload?: any }) => {
    const p = event.payload || {}
    const type = event.type.toUpperCase()
    if (type === 'CONNECTED') { if (!this.flight) void this.refresh(); return }
    this.epoch++
    if (type === 'NOTIFICATION' || type === 'NEW_NOTIFICATION') {
      const item = normalizeNotification(p)
      if (item.id && !['REMINDER', 'DEADLINE_WARNING'].includes(item.type.toUpperCase())) {
        const previous = this.snapshot.items.find(n => n.id === item.id)
        if (!item.createdAt && previous) item.createdAt = previous.createdAt
        if (!previous || p.updated) {
          const increment = (!item.isRead ? 1 : 0) - (previous && !previous.isRead ? 1 : 0)
          this.update({ items: sorted([item, ...this.snapshot.items.filter(n => n.id !== item.id)]), unreadCount: Math.max(0, this.snapshot.unreadCount + increment) })
        }
      }
    } else if (type === 'NOTIFICATION_READ') {
      const unread = this.snapshot.items.some(n => n.id === p.notificationId && !n.isRead)
      this.update({ items: this.snapshot.items.map(n => n.id === p.notificationId ? { ...n, read: true, isRead: true } : n), unreadCount: Math.max(0, this.snapshot.unreadCount - (unread ? 1 : 0)) })
    } else if (type === 'ALL_READ') {
      this.update({ items: this.snapshot.items.map(n => ({ ...n, read: true, isRead: true })), unreadCount: 0 })
    } else if (type === 'NOTIFICATION_DELETED') {
      const unread = this.snapshot.items.some(n => n.id === p.notificationId && !n.isRead)
      this.update({ items: this.snapshot.items.filter(n => n.id !== p.notificationId), unreadCount: Math.max(0, this.snapshot.unreadCount - (unread ? 1 : 0)) })
    } else if (type === 'ALL_DELETED') {
      this.update({ items: [], unreadCount: 0 })
    }
    if (Number.isInteger(p.unreadCount) && p.unreadCount >= 0) this.update({ unreadCount: p.unreadCount })
    void this.refresh()
  }

  mutate = (operation: 'read' | 'readAll' | 'delete' | 'deleteAll', id?: string): Promise<void> => {
    const work = this.queue.then(async () => {
      if (!this.active) return
      const before = this.snapshot.items
      const affected = before.filter(n => !id || n.id === id)
      if (operation === 'read' && affected[0]?.isRead) return
      this.epoch++
      const deleting = operation === 'delete' || operation === 'deleteAll'
      const changedUnread = affected.filter(n => !n.isRead).length
      const countDelta = !id ? this.snapshot.unreadCount : changedUnread
      this.update({ working: true, error: '', items: deleting ? before.filter(n => id && n.id !== id) : before.map(n => !id || n.id === id ? { ...n, isRead: true, read: true } : n),
        unreadCount: !id ? 0 : Math.max(0, this.snapshot.unreadCount - changedUnread) })
      try {
        if (operation === 'read') await notificationsApi.markNotificationAsRead(id!)
        if (operation === 'readAll') await notificationsApi.markAllNotificationsAsRead()
        if (operation === 'delete') await notificationsApi.deleteNotification(id!)
        if (operation === 'deleteAll') await notificationsApi.deleteAllNotifications()
      } catch (error) {
        // Restore only the affected records, preserving messages received during the write.
        this.update({ items: sorted([...this.snapshot.items.filter(n => !affected.some(a => a.id === n.id)), ...affected]),
          unreadCount: this.snapshot.unreadCount + countDelta,
          error: 'Thao tác chưa được xác nhận. Vui lòng thử lại.' })
        throw error
      } finally {
        this.epoch++
        this.update({ working: false })
        void this.refresh()
      }
    })
    this.queue = work.catch(() => {})
    return work
  }
}

import * as pdfjsLib from 'pdfjs-dist'

// Set worker source to unpkg / jsDelivr CDN to guarantee application/javascript MIME type across all environments
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdn.jsdelivr.net/npm/pdfjs-dist@${pdfjsLib.version || '4.0.379'}/build/pdf.worker.min.mjs`

export async function renderPdfToImages(file: File, scale = 0.9, maxPages = 30): Promise<string[]> {
  const arrayBuffer = await file.arrayBuffer()
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise

  // Support multi-page PDFs (up to maxPages, default 30) for full document AI analysis
  const numPages = Math.min(pdf.numPages, maxPages)
  const pageImages: string[] = []

  // Optimize scale and compression dynamically to keep memory footprint light for 10+ page PDFs
  const effectiveScale = numPages > 15 ? Math.min(scale, 0.75) : (numPages > 5 ? Math.min(scale, 0.8) : scale)
  const jpegQuality = numPages > 15 ? 0.55 : (numPages > 5 ? 0.60 : 0.65)

  for (let i = 1; i <= numPages; i++) {
    const page = await pdf.getPage(i)
    const viewport = page.getViewport({ scale: effectiveScale })

    const canvas = document.createElement('canvas')
    const context = canvas.getContext('2d')
    if (!context) throw new Error('Could not get 2d context')

    canvas.width = viewport.width
    canvas.height = viewport.height

    const renderContext = {
      canvasContext: context,
      viewport: viewport,
      canvas: canvas as any,
    }

    await page.render(renderContext as any).promise

    // Convert to optimized JPEG base64
    const base64Img = canvas.toDataURL('image/jpeg', jpegQuality)
    pageImages.push(base64Img)
  }

  return pageImages
}

export async function processCropImagesInHtml(html: string, pageImages: string[]): Promise<string> {
  const cropRegex = /src="crop:\/\/(\d+)\/(\d+)\/(\d+)\/(\d+)\/(\d+)"/g

  let match: RegExpExecArray | null
  let finalHtml = html

  const replacements: { old: string; new: string }[] = []

  while ((match = cropRegex.exec(html)) !== null) {
    const fullMatch = match[0]
    const pageIdx = parseInt(match[1], 10)
    const ymin = parseInt(match[2], 10)
    const xmin = parseInt(match[3], 10)
    const ymax = parseInt(match[4], 10)
    const xmax = parseInt(match[5], 10)

    if (pageImages[pageIdx]) {
      const base64Src = pageImages[pageIdx]

      const img = new Image()
      await new Promise((resolve, reject) => {
        img.onload = resolve
        img.onerror = reject
        img.src = base64Src
      })

      const sx = (xmin / 1000) * img.width
      const sy = (ymin / 1000) * img.height
      const sw = ((xmax - xmin) / 1000) * img.width
      const sh = ((ymax - ymin) / 1000) * img.height

      const canvas = document.createElement('canvas')
      canvas.width = sw
      canvas.height = sh
      const ctx = canvas.getContext('2d')
      if (ctx) {
        ctx.drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh)
        const croppedBase64 = canvas.toDataURL('image/jpeg', 0.9)
        replacements.push({ old: fullMatch, new: `src="${croppedBase64}"` })
      }
    }
  }

  for (const r of replacements) {
    finalHtml = finalHtml.replace(r.old, r.new)
  }

  return finalHtml
}

import { BASE, request } from '../api/client'
import { AUTH_STORAGE_KEYS, getStoredItem } from '../api/storage'
import type { NotificationItem } from '../notifications/feed'

export type NotificationPayload = NotificationItem
export type ConnectionStatus = 'disconnected' | 'connecting' | 'connected'

// Authenticated fetch streaming works through the same API proxy as REST,
// including HTTPS deployments without exposing a separate WebSocket port.
export class NotificationSocket {
  public onEvent: ((event: { type: string; payload?: any }) => void) | null = null
  public onStatusChange: ((status: ConnectionStatus) => void) | null = null
  public onServerTime: ((time: string) => void) | null = null
  private controller: AbortController | null = null
  private timer: ReturnType<typeof setTimeout> | null = null
  private active = false
  private attempt = 0
  private generation = 0
  private status: ConnectionStatus = 'disconnected'
  getStatus() { return this.status }
  isConnected() { return this.status === 'connected' }
  private setStatus(status: ConnectionStatus) { this.status = status; this.onStatusChange?.(status) }
  connect(_token: string) {
    this.disconnect()
    this.active = true
    void this.open(++this.generation)
  }
  private async open(generation: number): Promise<void> {
    if (!this.active || generation !== this.generation) return
    const controller = new AbortController()
    this.controller = controller
    let watchdog: ReturnType<typeof setTimeout> | undefined
    const touch = () => { clearTimeout(watchdog); watchdog = setTimeout(() => controller.abort(), 45_000) }
    try {
      this.setStatus('connecting')
      touch()
      const response = await fetch(`${BASE}/notifications/stream`, {
        headers: { Authorization: `Bearer ${getStoredItem(AUTH_STORAGE_KEYS.token) || ''}`, Accept: 'text/event-stream' },
        cache: 'no-store', signal: controller.signal,
      })
      if (response.status === 401) {
        // Use the common refresh-token queue; the provider will reconnect after session sync.
        await request('/auth/me', { cache: 'no-store' })
        throw new Error('Reconnect with refreshed session')
      }
      if (!response.ok || !response.body || !response.headers.get('content-type')?.includes('text/event-stream')) throw new Error('Stream unavailable')
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      while (this.active && generation === this.generation) {
        const { done, value } = await reader.read()
        if (done) break
        if (!this.active || generation !== this.generation) return
        touch()
        buffer = (buffer + decoder.decode(value, { stream: true })).replace(/\r\n/g, '\n')
        if (buffer.length > 1024 * 1024) throw new Error('Stream frame too large')
        let end: number
        while ((end = buffer.indexOf('\n\n')) >= 0) {
          const frame = buffer.slice(0, end)
          buffer = buffer.slice(end + 2)
          const body = frame.split('\n').filter(line => line.startsWith('data:')).map(line => line.slice(5).trimStart()).join('\n')
          if (!body) continue
          try {
            const event = JSON.parse(body)
            if (typeof event.type !== 'string') continue
            if (event.serverTime || event.payload?.serverTime) this.onServerTime?.(event.serverTime || event.payload.serverTime)
            if (event.type === 'CONNECTED') {
              this.attempt = 0
              this.setStatus('connected')
            }
            this.onEvent?.(event)
          } catch { /* Malformed frames must not tear down a healthy connection. */ }
        }
      }
    } catch { /* Reconciliation on reconnect recovers missed events. */ }
    finally {
      clearTimeout(watchdog)
      controller.abort()
      if (this.active && generation === this.generation) {
        this.setStatus('disconnected')
        const delay = Math.min(30_000, 1000 * 2 ** Math.min(this.attempt++, 5)) * (0.8 + Math.random() * 0.4)
        this.timer = setTimeout(() => { void this.open(generation) }, delay)
      }
    }
  }
  disconnect() {
    this.active = false
    this.generation++
    if (this.timer) clearTimeout(this.timer)
    this.controller?.abort()
    this.setStatus('disconnected')
  }
}

'use client'

import { emitAnalyticsEvent } from '@/lib/events/analytics'
import { createContext, useContext, useEffect, useMemo, useRef, useState, useSyncExternalStore, type ReactNode } from 'react'
import { useAuth } from './auth-provider'
import { NotificationSocket, type ConnectionStatus, type NotificationPayload } from '@/lib/websocket/notification-socket'
import { NotificationFeed, type NotificationItem } from '@/lib/notifications/feed'
import { subscribeNotificationEvents, emitNotificationEvent } from '@/lib/events/notifications'
import { clearClientApiCache } from '@/lib/api/client'
import { assignmentNoticeVersion, emitAssignmentsChanged } from '@/lib/events/assignments'

export interface NotificationContextValue {
  notifications: NotificationItem[]
  unreadCount: number
  loading: boolean
  working: boolean
  error: string
  hasMore: boolean
  hasNew: boolean
  latestNotification: NotificationPayload | null
  isConnected: boolean
  connectionStatus: ConnectionStatus
  clockOffset: number
  refresh: () => void
  loadMore: () => void
  clearNew: () => void
  markAsRead: (id: string) => Promise<void>
  markAllAsRead: () => Promise<void>
  deleteNotification: (id: string) => Promise<void>
  deleteAllNotifications: () => Promise<void>
}
const NotificationContext = createContext<NotificationContextValue | null>(null)

export function NotificationProvider({ children }: { children: ReactNode }) {
  const { user, token, isAuthenticated, loading: authLoading } = useAuth()
  const owner = isAuthenticated ? user?.id : undefined
  const feed = useMemo(() => new NotificationFeed(), [owner])
  const snapshot = useSyncExternalStore(feed.subscribe, feed.getSnapshot, feed.getSnapshot)
  const assignmentNotices = useRef<{ owner?: string; versions: Set<string> }>({ versions: new Set() })
  useEffect(() => {
    if (assignmentNotices.current.owner !== owner) assignmentNotices.current = { owner, versions: new Set() }
    const versions = new Set(snapshot.items.map(assignmentNoticeVersion).filter((version): version is string => version !== null))
    const changed = [...versions].some(version => !assignmentNotices.current.versions.has(version))
    assignmentNotices.current.versions = versions
    // Works for live events and the polling fallback after a missed connection.
    if (owner && changed) emitAssignmentsChanged()
  }, [owner, snapshot.items])
  const [connection, setConnection] = useState<{ owner?: string; status: ConnectionStatus; offset: number }>({ status: 'disconnected', offset: 0 })
  const [latest, setLatest] = useState<{ owner?: string; item: NotificationPayload | null; hasNew: boolean }>({ item: null, hasNew: false })
  useEffect(() => {
    if (!owner || !token || authLoading) return
    feed.start()
    const socket = new NotificationSocket()
    let active = true
    let highlight: ReturnType<typeof setTimeout>
    socket.onStatusChange = status => { if (active) setConnection(prev => ({ owner, status, offset: prev.owner === owner ? prev.offset : 0 })) }
    socket.onServerTime = time => {
      const server = Date.parse(time)
      if (active && Number.isFinite(server)) setConnection(prev => ({ ...prev, owner, offset: server - Date.now() }))
    }
    socket.onEvent = event => {
      if (!active) return
      if (event.type === 'HEARTBEAT') return
      if (event.type === 'ANALYTICS_INVALIDATED') { emitAnalyticsEvent(); return }
      if (event.type === 'CONNECTED') { emitAnalyticsEvent(); emitAssignmentsChanged() }
      clearClientApiCache('/notifications')
      const existed = feed.getSnapshot().items.some(n => n.id === event.payload?.id)
      feed.receive(event)
      if (['NOTIFICATION', 'NEW_NOTIFICATION'].includes(event.type) && event.payload?.id && (!existed || event.payload.updated) && !event.payload.isRead && !['REMINDER', 'DEADLINE_WARNING'].includes(String(event.payload.type || event.payload.notificationType).toUpperCase())) {
        setLatest({ owner, item: event.payload, hasNew: true })
        clearTimeout(highlight)
        highlight = setTimeout(() => setLatest(prev => ({ ...prev, hasNew: false })), 5000)
      }
    }
    socket.connect(token)
    const unsubscribe = subscribeNotificationEvents(() => { void feed.refresh() })
    const online = () => { socket.connect(token); void feed.refresh() }
    window.addEventListener('online', online)
    // Repair missed events after outages and provide a fallback if a proxy blocks streaming.
    let tick = 0
    const poll = setInterval(() => {
      if (document.visibilityState === 'visible' && (!socket.isConnected() || ++tick % 4 === 0)) void feed.refresh()
    }, 15_000)
    return () => { active = false; socket.disconnect(); feed.stop(); clearTimeout(highlight); clearInterval(poll); unsubscribe(); window.removeEventListener('online', online) }
  }, [owner, token, authLoading, feed])

  const act = async (operation: 'read' | 'readAll' | 'delete' | 'deleteAll', id?: string) => {
    try { await feed.mutate(operation, id) }
    finally { emitNotificationEvent() }
  }
  const value: NotificationContextValue = {
    ...snapshot, notifications: owner ? snapshot.items : [], unreadCount: owner ? snapshot.unreadCount : 0,
    hasNew: latest.owner === owner && latest.hasNew, latestNotification: latest.owner === owner ? latest.item : null,
    isConnected: connection.owner === owner && connection.status === 'connected', connectionStatus: connection.owner === owner ? connection.status : 'disconnected',
    clockOffset: connection.owner === owner ? connection.offset : 0,
    refresh: () => { feed.clearError(); void feed.refresh() }, loadMore: () => { void feed.loadMore() },
    clearNew: () => setLatest(prev => ({ ...prev, hasNew: false })),
    markAsRead: id => act('read', id), markAllAsRead: () => act('readAll'),
    deleteNotification: id => act('delete', id), deleteAllNotifications: () => act('deleteAll'),
  }
  return <NotificationContext.Provider value={value}>{children}</NotificationContext.Provider>
}
export function useNotifications() {
  const context = useContext(NotificationContext)
  if (!context) throw new Error('useNotifications must be used within NotificationProvider')
  return context
}

import { gradingApi as api } from '@/lib/api/modules/grading'
import { cleanAssignmentHtml } from '@/utils/htmlCleaner'

export interface AiGenerationResult {
  content: string
  rubric: any
  blueprint: any
  metadata: any
  step: 1 | 2 | 3
}

export interface AiGenerationState {
  isGenerating: boolean
  loadingMsg: string
  progress: number
  result: AiGenerationResult | null
  error: string | null
  selectedSemester?: string
  subjectCode?: string
  assignmentType?: string
  textPrompt?: string
  isCompleted: boolean
  pageImages?: string[]
}

type Listener = (state: AiGenerationState) => void

class AiGenerationStoreManager {
  private state: AiGenerationState = {
    isGenerating: false,
    loadingMsg: '',
    progress: 0,
    result: null,
    error: null,
    isCompleted: false,
  }

  private listeners: Set<Listener> = new Set()
  private abortController: AbortController | null = null

  getState(): AiGenerationState {
    return this.state
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener)
    listener(this.state)
    return () => {
      this.listeners.delete(listener)
    }
  }

  private setState(partial: Partial<AiGenerationState>) {
    this.state = { ...this.state, ...partial }
    this.listeners.forEach((l) => l(this.state))
  }

  clearCompleted() {
    this.setState({
      isCompleted: false,
    })
  }

  cancelGeneration() {
    if (this.abortController) {
      this.abortController.abort()
      this.abortController = null
    }
    this.setState({
      isGenerating: false,
      loadingMsg: '',
      progress: 0,
      error: null,
      isCompleted: false,
    })
  }

  reset() {
    this.cancelGeneration()
    this.setState({
      result: null,
      selectedSemester: undefined,
      subjectCode: undefined,
      assignmentType: undefined,
      textPrompt: undefined,
      isCompleted: false,
    })
  }

  async startGeneration(
    textPrompt: string,
    selectedSemester: string,
    subjectCode: string,
    assignmentType?: string
  ) {
    this.cancelGeneration()
    this.abortController = new AbortController()

    this.setState({
      isGenerating: true,
      loadingMsg: 'AITA đang tạo nội dung đề bài bằng AI...',
      progress: 20,
      error: null,
      result: null,
      isCompleted: false,
      selectedSemester,
      subjectCode,
      assignmentType,
      textPrompt,
    })

    try {
      const promptHeader = [
        subjectCode ? `Subject: ${subjectCode}` : '',
        assignmentType ? `Assignment type: ${assignmentType}` : '',
      ].filter(Boolean).join('\n')
      const finalPrompt = promptHeader ? `${promptHeader}\n\n${textPrompt}` : textPrompt
      const markdown = await api.generateContent(finalPrompt, selectedSemester, subjectCode, {
        signal: this.abortController.signal,
      })

      this.setState({
        loadingMsg: 'Đang phân tích cấu trúc đề bài & trích xuất tiêu chí chấm...',
        progress: 50,
      })
      const draftBlueprint = await api.parseRequirements(markdown, null, subjectCode)

      this.setState({
        loadingMsg: 'Đang chạy tính toán barem rubric & sinh test cases...',
        progress: 80,
      })
      const generatedRubric = await api.generateRubric(draftBlueprint)

      let finalMarkdown = markdown
      if (draftBlueprint.projectType === 'algorithm') {
        const ioRule = generatedRubric.rules?.find((r: any) => r.scoringStrategy === 'StdInOutProbe')
        const testCases = ioRule?.requiredEvidence?.[0]?.stdInOutProbe?.testCases
        if (testCases && testCases.length > 0) {
          finalMarkdown += `<br/><h3>Expected Behavior (Test Cases)</h3><ul>`
          testCases.forEach((tc: any, idx: number) => {
            finalMarkdown += `<li><strong>Test Case ${idx + 1}:</strong><br/>Input:<pre>${tc.input}</pre>Output:<pre>${tc.expectedOutput}</pre></li><br/>`
          })
          finalMarkdown += `</ul>`
        }
      }

      const result: AiGenerationResult = {
        content: cleanAssignmentHtml(finalMarkdown),
        rubric: generatedRubric,
        blueprint: draftBlueprint,
        metadata: {
          title: draftBlueprint.assignmentTitle || 'AI Generated Assignment',
          description: draftBlueprint.description || '',
          projectType: draftBlueprint.projectType || 'backend',
          subject: subjectCode || draftBlueprint.subject || '',
          category: assignmentType || 'Assignment',
        },
        step: 2,
      }

      this.setState({
        isGenerating: false,
        loadingMsg: '',
        progress: 100,
        result,
        isCompleted: true,
      })
    } catch (err: any) {
      if (err.name === 'AbortError') return
      this.setState({
        isGenerating: false,
        loadingMsg: '',
        progress: 0,
        error: err.response?.data?.error || err.message || 'Không thể tạo đề bài bằng AI',
        isCompleted: false,
      })
    }
  }

  async startFileGeneration(file: File, selectedSemester: string, subjectCode: string, assignmentType?: string) {
    this.cancelGeneration()
    this.abortController = new AbortController()

    this.setState({
      isGenerating: true,
      loadingMsg: `Đang đọc và trích xuất nội dung từ tập tin ${file.name}...`,
      progress: 15,
      error: null,
      result: null,
      isCompleted: false,
      selectedSemester,
      subjectCode,
      assignmentType,
      pageImages: [],
    })

    try {
      let pageImages: string[] = []
      if (file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')) {
        try {
          this.setState({ loadingMsg: 'Đang trích xuất hình ảnh các trang PDF cho AI Vision...', progress: 20 })
          const { renderPdfToImages } = await import('@/lib/pdf')
          pageImages = await renderPdfToImages(file, 0.9, 30)
          this.setState({
            pageImages,
            loadingMsg: `Đã trích xuất ${file.name} (${pageImages.length} trang) thành công. Đang phân tích...`,
            progress: 35,
          })
        } catch (pdfErr) {
          console.warn('[AiGenerationStore] PDF page rendering warning, falling back to text extraction:', pdfErr)
        }
      }

      const extractedData: any = await api.extractText(file, selectedSemester, subjectCode)
      const extractedText = (extractedData?.text?.rawText && extractedData.text.rawText.trim().length > 0)
        ? extractedData.text.rawText
        : (typeof extractedData?.text === 'string' && extractedData.text.trim().length > 0
          ? extractedData.text
          : (extractedData?.rawText || ''))

      this.setState({
        loadingMsg: 'AITA đang tạo cấu trúc bài tập từ tài liệu trích xuất...',
        progress: 45,
      })
      const promptHeader = [
        subjectCode ? `Subject: ${subjectCode}` : '',
        assignmentType ? `Assignment type: ${assignmentType}` : '',
      ].filter(Boolean).join('\n')
      const finalPrompt = promptHeader ? `${promptHeader}\n\n${extractedText}` : extractedText
      const markdown = await api.generateContent(finalPrompt, selectedSemester, subjectCode, {
        signal: this.abortController.signal,
        pageImages: pageImages.length > 0 ? pageImages : undefined,
      })

      this.setState({
        loadingMsg: 'Đang phân tích yêu cầu & thiết lập quy tắc rubric...',
        progress: 70,
      })
      const draftBlueprint = await api.parseRequirements(markdown, null, subjectCode)
      const generatedRubric = await api.generateRubric(draftBlueprint)

      let finalMarkdown = markdown
      if (draftBlueprint.projectType === 'algorithm') {
        const ioRule = generatedRubric.rules?.find((r: any) => r.scoringStrategy === 'StdInOutProbe')
        const testCases = ioRule?.requiredEvidence?.[0]?.stdInOutProbe?.testCases
        if (testCases && testCases.length > 0) {
          finalMarkdown += `<br/><h3>Expected Behavior (Test Cases)</h3><ul>`
          testCases.forEach((tc: any, idx: number) => {
            finalMarkdown += `<li><strong>Test Case ${idx + 1}:</strong><br/>Input:<pre>${tc.input}</pre>Output:<pre>${tc.expectedOutput}</pre></li><br/>`
          })
          finalMarkdown += `</ul>`
        }
      }

      const result: AiGenerationResult = {
        content: cleanAssignmentHtml(finalMarkdown),
        rubric: generatedRubric,
        blueprint: draftBlueprint,
        metadata: {
          title: draftBlueprint.assignmentTitle || 'AI Generated Assignment',
          description: draftBlueprint.description || '',
          projectType: draftBlueprint.projectType || 'backend',
          subject: subjectCode || draftBlueprint.subject || '',
          category: assignmentType || 'Assignment',
        },
        step: 2,
      }

      this.setState({
        isGenerating: false,
        loadingMsg: '',
        progress: 100,
        result,
        isCompleted: true,
      })
    } catch (err: any) {
      if (err.name === 'AbortError') return
      this.setState({
        isGenerating: false,
        loadingMsg: '',
        progress: 0,
        error: err.response?.data?.error || err.message || 'Không thể trích xuất & tạo đề bài từ tập tin',
        isCompleted: false,
      })
    }
  }
}

export const aiGenerationStore = new AiGenerationStoreManager()

